window.TREE={"subject":"민법개론","key":"pt_civil","brand":"모두의 전문직","parts":[{"no":1,"name":"민법총칙","chs":["1-01"],"color":"--fam-geo"},{"no":2,"name":"물권법","chs":["2-02"],"color":"--fam-soc"},{"no":3,"name":"채권총론","chs":["3-03"],"color":"--fam-eth"},{"no":4,"name":"채권각론","chs":["4-04"],"color":"--mint"}],"chs":[{"key":"1-01","part":1,"no":1,"name":"민법총칙","nodes":[1,2,3,4]},{"key":"2-02","part":2,"no":2,"name":"물권법","nodes":[5,6,7,8]},{"key":"3-03","part":3,"no":3,"name":"채권총론","nodes":[9,10,11,12]},{"key":"4-04","part":4,"no":4,"name":"채권각론","nodes":[13,14,15,16]}],"nodes":[{"no":1,"part":1,"ch":1,"title":"서론 및 권리의 주체","name":"서론 및 권리의 주체","vol":20,"q":80},{"no":2,"part":1,"ch":1,"title":"권리의 객체","name":"권리의 객체","vol":7,"q":31},{"no":3,"part":1,"ch":1,"title":"법률행위 총론","name":"법률행위 총론","vol":47,"q":190},{"no":4,"part":1,"ch":1,"title":"소멸시효","name":"소멸시효","vol":11,"q":47},{"no":5,"part":2,"ch":2,"title":"물권총론","name":"물권총론","vol":10,"q":43},{"no":6,"part":2,"ch":2,"title":"점유권과 소유권","name":"점유권과 소유권","vol":20,"q":83},{"no":7,"part":2,"ch":2,"title":"용익물권","name":"용익물권","vol":16,"q":65},{"no":8,"part":2,"ch":2,"title":"담보물권","name":"담보물권","vol":36,"q":144},{"no":9,"part":3,"ch":3,"title":"채권의 목적과 효력","name":"채권의 목적과 효력","vol":22,"q":88},{"no":10,"part":3,"ch":3,"title":"책임재산의 보전","name":"책임재산의 보전","vol":14,"q":56},{"no":11,"part":3,"ch":3,"title":"다수당사자의 채권관계·채권양도와 채무인수","name":"다수당사자의 채권관계·채권양도와 채무인수","vol":23,"q":92},{"no":12,"part":3,"ch":3,"title":"채권의 소멸","name":"채권의 소멸","vol":6,"q":24},{"no":13,"part":4,"ch":4,"title":"계약총론","name":"계약총론","vol":25,"q":101},{"no":14,"part":4,"ch":4,"title":"계약각론","name":"계약각론","vol":19,"q":79},{"no":15,"part":4,"ch":4,"title":"사무관리·부당이득","name":"사무관리·부당이득","vol":9,"q":37},{"no":16,"part":4,"ch":4,"title":"불법행위","name":"불법행위","vol":7,"q":31}],"stat":{"parts":4,"chs":4,"nodes":16,"q":1191}};
window.QBANK={"1":[{"y":2016,"e":"변리사 1차","qn":1,"i":"변리사2016_53-01","t":"신의성실의 원칙에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면","c":"A","mc":{"s":"신의성실의 원칙에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면","d":"판례에 따름)\nㄱ. 계약 성립의 기초가 되지 않는 사정이 그 후 변경되어 일방 당사자가 계약 당시 의도한 계약 목적을 달성할 수 없게 됨으로써 손해를 입은 경우, 특별한 사정이 없는 한 사정변경을 이유로 한 계약 해제가 인정되지 않는다.\nㄴ. 회사의 이사가 채무액과 변제기가 특정되어 있는 회사 채무에 대하여 보증계약을 체결한 경우, 이사직 사임이라는 사정변경을 이유로 일방적으로 보증계약을 해지할 수 있다.\nㄷ. 신의성실의 원칙에 반하는 것 또는 권리남용은 강행규정에 위배되는 것이 므로 당사자의 주장이 없더라도 법원은 직권으로 판단할 수 있다.\nㄹ. 강행법규에 위반한 자가 스스로 그 약정의 무효를 주장하는 것은 특별한 사정이 없는 한 신의성실의 원칙에 반하는 것으로서 허용되지 않는다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄱ, ㄹ","ㄴ, ㄷ","ㄷ, ㄹ"],"a":2}},{"y":2016,"e":"변리사 1차","qn":2,"i":"변리사2016_53-02","t":"제한능력자의 행위능력에 관한 설명으로 옳지 않은 것은? (다툼이 있으면 판례에","c":"A","mc":{"s":"제한능력자의 행위능력에 관한 설명으로 옳지 않은 것은? (다툼이 있으면 판례에","d":"따름)","o":["법정대리인의 동의 없이 신용구매계약을 체결한 미성년자는 특별한 사정이 없는 한그 동의 없음을 이유로 위 계약을 취소할 수 있다.","미성년자가 법률행위를 함에 있어서 요구되는 법정대리인의 동의는 언제나 명시적 이어야 하는 것은 아니고 묵시적으로도 가능하다.","피성년후견인이 성년후견인의 동의 없이 일용품의 구입 등 일상생활에 필요하고 그 대가가 과도하지 아니한 법률행위를 한 경우, 성년후견인이 이를 취소할 수 없다.","성년후견개시의 심판을 받은 자가 취소할 수 없는 범위에 속하는 법률행위를 성년후견인의 동의 없이 한 경우에는 유효한 법률행위가 성립한다.","한정후견인의 동의가 있어야 하는 법률행위에 있어서 동의가 없으면 피한정후견인의 이익이 침해될 염려가 있음에도 동의하지 않는 경우, 피한정후견인이 동의 없이 법률행위를 하였다면 한정후견인은 이를 취소할 수 없다."],"a":5}},{"y":2016,"e":"변리사 1차","qn":3,"i":"변리사2016_53-03","t":"법인의 불법행위(민법 제35조)에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에","c":"A","mc":{"s":"법인의 불법행위(민법 제35조)에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에","d":"따름)","o":["법인의 불법행위는 대표권이 없는 이사가 제3자에 대하여 행한 불법행위에 의해 서도 성립한다.","법인의 불법행위는 법인을 실질적으로 운영하면서 법인을 사실상 대표하여 법인의 사무를 집행하는 자가 법인사무에 관하여 제3자에 대하여 행한 불법행위에 대해서는 성립하지 않는다.","법인의 불법행위는 감사의 행위에 의해서도 성립한다.","법인의 불법행위는 대표기관이 법인의 목적범위 외의 행위로 인하여 타인에게 손해를 가한 때에도 인정된다.","법인의 불법행위책임의 성립요건으로 요구되는 대표기관의 직무관련성은 행위의 외형을 기준으로 객관적으로 판단하여야 한다."],"a":5}},{"y":2017,"e":"변리사 1차","qn":1,"i":"변리사2017_54-01","t":"관습법과 사실인 관습에 관한 설명으로 옳지 않은 것은? (다툼이 있으면 판례에","c":"A","mc":{"s":"관습법과 사실인 관습에 관한 설명으로 옳지 않은 것은? (다툼이 있으면 판례에","d":"따름)","o":["관습법은 법원(法源)으로서 법령에 저촉되지 않는 한, 법칙으로서의 효력이 있다.","미등기 무허가건물의 매수인은 그 소유권이전등기를 경료하지 않으면 건물의 소유권을 취득할 수 없지만, 소유권에 준하는 관습상의 물권이 인정될 수는 있다.","종중의 명칭사용이 그에 관한 관습에 어긋난다고 하여도, 그러한 사실만으로 그 종중의 실체를 부인할 수는 없다.","사실인 관습은 사적 자치가 인정되는 분야의 제정법이 임의규정인 경우에는 법률행위의 해석기준이 되므로, 이를 재판의 자료로 할 수 있다.","제정법규와 배치되는 사실인 관습의 효력을 인정하려면, 그러한 관습을 인정할 수 있는 당사자의 주장과 입증이 있어야 할 뿐만 아니라 그 관습이 임의규정에 관한 것인지 여부를 심리\u0001판단해야 한다."],"a":2}},{"y":2017,"e":"변리사 1차","qn":2,"i":"변리사2017_54-02","t":"甲은 2014. 5. 20. 항공기 추락으로 실종된 후, 2015. 12. 20. 실종선고가 청구되어 2016. 7. 20. 실종선고가 되었다. 甲에게는 가족으로 배우자 乙 외에 어머니 丙, 아들 丁이 있었고, 유산으로 X건물을 남겼다. 이에 관한 설명으로 옳지 않은 것을 모두 고른 것은?","c":"A","mc":{"s":"甲은 2014. 5. 20. 항공기 추락으로 실종된 후, 2015. 12. 20. 실종선고가 청구되어 2016. 7. 20. 실종선고가 되었다. 甲에게는 가족으로 배우자 乙 외에 어머니 丙, 아들 丁이 있었고, 유산으로 X건물을 남겼다. 이에 관한 설명으로 옳지 않은 것을 모두 고른 것은?","d":"ㄱ. 특별한 사정이 없는 한 乙, 丙, 丁은 모두 甲의 실종선고에 대하여 이해관계가 있는 자로서 실종선고를 청구할 수 있다.\nㄴ. 乙의 甲에 대한 이혼판결이 2016. 5. 10. 확정되었더라도, 그 후 甲에 대한 실종선고로 사망간주시점이 소급되면, 이혼판결은 사망자를 상대로한 것이므로 무효가 된다.\nㄷ. 甲에 대한 실종선고로 X건물은 이미 상속되었는데, 2015. 6. 10. 甲의 생존사실이 밝혀진 경우, 실종선고가 취소되기 전에는 위 상속은 효력이 있다.","o":["ㄱ","ㄴ","ㄱ, ㄴ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":3}},{"y":2017,"e":"변리사 1차","qn":3,"i":"변리사2017_54-03","t":"비법인사단인 A종중과 그 대표자 甲, 그리고 乙 사이의 법률관계에 관한 설명으로 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"비법인사단인 A종중과 그 대표자 甲, 그리고 乙 사이의 법률관계에 관한 설명으로 옳은 것을 모두 고른 것은?","d":"ㄱ. 甲이 乙에게 한 A의 업무에 대한 포괄적 위임과 그에 따른 乙의 대행행위는 A에게 그 효력이 미친다.\nㄴ. 비법인사단은 자연인과 달리 명예권을 가질 수 없으므로, A의 명예를 훼손한 乙에 대하여 A가 손해배상을 청구할 수는 없다.\nㄷ. 甲의 불법행위로 乙에게 손해가 발생한 경우, 甲의 행위가 직무에 관한 것이 아님을 乙이 알았다면, 乙은 A에 대하여 민법 제35조 제1항에 따른 불법행위책임을 물을 수 없다.\nㄹ. 甲의 불법행위로 乙에게 손해가 발생한 경우, 甲의 행위가 법령의 규정에 위배되더라도 외관상 객관적으로 직무에 관한 행위라고 인정된다면, A는 乙에 대하여 민법 제35조 제1항에 따른 불법행위책임을 진다.","o":["ㄱ","ㄷ","ㄱ, ㄴ","ㄷ, ㄹ","ㄱ, ㄴ, ㄹ"],"a":4}},{"y":2018,"e":"변리사 1차","qn":3,"i":"변리사2018_55-03-1","t":"온천에 관한 권리는 관습법상의 물권이나 준물권이라고 볼 수 없다.","ox":"O","m":"①","c":"A","tp":"관습법과 관습"},{"y":2018,"e":"변리사 1차","qn":3,"i":"변리사2018_55-03-2","t":"관습법은 사회의 거듭된 관행과 법적 확신이 없어도 성립된다.","ox":"X","m":"②","c":"A","tp":"관습법과 관습"},{"y":2018,"e":"변리사 1차","qn":3,"i":"변리사2018_55-03-3","t":"관습은 당사자의 주장\u0001입증을 기다림이 없이 법원이 직권으로 이를 확정하여야 한다.","ox":"X","m":"③","c":"A","tp":"관습법과 관습"},{"y":2018,"e":"변리사 1차","qn":3,"i":"변리사2018_55-03-4","t":"공동선조와 성과 본을 같이하는 후손이면 미성년자라도 성별의 구별 없이 당연히 종중의 구성원이 된다.","ox":"X","m":"④","c":"A","tp":"관습법과 관습"},{"y":2018,"e":"변리사 1차","qn":3,"i":"변리사2018_55-03-5","t":"관습법이 사회생활규범으로 승인되었다면 사회를 지배하는 기본적 이념이나 사회질서의 변화로 인하여 그 관습법을 적용하여야 할 시점에 있어서의 전체 법질 서에 부합하지 않게 되었더라도 그 법규범으로서의 효력이 인정된다.","ox":"X","m":"⑤","c":"A","tp":"관습법과 관습"},{"y":2018,"e":"변리사 1차","qn":4,"i":"변리사2018_55-04-1","t":"미성년자는 임의대리인이 될 수 없다.","ox":"X","m":"①","c":"A"},{"y":2018,"e":"변리사 1차","qn":4,"i":"변리사2018_55-04-2","t":"법정대리인이 미성년자에게 영업을 허락한 후 그 허락을 취소한 경우에 미성년자는 그 영업허락의 취소 전에 그 영업을 위하여 한 상품주문행위를 미성년임을 이유로 취소할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"변리사 1차","qn":4,"i":"변리사2018_55-04-3","t":"미성년자가 법정대리인의 동의 없이 법률행위를 한 경우에 법정대리인의 취소권이 기간경과로 소멸되지 않는 한, 미성년자는 성년이 되기 전까지만 취소할 수 있고 성년이 된 후에는 취소할 수 없다.","ox":"X","m":"③","c":"A"},{"y":2018,"e":"변리사 1차","qn":4,"i":"변리사2018_55-04-4","t":"甲이 乙과 계약을 체결할 당시 乙이 미성년자임을 알고 계약했더라도 甲은 철회 권을 행사할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2018,"e":"변리사 1차","qn":4,"i":"변리사2018_55-04-5","t":"미성년자가 법정대리인의 동의 없이 법률행위를 하면서 특약에 의하여 미성년을 이유로 한 취소를 하지 않기로 한 경우에는 미성년을 이유로 그 법률행위를 취소할 수 없다.","ox":"X","m":"⑤","c":"A"},{"y":2018,"e":"변리사 1차","qn":7,"i":"변리사2018_55-07-1","t":"권리능력 없는 사단의 구성원은 그가 사단의 대표자이거나 사원총회의 결의를 거쳤다 하더라도 그 사단의 재산에 관한 제3자와의 소송에서 당사자가 될 수 없다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"변리사 1차","qn":7,"i":"변리사2018_55-07-2","t":"권리능력 없는 사단의 사원이 집합체로서 물건을 소유한 경우에는 합유로 한다.","ox":"X","m":"②","c":"A"},{"y":2018,"e":"변리사 1차","qn":7,"i":"변리사2018_55-07-3","t":"권리능력 없는 사단에 구성원이 없게 되었다면 그 사단은 바로 소멸하여 소송상의 당사자능력을 상실한다.","ox":"X","m":"③","c":"A"},{"y":2018,"e":"변리사 1차","qn":7,"i":"변리사2018_55-07-4","t":"권리능력 없는 사단의 대표자는 필요한 경우에 자신의 업무를 타인에게 포괄적으로 위임할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2018,"e":"변리사 1차","qn":7,"i":"변리사2018_55-07-5","t":"권리능력 없는 사단의 사원의 지위는 규약에 의해서라도 양도나 상속될 수 없다.","ox":"X","m":"⑤","c":"A"},{"y":2018,"e":"변리사 1차","qn":8,"i":"변리사2018_55-08","t":"신의성실의 원칙에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으","c":"A","mc":{"s":"신의성실의 원칙에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으","d":"면 판례에 따름)\nㄱ. 회사의 이사가 채무액과 변제기가 특정되어 있는 회사 채무를 보증한 경우에는 이사직 사임이라는 사정변경을 이유로 일방적으로 보증계약을 해지할 수 없다.\nㄴ. 공무원의 불법행위에 따른 국가배상청구권의 소멸시효 기간이 지났으 나 국가가 소멸시효 완성을 주장하는 것이 신의성실의 원칙에 반하는 권리남용으로 허용될 수 없어 배상책임을 이행한 경우, 국가가 사건의 은폐\u0001조작 등 권리남용에 해당하게 된 원인행위를 적극적으로 주도한 공무원에게 구상권을 행사하는 것은 신의칙상 허용되지 않는다.\nㄷ. 주식회사 대표이사의 대표권 남용행위의 상대방이 그와 같은 사정을 알았던 경우에 회사는 상대방의 악의를 증명하여 행위의 효과를 부인할 수 있다.\nㄹ. 재산권의 거래계약에 있어서 일방 당사자에게 상대방에 대한 고지의무 가 인정되는 경우에는 상대방이 고지의무의 대상이 되는 사실을 이미 알고 있는 때에도 여전히 고지의무를 부담한다.\nㅁ. 부동산 거래에 있어 거래 상대방이 일정한 사정에 관한 고지를 받았더 라면 그 거래를 하지 않았을 것임이 경험칙상 명백한 경우에는 신의성실의 원칙상 사전에 상대방에게 그와 같은 사정을 고지할 의무가 있다.","o":["ㄱ, ㄴ, ㄹ","ㄱ, ㄴ, ㅁ","ㄱ, ㄷ, ㅁ","ㄴ, ㄷ, ㄹ","ㄷ, ㄹ, ㅁ"],"a":3}},{"y":2018,"e":"변리사 1차","qn":9,"i":"변리사2018_55-09-1","t":"법인의 정관에 법인 대표권의 제한에 관한 규정이 있다면, 그러한 취지가 등기되어 있지 않은 경우에도 법인은 그 제한으로써 악의의 제3자에게 대항할 수 있다.","ox":"X","m":"①","c":"A","tp":"법인의 이사"},{"y":2018,"e":"변리사 1차","qn":9,"i":"변리사2018_55-09-2","t":"법인의 정관에 이사의 해임사유에 관한 규정이 있는 경우에는 이사의 중대한 의무 위반이 있더라도 법인은 정관에서 정하지 아니한 사유로 이사를 해임할 수 없다.","ox":"X","m":"②","c":"A","tp":"법인의 이사"},{"y":2018,"e":"변리사 1차","qn":9,"i":"변리사2018_55-09-3","t":"법인과 이사의 법률관계는 신뢰를 기초로 한 위임 유사의 관계이고, 위임계약은 원래 해지의 자유가 인정되어 쌍방 누구나 정당한 이유 없이도 언제든지 해지할 수 있으며, 다만 불리한 시기에 부득이한 사유 없이 해지한 경우에 한하여 상대방에게 그로 인한 손해배상책임을 부담할 뿐이다.","ox":"O","m":"③","c":"A","tp":"법인의 이사"},{"y":2018,"e":"변리사 1차","qn":9,"i":"변리사2018_55-09-4","t":"이사의 임기가 만료되었더라도 아직 임기가 만료되지 아니한 다른 이사들로 법인이 정상적인 활동을 할 수 있는 경우에는 임기만료된 이사로 하여금 이사로서 직무를 행사하게 할 필요가 없고, 법인의 정상적인 활동이 가능한지 여부는 이 사의 임기만료시뿐만 아니라 이후의 사정까지도 종합적으로 고려하여 판단하여야 한다.","ox":"X","m":"④","c":"A","tp":"법인의 이사"},{"y":2018,"e":"변리사 1차","qn":9,"i":"변리사2018_55-09-5","t":"대표권 없는 이사도 법인의 기관이므로 그의 행위로 인하여 민법 제35조 소정의 법인의 불법행위가 성립할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"법인의 이사"},{"y":2018,"e":"변리사 1차","qn":10,"i":"변리사2018_55-10-1","t":"의사능력이란 자신의 행위의 의미나 결과를 정상적인 인식력과 예기력을 바탕으로 합리적으로 판단할 수 있는 정신적 능력 내지 지능을 말한다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"변리사 1차","qn":10,"i":"변리사2018_55-10-2","t":"의사능력의 유무는 구체적인 법률행위와 관련하여 개별적으로 판단되어야 한다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"변리사 1차","qn":10,"i":"변리사2018_55-10-3","t":"미성년자가 의사무능력 상태에서 법정대리인의 동의 없이 법률행위를 한 경우, 법정대리인은 미성년을 이유로 법률행위를 취소할 수 있다.","ox":"O","m":"③","c":"A","tp":"의사능력"},{"y":2018,"e":"변리사 1차","qn":10,"i":"변리사2018_55-10-4","t":"어떤 법률행위에 그 일상적인 의미만을 이해하여서는 알기 어려운 특별한 법률 적인 의미나 효과가 부여되어 있는 경우에도 의사능력이 인정되기 위하여 그 행위의 일상적인 의미에 대한 이해만으로 족하고 법률적인 의미나 효과에 대한이 해는 요구되지 않는다.","ox":"X","m":"④","c":"A"},{"y":2018,"e":"변리사 1차","qn":10,"i":"변리사2018_55-10-5","t":"의사무능력자의 법률행위에 있어서는 그 행위의 무효를 주장하는 자가 의사능력이 없었음을 증명하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"변리사 1차","qn":1,"i":"변리사2019_56-01","t":"신의성실의 원칙에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면 판례에","c":"A","mc":{"s":"신의성실의 원칙에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면 판례에","d":"따름)\nㄱ. 사정변경을 이유로 계약의 해제가 인정되는 경우는 계약준수 원칙의 예외에 해당한다.\nㄴ. 사용자는 근로계약에 수반되는 신의칙상의 부수의무로서 피용자가 노무를 제공하는 과정에서 건강을 해치는 일이 없도록 필요한 조치를 강구하여야할 의무를 부담한다.\nㄷ. 채권자가 채권을 확보하기 위하여 제3자의 부동산을 채무자에게 명의신탁 하도록 한 다음 그 부동산에 대하여 강제집행을 하는 행위는 신의칙상 허용되지 않는다.\nㄹ. 아파트 분양자는 아파트 단지 인근에 쓰레기 매립장이 건설예정인 사실을 분양계약자에게 고지할 신의칙상 의무를 부담한다.","o":["ㄱ","ㄴ, ㄷ","ㄷ, ㄹ","ㄱ, ㄴ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":5}},{"y":2019,"e":"변리사 1차","qn":2,"i":"변리사2019_56-02-2","t":"甲은 법정대리인의 동의가 없었다는 이유로 자신이 체결한 매매계약을 원칙적으로 취소할 수 없다.","ox":"X","m":"②","c":"A"},{"y":2019,"e":"변리사 1차","qn":2,"i":"변리사2019_56-02-3","t":"乙은 매매계약을 체결할 당시 甲이 17세라는 것을 알았던 경우에도 甲의 법정대리인에게 매매계약을 추인할 것인지 여부의 확답을 촉구할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"변리사 1차","qn":2,"i":"변리사2019_56-02-4","t":"甲이 매매계약에 대하여 법정대리인의 동의서를 위조하였고, 乙이 이를 믿고 계약을 체결한 경우, 甲의 법정대리인도 매매계약을 취소할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"변리사 1차","qn":2,"i":"변리사2019_56-02-5","t":"매매계약을 체결할 당시 甲이 17세라는 것을 乙이 알았던 경우, 乙은 매매계약과 관련한 자신의 의사표시를 철회할 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"변리사 1차","qn":3,"i":"변리사2019_56-03-1","t":"민법상 재단법인은 비영리법인이다.","ox":"O","m":"①","c":"A","tp":"민법상 법인"},{"y":2019,"e":"변리사 1차","qn":3,"i":"변리사2019_56-03-2","t":"사원자격의 득실에 관한 규정은 재단법인 정관의 필요적 기재사항에 해당한다.","ox":"X","m":"②","c":"A","tp":"민법상 법인"},{"y":2019,"e":"변리사 1차","qn":3,"i":"변리사2019_56-03-3","t":"해산한 법인은 청산의 목적범위 내에서만 권리가 있고 의무를 부담한다.","ox":"O","m":"③","c":"A","tp":"민법상 법인"},{"y":2019,"e":"변리사 1차","qn":3,"i":"변리사2019_56-03-4","t":"이사의 대표권에 대한 제한은 이를 등기하지 않으면, 제3자가 악의이더라도 대항하지 못한다.","ox":"O","m":"④","c":"A","tp":"민법상 법인"},{"y":2019,"e":"변리사 1차","qn":3,"i":"변리사2019_56-03-5","t":"청산종결의 등기가 마쳐졌더라도 청산사무가 종료되지 않은 경우에는 그 범위 내에서 청산법인으로서 존속한다.","ox":"O","m":"⑤","c":"A","tp":"민법상 법인"},{"y":2021,"e":"변리사 1차","qn":1,"i":"변리사2021_58-01","t":"권리남용금지의 원칙에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면","c":"A","mc":{"s":"권리남용금지의 원칙에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면","d":"판례에 따름)\nㄱ. 채무자가 소멸시효완성 전에 채권자의 권리행사를 현저하게 곤란하게 하여 시효가 완성된 경우, 채무자가 시효의 완성을 주장하는 것은 권리 남용이 된다.\nㄴ. 권리남용은 당사자의 주장이 없더라도 법원은 직권으로 판단할 수 있다.\nㄷ. 거래당사자가 유치권을 자신의 이익을 위하여 고의적으로 작출하여 유치권의 최우선순위담보권으로서의 지위를 부당하게 이용함으로써 신의성실의 원칙에 반한다고 평가되는 경우에는 유치권의 남용이 된다.\nㄹ. 권리남용으로 인정되는 경우, 남용의 구체적 효과는 권리의 종류와 남용의 결과에 관계없이 권리의 박탈이라는 점에서는 동일하다.","o":["ㄱ, ㄴ","ㄴ, ㄷ","ㄷ, ㄹ","ㄱ, ㄴ, ㄷ","ㄴ, ㄷ, ㄹ"],"a":4}},{"y":2021,"e":"변리사 1차","qn":2,"i":"변리사2021_58-02","t":"법인의 기관에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면 판례에","c":"A","mc":{"s":"법인의 기관에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면 판례에","d":"따름)\nㄱ. 법인의 정관에 이사의 해임사유에 관한 규정이 있는 경우, 법인으로서 는 이사의 중대한 의무위반 등의 특별한 사정이 없는 이상 정관에서 정하지 아니한 사유로 이사를 해임할 수 없다.\nㄴ. 이사와 감사의 성명\u0001주소는 등기사항이다.\nㄷ. 법인과 이사의 이익이 상반되는 경우, 법원이 선임한 특별대리인은 그 사항에 대하여 법인을 대표한다.\nㄹ. 이사의 대표권 제한이 정관에 기재된 경우, 이를 등기하지 않아도 악의의 제3자에게 대항할 수 있다.","o":["ㄱ, ㄷ","ㄴ, ㄹ","ㄱ, ㄴ, ㄹ","ㄱ, ㄷ, ㄹ","ㄴ, ㄷ, ㄹ"],"a":1}},{"y":2021,"e":"변리사 1차","qn":3,"i":"변리사2021_58-03-1","t":"비법인사단은 부동산소유권에 관하여 등기의무자가 될 수 없다.","ox":"X","m":"①","c":"A"},{"y":2021,"e":"변리사 1차","qn":3,"i":"변리사2021_58-03-2","t":"비법인사단의 해산에 따른 청산절차에는 사단법인의 청산인에 관한 민법 규정을 유추적용할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"변리사 1차","qn":3,"i":"변리사2021_58-03-3","t":"비법인사단의 대표자가 행한 타인에 대한 업무의 포괄적 위임과 그에 따른 포괄적 수 임인의 대행행위는 비법인사단에 대하여 그 효력이 있다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"변리사 1차","qn":3,"i":"변리사2021_58-03-4","t":"비법인사단의 채무는 구성원의 지분비율에 따라 귀속한다.","ox":"X","m":"④","c":"A"},{"y":2021,"e":"변리사 1차","qn":3,"i":"변리사2021_58-03-5","t":"이사의 결원으로 인하여 손해가 생길 염려가 있더라도 이해관계인은 법원에 임시이사의 선임을 청구할 수 없다.","ox":"X","m":"⑤","c":"A","tp":"비법인사단"},{"y":2023,"e":"변리사 1차","qn":1,"i":"변리사2023_60-01","t":"가상화폐 투자에 실패한 甲은 부인 乙을 볼 면목이 없어 2015. 9. 15. 지리산으로 들어가 누구와도 연락을 하지 않았다. 甲의 생사를 알지 못한 乙은 2021. 9. 7. 법원에 실종선고를 청구하여 2022. 3. 10. 실종선고가 되었다. 甲의 실종선고로 甲에 대한 사망보험금 5억 원을 수령한 乙은 주식에 투자하여 큰 손실을 보았다. 지리 산에서 삶의 새로운 목표를 찾은 甲은 2023. 2. 5. 집으로 돌아왔다. 이에 관한 설명으로 옳은 것은?","c":"A","mc":{"s":"가상화폐 투자에 실패한 甲은 부인 乙을 볼 면목이 없어 2015. 9. 15. 지리산으로 들어가 누구와도 연락을 하지 않았다. 甲의 생사를 알지 못한 乙은 2021. 9. 7. 법원에 실종선고를 청구하여 2022. 3. 10. 실종선고가 되었다. 甲의 실종선고로 甲에 대한 사망보험금 5억 원을 수령한 乙은 주식에 투자하여 큰 손실을 보았다. 지리 산에서 삶의 새로운 목표를 찾은 甲은 2023. 2. 5. 집으로 돌아왔다. 이에 관한 설명으로 옳은 것은?","d":"","o":["실종선고로 甲의 사망이 의제된 시점은 2022. 3. 10.이다.","甲의 실종선고가 취소되지 않더라도 甲이 살아 있는 것이 증명되었으므로, 보험회사 는 乙을 상대로 한 사망보험금 반환소송에서 승소할 수 있다.","甲에 대한 실종선고가 취소되면, 선의인 乙은 현존이익 한도에서 보험금을 반환하면 된다.","실종선고를 취소하지 않는 한, 甲은 공직선거권이 없다.","법원에 의해 甲의 실종선고가 취소되면, 그 때부터 장래를 향하여 甲에 대한 실종선고의 효력이 부정된다."],"a":3}},{"y":2023,"e":"변리사 1차","qn":2,"i":"변리사2023_60-02-1","t":"2023. 2. 18. 현재 甲은 이미 성년이 되었으므로, 매매계약을 취소할 수 없다.","ox":"X","m":"①","c":"A"},{"y":2023,"e":"변리사 1차","qn":2,"i":"변리사2023_60-02-2","t":"만일 甲이 2022. 2. 17. 丁의 동의 없이 매매계약을 추인하였더라도, 甲은 위 매매계약을 취소할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"변리사 1차","qn":2,"i":"변리사2023_60-02-3","t":"만일 甲이 2022. 5. 15. 丁의 동의 없이 매매계약을 추인한 경우, 그 추인은 유효하다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"변리사 1차","qn":2,"i":"변리사2023_60-02-4","t":"만일 甲이 2022. 10. 5. 아무런 이의를 제기하지 않고 乙로부터 매매대금을 수령한 경우, 매매계약을 취소할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"변리사 1차","qn":2,"i":"변리사2023_60-02-5","t":"2023. 2. 18. 현재 甲은 위 매매계약을 丁의 동의 없이 유효하게 추인할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"변리사 1차","qn":3,"i":"변리사2023_60-03-1","t":"생전처분으로 재단법인을 설립하는 때에는 증여에 관한 규정을 준용한다.","ox":"O","m":"①","c":"A","tp":"민법상 법인"},{"y":2023,"e":"변리사 1차","qn":3,"i":"변리사2023_60-03-2","t":"유언으로 재단법인을 설립하는 때에는 출연재산(지명채권)은 유언의 효력이 발생한 때로부터 법인에 귀속한 것으로 본다.","ox":"O","m":"②","c":"A","tp":"민법상 법인"},{"y":2023,"e":"변리사 1차","qn":3,"i":"변리사2023_60-03-3","t":"이사의 대표권에 대한 제한은 이를 등기하지 아니하면 그 효력이 없다.","ox":"X","m":"③","c":"A","tp":"민법상 법인"},{"y":2023,"e":"변리사 1차","qn":3,"i":"변리사2023_60-03-4","t":"재단법인의 목적을 달성할 수 없는 때에는 설립자나 이사는 주무관청의 허가를 얻어 설립의 취지를 참작하여 그 목적 기타 정관의 규정을 변경할 수 있다.","ox":"O","m":"④","c":"A","tp":"민법상 법인"},{"y":2023,"e":"변리사 1차","qn":3,"i":"변리사2023_60-03-5","t":"재단법인의 설립자가 그 명칭, 사무소소재지 또는 이사임면의 방법을 정하지 아니하고 사망한 때에는 이해관계인 또는 검사의 청구에 의하여 법원이 이를 정한다.","ox":"O","m":"⑤","c":"A","tp":"민법상 법인"},{"y":2024,"e":"변리사 1차","qn":1,"i":"변리사2024_61-01-1","t":"채권자는 물상보증인이 되려는 자에게 주채무자의 신용상태를 조사해서 고지할 신의칙상 의무를 부담한다.","ox":"X","m":"①","c":"A","tp":"신의성실의 원칙"},{"y":2024,"e":"변리사 1차","qn":1,"i":"변리사2024_61-01-2","t":"병원은 입원환자의 휴대품 등의 도난을 방지함에 필요한 적절한 조치를 강구하여 줄신의칙상 보호의무를 부담한다.","ox":"O","m":"②","c":"A","tp":"신의성실의 원칙"},{"y":2024,"e":"변리사 1차","qn":1,"i":"변리사2024_61-01-3","t":"숙박업자는 투숙고객에게 객실을 사용\u0001수익하게 할 의무를 넘어서 고객의 안전을 배려하여야 할 신의칙상 보호의무를 부담한다.","ox":"O","m":"③","c":"A","tp":"신의성실의 원칙"},{"y":2024,"e":"변리사 1차","qn":1,"i":"변리사2024_61-01-4","t":"사적 자치의 영역을 넘어 공공질서를 위하여 공익적 요구를 선행시켜야 할 경우, 신의칙은 합법성의 원칙을 희생하여서라도 구체적 신뢰보호의 필요성이 인정되는 경우에 한하여 예외적으로 적용된다.","ox":"O","m":"④","c":"A","tp":"신의성실의 원칙"},{"y":2024,"e":"변리사 1차","qn":1,"i":"변리사2024_61-01-5","t":"어떤 법률관계가 신의칙에 위반되는지의 여부는 법원의 직권조사사항이다.","ox":"O","m":"⑤","c":"A","tp":"신의성실의 원칙"},{"y":2024,"e":"변리사 1차","qn":2,"i":"변리사2024_61-02","t":"비법인사단 A의 유일한 이사인 대표이사 甲이 대표자로서의 모든 권한을 乙에게 포괄적으로 위임하여 乙이 실질적으로 A의 대표자로서 행위한 경우에 관한 설명으로 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"비법인사단 A의 유일한 이사인 대표이사 甲이 대표자로서의 모든 권한을 乙에게 포괄적으로 위임하여 乙이 실질적으로 A의 대표자로서 행위한 경우에 관한 설명으로 옳은 것을 모두 고른 것은?","d":"ㄱ. 乙이 포괄적 수임인으로서 행한 대행행위의 효력은 원칙적으로 A에게 미친다.\nㄴ. 乙이 A의 사무집행과 관련한 불법행위로 丙에게 손해를 입힌 경우, 丙은 A에게 법인의 불법행위책임에 따른 손해배상을 청구할 수 있다.\nㄷ. 乙이 자신의 사익을 도모하기 위해 A의 사무를 처리하다가 丁에게 손해를 입힌 경우에는 법인의 불법행위책임에 있어서 직무관련성이 부정된다.\nㄹ. 甲이 乙에게 대표자로서의 권한을 포괄적으로 위임하고 대표이사로서의 직무를 전혀 집행하지 않은 것은 그 자체로 이사의 선관주의의무에 위반하는 행위이다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":3}},{"y":2024,"e":"변리사 1차","qn":3,"i":"변리사2024_61-03","t":"의사무능력자 甲은 자기 소유 X건물에 乙은행 앞으로 저당권을 설정해 주고 금원을 대출받아 곧바로 이를 丙에게 대여하였다. 이에 관한 설명으로 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"의사무능력자 甲은 자기 소유 X건물에 乙은행 앞으로 저당권을 설정해 주고 금원을 대출받아 곧바로 이를 丙에게 대여하였다. 이에 관한 설명으로 옳은 것을 모두 고른 것은?","d":"ㄱ. 甲이 자신의 의사무능력을 이유로 乙과 체결한 저당권설정계약의 무효를 주장하는 것은 특별한 사정이 없는 한 신의칙에 반한다.\nㄴ. 甲은 선의\u0001악의를 불문하고 받은 이익이 현존하는 한도에서 乙에게 그 이 익을 반환할 의무를 부담한다.\nㄷ. 甲이 丙에 대한 부당이득반환채권을 乙에게 양도할 의무와 乙의 저당권등 기말소의무는 동시이행관계에 있다.","o":["ㄱ","ㄴ","ㄱ, ㄷ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":4}},{"y":2026,"e":"변리사 1차","qn":1,"i":"변리사2026_63-01","t":"신의성실의 원칙에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면 판","c":"A","mc":{"s":"신의성실의 원칙에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면 판","d":"례에 따름)\nㄱ. 임대차계약에서 차임불증액의 특약이 있더라도 그 후 특약을 그대로 유지 시키는 것이 신의칙에 반한다고 인정될 정도의 사정변경이 있는 경우에는 임대인의 차임증액청구가 인정될 수 있다.\nㄴ. 회사의 이사가 재직 중에 채무액과 변제기가 특정되어 있는 회사채무에 대하여 보증계약을 체결한 후 사임한 경우, 특별한 사정이 없는 한 이사직 사임이라는 사정변경을 이유로 보증계약을 일방적으로 해지할 수는 없다.\nㄷ. 건물의 소유를 목적으로 한 토지의 임차인이 임대차계약을 체결할 당시 임대인과의 사이에 건물 기타 지상시설 일체를 포기하기로 약정한 경우, 토지 임차인이 위 약정에 위반하여 지상물매수청구권을 행사하는 것은 특별한 사정이 없는 한 신의칙에 반한다.","o":["ㄱ","ㄷ","ㄱ, ㄴ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":3}},{"y":2026,"e":"변리사 1차","qn":2,"i":"변리사2026_63-02-1","t":"부재자로부터 재산의 처분권한을 위임받은 자는 부재자의 생사불명을 이유로 법원에 의해 부재자의 재산관리인으로 선임된 이후에도 부재자의 재산처분에 법원의 허가를 받을 필요가 없다.","ox":"X","m":"①","c":"A","tp":"부재 및 실종"},{"y":2026,"e":"변리사 1차","qn":2,"i":"변리사2026_63-02-2","t":"부재자 재산관리인이 선임결정이 취소되기 전에 법원의 허가를 받고 한 처분행위는 부재자에 대한 실종기간이 만료된 후에 이루어졌더라도 유효하고 그 효과는 부재자의 재산상속인에게 미친다.","ox":"O","m":"②","c":"A","tp":"부재 및 실종"},{"y":2026,"e":"변리사 1차","qn":2,"i":"변리사2026_63-02-3","t":"후순위상속인이라도 부재자에 대한 실종선고의 여부에 따라 상속지분의 차이가 생기는 경우에는 부재자에 대한 실종선고를 청구할 수 있는 이해관계인에 해당한다.","ox":"X","m":"③","c":"A","tp":"부재 및 실종"},{"y":2026,"e":"변리사 1차","qn":2,"i":"변리사2026_63-02-4","t":"실종자를 당사자로 한 판결이 확정된 후에 실종선고가 확정되어 그 사망간주의 시점이 소제기 이전으로 소급하는 경우, 그 판결은 당사자능력이 없는 사망자를 상대로한 판결로서 소급하여 무효이다.","ox":"X","m":"④","c":"A","tp":"부재 및 실종"},{"y":2026,"e":"변리사 1차","qn":2,"i":"변리사2026_63-02-5","t":"실종선고가 이미 확정된 자에 대하여 그 실종선고가 취소됨이 없이 다시 실종선고가 내려진 경우, 새로이 선고된 실종선고를 기초로 상속관계를 판단하여야 한다.","ox":"X","m":"⑤","c":"A","tp":"부재 및 실종"},{"y":2026,"e":"변리사 1차","qn":3,"i":"변리사2026_63-03-1","t":"재단법인의 정관변경은 그 변경방법을 정관에서 정한 때에는 주무관청의 허가를 얻지 않아도 효력이 있다.","ox":"X","m":"①","c":"A","tp":"민법상 법인"},{"y":2026,"e":"변리사 1차","qn":3,"i":"변리사2026_63-03-2","t":"재단법인의 기본재산에 관한 근저당권 설정행위는 특별한 사정이 없는 한 주무관청의 허가를 얻을 필요가 없다.","ox":"O","m":"②","c":"A","tp":"민법상 법인"},{"y":2026,"e":"변리사 1차","qn":3,"i":"변리사2026_63-03-3","t":"법인과 이사의 이익이 상반되는 사항에 관하여 이해관계인 또는 검사의 청구가 있는 경우, 법원은 임시이사를 선임하여야 한다.","ox":"X","m":"③","c":"A","tp":"민법상 법인"},{"y":2026,"e":"변리사 1차","qn":3,"i":"변리사2026_63-03-4","t":"사원총회의 결의로 정관의 규범적 의미와 다른 해석이 표명된 경우, 그 결의에 의한 해석은 법원을 구속한다.","ox":"X","m":"④","c":"A","tp":"민법상 법인"},{"y":2026,"e":"변리사 1차","qn":3,"i":"변리사2026_63-03-5","t":"청산 중인 법인의 청산인은 채권신고기간 내에는 채권자에 대한 변제를 할 수 없으므로 법인은 그 기간 동안 채권자에 대한 지연배상책임을 면한다.","ox":"X","m":"⑤","c":"A","tp":"민법상 법인"}],"2":[{"y":2016,"e":"변리사 1차","qn":4,"i":"변리사2016_53-04-1","t":"주택에 부속하여 지어진 연탄창고는 그 주택에서 떨어져 지어진 것일지라도 그 주택의 종물이다.","ox":"O","m":"①","c":"A","tp":"주물과 종물"},{"y":2016,"e":"변리사 1차","qn":4,"i":"변리사2016_53-04-2","t":"주물과 종물의 관계에 관한 법리는 특별한 사정이 없는 한 권리 상호 간의 관계에도 적용된다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"변리사 1차","qn":4,"i":"변리사2016_53-04-3","t":"물건이 주물의 소유자의 상용에 공여되고 있다면, 주물 그 자체의 효용과 직접 관계가 없는 것도 종물이다.","ox":"X","m":"③","c":"A","tp":"주물과 종물"},{"y":2016,"e":"변리사 1차","qn":4,"i":"변리사2016_53-04-4","t":"주물을 처분할 때에 특약으로 종물을 제외할 수 있고, 종물만을 별도로 처분할 수도 있다.","ox":"O","m":"④","c":"A","tp":"주물과 종물"},{"y":2016,"e":"변리사 1차","qn":4,"i":"변리사2016_53-04-5","t":"저당권의 효력은 특별한 사정이 없는 한 당해 저당부동산의 종물에도 미친다.","ox":"O","m":"⑤","c":"A","tp":"주물과 종물"},{"y":2017,"e":"변리사 1차","qn":4,"i":"변리사2017_54-04-1","t":"어떤 토지가 지적공부상 1필의 토지로 등록되면 특별한 사정이 없는 한, 그 경계는 지적도상의 경계에 의하여 특정된다.","ox":"O","m":"①","c":"A","tp":"물건"},{"y":2017,"e":"변리사 1차","qn":4,"i":"변리사2017_54-04-2","t":"입목등기를 하지 않은 수목은 명인방법을 갖추더라도 독립된 물건이 될 수 없다.","ox":"X","m":"②","c":"A"},{"y":2017,"e":"변리사 1차","qn":4,"i":"변리사2017_54-04-3","t":"주물 소유자의 사용에 공여되고 있는 물건은 주물 자체의 효용과 관계없는 물건이라도 종물이 된다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"변리사 1차","qn":4,"i":"변리사2017_54-04-4","t":"성숙한 농작물은 명인방법을 갖추어야 경작자의 소유가 된다.","ox":"X","m":"④","c":"A","tp":"물건"},{"y":2017,"e":"변리사 1차","qn":4,"i":"변리사2017_54-04-5","t":"토지등기부에 분필등기가 되면 「공간정보의 구축 및 관리 등에 관한 법률」이 정하는 바에 따른 분할절차를 밟지 않아도 분필의 효과가 발생한다.","ox":"X","m":"⑤","c":"A","tp":"물건"},{"y":2018,"e":"변리사 1차","qn":12,"i":"변리사2018_55-12-1","t":"특정물과 불특정물의 구별은 당사자의 의사에 따른 주관적인 구별이다.","ox":"O","m":"①","c":"A","tp":"물건"},{"y":2018,"e":"변리사 1차","qn":12,"i":"변리사2018_55-12-2","t":"종물은 주물의 일부이거나 구성부분이어야 한다.","ox":"X","m":"②","c":"A","tp":"물건"},{"y":2018,"e":"변리사 1차","qn":12,"i":"변리사2018_55-12-3","t":"관리할 수 있는 전기는 동산이다.","ox":"O","m":"③","c":"A","tp":"물건"},{"y":2018,"e":"변리사 1차","qn":12,"i":"변리사2018_55-12-4","t":"건물을 사용함으로써 얻는 이득은 그 건물의 과실에 준하는 것이다.","ox":"O","m":"④","c":"A","tp":"물건"},{"y":2018,"e":"변리사 1차","qn":12,"i":"변리사2018_55-12-5","t":"수확되지 아니한 성숙한 쪽파와 같은 농작물 매매에 있어서 매수인이 그 소유권을 취득하기 위해서는 명인방법을 갖추어야 한다.","ox":"O","m":"⑤","c":"A","tp":"물건"},{"y":2019,"e":"변리사 1차","qn":4,"i":"변리사2019_56-04-1","t":"소유권이전의 대가, 노동의 대가는 법정과실이다.","ox":"X","m":"①","c":"A","tp":"원물과 과실"},{"y":2019,"e":"변리사 1차","qn":4,"i":"변리사2019_56-04-2","t":"물건의 용법에 의하여 수취하는 산출물은 천연과실이다.","ox":"O","m":"②","c":"A","tp":"원물과 과실"},{"y":2019,"e":"변리사 1차","qn":4,"i":"변리사2019_56-04-3","t":"천연과실은 그 원물로부터 분리하는 때에 이를 수취할 권리자에게 속한다.","ox":"O","m":"③","c":"A","tp":"원물과 과실"},{"y":2019,"e":"변리사 1차","qn":4,"i":"변리사2019_56-04-4","t":"미분리의 과실은 독립한 물건이 아니지만, 명인방법을 갖춘 경우에는 타인 소유권의 객체가 될 수 있다.","ox":"O","m":"④","c":"A","tp":"원물과 과실"},{"y":2019,"e":"변리사 1차","qn":4,"i":"변리사2019_56-04-5","t":"법정과실은 수취할 권리의 존속기간일수의 비율로 취득할 수 있는 것이지만, 당사자가 그와 다르게 약정할 수도 있다.","ox":"O","m":"⑤","c":"A","tp":"원물과 과실"},{"y":2021,"e":"변리사 1차","qn":5,"i":"변리사2021_58-05-1","t":"부동산에 부속된 동산을 분리하면 그 동산의 경제적 가치가 없는 경우에는 타인이 권원에 의하여 동산을 부속시킨 경우라도 그 동산은 부동산소유자에게 귀속된다.","ox":"O","m":"①","c":"A","tp":"물건"},{"y":2021,"e":"변리사 1차","qn":5,"i":"변리사2021_58-05-2","t":"집합물에 대한 양도담보권자가 점유개정의 방법으로 양도담보권설정계약 당시 존재하는 집합물의 점유를 취득한 후 양도담보권설정자가 자기 소유의 집합물을 이루는 물건을 반입한 경우, 나중에 반입된 물건에는 양도담보권의 효력이 미치지 않는다.","ox":"X","m":"②","c":"A"},{"y":2021,"e":"변리사 1차","qn":5,"i":"변리사2021_58-05-3","t":"적법한 경작권 없이 타인의 토지를 경작하였다면 그 경작한 입도(立稻)가 성숙한 경우에도 경작자는 그 입도의 소유권을 갖지 못한다.","ox":"X","m":"③","c":"A","tp":"물건"},{"y":2021,"e":"변리사 1차","qn":5,"i":"변리사2021_58-05-4","t":"종물은 주물의 처분에 따르므로, 당사자의 특약으로 종물만을 별도로 처분할 수 없다.","ox":"X","m":"④","c":"A","tp":"물건"},{"y":2021,"e":"변리사 1차","qn":5,"i":"변리사2021_58-05-5","t":"입목에 관한 법률에 의하여 소유권보존등기가 마쳐진 입목은 토지와 분리하여 양도될 수 있으나, 저당권의 객체는 될 수 없다.","ox":"X","m":"⑤","c":"A","tp":"물건"},{"y":2023,"e":"변리사 1차","qn":4,"i":"변리사2023_60-04","t":"동일소유자에게 속하는 다음 물건 중 주물과 종물의 관계로 보기 어려운 것은?","c":"A","mc":{"s":"동일소유자에게 속하는 다음 물건 중 주물과 종물의 관계로 보기 어려운 것은?","d":"","o":["배와 노","자물쇠와 열쇠","주유소건물과 주유기","횟집과 수족관","주유소부지와 그 지하에 매설된 유류저장탱크"],"a":5}},{"y":2024,"e":"변리사 1차","qn":4,"i":"변리사2024_61-04-1","t":"독립한 물건이라도 부동산은 종물이 될 수 없다.","ox":"X","m":"①","c":"A","tp":"주물과 종물"},{"y":2024,"e":"변리사 1차","qn":4,"i":"변리사2024_61-04-2","t":"주물의 점유로 인한 시효취득의 효력은 점유하지 않은 종물에도 미친다.","ox":"X","m":"②","c":"A","tp":"주물과 종물"},{"y":2024,"e":"변리사 1차","qn":4,"i":"변리사2024_61-04-3","t":"주물에 대한 압류의 효력은 원칙적으로 종물에 미치지 않는다.","ox":"X","m":"③","c":"A","tp":"주물과 종물"},{"y":2024,"e":"변리사 1차","qn":4,"i":"변리사2024_61-04-4","t":"주물 그 자체의 효용과 직접 관계가 없더라도 주물의 소유자의 상용에 공여되고 있는 물건은 종물이다.","ox":"X","m":"④","c":"A","tp":"주물과 종물"},{"y":2024,"e":"변리사 1차","qn":4,"i":"변리사2024_61-04-5","t":"원본채권이 양도되는 경우, 특별한 의사표시가 없으면 이미 변제기에 도달한 이자채 권은 함께 양도되지 않는다.","ox":"O","m":"⑤","c":"A","tp":"주물과 종물"}],"3":[{"y":2016,"e":"변리사 1차","qn":5,"i":"변리사2016_53-05-1","t":"계약체결 당시 불공정한 법률행위가 아니더라도 사후에 외부 환경의 급격한 변화로 계약당사자 일방에게 큰 손실이, 상대방에게는 그에 상응하는 큰 이익이 발생할 수 있는 계약은 불공정한 계약에 해당한다.","ox":"X","m":"①","c":"A"},{"y":2016,"e":"변리사 1차","qn":5,"i":"변리사2016_53-05-2","t":"폭리행위의 악의가 없거나 급부와 반대급부 사이에 현저한 불균형이 존재하지 않으면 불공정한 법률행위가 인정되지 않는다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"변리사 1차","qn":5,"i":"변리사2016_53-05-3","t":"대리인이 매매계약을 체결한 경우, 무경험은 그 대리인을 기준으로 판단하고 궁박 상태에 있었는지의 여부는 본인의 입장에서 판단해야 한다.","ox":"O","m":"③","c":"A","tp":"불공정한 법률행위"},{"y":2016,"e":"변리사 1차","qn":5,"i":"변리사2016_53-05-4","t":"매매계약이 약정된 매매대금의 과다로 불공정한 법률행위에 해당하여 무효인 경우에 무효행위의 전환에 관한 민법 제138조가 적용될 수 있다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"변리사 1차","qn":5,"i":"변리사2016_53-05-5","t":"아무런 대가관계나 부담 없이 당사자 일방이 상대방에게 일방적인 급부를 하는 법률행위는 불공정한 법률행위가 아니다.","ox":"O","m":"⑤","c":"A"},{"y":2016,"e":"변리사 1차","qn":6,"i":"변리사2016_53-06-1","t":"사기에 의한 의사표시에는 의사와 표시의 불일치가 있을 수 없고, 단지 의사표시의 동기에 착오가 있을 뿐이다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"변리사 1차","qn":6,"i":"변리사2016_53-06-2","t":"상대방의 대리인 등 상대방과 동일시할 수 있는 자의 사기는 제3자의 사기에 해당하지 않는다.","ox":"O","m":"②","c":"A","tp":"사기에 의한 의사표시"},{"y":2016,"e":"변리사 1차","qn":6,"i":"변리사2016_53-06-3","t":"상품의 선전\u0001광고에 있어서 중요한 사항에 관하여 구체적 사실을 신의성실의 의무에 비추어 비난받을 정도의 방법으로 허위로 고지하는 것은 기망행위에 해당한다.","ox":"O","m":"③","c":"A","tp":"사기에 의한 의사표시"},{"y":2016,"e":"변리사 1차","qn":6,"i":"변리사2016_53-06-4","t":"사기에 의한 법률행위가 동시에 불법행위를 구성하는 때에는, 취소의 효과로 생기는 부당이득반환청구권과 불법행위로 인한 손해배상청구권은 경합하여 병존한다.","ox":"O","m":"④","c":"A","tp":"사기에 의한 의사표시"},{"y":2016,"e":"변리사 1차","qn":6,"i":"변리사2016_53-06-5","t":"사기에 의한 의사표시의 취소로써 대항하지 못하는 선의의 제3자란 취소 전부터 취소를 주장하는 자와 양립되지 않는 법률관계를 가졌던 제3자에 한한다.","ox":"X","m":"⑤","c":"A"},{"y":2016,"e":"변리사 1차","qn":7,"i":"변리사2016_53-07","t":"의사표시의 효력발생에 관한 설명으로 옳지 않은 것은? (다툼이 있으면 판례에","c":"A","mc":{"s":"의사표시의 효력발생에 관한 설명으로 옳지 않은 것은? (다툼이 있으면 판례에","d":"따름)","o":["준법률행위의 도달은 의사표시와 마찬가지로 사회관념상 상대방이 준법률행위의 내용을 알 수 있는 객관적 상태에 놓여졌을 때를 말한다.","의사표시의 상대방이 정당한 사유 없이 통지의 수령을 거절한 경우 상대방이 그 통지의 내용을 알 수 있는 객관적 상태에 놓여 있는 때에 의사표시의 효력이 발생한다.","채권양도의 통지는 채무자의 주소 등에 해당하지 아니하는 장소에서라도 채무자가 사회통념상 그 통지의 내용을 알 수 있는 객관적 상태에 놓여졌을 때에 그 효력이 발생한다.","보통우편의 방법으로 의사표시를 통지한 경우에도 발송되었다는 사실만 증명되면, 상당한 기간 내에 도달한 것으로 추정된다.","표의자의 의사표시가 상대방에게 도달하기 전에 그 표의자가 사망한 경우, 상속인은 의사표시의 도달 전에 이를 철회할 수 있다."],"a":4}},{"y":2016,"e":"변리사 1차","qn":8,"i":"변리사2016_53-08-1","t":"비법인사단인 교회의 대표자가 교인총회의 결의를 거치지 않고 총유물인 교회재산을 처분한 행위에 대하여는 민법 제126조(권한을 넘은 표현대리)를 준용할 수 있다.","ox":"X","m":"①","c":"A"},{"y":2016,"e":"변리사 1차","qn":8,"i":"변리사2016_53-08-2","t":"민법 제129조(대리권소멸후의 표현대리)에 의하여 인정되는 표현대리를 기본대리권으로 하여 그 권한을 넘는 표현대리가 성립할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"변리사 1차","qn":8,"i":"변리사2016_53-08-3","t":"민법 제125조(대리권수여의 표시에 의한 표현대리)의 표현대리가 인정되려면, 대리행위의 상대방이 대리인으로 행위한 사람에게 실제로는 대리권이 없다는 점에 대하여 선의일 뿐만 아니라 무과실이어야 한다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"변리사 1차","qn":8,"i":"변리사2016_53-08-4","t":"민법 제126조의 표현대리가 인정되려면, 대리행위의 상대방이 대리행위가 대리권의 범위 내에 있다고 믿고 그와 같이 믿는 데 정당한 이유가 있을 것을 요한다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"변리사 1차","qn":8,"i":"변리사2016_53-08-5","t":"민법 제125조의 표현대리는 어떤 자가 본인을 대리하여 제3자와 법률행위를 함에 있어 본인이 그 자에게 대리권을 수여하였다는 표시를 제3자에게 한 경우에 성립한다.","ox":"O","m":"⑤","c":"A"},{"y":2016,"e":"변리사 1차","qn":9,"i":"변리사2016_53-09","t":"법률행위의 무효와 취소에 관한 설명으로 옳지 않은 것은? (다툼이 있으면 판례에","c":"A","mc":{"s":"법률행위의 무효와 취소에 관한 설명으로 옳지 않은 것은? (다툼이 있으면 판례에","d":"따름)","o":["취소의 의사표시란 반드시 명시적이어야 하는 것은 아니고, 취소자가 자신의 법률행위의 효력을 처음부터 배제하려고 한다는 의사가 드러나면 된다.","매매계약 체결 당시 일정한 기간 안에 토지거래허가를 받기로 약정하였다고 하더라도, 특별한 사정이 없는 한 그 약정기간이 경과하였다는 사정만으로 곧바로 매매계약이 확정적으로 무효가 된다고 할 수 없다.","법률행위의 취소를 당연한 전제로 한 소송상의 이행청구나 이행거절 가운데는 취소의 의사표시가 포함되어 있다.","무효인 계약의 성립에 기초하여 외견상 있는 것처럼 보이는 의무를 위반한 계약 당사자를 상대로 하여 채무불이행을 이유로 하는 손해배상을 청구할 수 있다.","징계해임이 정당한 사유나 절차의 흠결로 인하여 무효인 경우 직권해임으로서 정당한 사유 및 절차적 요건을 갖추었다 하더라도 직권해임으로서의 효력을 발휘할 수 없다."],"a":4}},{"y":2016,"e":"변리사 1차","qn":10,"i":"변리사2016_53-10-1","t":"복대리인은 대리인의 보조자 내지 대리인의 대리인이다.","ox":"X","m":"①","c":"A"},{"y":2016,"e":"변리사 1차","qn":10,"i":"변리사2016_53-10-2","t":"임의대리인은 원칙적으로 복임권을 갖지 못한다.","ox":"O","m":"②","c":"A","tp":"복대리"},{"y":2016,"e":"변리사 1차","qn":10,"i":"변리사2016_53-10-3","t":"법정대리인은 재산상의 법률행위에 대하여 복임권이 있다.","ox":"O","m":"③","c":"A","tp":"복대리"},{"y":2016,"e":"변리사 1차","qn":10,"i":"변리사2016_53-10-4","t":"복대리인은 행위능력자임을 요하지 아니한다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"변리사 1차","qn":10,"i":"변리사2016_53-10-5","t":"甲이 채권자를 특정하지 않은 채 부동산을 담보로 제공하면서 금원을 차용해 줄것을 乙에게 위임하였다면, 甲의 의사에는 ‘복대리인 선임에 관한 승낙’이 포함되어 있다.","ox":"O","m":"⑤","c":"A"},{"y":2016,"e":"변리사 1차","qn":11,"i":"변리사2016_53-11-1","t":"불확정기한부 법률행위는 특별한 사정이 없는 한 그 법률행위에 따른 채무가 이미 발생한 것으로 본다.","ox":"O","m":"①","c":"A","tp":"조건과 기한"},{"y":2016,"e":"변리사 1차","qn":11,"i":"변리사2016_53-11-2","t":"기성조건이 정지조건이면 조건 없는 법률행위가 된다.","ox":"O","m":"②","c":"A","tp":"조건과 기한"},{"y":2016,"e":"변리사 1차","qn":11,"i":"변리사2016_53-11-3","t":"조건부 법률행위에서 조건은 외부에 표시되지 않으면 그 법률행위의 동기에 불과하다.","ox":"O","m":"③","c":"A","tp":"조건과 기한"},{"y":2016,"e":"변리사 1차","qn":11,"i":"변리사2016_53-11-4","t":"조건을 붙이는 것이 허용되지 않는 법률행위에 조건을 붙인 경우 그 법률행위는 조건 없는 법률행위로서 유효하다.","ox":"X","m":"④","c":"A","tp":"조건과 기한"},{"y":2016,"e":"변리사 1차","qn":11,"i":"변리사2016_53-11-5","t":"부관이 붙은 법률행위에 있어서 부관에 표시된 사실이 발생하지 않으면 채무를 이행하지 않아도 된다고 보는 것이 상당한 경우 그 부관은 조건으로 보아야 한다.","ox":"O","m":"⑤","c":"A","tp":"조건과 기한"},{"y":2017,"e":"변리사 1차","qn":5,"i":"변리사2017_54-05","t":"민법 제103조의 반사회적 법률행위에 해당하지 않는 것을 모두 고른 것은?","c":"A","mc":{"s":"민법 제103조의 반사회적 법률행위에 해당하지 않는 것을 모두 고른 것은?","d":"(다툼이 있으면 판례에 따름)\nㄱ. 강제집행을 면할 목적으로 부동산에 허위의 근저당권을 설정하는 행위ㄴ. 의무의 강제에 의하여 얻어지는 채권자의 이익에 비하여 과도하게 중한 위약벌의 약정ㄷ. 뇌물로 받은 금전을 소극적으로 은닉하기 위하여 이를 임치하는 약정ㄹ. 해외연수 후 그 비용과 관련하여 일정기간 동안 소속회사에서 근무해야 한다는 사규나 약정ㅁ. 공무원의 직무에 관한 사항에 대하여 특별한 청탁을 하게 하고, 그에 대한 보수로 금전을 지급하기로 하는 약정","o":["ㄱ, ㄴ, ㄷ","ㄱ, ㄷ, ㄹ","ㄴ, ㄹ, ㅁ","ㄷ, ㄹ, ㅁ","ㄱ, ㄴ, ㄷ, ㅁ"],"a":2}},{"y":2017,"e":"변리사 1차","qn":6,"i":"변리사2017_54-06","t":"사기나 강박에 의한 의사표시에 관한 설명으로 옳지 않은 것은? (다툼이","c":"A","mc":{"s":"사기나 강박에 의한 의사표시에 관한 설명으로 옳지 않은 것은? (다툼이","d":"있으면 판례에 따름)","o":["민법상의 법률행위에 관한 규정은 특별한 사정이 없는 한 소송행위에는 적용이 없으므로, 소송행위가 강박에 의하여 이루어지더라도 이를 이유로 취소할 수는 없다.","매도인의 기망에 의하여 타인 소유의 물건을 매도인의 것으로 알고 매수한 자는 만일 그것이 타인의 물건인 줄 알았더라면 매수하지 아니하였을 사정이 있는 경우, 매도인의 사기를 이유로 매매계약을 취소할 수 있다.","상대방의 사기에 속아 신원보증서류에 서명날인한다는 착각에 빠진 상태로 연대 보증서면에 서명날인한 경우, 이러한 표시상의 착오에서는 착오 이외에 사기를 이유로도 연대보증계약을 취소할 수 있다.","은행 출장소장은 은행 또는 은행과 동일시할 수 있는 자이므로, 그의 사기에 속아 은행과 대출계약을 체결한 사람은 은행이 그 사기사실을 알았거나 알 수 있었을 경우에 한하여 대출계약을 취소할 수 있는 것은 아니다.","강박에 의한 법률행위가 동시에 불법행위를 구성하는 경우, 그 취소의 효과로 생기는 부당이득반환청구권과 불법행위로 인한 손해배상청구권은 경합하지만 중 첩적으로 행사할 수는 없다."],"a":3}},{"y":2017,"e":"변리사 1차","qn":7,"i":"변리사2017_54-07-2","t":"특별한 사정이 없는 한, 乙은 丙에게 약정된 매매대금 지급기일을 연기해 줄 권한은 없다.","ox":"O","m":"②","c":"A","tp":"甲은 乙에게 자기 소유의 아파트에 대하여 매매계약의 체결"},{"y":2017,"e":"변리사 1차","qn":7,"i":"변리사2017_54-07-3","t":"丙이 甲에 대하여 소유권이전등기를 청구하는 경우, 乙의 대리권 존재 사실에 대한 증명책임은 丙이 진다.","ox":"O","m":"③","c":"A","tp":"甲은 乙에게 자기 소유의 아파트에 대하여 매매계약의 체결"},{"y":2017,"e":"변리사 1차","qn":7,"i":"변리사2017_54-07-4","t":"만약 乙이 甲을 위한 것임을 표시하지 않고 매매계약을 체결하였는데 乙이 甲의 대리인임을 丙이 알았다면, 그 계약의 효력은 甲에게 미친다.","ox":"O","m":"④","c":"A","tp":"甲은 乙에게 자기 소유의 아파트에 대하여 매매계약의 체결"},{"y":2017,"e":"변리사 1차","qn":7,"i":"변리사2017_54-07-5","t":"乙이 丙으로부터 받은 매매대금을 유용할 배임적 의도를 갖고 있었고 丙이 이를 알았다면, 그 한도에서 乙은 무권대리가 된다.","ox":"X","m":"⑤","c":"A","tp":"甲은 乙에게 자기 소유의 아파트에 대하여 매매계약의 체결"},{"y":2017,"e":"변리사 1차","qn":8,"i":"변리사2017_54-08-2","t":"甲은 乙의 처분행위와 사문서위조행위를 불문에 붙이기로 합의하는 등 묵시적인 방법으로도 매매계약을 추인할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"변리사 1차","qn":8,"i":"변리사2017_54-08-3","t":"乙이 甲을 단독으로 상속하여 X토지의 소유자가 되면, 乙은 본인의 지위에서 매매계약의 추인을 거절할 수 있다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"변리사 1차","qn":8,"i":"변리사2017_54-08-4","t":"丙이 매매계약 당시 乙이 무권대리인임을 알지 못하였다면, 丙은 본인의 추인이 있을 때까지 乙을 상대로 매수의 의사표시를 철회할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"변리사 1차","qn":8,"i":"변리사2017_54-08-5","t":"丙이 상당한 기간을 정하여 매매계약의 추인 여부에 대한 확답을 최고하였으나 甲이 그 기간 내에 확답을 발하지 않으면 추인을 거절한 것으로 본다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"변리사 1차","qn":9,"i":"변리사2017_54-09","t":"민법상의 불공정한 법률행위에 관한 설명으로 옳지 않은 것은? (다툼이 있으면","c":"A","mc":{"s":"민법상의 불공정한 법률행위에 관한 설명으로 옳지 않은 것은? (다툼이 있으면","d":"판례에 따름)","o":["궁박, 경솔, 무경험은 모두 구비되어야 하는 요건이 아니라 그 중 일부만 갖추어 져도 충분하다.","궁박은 경제적인 것에 한정하지 않으며 정신적, 신체적인 원인에 기인하는 것을 포함한다.","무경험은 생활체험의 부족을 의미하는 것으로, 거래일반에 대한 경험부족이 아니라 특정영역에 있어서의 경험부족을 의미한다.","당사자 중 일방이 상대방의 궁박, 경솔 또는 무경험을 알면서 이를 이용하려는 의사가 있어야 한다.","불공정한 법률행위로서 무효인 경우, 추인에 의하여 무효인 법률행위가 유효로될 수는 없지만, 무효행위의 전환에 관한 민법 제138조는 적용될 수 있다."],"a":3}},{"y":2017,"e":"변리사 1차","qn":10,"i":"변리사2017_54-10","t":"민법상 조건부 법률행위에 관한 설명으로 옳지 않은 것은? (다툼이 있으면","c":"A","mc":{"s":"민법상 조건부 법률행위에 관한 설명으로 옳지 않은 것은? (다툼이 있으면","d":"판례에 따름)","o":["정지조건부 채권양도에 있어서 정지조건이 성취되었다는 사실은 채권양도의 효력을 부정하는 자가 증명해야 한다.","어떤 법률행위에 정지조건이 붙어 있는지 여부는 그 조건의 존재를 주장하는 자가 증명해야 한다.","조건이 법률행위 당시에 이미 성취할 수 없는 것인 경우에 그 조건이 해제조건이면 조건 없는 법률행위가 된다.","조건성취의 효력발생시기에 관한 민법의 규정은 임의규정이다.","조건부 법률행위에 있어서 조건의 내용 자체가 불법으로 무효인 경우, 특별한 사정이 없는 한 그 조건만을 분리하여 일부만 무효로 할 수는 없다."],"a":1}},{"y":2018,"e":"변리사 1차","qn":2,"i":"변리사2018_55-02","t":"법률행위의 무효와 취소에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에","c":"A","mc":{"s":"법률행위의 무효와 취소에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에","d":"따름)","o":["법률행위가 무효임을 알고 당사자가 추인한 때에는 새로운 법률행위로 추정한다.","취소할 수 있는 법률행위의 상대방이 확정된 경우에는 그 취소는 그 상대방에 대한 의사표시로 하여야 한다.","취소권은 법률행위를 추인할 수 있는 날로부터 5년 뒤에도 소멸하지 않는다.","폭리행위는 그 무효원인이 해소되지 않았더라도 당사자의 추인이 있으면 유효로될 수 있다.","미성년을 이유로 취소할 수 있다는 사실을 알고 법정대리인의 동의 없이 법률행위를 한 미성년자가 그 법률행위를 적법하게 취소한 경우, 미성년자는 그 행위로 받은 이익에 이자를 붙여서 반환하여야 한다."],"a":2}},{"y":2018,"e":"변리사 1차","qn":5,"i":"변리사2018_55-05","t":"반사회질서행위의 효과에 관한 설명으로 옳지 않은 것은? (다툼이 있으면 판","c":"A","mc":{"s":"반사회질서행위의 효과에 관한 설명으로 옳지 않은 것은? (다툼이 있으면 판","d":"례에 따름)","o":["도박자금에 제공할 목적으로 금전을 대차한 때에 그 대차계약으로 인한 금전의 반환을 청구할 수 없다.","반사회질서행위의 무효는 이를 주장할 이익이 있는 자라면 누구든지 그 무효를 주장할 수 있다.","법률행위의 성립과정에 강박이라는 불법적 방법이 사용된 데에 불과한 때에는 반사회질서행위로서 무효라고 할 수는 없다.","본처가 남편의 과거 부첩(夫妾)관계를 용서한 때에는 그것이 손해배상청구권의 포기라고 해석되는 한 그대로의 법적 효력이 인정될 수 있다.","법률행위가 반사회질서행위로 무효인지 여부는 그 효력이 발생한 때를 기준으로 판단하여야 한다."],"a":5}},{"y":2018,"e":"변리사 1차","qn":6,"i":"변리사2018_55-06","t":"甲의 대리인 乙은 계약의 체결과 취소 등 포괄적인 대리권을 수여받아 甲의 대리인으로서 丙과 계약을 체결하였다. 이에 관한 설명으로 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"甲의 대리인 乙은 계약의 체결과 취소 등 포괄적인 대리권을 수여받아 甲의 대리인으로서 丙과 계약을 체결하였다. 이에 관한 설명으로 옳은 것을 모두 고른 것은?","d":"ㄱ. 乙이 丙을 기망한 경우, 丙은 의사표시를 취소할 수 있다.\nㄴ. 丙이 乙을 기망한 경우, 甲은 의사표시를 취소할 수 있다.\nㄷ. 丙이 乙을 기망한 경우, 乙은 의사표시를 취소할 수 있다.","o":["ㄱ","ㄴ","ㄱ, ㄷ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":5}},{"y":2018,"e":"변리사 1차","qn":11,"i":"변리사2018_55-11-1","t":"복대리인은 대리인의 대리인이다.","ox":"X","m":"①","c":"A"},{"y":2018,"e":"변리사 1차","qn":11,"i":"변리사2018_55-11-2","t":"임의대리인은 그 책임으로 언제든지 복대리인을 선임할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2018,"e":"변리사 1차","qn":11,"i":"변리사2018_55-11-3","t":"대리인이 대리권 소멸 후 선임한 복대리인과 상대방 사이의 법률행위에도 상대방이 대리권 소멸 사실을 알지 못하여 복대리인에게 적법한 대리권이 있는 것으로 믿었고 그와 같이 믿은 데 과실이 없다면, 대리권소멸 후의 표현대리(민법 제 129조)가 성립할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"변리사 1차","qn":11,"i":"변리사2018_55-11-4","t":"법정대리인이 부득이한 사유로 복대리인을 선임한 경우에는 그 부적임 또는 불성실함을 알고 본인에 대한 통지나 그 해임을 태만한 때가 아니면 책임이 없다.","ox":"X","m":"④","c":"A"},{"y":2018,"e":"변리사 1차","qn":11,"i":"변리사2018_55-11-5","t":"대리인의 사망으로 대리권이 소멸한 경우에도 복대리권은 소멸하지 않는다.","ox":"X","m":"⑤","c":"A"},{"y":2019,"e":"변리사 1차","qn":5,"i":"변리사2019_56-05-1","t":"착오가 의사표시자의 중대한 과실로 인한 경우에는 상대방이 그 착오를 알고 이를 이용하였더라도 의사표시자는 착오를 이유로 의사표시를 취소할 수 없다.","ox":"X","m":"①","c":"A","tp":"법률행위의 무효와 취소"},{"y":2019,"e":"변리사 1차","qn":5,"i":"변리사2019_56-05-2","t":"통정허위표시의 무효는 선의의 제3자에게 대항하지 못하며, 이때 제3자는 선의이면 족하고 무과실을 요하지 않는다.","ox":"O","m":"②","c":"A","tp":"법률행위의 무효와 취소"},{"y":2019,"e":"변리사 1차","qn":5,"i":"변리사2019_56-05-3","t":"무효인 가등기를 유효한 등기로 전용할 것을 약정하였다면, 무효행위의 전환이론에 따라 무효인 가등기는 그 등기시로 소급하여 유효로 전환된다.","ox":"X","m":"③","c":"A","tp":"법률행위의 무효와 취소"},{"y":2019,"e":"변리사 1차","qn":5,"i":"변리사2019_56-05-4","t":"취소권을 행사할 수 있는 기간의 경과 여부는 당사자가 주장하여야 하므로, 법원이 이를 당연히 조사하고 고려해야 할 사항은 아니다.","ox":"X","m":"④","c":"A","tp":"법률행위의 무효와 취소"},{"y":2019,"e":"변리사 1차","qn":5,"i":"변리사2019_56-05-5","t":"유동적 무효인 토지거래계약이 확정적으로 무효가 된 경우, 이에 대해 귀책사유가 있는 자는 계약의 무효를 주장할 수 없다.","ox":"X","m":"⑤","c":"A","tp":"법률행위의 무효와 취소"},{"y":2019,"e":"변리사 1차","qn":6,"i":"변리사2019_56-06-1","t":"공무원 甲이 사직의 의사표시를 하는 것과 같은 사인의 공법행위에도 진의 아닌 의사표시에 관한 민법 규정이 적용된다.","ox":"X","m":"①","c":"A"},{"y":2019,"e":"변리사 1차","qn":6,"i":"변리사2019_56-06-2","t":"甲이 상대방 乙에게 진의 아닌 의사표시의 무효를 주장하는 경우, 乙의 악의나 과실 유무는 甲이 증명해야 한다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"변리사 1차","qn":6,"i":"변리사2019_56-06-3","t":"채무자 甲의 법률행위가 통정허위표시로서 무효인 경우에도 그 법률행위가 채권자취소권의 요건을 갖추었다면, 甲의 채권자 乙은 채권자취소권을 행사할 수 있다.","ox":"O","m":"③","c":"A","tp":"의사표시"},{"y":2019,"e":"변리사 1차","qn":6,"i":"변리사2019_56-06-4","t":"통정허위표시의 제3자가 악의라도 그 전득자가 통정허위표시에 대하여 선의인 때에는 전득자에게 허위표시의 무효를 주장할 수 없다.","ox":"O","m":"④","c":"A","tp":"의사표시"},{"y":2019,"e":"변리사 1차","qn":6,"i":"변리사2019_56-06-5","t":"의사표시의 상대방이 의사표시를 받은 때에 제한능력자인 경우에는 의사표시자는 원칙적으로 그 의사표시로써 대항할 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"변리사 1차","qn":7,"i":"변리사2019_56-07","t":"착오나 사기에 의한 의사표시에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에","c":"A","mc":{"s":"착오나 사기에 의한 의사표시에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에","d":"따름)","o":["동기의 착오가 상대방에 의하여 제공되거나 유발된 경우에는 착오를 이유로 취소할 수 없다.","법률행위 내용의 중요부분에 대한 착오를 판단할 때, 의사표시자의 경제적인 불이익 여부는 문제되지 않는다.","착오를 이유로 한 취소권은 추인할 수 있는 날로부터 3년 내에, 법률행위를 한 날로부터 10년 내에 행사하여야 한다.","법률행위가 사기에 의한 것으로서 취소되는 경우, 그 법률행위가 동시에 불법행위를 구성하는 때에는 취소의 효과로 생기는 부당이득반환청구권과 불법행위로 인한 손해배상청구권을 중첩적으로 행사할 수 있다.","제3자의 사기로 인하여 계약을 체결한 경우, 그 제3자에 대하여 불법행위로 인한 손해배상을 청구하기 위해서는 먼저 그 계약을 취소해야 한다."],"a":3}},{"y":2019,"e":"변리사 1차","qn":9,"i":"변리사2019_56-09-1","t":"乙이 무권대리인임을 알았던 丙은 甲에게 乙의 대리행위에 대한 추인 여부의 확답을 최고할 수 없다.","ox":"X","m":"①","c":"A","tp":"무권대리인 乙은 자신을 甲의 대리인이라고 하면서 丙과 매매계약을 체결하였다. 이"},{"y":2019,"e":"변리사 1차","qn":9,"i":"변리사2019_56-09-2","t":"丙이 매매계약을 적법하게 철회하였다면 乙의 무권대리행위는 확정적으로 무효가 되어 그 후에는 甲이 매매계약을 추인할 수 없다.","ox":"O","m":"②","c":"A","tp":"무권대리인 乙은 자신을 甲의 대리인이라고 하면서 丙과 매매계약을 체결하였다. 이"},{"y":2019,"e":"변리사 1차","qn":9,"i":"변리사2019_56-09-3","t":"甲이 乙에 대하여 매매계약에 관한 추인의 의사표시를 한 경우, 이러한 추인의 의사표시를 丙이 알지 못하였다면 丙은 철회할 수 있다.","ox":"O","m":"③","c":"A","tp":"무권대리인 乙은 자신을 甲의 대리인이라고 하면서 丙과 매매계약을 체결하였다. 이"},{"y":2019,"e":"변리사 1차","qn":9,"i":"변리사2019_56-09-4","t":"丙이 매매계약을 철회하는 경우, 철회의 효과를 다투는 甲은 丙이 乙에게 대리권이 없다는 사실에 관하여 악의임을 증명할 책임이 있다.","ox":"O","m":"④","c":"A","tp":"무권대리인 乙은 자신을 甲의 대리인이라고 하면서 丙과 매매계약을 체결하였다. 이"},{"y":2019,"e":"변리사 1차","qn":9,"i":"변리사2019_56-09-5","t":"乙이 甲을 단독상속한 경우, 乙은 甲의 지위에서 무권대리임을 이유로 매매계약의 무효를 주장하는 것은 허용되지 않는다.","ox":"O","m":"⑤","c":"A","tp":"무권대리인 乙은 자신을 甲의 대리인이라고 하면서 丙과 매매계약을 체결하였다. 이"},{"y":2019,"e":"변리사 1차","qn":11,"i":"변리사2019_56-11-2","t":"乙의 대리행위가 무권대리라는 이유로 甲이 무효를 주장하는 경우, 乙의 대리행위가 권한을 넘은 표현대리행위라는 주장 및 증명책임은 丙에게 있다.","ox":"O","m":"②","c":"A","tp":"乙은 甲의 대리인으로서 甲을 위하여 丙과 계약을 체결하였다. 이"},{"y":2019,"e":"변리사 1차","qn":11,"i":"변리사2019_56-11-3","t":"매매계약의 체결에 관한 권한을 수여받은 乙이 甲을 대리하여 매매계약을 체결한 경우, 乙은 특별한 사정이 없는 한 甲을 대리하여 매매계약의 해제 등 일체의 처분권을 행사할 수 있다.","ox":"X","m":"③","c":"A","tp":"乙은 甲의 대리인으로서 甲을 위하여 丙과 계약을 체결하였다. 이"},{"y":2019,"e":"변리사 1차","qn":11,"i":"변리사2019_56-11-4","t":"甲으로부터 아파트에 관한 일체의 관리권한을 위임받아 甲으로 가장하여 아파트를 丙에게 임대한 乙이 다시 甲으로 가장하여 임차인 丙에게 아파트를 매도하였다면, 권한을 넘은 표현대리의 법리를 유추적용할 수 있다.","ox":"O","m":"④","c":"A","tp":"乙은 甲의 대리인으로서 甲을 위하여 丙과 계약을 체결하였다. 이"},{"y":2019,"e":"변리사 1차","qn":11,"i":"변리사2019_56-11-5","t":"대리권 수여행위는 묵시적인 의사표시로도 할 수 있으므로, 乙이 甲의 대리인의 외양을 가지고 행위하는 것을 甲이 알면서도 이의를 하지 않고 방임하는 등 사실상의 용태에 의하여 대리권의 수여가 추단되는 경우도 있다.","ox":"O","m":"⑤","c":"A","tp":"乙은 甲의 대리인으로서 甲을 위하여 丙과 계약을 체결하였다. 이"},{"y":2019,"e":"변리사 1차","qn":12,"i":"변리사2019_56-12-1","t":"종기 있는 법률행위는 기한이 도래한 때로부터 그 효력을 잃는다.","ox":"O","m":"①","c":"A","tp":"조건과 기한"},{"y":2019,"e":"변리사 1차","qn":12,"i":"변리사2019_56-12-2","t":"기한의 이익은 이를 포기할 수 있지만, 상대방의 이익을 해하지 못한다.","ox":"O","m":"②","c":"A","tp":"조건과 기한"},{"y":2019,"e":"변리사 1차","qn":12,"i":"변리사2019_56-12-3","t":"조건이 법률행위 당시 이미 성취한 것인 경우에는 그 조건이 해제조건이면 그 법률행위는 조건 없는 법률행위로 한다.","ox":"X","m":"③","c":"A","tp":"조건과 기한"},{"y":2019,"e":"변리사 1차","qn":12,"i":"변리사2019_56-12-4","t":"조건 있는 법률행위의 당사자는 조건의 성부가 미정인 동안에 조건의 성취로 인하여 생길 상대방의 이익을 해하지 못한다.","ox":"O","m":"④","c":"A","tp":"조건과 기한"},{"y":2019,"e":"변리사 1차","qn":12,"i":"변리사2019_56-12-5","t":"조건의 성취로 인하여 불이익을 받을 당사자가 신의성실에 반하여 조건의 성취를 방해한 때에는 상대방은 그 조건이 성취한 것으로 주장할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"조건과 기한"},{"y":2021,"e":"변리사 1차","qn":4,"i":"변리사2021_58-04-1","t":"상계에는 시기(始期)를 붙이지 못한다.","ox":"O","m":"①","c":"A","tp":"법률행위의 부관"},{"y":2021,"e":"변리사 1차","qn":4,"i":"변리사2021_58-04-2","t":"현상광고에 정한 행위의 완료에 조건이나 기한을 붙일 수 있다.","ox":"O","m":"②","c":"A","tp":"법률행위의 부관"},{"y":2021,"e":"변리사 1차","qn":4,"i":"변리사2021_58-04-3","t":"무상임치와 무이자 소비대차의 경우, 채무자만이 기한이익을 갖는다.","ox":"X","m":"③","c":"A","tp":"법률행위의 부관"},{"y":2021,"e":"변리사 1차","qn":4,"i":"변리사2021_58-04-4","t":"조건의 성취로 인하여 이익을 받을 당사자가 신의성실에 반하여 조건을 성취시킨 때에는 상대방은 그 조건이 성취하지 아니한 것으로 주장할 수 있다.","ox":"O","m":"④","c":"A","tp":"법률행위의 부관"},{"y":2021,"e":"변리사 1차","qn":4,"i":"변리사2021_58-04-5","t":"부관이 붙은 법률행위에 있어서 부관에 표시된 사실이 발생한 때뿐만 아니라 발생하지 않는 것으로 확정된 때에도 그 채무를 이행하여야 한다고 보는 것이 상당한 경우에는 표시된 사실의 발생 여부가 확정되는 것을 불확정기한으로 정한 것으로 본다.","ox":"O","m":"⑤","c":"A","tp":"법률행위의 부관"},{"y":2021,"e":"변리사 1차","qn":7,"i":"변리사2021_58-07-1","t":"불공정한 법률행위에도 무효행위 전환의 법리가 적용될 수 있다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"변리사 1차","qn":7,"i":"변리사2021_58-07-2","t":"불공정한 법률행위로서 무효인 경우에도 추인하면 유효로 된다.","ox":"X","m":"②","c":"A"},{"y":2021,"e":"변리사 1차","qn":7,"i":"변리사2021_58-07-3","t":"불공정한 법률행위에 관한 규정은 부담 없는 증여의 경우에도 적용된다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"변리사 1차","qn":7,"i":"변리사2021_58-07-4","t":"경매에서 경매부동산의 매각대금이 시가에 비하여 현저히 저렴한 경우, 불공정한 법률행위에 해당하여 무효이다.","ox":"X","m":"④","c":"A"},{"y":2021,"e":"변리사 1차","qn":7,"i":"변리사2021_58-07-5","t":"법률행위가 현저하게 공정을 잃은 경우, 특별한 사정이 없는 한 그 법률행위는 궁박\u0001경솔\u0001무경험으로 인해 이루어진 것으로 추정된다.","ox":"X","m":"⑤","c":"A","tp":"불공정한 법률행위"},{"y":2021,"e":"변리사 1차","qn":8,"i":"변리사2021_58-08-1","t":"법률에 관한 착오는 그것이 법률행위 내용의 중요부분에 관한 것이라 하더라도 착오를 이유로 취소할 수 없다.","ox":"X","m":"①","c":"A","tp":"착오로 인한 법률행위"},{"y":2021,"e":"변리사 1차","qn":8,"i":"변리사2021_58-08-2","t":"착오로 인한 의사표시의 취소에 관한 민법 제109조 제1항은 당사자의 합의로 그 적용을 배제할 수 없다.","ox":"X","m":"②","c":"A","tp":"착오로 인한 법률행위"},{"y":2021,"e":"변리사 1차","qn":8,"i":"변리사2021_58-08-3","t":"착오한 표의자의 중대한 과실 유무에 관한 증명책임은 의사표시의 효력을 부인하는 착오자에게 있다.","ox":"X","m":"③","c":"A","tp":"착오로 인한 법률행위"},{"y":2021,"e":"변리사 1차","qn":8,"i":"변리사2021_58-08-4","t":"상대방이 표의자의 착오를 알고 이용한 경우, 그 착오가 표의자의 중대한 과실로 인한 것이라고 하더라도 표의자는 착오에 의한 의사표시를 취소할 수 있다.","ox":"O","m":"④","c":"A","tp":"착오로 인한 법률행위"},{"y":2021,"e":"변리사 1차","qn":8,"i":"변리사2021_58-08-5","t":"표의자가 착오를 이유로 의사표시를 취소한 경우, 취소로 인하여 손해를 입은 상대방은 표의자에게 불법행위로 인한 손해배상을 청구할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"착오로 인한 법률행위"},{"y":2021,"e":"변리사 1차","qn":9,"i":"변리사2021_58-09-2","t":"乙이 미성년자인 경우, 甲은 乙의 제한능력을 이유로 X토지에 대한 매매계약을 취소할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"변리사 1차","qn":9,"i":"변리사2021_58-09-3","t":"丙과의 매매계약이 불공정한 법률행위에 해당하는지 여부가 문제된 경우, 매도인의 무경험은 甲을 기준으로 판단한다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"변리사 1차","qn":9,"i":"변리사2021_58-09-4","t":"乙이 丙으로부터 매매대금을 수령한 경우, 甲에게 이를 아직 전달하지 않았더라도 특별한 사정이 없는 한 丙의 매매대금채무는 소멸한다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"변리사 1차","qn":9,"i":"변리사2021_58-09-5","t":"甲이 乙에게 매매계약의 체결과 이행에 관한 포괄적 대리권을 수여한 경우, 특별한 사정이 없는 한 乙은 약정된 매매대금 지급기일을 연기하여 줄 권한을 가진다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"변리사 1차","qn":10,"i":"변리사2021_58-10-1","t":"제한능력자의 법률행위에 대한 법정대리인의 추인은 취소의 원인이 소멸된 후에 하여야 그 효력이 있다.","ox":"X","m":"①","c":"A","tp":"법률행위의 취소"},{"y":2021,"e":"변리사 1차","qn":10,"i":"변리사2021_58-10-2","t":"취소할 수 있는 법률행위로 취득한 권리를 취소권자의 상대방이 제3자에게 양도한 경우, 법정추인이 되지 않는다.","ox":"O","m":"②","c":"A","tp":"법률행위의 취소"},{"y":2021,"e":"변리사 1차","qn":10,"i":"변리사2021_58-10-3","t":"법률행위의 취소를 전제로 한 소송상의 이행청구나 이를 전제로 한 이행거절에는 취소의 의사표시가 포함되어 있다고 볼 수 있다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"변리사 1차","qn":10,"i":"변리사2021_58-10-4","t":"취소할 수 있는 법률행위는 취소권자가 추인할 수 있는 후에 이의를 보류하지 않고 이행청구를 하면 추인한 것으로 본다.","ox":"O","m":"④","c":"A","tp":"법률행위의 취소"},{"y":2021,"e":"변리사 1차","qn":10,"i":"변리사2021_58-10-5","t":"취소권자가 취소할 수 있는 법률행위를 적법하게 추인한 경우, 그 법률행위를 다시 취소할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"법률행위의 취소"},{"y":2021,"e":"변리사 1차","qn":11,"i":"변리사2021_58-11-1","t":"甲이 허가신청절차에 협력하지 않으면 乙은 甲에 대하여 협력의무의 이행을 소구할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"변리사 1차","qn":11,"i":"변리사2021_58-11-2","t":"甲이 허가신청절차에 협력할 의무를 이행하지 않더라도 특별한 사정이 없는 한 乙은 이를 이유로 계약을 해제할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"변리사 1차","qn":11,"i":"변리사2021_58-11-3","t":"甲과 乙이 허가신청절차 협력의무의 이행거절의사를 명백히 표시한 경우, 매매계약은 확정적으로 무효가 된다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"변리사 1차","qn":11,"i":"변리사2021_58-11-4","t":"매매계약이 乙의 사기에 의해 체결된 경우, 甲은 토지거래허가를 신청하기 전에 사기를 이유로 계약을 취소함으로써 허가신청절차의 협력의무를 면할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"변리사 1차","qn":11,"i":"변리사2021_58-11-5","t":"X토지가 중간생략등기의 합의에 따라 乙로부터 丙에게 허가 없이 전매된 경우, 丙은 甲에 대하여 직접 허가신청절차의 협력의무 이행청구권을 가진다.","ox":"X","m":"⑤","c":"A"},{"y":2021,"e":"변리사 1차","qn":12,"i":"변리사2021_58-12-1","t":"丙이 乙의 대리행위가 유권대리라고 주장하는 경우, 그 주장 속에는 표현대리의 주장이 포함된 것으로 보아야 한다.","ox":"X","m":"①","c":"A"},{"y":2021,"e":"변리사 1차","qn":12,"i":"변리사2021_58-12-2","t":"丙이 계약체결 당시에 乙에게 매매계약 체결의 대리권이 없음을 알았더라도 丙의 甲에 대한 최고권이 인정된다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"변리사 1차","qn":12,"i":"변리사2021_58-12-3","t":"丙이 계약체결 당시에 乙에게 매매계약 체결의 대리권이 없음을 알았더라도 계약을 철회할 수 있다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"변리사 1차","qn":12,"i":"변리사2021_58-12-4","t":"乙의 행위가 권한을 넘은 표현대리로 인정되는 경우, 丙에게 과실(過失)이 있다면 과실상계의 법리에 따라 甲의 책임이 경감될 수 있다.","ox":"X","m":"④","c":"A"},{"y":2021,"e":"변리사 1차","qn":12,"i":"변리사2021_58-12-5","t":"丙이 乙의 대리행위가 권한을 넘은 표현대리라고 주장하는 경우, 乙에게 매매계약체 결의 대리권이 있다고 丙이 믿을 만한 정당한 이유가 있었는지의 여부는 계약성립이 후의 모든 사정을 고려하여 판단해야 한다.","ox":"X","m":"⑤","c":"A"},{"y":2023,"e":"변리사 1차","qn":7,"i":"변리사2023_60-07","t":"민법 제104조의 불공정한 법률행위에 관한 설명으로 옳은 것은? (다툼이 있으면","c":"A","mc":{"s":"민법 제104조의 불공정한 법률행위에 관한 설명으로 옳은 것은? (다툼이 있으면","d":"판례에 따름)","o":["행정기관에 진정서를 제출하여 상대방을 궁지에 빠뜨린 다음 이를 취하하는 조건으로 거액의 급부를 제공받기로 약정한 것은 불공정한 법률행위에 해당한다.","법률행위의 성립시에는 존재하지 않았던 급부간의 현저한 불균형이 그 이후 외부적 사정의 급격한 변화로 인하여 발생하였다면 다른 요건이 충족되는 한 그때부터 불공정한 법률행위가 인정된다.","불공정한 법률행위의 성립요건으로 요구되는 무경험이란 일반적인 생활체험의 부족이 아니라 해당 법률행위가 행해진 바로 그 영역에서의 경험 부족을 의미한다.","법률행위가 현저히 공정을 잃었고, 어느 한 당사자에게 궁박의 사정이 존재한다고 하여도 그 상대방에게 이러한 사정을 이용하려는 폭리행위의 악의가 없었다면 불공정한 법률행위는 인정되지 않는다.","불공정한 법률행위를 할 때 당사자간에 그 법률행위의 불공정성을 이유로 하여 법률행위의 효력을 다툴 수 없다는 합의가 함께 행해졌다면 그러한 합의는 유효하다."],"a":4}},{"y":2023,"e":"변리사 1차","qn":8,"i":"변리사2023_60-08-1","t":"통정허위표시에 의한 법률행위도 채권자취소권의 대상인 사해행위가 될 수 있다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"변리사 1차","qn":8,"i":"변리사2023_60-08-2","t":"임대차보증금반환채권을 담보할 목적으로 임대인과 임차인이 체결한 전세권설정계약은 특별한 사정이 없는 한 임대차계약의 내용과 양립할 수 없는 범위에서만 통정허위표시로 인정된다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"변리사 1차","qn":8,"i":"변리사2023_60-08-3","t":"차명(借名)으로 대출받으면서 명의대여자에게는 법률효과를 귀속시키지 않기로 하는 합의가 대출기관과 실제 차주 사이에 있었다면 명의대여자의 명의로 작성된 대출계약은 통정허위표시이다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"변리사 1차","qn":8,"i":"변리사2023_60-08-4","t":"통정허위표시에 따른 선급금 반환채무 부담행위에 기하여 선의로 그 채무를 보증한 자는 보증채무의 이행 여부와 상관없이 허위표시의 무효로부터 보호받는 제3자에 해당한다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"변리사 1차","qn":8,"i":"변리사2023_60-08-5","t":"파산관재인은 그가 비록 통정허위표시에 대해 악의였다고 하더라도 파산채권자 모두가 악의로 되지 않는 한 선의의 제3자로 인정된다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"변리사 1차","qn":9,"i":"변리사2023_60-09-1","t":"법률행위의 자연적 해석이 행해지는 경우, 표시상의 착오는 문제될 여지가 없다.","ox":"O","m":"①","c":"A","tp":"착오로 인한 의사표시"},{"y":2023,"e":"변리사 1차","qn":9,"i":"변리사2023_60-09-2","t":"의사의 수술 후 환자에게 새로이 발생한 증세에 대하여 그 책임소재와 손해배상 여부를 둘러싸고 분쟁이 있다가 화해계약이 체결되었다면, 이후에 그 증세가 수술로 인한 것이 아니라는 것이 밝혀졌더라도 의사는 착오를 이유로 위 화해계약을 취소할 수 없다.","ox":"O","m":"②","c":"A","tp":"착오로 인한 의사표시"},{"y":2023,"e":"변리사 1차","qn":9,"i":"변리사2023_60-09-3","t":"해제되어 이미 실효된 계약도 착오취소의 대상이 될 수 있다.","ox":"O","m":"③","c":"A","tp":"착오로 인한 의사표시"},{"y":2023,"e":"변리사 1차","qn":9,"i":"변리사2023_60-09-4","t":"착오가 법률행위 내용의 일부에만 관계된 경우라면 일부무효의 법리가 유추적용되어 일부취소가 인정될 수도 있다.","ox":"O","m":"④","c":"A","tp":"착오로 인한 의사표시"},{"y":2023,"e":"변리사 1차","qn":9,"i":"변리사2023_60-09-5","t":"예술품의 위작(僞作)을 진품으로 착각한 매도인의 말을 믿고서 과실 없이 진품에 상응하는 가격으로 그 위작을 구입한 매수인이 매도인에게 하자담보책임을 물을 수 있다면 그는 착오취소를 주장할 수 없다.","ox":"X","m":"⑤","c":"A","tp":"착오로 인한 의사표시"},{"y":2023,"e":"변리사 1차","qn":10,"i":"변리사2023_60-10-1","t":"대리권은 대리인의 권리이자 의무의 성격을 갖는다.","ox":"X","m":"①","c":"A","tp":"민법상 대리"},{"y":2023,"e":"변리사 1차","qn":10,"i":"변리사2023_60-10-2","t":"대리권 남용에 대해 진의 아닌 의사표시에 관한 민법 제107조 제1항 단서가 유추적용 되는 경우, 선의의 제3자 보호에 관한 동조 제2항도 함께 유추적용된다.","ox":"O","m":"②","c":"A","tp":"민법상 대리"},{"y":2023,"e":"변리사 1차","qn":10,"i":"변리사2023_60-10-3","t":"복대리인은 본인의 대리인이므로 원대리인의 복임행위는 본인을 위한 대리행위이다.","ox":"X","m":"③","c":"A","tp":"민법상 대리"},{"y":2023,"e":"변리사 1차","qn":10,"i":"변리사2023_60-10-4","t":"대리권이 이미 소멸한 원대리인에 의해 선임된 복대리인의 대리행위에 대해서는 대리권 소멸 후의 표현대리(제129조)가 성립할 여지가 없다.","ox":"X","m":"④","c":"A","tp":"민법상 대리"},{"y":2023,"e":"변리사 1차","qn":10,"i":"변리사2023_60-10-5","t":"자신에게 유효한 대리권이 있다고 과실 없이 믿었던, 행위능력 있는 선의의 무권대리 인은 본인의 추인이 없더라도 상대방에 대한 무권대리인의 책임에 관한 민법 제135조에 따른 책임을 지지 않는다.","ox":"X","m":"⑤","c":"A","tp":"민법상 대리"},{"y":2023,"e":"변리사 1차","qn":11,"i":"변리사2023_60-11-1","t":"甲과 乙이 관할관청으로부터 허가를 받으면 유동적 무효상태에 있던 위 매매계약은 소급해서 유효로 된다.","ox":"O","m":"①","c":"A","tp":"부동산 거래신고 등"},{"y":2023,"e":"변리사 1차","qn":11,"i":"변리사2023_60-11-2","t":"乙의 매수인 지위를 丙이 이전받는다는 취지의 약정을 甲, 乙, 丙이 한 경우, 그와 같은 합의는 甲과 乙간의 위 매매계약에 관한 관할관청의 허가가 있어야 비로소 효력이 발생한다.","ox":"O","m":"②","c":"A","tp":"부동산 거래신고 등"},{"y":2023,"e":"변리사 1차","qn":11,"i":"변리사2023_60-11-3","t":"보전의 필요성이 인정되는 한 乙은 甲에 대한 토지거래허가 신청절차의 협력의무이 행청구권을 피보전권리로 하여 甲의 권리를 대위 행사할 수 있다.","ox":"O","m":"③","c":"A","tp":"부동산 거래신고 등"},{"y":2023,"e":"변리사 1차","qn":11,"i":"변리사2023_60-11-4","t":"甲과 乙이 관할관청에 토지거래허가를 신청하여 그 허가를 받은 후에도 乙은 다른 사유가 없는 한 계약금을 포기하고 위 매매계약을 해제할 수 있다.","ox":"O","m":"④","c":"A","tp":"부동산 거래신고 등"},{"y":2023,"e":"변리사 1차","qn":11,"i":"변리사2023_60-11-5","t":"乙은 특별한 사정이 없는 한 위 매매계약의 허가를 받기 전까지 부당이득반환청구권을 행사하여 甲에게 이미 지급한 계약금의 반환을 청구할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"부동산 거래신고 등"},{"y":2023,"e":"변리사 1차","qn":12,"i":"변리사2023_60-12-1","t":"이행지체의 경우 채권자는 채무자를 상대로 상당한 기간을 정하여 이행을 청구하면서 그 기간 내에 이행이 없으면 계약은 당연히 해제된 것으로 한다는 취지의 해제조건부 해제권 행사를 할 수 있다.","ox":"X","m":"①","c":"A","tp":"조건과 기한"},{"y":2023,"e":"변리사 1차","qn":12,"i":"변리사2023_60-12-2","t":"동산에 대한 소유권유보부 매매의 경우 물권행위인 소유권이전의 합의가 매매대금의 완납을 정지조건으로 하여 성립한다.","ox":"O","m":"②","c":"A","tp":"조건과 기한"},{"y":2023,"e":"변리사 1차","qn":12,"i":"변리사2023_60-12-3","t":"부첩(夫妾)관계의 종료를 해제조건으로 하는 증여계약은 무효이다.","ox":"O","m":"③","c":"A","tp":"조건과 기한"},{"y":2023,"e":"변리사 1차","qn":12,"i":"변리사2023_60-12-4","t":"불확정기한의 경우 기한사실의 발생이 불가능한 것으로 확정되어도 기한은 도래한 것으로 본다.","ox":"O","m":"④","c":"A","tp":"조건과 기한"},{"y":2023,"e":"변리사 1차","qn":12,"i":"변리사2023_60-12-5","t":"기한이익 상실의 특약은 특별한 사정이 없는 한 형성권적 기한이익 상실의 특약으로 추정된다.","ox":"O","m":"⑤","c":"A","tp":"조건과 기한"},{"y":2024,"e":"변리사 1차","qn":5,"i":"변리사2024_61-05","t":"甲이 자신의 X건물을 乙에게 매도하는 계약을 체결하고 계약금 및 중도금을 수령 하였으나 아직 소유권이전등기를 마쳐주지 않았다. 이러한 사실을 알고 있는 丙이 甲의 배임행위에 적극적으로 가담하여 甲으로부터 X건물을 매수하고 소유권이전등기를 경료받았다. 이에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으","c":"A","mc":{"s":"甲이 자신의 X건물을 乙에게 매도하는 계약을 체결하고 계약금 및 중도금을 수령 하였으나 아직 소유권이전등기를 마쳐주지 않았다. 이러한 사실을 알고 있는 丙이 甲의 배임행위에 적극적으로 가담하여 甲으로부터 X건물을 매수하고 소유권이전등기를 경료받았다. 이에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으","d":"면 판례에 따름)\nㄱ. 甲과 丙이 체결한 매매계약은 반사회적 법률행위로서 무효이다.\nㄴ. 乙은 甲을 대위함이 없이 직접 丙에 대하여 그 소유권이전등기의 말소를 청구할 수 있다.\nㄷ. 乙은 甲에 대한 소유권이전등기청구권을 보전하기 위하여 甲과 丙 사이의 매매계약에 대하여 채권자취소권을 행사할 수 있다.\nㄹ. 丁이 丙을 소유권자로 믿고 丙으로부터 X건물을 매수하여 소유권이전등기를 마친 경우, 丁은 甲과 丙 사이의 매매계약의 유효를 주장할 수 있다.","o":["ㄱ","ㄱ, ㄷ","ㄴ, ㄹ","ㄱ, ㄴ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":1}},{"y":2024,"e":"변리사 1차","qn":6,"i":"변리사2024_61-06-1","t":"상대방 있는 의사표시에 관하여 제3자가 표의자를 강박한 경우, 표의자는 상대방이 그 사실을 알았거나 알 수 있었을 경우에 한하여 강박에 의한 의사표시를 취소할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"변리사 1차","qn":6,"i":"변리사2024_61-06-2","t":"매매목적물에 하자가 있는 사실을 착오로 알지 못하고 매매계약을 체결한 매수인은 착오로 인한 의사표시의 취소 요건을 갖추더라도 매도인의 하자담보책임이 성립하는 경우에는 착오를 이유로 그 계약을 취소할 수 없다.","ox":"X","m":"②","c":"A"},{"y":2024,"e":"변리사 1차","qn":6,"i":"변리사2024_61-06-3","t":"통정허위표시로 매매계약이 체결된 경우, 매도인이 그 계약상 채무를 이행하지 않더라도 매수인은 매도인에게 채무불이행으로 인한 손해배상을 청구할 수 없다.","ox":"O","m":"③","c":"A","tp":"의사표시"},{"y":2024,"e":"변리사 1차","qn":6,"i":"변리사2024_61-06-4","t":"경과실로 인한 착오로 의사표시를 한 자가 착오를 이유로 그 의사표시를 취소한 경우, 상대방은 이로 인해 손해를 입더라도 표의자에게 불법행위로 인한 손해배상을 청구할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"변리사 1차","qn":6,"i":"변리사2024_61-06-5","t":"상대방이 표의자의 착오를 알고 이용한 경우에는 착오가 표의자의 중대한 과실로 인한 것이더라도 표의자는 착오를 이유로 의사표시를 취소할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"변리사 1차","qn":7,"i":"변리사2024_61-07-1","t":"상대방 있는 의사표시는 원칙적으로 상대방에게 도달되어야 효력이 발생한다.","ox":"O","m":"①","c":"A","tp":"의사표시의 효력발생"},{"y":2024,"e":"변리사 1차","qn":7,"i":"변리사2024_61-07-2","t":"청약자가 청약의 의사표시를 발송한 후 사망한 경우에도 그 의사표시의 효력에 영향을 미치지 아니한다.","ox":"O","m":"②","c":"A","tp":"의사표시의 효력발생"},{"y":2024,"e":"변리사 1차","qn":7,"i":"변리사2024_61-07-3","t":"적법하게 성립된 매매에 관하여 해제사유가 발생한 경우, 해제의 의사가 상대방 당사자의 미성년 자(子)에게 도달하면 그 즉시 해제의 효력이 발생한다.","ox":"X","m":"③","c":"A","tp":"의사표시의 효력발생"},{"y":2024,"e":"변리사 1차","qn":7,"i":"변리사2024_61-07-4","t":"상대방이 부당하게 등기취급 우편물의 수취를 거부함으로써 우편물의 내용을 알 수 있는 객관적 상태의 형성을 방해한 것이 신의성실의 원칙에 반한다고 인정되는 경우, 수취 거부 시에 의사표시의 효력이 생긴 것으로 보아야 한다.","ox":"O","m":"④","c":"A","tp":"의사표시의 효력발생"},{"y":2024,"e":"변리사 1차","qn":7,"i":"변리사2024_61-07-5","t":"의사표시가 담긴 우편물이 상대방의 집에 도달하자 가사도우미가 수취한 후 개봉하지 않은 채 식탁 위에 두었는데, 그 즈음 우연히 그 집을 방문한 의사표시자가 그 미개 봉된 우편물을 회수하여 가지고 간 경우, 그 의사표시가 도달한 것으로 볼 수 없다.","ox":"O","m":"⑤","c":"A","tp":"의사표시의 효력발생"},{"y":2024,"e":"변리사 1차","qn":8,"i":"변리사2024_61-08-1","t":"법정대리인은 원칙적으로 부득이한 사유가 있는 때에 한하여 복임권이 있다.","ox":"X","m":"①","c":"A","tp":"복대리"},{"y":2024,"e":"변리사 1차","qn":8,"i":"변리사2024_61-08-2","t":"법정대리인이 부득이한 사유로 복대리인을 선임한 경우, 법정대리인은 그 선임감독에 관한 책임이 있다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"변리사 1차","qn":8,"i":"변리사2024_61-08-3","t":"임의대리인에게는 원칙적으로 복대리인을 선임할 권한이 없다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"변리사 1차","qn":8,"i":"변리사2024_61-08-4","t":"임의대리인이 본인의 승낙을 얻어 복대리인을 선임한 경우, 임의대리인은 그 선임감독에 관한 책임이 있다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"변리사 1차","qn":8,"i":"변리사2024_61-08-5","t":"임의대리의 목적인 법률행위의 성질상 대리인 자신에 의한 처리가 필요하지 아니한 경우, 본인이 복대리 금지의 의사를 명시하지 아니하는 한 복대리인의 선임에 관하여 묵시적인 승낙이 있는 것으로 보는 것이 타당하다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"변리사 1차","qn":9,"i":"변리사2024_61-09-1","t":"乙이 위 계약을 적법하게 추인하면, 丙은 甲을 상대로 계약상의 책임이나 무권대리인의 책임을 일절 물을 수 없다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"변리사 1차","qn":9,"i":"변리사2024_61-09-2","t":"乙이 甲에게 추인의 의사표시를 한 경우, 丙은 乙의 추인 사실을 몰랐다면 계약당시 乙의 무권대리사실에 관하여 선의인 때에 한하여 위 계약을 철회할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"변리사 1차","qn":9,"i":"변리사2024_61-09-3","t":"乙이 추인을 거절한 경우, 丙은 무권대리사실에 관하여 선의\u0001무과실이라면 甲에게 과실이 없더라도 甲을 상대로 무권대리인으로서의 책임을 추궁할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"변리사 1차","qn":9,"i":"변리사2024_61-09-4","t":"甲이 무권대리인으로서 책임을 부담하는 경우, 丙은 위 계약에서의 위약금 조항의 효력을 주장할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"변리사 1차","qn":9,"i":"변리사2024_61-09-5","t":"만일 丙이 丁에게 위 부동산을 매도한 경우, 乙이 丁에게만 추인의 의사를 표시하면 추인의 효력은 발생하지 아니한다.","ox":"X","m":"⑤","c":"A"},{"y":2024,"e":"변리사 1차","qn":10,"i":"변리사2024_61-10-1","t":"미성년자가 체결한 계약이 법정대리인의 동의없음을 이유로 취소할 수 있는 경우, 계약당사자인 미성년자는 단독으로 그 계약을 취소할 수 없다.","ox":"X","m":"①","c":"A"},{"y":2024,"e":"변리사 1차","qn":10,"i":"변리사2024_61-10-2","t":"계약을 체결할 수 있는 권한만을 가진 임의대리인이 상대방의 사기로 계약을 체결한 경우, 그 임의대리인은 그 계약을 취소할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2024,"e":"변리사 1차","qn":10,"i":"변리사2024_61-10-3","t":"미성년자인 임의대리인이 계약을 체결한 경우, 본인은 미성년자에 의한 대리행위라는 이유로 취소할 수 있다.","ox":"X","m":"③","c":"A"},{"y":2024,"e":"변리사 1차","qn":10,"i":"변리사2024_61-10-4","t":"전세권자의 사기에 의해 건물에 전세권이 설정되고 그 건물이 양도된 경우, 건물양수 인은 전세권자의 사기를 이유로 전세권 설정 계약을 취소할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"변리사 1차","qn":10,"i":"변리사2024_61-10-5","t":"미성년자가 단독으로 발급받은 신용카드를 이용하여 구입한 물품의 대금을 성년자가 되어 이의없이 결제한 후에도 그 물품구입계약을 미성년자의 행위임을 이유로 취소할 수 있다.","ox":"X","m":"⑤","c":"A"},{"y":2024,"e":"변리사 1차","qn":11,"i":"변리사2024_61-11-1","t":"乙은 甲을 상대로 허가가 나오는 것을 조건으로 하여 잔금과 상환으로 이전등기를 해 달라고 청구할 수 있다.","ox":"X","m":"①","c":"A","tp":"부동산 거래신고 등"},{"y":2024,"e":"변리사 1차","qn":11,"i":"변리사2024_61-11-2","t":"허가가 나오기 전이라도 甲은 乙이 잔금기일에 잔금을 지급하지 않았다는 것을 이유로 위 계약을 해제할 수 있다.","ox":"X","m":"②","c":"A","tp":"부동산 거래신고 등"},{"y":2024,"e":"변리사 1차","qn":11,"i":"변리사2024_61-11-3","t":"위 계약이 확정적으로 무효가 된 경우, 그에 관해 귀책사유가 있는 당사자도 계약의 무효를 주장할 수 있다.","ox":"O","m":"③","c":"A","tp":"부동산 거래신고 등"},{"y":2024,"e":"변리사 1차","qn":11,"i":"변리사2024_61-11-4","t":"거래허가를 신청하기 전에는 乙의 기망행위로 위 계약을 체결하였더라도 甲은 그 계약을 취소할 수 없다.","ox":"X","m":"④","c":"A","tp":"부동산 거래신고 등"},{"y":2024,"e":"변리사 1차","qn":11,"i":"변리사2024_61-11-5","t":"만일 계약 당시 합의에 따라 계약금을 乙이 丙에게 지급하였는데 그 후 위 계약이 확정적으로 무효가 된 경우, 특별한 사정이 없는 한 乙은 丙을 상대로 지급한 계약금 상당액의 반환을 청구할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"부동산 거래신고 등"},{"y":2026,"e":"변리사 1차","qn":5,"i":"변리사2026_63-05-1","t":"매매계약이 불공정한 법률행위에 해당하는지는 매매계약이 체결된 당시를 기준으로 판단한다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"변리사 1차","qn":5,"i":"변리사2026_63-05-2","t":"매매계약이 불공정한 법률행위로서 무효인 경우, 특별한 사정이 없는 한 그 매매계약에 관한 부제소합의도 무효이다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"변리사 1차","qn":5,"i":"변리사2026_63-05-3","t":"불공정한 법률행위로 무효인 경우, 당사자가 이를 추인하면 그때부터는 무효인 법률행위가 유효로 된다.","ox":"X","m":"③","c":"A"},{"y":2026,"e":"변리사 1차","qn":5,"i":"변리사2026_63-05-4","t":"불공정한 법률행위로서 무효인 경우에도 무효행위의 전환에 관한 민법 제138조가 적용될 수 있다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"변리사 1차","qn":5,"i":"변리사2026_63-05-5","t":"대리인에 의한 법률행위의 경우, 경솔과 무경험은 대리인을 기준으로 판단하고 궁박 상태에 있었는지의 여부는 본인을 기준으로 판단한다.","ox":"O","m":"⑤","c":"A","tp":"불공정한 법률행위"},{"y":2026,"e":"변리사 1차","qn":6,"i":"변리사2026_63-06-1","t":"채무자의 법률행위가 통정허위표시로 무효인 경우에도 채권자취소권의 대상이 될 수 있다.","ox":"O","m":"①","c":"A","tp":"의사표시"},{"y":2026,"e":"변리사 1차","qn":6,"i":"변리사2026_63-06-2","t":"매도인이 채무불이행을 이유로 하여 매매계약을 적법하게 해제한 후에도 매수인은 착오를 이유로 그 계약을 취소할 수 있다.","ox":"O","m":"②","c":"A","tp":"의사표시"},{"y":2026,"e":"변리사 1차","qn":6,"i":"변리사2026_63-06-3","t":"동기의 착오가 상대방의 부정한 방법에 의하여 유발된 경우에는 동기가 표시되지 않았더라도 표의자는 착오를 이유로 의사표시를 취소할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"변리사 1차","qn":6,"i":"변리사2026_63-06-4","t":"매도인이 제3자의 기망행위에 의해 매수인과 매매계약을 체결한 경우, 매도인이 그 제3자에게 사기에 의한 불법행위를 이유로 손해배상을 청구하기 위해서는 먼저 그 매매계약을 취소하여야 한다.","ox":"X","m":"④","c":"A","tp":"의사표시"},{"y":2026,"e":"변리사 1차","qn":6,"i":"변리사2026_63-06-5","t":"표의자가 재단법인의 설립을 위해 서면에 의한 출연행위를 한 경우, 법인이 성립되고 출연된 재산이 기본재산이더라도 착오에 의한 의사표시의 취소 요건을 갖추면 표의자는 이를 이유로 출연행위를 취소할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"변리사 1차","qn":7,"i":"변리사2026_63-07","t":"복대리에 관한 설명으로 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"복대리에 관한 설명으로 옳은 것을 모두 고른 것은?","d":"ㄱ. 복대리인은 대리인이 자신의 이름으로 선임한 본인의 대리인이다.\nㄴ. 법정대리인이 부득이한 사유로 복대리인을 선임한 경우, 법정대리인은 본인에게 대하여 그 선임감독에 관한 책임이 있다.\nㄷ. 임의대리인이 부득이한 사유로 복대리인을 선임한 경우, 임의대리인은 본인에게 대하여 그 선임감독에 관한 책임이 있다.\nㄹ. 복임권이 없는 대리인에 의하여 선임된 복대리인의 권한도 권한을 넘은 표현대리의 기본대리권이 될 수 있다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄱ, ㄴ, ㄹ","ㄴ, ㄷ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":5}},{"y":2026,"e":"변리사 1차","qn":8,"i":"변리사2026_63-08-1","t":"대리권 수여의 표시에 의한 표현대리에서 대리인이 대리인이라고 하지 않았더라도 사회통념상 대리권을 추단할 수 있는 직함이나 명칭을 사용하는 것을 본인이 묵인한 경우에는 대리권 수여의 표시가 있은 것으로 볼 수 있다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"변리사 1차","qn":8,"i":"변리사2026_63-08-2","t":"권한을 넘은 표현대리는 특별한 사정이 없는 한, 대리인이 사술을 써서 대리행위의 표시없이 단지 본인의 성명을 모용하여 자기가 마치 본인인 것처럼 기망하여 본인 명의로 직접 법률행위를 한 경우에도 성립될 수 있다.","ox":"X","m":"②","c":"A"},{"y":2026,"e":"변리사 1차","qn":8,"i":"변리사2026_63-08-3","t":"대리권 소멸 후의 표현대리에 관한 민법 제129조는 법정대리인의 대리권 소멸에 관하여서는 적용될 수 없다.","ox":"X","m":"③","c":"A"},{"y":2026,"e":"변리사 1차","qn":8,"i":"변리사2026_63-08-4","t":"지방자치단체가 사경제주체로서 한 법률행위에 대해서는 표현대리에 관한 법리가 적용되지 않는다.","ox":"X","m":"④","c":"A"},{"y":2026,"e":"변리사 1차","qn":8,"i":"변리사2026_63-08-5","t":"학교법인을 대표하는 이사장이 사립학교법상 규정을 위반하여 이사회의 심의\u0001결정없이 학교법인의 기본재산을 처분하는 행위에 대해서도 권한을 넘은 표현대리에 관한 규정이 준용될 수 있다.","ox":"X","m":"⑤","c":"A"},{"y":2026,"e":"변리사 1차","qn":9,"i":"변리사2026_63-09-1","t":"乙이 무권대리인임을 계약체결 당시 丙이 알았더라도 丙은 상당한 기간을 정하여 甲에게 계약의 추인 여부의 확답을 최고할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"변리사 1차","qn":9,"i":"변리사2026_63-09-2","t":"甲이 丙에게 계약을 이미 추인하였더라도 丙이 계약체결 당시 乙이 무권대리인임을 알지 못하였다면, 丙은 甲 또는 乙에 대하여 계약을 철회할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2026,"e":"변리사 1차","qn":9,"i":"변리사2026_63-09-3","t":"甲이 계약 내용 중 일부에 대하여 추인하였더라도 丙의 동의를 얻지 못하는 한 그 추인은 효력이 없다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"변리사 1차","qn":9,"i":"변리사2026_63-09-4","t":"甲은 乙에 대한 추인거절의 의사표시로써 丙에게 대항할 수 없으나, 丙이 그 사실을안 때에는 대항할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"변리사 1차","qn":9,"i":"변리사2026_63-09-5","t":"乙이 甲을 단독으로 상속하여 X토지의 소유자가 되면, 특별한 사정이 없는 한 乙은 본인의 지위에서 매매계약의 추인을 거절할 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"변리사 1차","qn":10,"i":"변리사2026_63-10","t":"취소할 수 있는 법률행위에 관하여 민법 제145조에서 규정하는 법정추인 사유에 해당하지 않는 것은?","c":"A","mc":{"s":"취소할 수 있는 법률행위에 관하여 민법 제145조에서 규정하는 법정추인 사유에 해당하지 않는 것은?","d":"","o":["취소권자의 상대방에 대한 채무의 일부 이행","취소권자에 대한 상대방의 이행 청구","취소권자와 상대방 사이의 경개계약 체결","취소권자의 채무자로서의 담보제공","취소권자의 취소할 수 있는 행위로 취득한 권리의 일부 양도"],"a":2}},{"y":2026,"e":"변리사 1차","qn":11,"i":"변리사2026_63-11","t":"법률행위의 부관에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면 판","c":"A","mc":{"s":"법률행위의 부관에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면 판","d":"례에 따름)\nㄱ. 조건이 법률행위의 당시 이미 성취한 것인 경우에는 그 조건이 해제조건이면 그 법률행위는 조건없는 법률행위로 한다.\nㄴ. 조건이 법률행위의 당시에 이미 성취할 수 없는 것인 경우에는 그 조건이 정지조건이면 그 법률행위는 무효로 한다.\nㄷ. 당사자가 불확정한 사실이 발생한 때를 이행기한으로 정한 경우, 그 사실이 발생한 때는 물론 그 사실의 발생이 불가능하게 된 때에도 그 이행기한은 도래한 것으로 보아야 한다.\nㄹ. 기한이익 상실의 특약은 특별한 사정이 없는 한 정지조건부 기한이익 상실의 특약으로 추정된다.","o":["ㄱ, ㄴ","ㄴ, ㄷ","ㄷ, ㄹ","ㄱ, ㄷ, ㄹ","ㄴ, ㄷ, ㄹ"],"a":2}}],"4":[{"y":2016,"e":"변리사 1차","qn":12,"i":"변리사2016_53-12-1","t":"형성권은 제척기간의 경과 자체만으로 곧 권리 소멸의 효과가 발생하지 않는다.","ox":"X","m":"①","c":"A"},{"y":2016,"e":"변리사 1차","qn":12,"i":"변리사2016_53-12-2","t":"수급인의 하자담보책임기간은 재판상 또는 재판 외의 권리행사기간인 제척기간이다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"변리사 1차","qn":12,"i":"변리사2016_53-12-3","t":"민법 제146조에서 규정하는 취소권의 행사기간은 제척기간으로서 법원의 직권조사 사항이다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"변리사 1차","qn":12,"i":"변리사2016_53-12-4","t":"매매예약완결권의 행사기간은 제척기간으로 해석되며, 기간의 중단이 있을 수 없다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"변리사 1차","qn":12,"i":"변리사2016_53-12-5","t":"점유보호청구권의 행사기간은 제척기간으로, 재판 외에서 권리를 행사할 수 있는 기간이 아니라 반드시 그 기간 내에 소를 제기하여야 하는 출소기간이다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"변리사 1차","qn":11,"i":"변리사2017_54-11-1","t":"A호텔의 음식료 채권은 1년의 소멸시효에 걸린다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"변리사 1차","qn":11,"i":"변리사2017_54-11-2","t":"소멸시효가 완성되기 전에 A호텔이 소를 제기했으므로, 소멸시효의 진행이 중단된다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"변리사 1차","qn":11,"i":"변리사2017_54-11-3","t":"A호텔이 소송을 취하하면 소멸시효 중단의 효력은 없으나, 6개월 내에 가압류를 하면 최초의 재판상 청구로 인하여 소멸시효가 중단된 것으로 본다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"변리사 1차","qn":11,"i":"변리사2017_54-11-4","t":"A호텔의 청구에 대하여 기각판결이 확정된 후, A호텔이 재심을 청구하면 소멸시효의 진행이 중단된다.","ox":"X","m":"④","c":"A"},{"y":2017,"e":"변리사 1차","qn":12,"i":"변리사2017_54-12-1","t":"재산을 관리하는 후견인에 대한 제한능력자의 권리는 그가 능력자가 된 때로부터 6개월 내에는 소멸시효가 완성되지 아니한다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"변리사 1차","qn":12,"i":"변리사2017_54-12-2","t":"채권자가 채무자를 상대로 법원에 신청한 화해가 불성립되어 채권자가 그로부터 1월내에 소를 제기한 경우, 채권의 소멸시효는 소제기 시부터 중단된다.","ox":"X","m":"②","c":"A"},{"y":2017,"e":"변리사 1차","qn":12,"i":"변리사2017_54-12-3","t":"소멸시효의 기간만료 전 1년 내에 제한능력자에게 법정대리인이 없는 경우, 그가 능력자가 되거나 법정대리인이 취임한 때로부터 1년 내에는 소멸시효가 완성 되지 아니한다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"변리사 1차","qn":12,"i":"변리사2017_54-12-4","t":"상속재산에 대한 권리는 상속인의 확정, 관리인의 선임 또는 파산선고가 있는 때로부터 1년 내에는 소멸시효가 완성되지 아니한다.","ox":"X","m":"④","c":"A"},{"y":2017,"e":"변리사 1차","qn":12,"i":"변리사2017_54-12-5","t":"채무자가 시효중단의 효력이 있는 승인을 하려면 채권자의 채권에 관한 처분의 능력이나 권한이 있어야 한다.","ox":"X","m":"⑤","c":"A","tp":"소멸시효"},{"y":2018,"e":"변리사 1차","qn":1,"i":"변리사2018_55-01-1","t":"부작위채권은 권리의 불행사가 있을 수 없으므로 소멸시효의 대상이 되지 않는다.","ox":"X","m":"①","c":"A"},{"y":2018,"e":"변리사 1차","qn":1,"i":"변리사2018_55-01-2","t":"주채무자가 시효완성의 이익을 포기한 경우 보증인은 주채무의 시효소멸을 원용할 수 없다.","ox":"X","m":"②","c":"A","tp":"소멸시효"},{"y":2018,"e":"변리사 1차","qn":1,"i":"변리사2018_55-01-3","t":"“시효의 중단은 당사자 및 그 승계인 간에만 효력이 있다”는 규정(민법 제169조) 에서 ‘승계인’에는 특정승계인이 포함되지 아니한다.","ox":"X","m":"③","c":"A","tp":"소멸시효"},{"y":2018,"e":"변리사 1차","qn":1,"i":"변리사2018_55-01-4","t":"기한을 정하지 않은 채권의 소멸시효의 기산점은 채권이 발생된 때가 아니라 이 행청구를 받은 때이다.","ox":"X","m":"④","c":"A"},{"y":2018,"e":"변리사 1차","qn":1,"i":"변리사2018_55-01-5","t":"단기 소멸시효에 걸리는 채권이라도 판결에 의하여 확정되면 그 소멸시효기간은 10년이다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"변리사 1차","qn":8,"i":"변리사2019_56-08-1","t":"제척기간이 경과하면 그 기산일에 소급하여 권리소멸의 효과가 발생한다.","ox":"X","m":"①","c":"A"},{"y":2019,"e":"변리사 1차","qn":8,"i":"변리사2019_56-08-2","t":"제척기간은 권리자의 청구나 압류 등이 있으면 중단되고 그때까지 경과된 기간은 산입 되지 않는다.","ox":"X","m":"②","c":"A"},{"y":2019,"e":"변리사 1차","qn":8,"i":"변리사2019_56-08-3","t":"점유보호청구권의 행사기간은 제척기간이기 때문에 점유보호청구권은 재판상·재판외에서 행사할 수 있다.","ox":"X","m":"③","c":"A"},{"y":2019,"e":"변리사 1차","qn":8,"i":"변리사2019_56-08-4","t":"제척기간이 지난 후에는 당사자가 책임질 수 없는 사유로 그 기간을 준수하지 못하였더라도 추후에 보완될 수 없다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"변리사 1차","qn":8,"i":"변리사2019_56-08-5","t":"채권양도의 통지는 그 양도인이 채권이 양도되었다는 사실을 채무자에게 알리는 행위 이므로, 채권양도의 통지만으로 제척기간의 준수에 필요한 권리의 재판외 행사가 이루어졌다고 볼 수 있다.","ox":"X","m":"⑤","c":"A"},{"y":2019,"e":"변리사 1차","qn":10,"i":"변리사2019_56-10-2","t":"甲이 乙을 사기죄로 고소하여 형사소송이 제기되었는데, 이 과정에서 배상명령을 신청하지 않은 경우에는 甲의 대여금채권의 소멸시효는 중단되지 않는다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"변리사 1차","qn":10,"i":"변리사2019_56-10-3","t":"甲이 乙을 상대로 대여금반환청구의 소를 제기하였다가 이후 그 소를 취하한 경우에도 甲의 대여금반환청구의 소제기로 인한 시효중단의 효력은 유지된다.","ox":"X","m":"③","c":"A"},{"y":2019,"e":"변리사 1차","qn":10,"i":"변리사2019_56-10-4","t":"乙의 재산에 대하여 甲의 가압류가 있는 경우에도 시효중단의 효력이 인정되지만, 당연무효의 가압류는 소멸시효의 중단사유에 해당하지 않는다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"변리사 1차","qn":10,"i":"변리사2019_56-10-5","t":"甲이 乙에게 대여금반환채무의 이행을 최고한 경우, 최고 후 6개월 내에 재판상의 청구를 하였다면 최고시에 시효중단의 효력이 발생한다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"변리사 1차","qn":6,"i":"변리사2021_58-06-1","t":"소멸시효에 관한 규정은 강행규정이지만, 법률행위에 의하여 경감할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"변리사 1차","qn":6,"i":"변리사2021_58-06-2","t":"공유물분할청구권은 공유관계가 존속하는 한 별도로 소멸시효가 진행되지 않는다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"변리사 1차","qn":6,"i":"변리사2021_58-06-3","t":"부당이득반환청구권의 소멸시효는 청구권이 성립한 때로부터 진행하고, 원칙적으로 권리의 존재나 발생을 알지 못하였다고 하더라도 소멸시효의 진행에 장애가 되지 않는다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"변리사 1차","qn":6,"i":"변리사2021_58-06-4","t":"부동산매수인이 소유권이전등기 없이 부동산을 인도받아 사용\u0001수익하다가 제3자에게 그 부동산을 처분하고 점유를 승계하여 준 경우, 소유권이전등기청구권의 소멸시효가 진행되지 않는다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"변리사 1차","qn":6,"i":"변리사2021_58-06-5","t":"원인채권의 지급을 확보하기 위하여 어음이 수수된 당사자 사이에 채권자가 어음채권에 관한 집행권원에 기하여 한 배당요구는 그 원인채권의 소멸시효를 중단시키는 효력이 없다.","ox":"X","m":"⑤","c":"A"},{"y":2023,"e":"변리사 1차","qn":5,"i":"변리사2023_60-05-1","t":"2023년 2월 10일(금요일) 오후 10시 30분부터 12시간이라고 한 경우, 기간의 만료점은 2023년 2월 11일(토요일) 오전 10시 30분이 된다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"변리사 1차","qn":5,"i":"변리사2023_60-05-2","t":"2004년 1월 17일 오후 2시에 태어난 甲이 성년이 되는 시점은 2023년 1월 17일 24시이다.","ox":"X","m":"②","c":"A"},{"y":2023,"e":"변리사 1차","qn":5,"i":"변리사2023_60-05-3","t":"2022년 11월 30일 오전 10시부터 3개월이라고 한 경우, 기간의 만료점은 2023년 2월 28일(화요일) 24시이다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"변리사 1차","qn":5,"i":"변리사2023_60-05-4","t":"2023년 5월 1일부터 10일간이라고 한 경우, 기간의 만료점은 2023년 5월 10일(수요일) 24시이다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"변리사 1차","qn":5,"i":"변리사2023_60-05-5","t":"사원총회소집일 1주일 전에 통지를 발송하도록 한 경우, 사원총회소집일이 2023년 3월 10일(금요일) 오후 2시면 소집통지를 늦어도 3월 2일 24시까지 발송하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"변리사 1차","qn":6,"i":"변리사2023_60-06","t":"소멸시효에 관한 설명으로 옳지 않은 것을 모두 고른 것은? (다툼이 있으면 판례","c":"A","mc":{"s":"소멸시효에 관한 설명으로 옳지 않은 것을 모두 고른 것은? (다툼이 있으면 판례","d":"에 따름)\nㄱ. 보험금청구권의 소멸시효는 보험계약자가 보험회사에 보험금을 청구한 때 로부터 진행한다.\nㄴ. 동일한 채권자에게 다수의 채무를 부담하는 채무자가 변제 충당을 지정하지 않고 일부 금원을 변제한 경우, 특별한 사정이 없는 한 그 변제는 모든 채무에 대한 승인으로서 소멸시효를 중단하는 효력이 있다.\nㄷ. 중첩적 채무인수에 의하여 인수인이 부담하는 채무에 대해서는 기존채무와 동일한 소멸시효기간이 적용된다.\nㄹ. 보험계약자가 보험금을 부정 취득할 목적으로 다수의 보험계약을 체결한 것이 민법 제103조(반사회질서의 법률행위)에 의해 무효로 된 경우, 보험 자가 지급한 보험금에 대한 부당이득반환청구권은 10년의 민사 소멸시효기간이 적용된다.","o":["ㄱ, ㄷ","ㄱ, ㄹ","ㄴ, ㄷ","ㄴ, ㄹ","ㄱ, ㄷ, ㄹ"],"a":2}},{"y":2024,"e":"변리사 1차","qn":12,"i":"변리사2024_61-12-1","t":"채권자가 채무자에게 등기우편으로 이행청구를 한 경우, 법에서 정한 후속수단을 취하지 않으면 그 이행청구만으로는 시효가 중단되지 않는다.","ox":"O","m":"①","c":"A","tp":"소멸시효 중단사유"},{"y":2024,"e":"변리사 1차","qn":12,"i":"변리사2024_61-12-2","t":"채권자가 채무자를 상대로 제기한 소송에서, 피고인 채무자에게 소송서류가 송달된 적이 없는 상태에서 판결이 선고되더라도 시효중단의 효력은 있다.","ox":"O","m":"②","c":"A","tp":"소멸시효 중단사유"},{"y":2024,"e":"변리사 1차","qn":12,"i":"변리사2024_61-12-3","t":"채무자가 채권자를 상대로 채무부존재확인소송을 제기하여 채권자가 이를 적극적으로 다툰 경우, 그 소가 법원에 접수된 때부터 시효중단의 효력이 인정된다.","ox":"X","m":"③","c":"A","tp":"소멸시효 중단사유"},{"y":2024,"e":"변리사 1차","qn":12,"i":"변리사2024_61-12-4","t":"채권양수인이 채무자를 상대로 소를 제기하였다가 채무자에 대한 양도통지가 없었다는 이유로 청구가 기각되어 확정된 후, 양도통지를 하고 그 확정된 때로부터 6개월 내에 다시 소를 제기한 경우, 시효중단의 효력은 전소(前訴)제기 시로 소급하여 발생한다.","ox":"O","m":"④","c":"A","tp":"소멸시효 중단사유"},{"y":2024,"e":"변리사 1차","qn":12,"i":"변리사2024_61-12-5","t":"채권자가 연대채무자의 1인에 대하여 가압류를 한 경우, 다른 연대채무자의 채무에 대해서는 시효가 중단되지 않는다.","ox":"O","m":"⑤","c":"A","tp":"소멸시효 중단사유"},{"y":2026,"e":"변리사 1차","qn":12,"i":"변리사2026_63-12","t":"채권에 대한 소멸시효가 중단되는 경우에 해당되지 않는 것은? (다툼이 있으면 판","c":"A","mc":{"s":"채권에 대한 소멸시효가 중단되는 경우에 해당되지 않는 것은? (다툼이 있으면 판","d":"례에 따름)","o":["피담보채무의 소멸을 이유로 물상보증인이 제기한 저당권설정등기의 말소를 구하는 소에 채권자 겸 저당권자가 응소하여 피담보채권의 존재를 주장한 경우","채권의 양수인이 채권양도의 대항요건을 갖추지 못한 상태에서 채무자를 상대로 재판상 청구를 한 경우","금전채권의 실현을 목적으로 채권자가 그 금전채권을 피담보채권으로 하여 근저당권 설정등기청구의 소를 제기한 경우","채권자가 채무자에 대하여 최고를 한 후, 6개월 이내에 채무자의 승인이 있는 경우","채권자가 채권에 대한 지급명령 신청이 각하된 후, 6개월 이내에 법원에 채무이행을 구하는 소를 제기한 경우"],"a":1}}],"5":[{"y":2016,"e":"변리사 1차","qn":13,"i":"변리사2016_53-13","t":"등기의 권리 추정력에 관한 설명으로 옳지 않은 것은? (다툼이 있으면 판례에","c":"A","mc":{"s":"등기의 권리 추정력에 관한 설명으로 옳지 않은 것은? (다툼이 있으면 판례에","d":"따름)","o":["甲이 X건물을 신축하였으나 그 건물이 乙 명의로 소유권보존등기가 된 경우,乙 명의의 보존등기에 대한 권리 추정력은 부정된다.","甲이 자신의 X건물을 乙에게 매도하고 소유권이전등기를 하여 준 경우, 乙은 제3자 뿐만 아니라 甲에 대해서도 적법한 등기원인에 의하여 소유권을 취득한 것으로 추정된다.","甲이 X건물에 대한 乙 명의의 소유권보존등기를 말소해 달라는 청구소송에서 승소 판결을 받아 그 보존등기를 말소하고 자신의 명의로 소유권보존등기를 마친 경우, 위 판결이 공시송달절차에 의한 것이더라도 甲 명의의 소유권보존등기는 적법한 것으로 추정된다.","甲 소유의 X건물을 乙이 丙에게 매도하고 소유권이전등기를 하여 준 경우, 丙이 乙을 甲의 대리인이라고 주장하면, 丙 명의의 등기가 원인무효임을 이유로 말소 하기 위해서는 甲이 乙에게 대리권이 없다는 사실을 증명하여야 한다.","미성년자인 甲이 자신의 X건물을 친권자 乙에게 증여하고 소유권이전등기를 하여 준 경우, 그 증여행위는 이해상반행위로서 특별한 사정이 없는 한 乙의 이전등기는 적법한 것으로 추정되지 않는다."],"a":5}},{"y":2017,"e":"변리사 1차","qn":17,"i":"변리사2017_54-17","t":"부동산 물권변동에 관한 설명으로 옳지 않은 것은? (다툼이 있으면 판례에","c":"A","mc":{"s":"부동산 물권변동에 관한 설명으로 옳지 않은 것은? (다툼이 있으면 판례에","d":"따름)","o":["소유권이전등기청구소송에서 승소판결이 확정된 경우에도 등기하여야 소유권을 취득한다.","전세권이 법정갱신된 경우, 전세권자는 등기 없이도 전세권설정자나 그 목적물을 취득한 제3자에 대하여 갱신된 권리를 주장할 수 있다.","신축건물의 보존등기를 건물 완성 전에 하였더라도 그 후 건물이 완성된 이상 그 등기는 무효가 아니다.","무허가건물의 신축자는 등기 없이 소유권을 원시취득하지만 이를 양도하는 경우에는 등기 없이 인도에 의하여 소유권을 이전할 수 없다.","공유물분할의 소에서 공유부동산의 특정한 일부씩을 각각의 공유자에게 귀속시 키는 것으로 현물분할하는 내용의 조정이 성립하였다면, 그 조정이 성립한 때 물권변동의 효력이 발생한다."],"a":5}},{"y":2017,"e":"변리사 1차","qn":18,"i":"변리사2017_54-18","t":"등기의 추정력에 관한 설명으로 옳지 않은 것은? (다툼이 있으면 판례에","c":"A","mc":{"s":"등기의 추정력에 관한 설명으로 옳지 않은 것은? (다툼이 있으면 판례에","d":"따름)","o":["소유권이전등기가 경료되어 있는 경우, 그 등기명의자는 제3자에 대하여서뿐만 아니라 그 전 소유자에 대하여서도 적법한 등기원인에 의하여 소유권을 취득한 것으로 추정된다.","허무인으로부터 등기를 이어받은 소유권이전등기는 원인무효이므로 그 등기명의 자에 대한 소유권추정은 깨어진다.","소유권이전등기의 원인으로 주장된 계약서가 진정하지 않은 것으로 증명된 경우 에도 등기는 적법한 것으로 추정된다.","등기가 원인 없이 말소된 경우에는 그 회복등기가 마쳐지기 전이라도 말소된 등 기의 등기명의인은 적법한 권리자로 추정된다.","신축된 건물의 소유권은 이를 건축한 사람이 원시취득하는 것이므로, 건물소유권 보존등기의 명의자가 이를 신축한 것이 아니라면 그 등기의 권리추정력은 깨어진다."],"a":3}},{"y":2018,"e":"변리사 1차","qn":13,"i":"변리사2018_55-13","t":"법률의 규정에 의한 부동산 물권변동에 관한 설명으로 옳지 않은 것은? (다","c":"A","mc":{"s":"법률의 규정에 의한 부동산 물권변동에 관한 설명으로 옳지 않은 것은? (다","d":"툼이 있으면 판례에 따름)","o":["상속재산인 부동산에 관하여 상속등기를 하지 않았더라도, 상속인은 상속이 개시된 때에 그 부동산의 소유권을 취득한다.","공용징수를 위한 수용절차에서 재결에 의하여 토지가 수용되는 경우, 보상금을 공탁한 사업시행자는 수용의 개시일에 그 토지의 소유권을 취득한다.","자기의 노력과 비용으로 건물을 신축한 자는 그 건축허가가 타인의 명의로 된경우에도 그 건물의 소유권을 원시취득한다.","공유물분할의 조정절차에서 공유자 사이에 공유토지에 대한 현물분할의 조정이 성립한 경우, 각 공유자는 조정에 기하여 지분이전등기를 마침으로써 분할된 부분에 대한 소유권을 취득한다.","민사집행법에 따른 경매를 통하여 부동산을 매수한 경우, 매수인은 경매법원의 촉탁에 의한 이전등기가 경료된 때에 소유권을 취득한다."],"a":5}},{"y":2018,"e":"변리사 1차","qn":18,"i":"변리사2018_55-18","t":"甲은 자신이 소유하는 건물을 乙에게 매도한 뒤 인도하였고, 乙은 이를 다시 丙에게 매도한 뒤 인도하였다. 이에 관한 설명으로 옳은 것은? (다툼이 있으","c":"A","mc":{"s":"甲은 자신이 소유하는 건물을 乙에게 매도한 뒤 인도하였고, 乙은 이를 다시 丙에게 매도한 뒤 인도하였다. 이에 관한 설명으로 옳은 것은? (다툼이 있으","d":"면 판례에 따름)","o":["乙이 무자력이 아닌 경우 丙은 乙의 甲에 대한 이전등기청구권을 대위행사할 수 없다.","甲, 乙, 丙 전원의 합의가 없더라도, 丙은 甲에게 직접 이전등기를 청구할 수 있다.","甲에서 직접 丙에게 이전등기하는 것에 관해 甲, 乙, 丙 전원의 합의가 있었으나, 甲과 乙 사이의 매매가 적법하게 합의해제된 경우, 甲은 丙의 이전등기청구를 거절할 수 없다.","甲에서 丙으로 직접 이전등기가 된 경우, 乙과 丙이 대금을 완제했더라도 甲은 중간생략등기의 합의가 없다는 이유로 丙 명의의 등기의 말소를 청구할 수 있다.","만약 乙이 甲으로부터 丙으로 이전등기하는 것에 동의했더라도, 乙은 甲에 대한 이전등기청구권을 잃지 않는다."],"a":5}},{"y":2018,"e":"변리사 1차","qn":19,"i":"변리사2018_55-19-2","t":"乙의 甲에 대한 본등기청구권은 乙의 가등기가 존속하는 동안 소멸시효에 걸리지 않는다.","ox":"X","m":"②","c":"A"},{"y":2018,"e":"변리사 1차","qn":19,"i":"변리사2018_55-19-3","t":"乙이 甲에게 본등기를 청구하여 乙 명의로 본등기가 이루어지면, 丙의 등기는 직권말소된다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"변리사 1차","qn":19,"i":"변리사2018_55-19-4","t":"乙이 가등기에 기한 본등기를 하면, 乙의 소유권취득의 효력은 가등기를 한 때로 소급한다.","ox":"X","m":"④","c":"A"},{"y":2018,"e":"변리사 1차","qn":19,"i":"변리사2018_55-19-5","t":"丙 명의의 소유권이전등기가 원인무효라면 가등기권리자인 乙이 직접 그 말소를 구할 수 있다.","ox":"X","m":"⑤","c":"A"},{"y":2019,"e":"변리사 1차","qn":14,"i":"변리사2019_56-14-1","t":"점유권은 혼동이나 소멸시효에 의해 소멸하지 않는다.","ox":"O","m":"①","c":"A","tp":"물권의 소멸"},{"y":2019,"e":"변리사 1차","qn":14,"i":"변리사2019_56-14-2","t":"소유권은 소멸시효에 의해 소멸하지 않지만, 타인이 시효취득하면 상대적으로 소멸할 수 있다.","ox":"O","m":"②","c":"A","tp":"물권의 소멸"},{"y":2019,"e":"변리사 1차","qn":14,"i":"변리사2019_56-14-3","t":"전세권에 저당권이 설정된 경우, 전세목적물에 대한 소유권과 전세권이 동일인에게 귀속되더라도 전세권은 혼동에 의해 소멸하지 않는다.","ox":"O","m":"③","c":"A","tp":"물권의 소멸"},{"y":2019,"e":"변리사 1차","qn":14,"i":"변리사2019_56-14-4","t":"후순위 저당권이 있는 부동산의 소유권을 선순위 저당권자가 아무런 조건 없이 증여 받아 취득한 경우, 혼동에 의해 저당권은 소멸한다.","ox":"X","m":"④","c":"A","tp":"물권의 소멸"},{"y":2019,"e":"변리사 1차","qn":14,"i":"변리사2019_56-14-5","t":"부동산공유자의 공유지분포기의 의사표시가 다른 공유자에게 도달하더라도 그 공유지분이 바로 소멸하는 것은 아니고, 다른 공유자는 자신에게 귀속될 공유지분에 관하여 소유권이전등기를 청구할 수 있을 뿐이다.","ox":"O","m":"⑤","c":"A","tp":"물권의 소멸"},{"y":2021,"e":"변리사 1차","qn":15,"i":"변리사2021_58-15-1","t":"본등기에 의한 물권변동의 효력은 가등기를 한 때에 소급하여 발생한다.","ox":"X","m":"①","c":"A"},{"y":2021,"e":"변리사 1차","qn":15,"i":"변리사2021_58-15-2","t":"등기가 원인 없이 말소된 경우, 그 회복등기가 마쳐지기 전이라도 말소된 등기의 등 기명의인은 적법한 권리자로 추정된다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"변리사 1차","qn":15,"i":"변리사2021_58-15-3","t":"합유자가 그 지분을 포기하면 지분권 이전등기를 하지 않더라도, 포기된 합유지분은 나머지 잔존 합유지분권자들에게 물권적으로 귀속하게 된다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"변리사 1차","qn":15,"i":"변리사2021_58-15-4","t":"매매로 인한 소유권이전등기에서 등기명의자가 등기원인을 증여로 주장하였다면 등기의 추정력은 깨어진다.","ox":"X","m":"④","c":"A"},{"y":2021,"e":"변리사 1차","qn":15,"i":"변리사2021_58-15-5","t":"사망자 명의로 신청하여 이루어진 이전등기도 특별한 사정이 없는 한 등기의 추정력이 인정되므로, 등기의 무효를 주장하는 자가 현재의 실체관계에 부합하지 않음을 증명하여야 한다.","ox":"X","m":"⑤","c":"A"},{"y":2021,"e":"변리사 1차","qn":16,"i":"변리사2021_58-16-2","t":"乙은 丙에 대하여 소유권에 기한 방해배제청구권을 행사할 수 없지만, 甲의 소유권에 기한 방해배제청구권을 대위 행사할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"변리사 1차","qn":16,"i":"변리사2021_58-16-3","t":"丙이 X토지를 자신의 것으로 오신하여 건축폐자재를 적치한 경우라 하더라도, 乙은 丙에 대하여 점유권에 기한 방해배제청구권을 행사할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"변리사 1차","qn":16,"i":"변리사2021_58-16-4","t":"甲은 丙에 대하여 점유권에 기한 방해배제청구권을 행사할 수 없지만, 乙의 점유권에 기한 방해배제청구권을 대위 행사할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2021,"e":"변리사 1차","qn":16,"i":"변리사2021_58-16-5","t":"X토지에 대한 임대차 계약이 종료되면 甲은 乙에 대하여 임대차 계약상 반환청구권을 행사할 수 있는데, 이는 채권적 청구권으로 물권적 청구권과 별개로 행사할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"변리사 1차","qn":14,"i":"변리사2023_60-14-1","t":"미등기건물에 대한 양도담보계약상의 채권자의 지위를 승계하여 건물을 관리하고 있는 자는 그 건물에 대한 철거처분권을 가진 자에 해당한다.","ox":"X","m":"①","c":"A","tp":"물권변동"},{"y":2023,"e":"변리사 1차","qn":14,"i":"변리사2023_60-14-2","t":"부동산 합유지분의 포기가 적법하더라도 그에 관한 등기가 경료되지 않았다면 그 포기된 합유지분은 나머지 잔존 합유지분권자들에게 귀속되지 않는다.","ox":"O","m":"②","c":"A","tp":"물권변동"},{"y":2023,"e":"변리사 1차","qn":14,"i":"변리사2023_60-14-3","t":"동산의 선의취득에서 물권적 합의가 동산의 인도보다 먼저 행하여진 경우 양수인의 선의\u0001무과실의 판단시점은 인도된 때를 기준으로 한다.","ox":"O","m":"③","c":"A","tp":"물권변동"},{"y":2023,"e":"변리사 1차","qn":14,"i":"변리사2023_60-14-4","t":"소유권이전의 약정을 내용으로 하는 화해조서는 민법 제187조(등기를 요하지 아니하는 부동산물권취득)의 판결에 포함되지 않는다.","ox":"O","m":"④","c":"A","tp":"물권변동"},{"y":2023,"e":"변리사 1차","qn":14,"i":"변리사2023_60-14-5","t":"공유물분할의 조정절차에서 공유자 사이에 공유토지에 관한 현물분할의 협의가 성립 하여 그 합의사항을 조서에 기재함으로써 조정이 성립하더라도 등기없이 그 협의에 따른 새로운 법률관계가 창설되는 것은 아니다.","ox":"O","m":"⑤","c":"A","tp":"물권변동"},{"y":2023,"e":"변리사 1차","qn":16,"i":"변리사2023_60-16","t":"부동산에 관한 등기 또는 등기청구권 등에 관한 설명으로 옳지 않은 것은? (다툼","c":"A","mc":{"s":"부동산에 관한 등기 또는 등기청구권 등에 관한 설명으로 옳지 않은 것은? (다툼","d":"이 있으면 판례에 따름)","o":["甲→乙→丙의 순으로 매매계약이 체결된 경우, 3자간 중간생략등기의 합의가 있더라도 乙의 甲에 대한 소유권이전등기청구권이 소멸되는 것은 아니다.","가등기에 의하여 순위 보전의 대상이 되어 있는 물권변동청구권이 양도된 경우, 양도 인과 양수인의 공동신청으로 그 가등기상 권리의 이전등기를 가등기에 대한 부기등기 의 형식으로 경료할 수 있다.","무효인 3자간 등기명의신탁에서 부동산을 매수하여 인도받아 계속 점유하는 명의신탁 자의 매도인에 대한 소유권이전등기청구권은 소멸시효에 걸리지 않는다.","매수인의 매도인에 대한 소유권이전청구권 보전을 위한 가등기가 경료된 경우, 소유권이전등기를 청구할 어떤 법률관계가 있다고 추정되지 않는다.","｢임야소유권 이전등기에 관한 특별조치법｣ 에 의한 소유권보존등기가 경료된 임야에 관하여 그 임야를 사정받은 사람이 따로 있는 것이 사후에 밝혀졌다면, 그 등기는 실체적 권리관계에 부합하는 등기로 추정되지 않는다."],"a":5}},{"y":2024,"e":"변리사 1차","qn":13,"i":"변리사2024_61-13","t":"부동산소유권의 변동을 위해 등기를 요하는 것을 모두 고른 것은? (다툼이 있으면","c":"A","mc":{"s":"부동산소유권의 변동을 위해 등기를 요하는 것을 모두 고른 것은? (다툼이 있으면","d":"판례에 따름)\nㄱ. 甲이 자기 소유의 X토지를 친구 乙에게 사인증여한 후, 甲이 사망하여 乙이 X토지를 취득하는 경우ㄴ. 甲\u0001乙\u0001丙 3인으로 구성된 조합에서 甲이 X토지에 관한 합유지분을 포기 하여 그의 지분이 乙과 丙에게 균분으로 귀속하는 경우ㄷ. 甲이 X토지에 관해 乙에게 소를 제기하여 법원으로부터 ‘乙은 甲에게 2023. 2. 1.자 매매계약을 원인으로 한 X토지의 소유권이전등기절차를 이행하라’ 는 확정판결을 받아 이에 기해 甲이 소유권을 취득하는 경우ㄹ. 甲 소유의 X토지를 乙이 20년간 소유의 의사로 평온\u0001공연하게 점유하여 점유취득시효의 요건이 완성되어 乙이 소유권을 취득하는 경우","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄷ, ㄹ","ㄴ, ㄷ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":5}},{"y":2026,"e":"변리사 1차","qn":13,"i":"변리사2026_63-13","t":"등기를 해야만 부동산물권 변동의 효력이 생기는 것은?","c":"A","mc":{"s":"등기를 해야만 부동산물권 변동의 효력이 생기는 것은?","d":"","o":["甲을 상속한 乙이 甲 소유의 X토지를 상속한 경우","甲이 乙의 소유명의로 등기되어 있는 X토지에 관한 소유권확인의 소에서 승소 판결을 받은 경우","甲 소유의 X토지를 보상금 지급을 정지조건으로 재결수용에 의해 乙이 수용한 경우","甲 소유의 X토지를 乙이 공매로 낙찰받고 매각대금을 완납한 경우","甲 소유의 X토지 위에 설정된 乙의 저당권의 피담보채권이 모두 변제된 경우"],"a":2}},{"y":2026,"e":"변리사 1차","qn":14,"i":"변리사2026_63-14-1","t":"부동산 매수인이 그 목적물을 인도받아서 이를 사용\u0001수익하고 있는 경우에는 그 매수인의 소유권이전등기청구권은 소멸시효에 걸리지 않는다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"변리사 1차","qn":14,"i":"변리사2026_63-14-2","t":"신축 중인 건물에 관한 소유권이전등기청구권의 소멸시효는 건물완공시부터 기산한다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"변리사 1차","qn":14,"i":"변리사2026_63-14-3","t":"토지에 대한 점유취득시효가 완성된 후 점유자가 그 토지에 대한 점유를 상실하면 특별한 사정이 없는 한 시효완성을 원인으로 한 소유권이전등기청구권도 즉시 소멸한다.","ox":"X","m":"③","c":"A"},{"y":2026,"e":"변리사 1차","qn":14,"i":"변리사2026_63-14-4","t":"채권담보의 목적으로 이루어진 부동산 양도담보에 있어서 피담보채무가 변제된 이후에 양도담보권설정자가 행사하는 소유권이전등기청구권은 물권적 청구권으로서 시효로 소멸하지 아니한다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"변리사 1차","qn":14,"i":"변리사2026_63-14-5","t":"부동산에 관하여 무효인 등기가 경료된 경우, 그 무효등기의 말소등기청구권과 말소 등기청구에 갈음하여 하는 진정명의회복을 위한 소유권이전등기청구권의 법적 성질은 모두 소유권에 기한 방해배제청구권이다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"변리사 1차","qn":17,"i":"변리사2026_63-17-1","t":"甲의 X토지에 乙이 1번 저당권, 丙이 2번 저당권을 취득하고 丁이 X토지를 가압류 한후에 丙이 X토지의 소유권을 취득한 경우, 丙의 저당권은 혼동으로 소멸하지 않는다.","ox":"O","m":"①","c":"A","tp":"물권의 소멸"},{"y":2026,"e":"변리사 1차","qn":17,"i":"변리사2026_63-17-2","t":"토지임차권이 대항요건을 갖춘 후에 그 토지에 제3자의 저당권이 설정된 경우, 토지 소유권과 임차권이 동일인에게 귀속하더라도 물권의 혼동 규정이 준용되어 임차권은 소멸하지 않는다.","ox":"O","m":"②","c":"A","tp":"물권의 소멸"},{"y":2026,"e":"변리사 1차","qn":17,"i":"변리사2026_63-17-3","t":"부동산의 공유자 일부의 공유지분 포기에 따른 물권변동은 다른 공유자 명의로 지분 이전등기를 하여야 그 효력이 발생한다.","ox":"O","m":"③","c":"A","tp":"물권의 소멸"},{"y":2026,"e":"변리사 1차","qn":17,"i":"변리사2026_63-17-4","t":"유치권자가 유치권을 포기하기로 한 경우, 유치물을 채무자에게 인도하여야 그 유치권이 소멸한다.","ox":"X","m":"④","c":"A","tp":"물권의 소멸"},{"y":2026,"e":"변리사 1차","qn":17,"i":"변리사2026_63-17-5","t":"근저당권자가 저당목적물의 소유권을 취득함으로써 근저당권이 혼동으로 소멸하더라도, 그 소유권취득이 무효인 것으로 밝혀지면 소멸하였던 근저당권은 당연히 부활한다.","ox":"O","m":"⑤","c":"A","tp":"물권의 소멸"}],"6":[{"y":2016,"e":"변리사 1차","qn":14,"i":"변리사2016_53-14","t":"甲은 무단으로 자신의 명의로 X토지에 관한 소유권보존등기를 하고 있다가, 매매를 원인으로 하여 乙 명의로 소유권을 이전해주었다. 그런데 X토지의 정당한 소유자 丙이 甲에 대해서는 소유권보존등기말소를, 乙에 대해서는 소유권이전등기 말소를 구하는 소를 제기하였다. 이 소송에서 법원은 甲 명의의 소유권보존등기는 원인무효이므로 그 말소등기절차를 이행할 의무가 있지만, 乙 명의의 소유권이전등기에 대해서는 등기부취득시효가 완성되어 실체관계에 부합하는 유효한 등기라고 판시하였고, 이 판결은 곧 확정되었다. 이에 대한 설명으로 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"甲은 무단으로 자신의 명의로 X토지에 관한 소유권보존등기를 하고 있다가, 매매를 원인으로 하여 乙 명의로 소유권을 이전해주었다. 그런데 X토지의 정당한 소유자 丙이 甲에 대해서는 소유권보존등기말소를, 乙에 대해서는 소유권이전등기 말소를 구하는 소를 제기하였다. 이 소송에서 법원은 甲 명의의 소유권보존등기는 원인무효이므로 그 말소등기절차를 이행할 의무가 있지만, 乙 명의의 소유권이전등기에 대해서는 등기부취득시효가 완성되어 실체관계에 부합하는 유효한 등기라고 판시하였고, 이 판결은 곧 확정되었다. 이에 대한 설명으로 옳은 것을 모두 고른 것은?","d":"ㄱ. 丙의 甲에 대한 소유권보존등기말소청구는 소유권에 기한 방해배제청구권의 성격을 갖는다.\nㄴ. 丙의 甲에 대한 소유권보존등기말소청구가 승소판결로 확정되었더라도 그 청구권의 법적 성격이 채권적 청구권으로 바뀌지는 않는다.\nㄷ. 丙은 甲에 대하여 불법행위를 이유로 손해배상을 청구할 수 있다.\nㄹ. 丙은 甲에 대하여 이행불능에 근거하여 X토지의 시가 상당액에 대한 전보배상을 청구할 수 있다.","o":["ㄱ, ㄴ","ㄷ, ㄹ","ㄱ, ㄴ, ㄷ","ㄴ, ㄷ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":3}},{"y":2016,"e":"변리사 1차","qn":15,"i":"변리사2016_53-15","t":"甲은 2015년 초에 乙소유의 X토지를 매입하면서, 친구인 丙이 乙과의 매매계약을 통하여 丙 명의로 소유권이전등기를 하되 나중에 甲이 원하면 甲의 명의로 X토지의 소유권을 이전해 주기로 丙과 합의한 후, 매매대금 명목으로 丙에게 5억원을 건네주었다. 수일 후 丙은 이러한 사정을 모르는 乙과 매매계약을 체결하고 같은 날 丙 명의의 소유권이전등기를 마쳤다. 그 후 丙이 X토지의 소유관계를 알고 있는 丁에게 매각하고 소유권이전등기를 넘겨주었다. 이에 대한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"甲은 2015년 초에 乙소유의 X토지를 매입하면서, 친구인 丙이 乙과의 매매계약을 통하여 丙 명의로 소유권이전등기를 하되 나중에 甲이 원하면 甲의 명의로 X토지의 소유권을 이전해 주기로 丙과 합의한 후, 매매대금 명목으로 丙에게 5억원을 건네주었다. 수일 후 丙은 이러한 사정을 모르는 乙과 매매계약을 체결하고 같은 날 丙 명의의 소유권이전등기를 마쳤다. 그 후 丙이 X토지의 소유관계를 알고 있는 丁에게 매각하고 소유권이전등기를 넘겨주었다. 이에 대한 설명으로 옳지 않은 것은?","d":"","o":["甲과 丙 사이의 합의는 무효이다.","丙은 X토지의 소유권을 적법하게 취득한다.","丁은 X토지의 소유권을 적법하게 취득한다.","甲의 丙에 대한 부당이득반환청구로서 X토지의 소유권을 甲에게 이전하라는 것은 허용되지 않는다.","甲은 丙에게 지급한 매수자금 5억원의 반환을 청구할 수 없다."],"a":5}},{"y":2016,"e":"변리사 1차","qn":16,"i":"변리사2016_53-16","t":"甲, 乙, 丙이 X토지를 각각 4:2:1의 지분비율로 공유하고 있다. 이에 관한 설명으로 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"甲, 乙, 丙이 X토지를 각각 4:2:1의 지분비율로 공유하고 있다. 이에 관한 설명으로 옳은 것을 모두 고른 것은?","d":"ㄱ. 乙이 甲, 丙과 협의 없이 X토지 지상에 Y건물을 신축한 경우, 丙은 乙에게 Y건물의 철거 및 X토지의 인도를 청구할 수 있다.\nㄴ. 乙과 丙으로부터 X토지를 임차한 丁은 이에 동의하지 않은 甲에게 임대차의 효력을 주장할 수 있다.\nㄷ. 甲이 X토지의 개량을 위하여 단독으로 丁과 공사계약을 체결하면서 공사 비용을 甲 자신이 전액 지급하기로 약정하였더라도, 乙과 丙 역시 丁에게 그들의 지분에 상응하는 공사비를 지급할 의무를 부담한다.\nㄹ. 甲, 乙, 丙이 X토지를 구분소유하는 경우 甲의 공유지분 위에 근저당권이 설정된 후 구분소유적 공유관계가 해소되어 각자의 단독소유로 분할되었다면, 그 근저당권은 甲의 단독소유로 분할된 토지에 집중된다.","o":["ㄱ","ㄱ, ㄴ","ㄱ, ㄹ","ㄱ, ㄷ, ㄹ","ㄴ, ㄷ, ㄹ"],"a":1}},{"y":2016,"e":"변리사 1차","qn":17,"i":"변리사2016_53-17","t":"甲소유의 X건물을 임차하여 점유한 乙이 丙과 도급계약을 체결하고 X건물을 수리하게 하여 그 건물의 가치가 증가하였다. 이 사안에 관한 설명으로 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"甲소유의 X건물을 임차하여 점유한 乙이 丙과 도급계약을 체결하고 X건물을 수리하게 하여 그 건물의 가치가 증가하였다. 이 사안에 관한 설명으로 옳은 것을 모두 고른 것은?","d":"ㄱ. 丙이 X건물을 수리하던 중 丁이 무단으로 X건물에 침입한 경우, 乙은 丁을 상대로 X건물의 점유권에 근거하여 방해배제를 청구할 수 없다.\nㄴ. 丙은 甲을 상대로 수리비 상당액의 부당이득반환을 청구할 수 없다.\nㄷ. 丙은 민법 제203조에 따라 甲을 상대로 수리비 상당의 비용상환을 청구할 수 있다.\nㄹ. 甲이 X건물의 소유권을 戊에게 이전한 경우, 乙은 민법 제203조에 따라 戊를 상대로 수리비 상당의 비용상환을 청구할 수 있다.","o":["ㄱ","ㄴ","ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"a":2}},{"y":2017,"e":"변리사 1차","qn":13,"i":"변리사2017_54-13-1","t":"자연인이나 법인뿐만 아니라 권리능력 없는 사단도 시효취득의 주체가 될 수 있다.","ox":"O","m":"①","c":"A","tp":"점유취득시효"},{"y":2017,"e":"변리사 1차","qn":13,"i":"변리사2017_54-13-2","t":"취득시효 완성으로 인한 소유권취득의 효력은 점유를 개시한 때에 소급한다.","ox":"O","m":"②","c":"A","tp":"점유취득시효"},{"y":2017,"e":"변리사 1차","qn":13,"i":"변리사2017_54-13-3","t":"토지에 대한 취득시효가 완성된 후 토지소유자가 그 토지 위에 담장을 설치한 경우, 시효완성자는 소유권에 기한 방해배제청구권의 행사로서 토지소유자를 상대로 담장의 철거를 청구할 수 없다.","ox":"O","m":"③","c":"A","tp":"점유취득시효"},{"y":2017,"e":"변리사 1차","qn":13,"i":"변리사2017_54-13-4","t":"취득시효기간의 완성 전에 등기부상의 소유명의가 변경되었다 하더라도 이는 취득시효의 중단사유가 될 수 없다.","ox":"O","m":"④","c":"A","tp":"점유취득시효"},{"y":2017,"e":"변리사 1차","qn":13,"i":"변리사2017_54-13-5","t":"미등기 부동산의 경우, 점유자가 취득시효기간의 완성만으로 등기 없이 소유권을 취득한다.","ox":"X","m":"⑤","c":"A","tp":"점유취득시효"},{"y":2017,"e":"변리사 1차","qn":14,"i":"변리사2017_54-14","t":"총유에 관한 설명으로 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"총유에 관한 설명으로 옳은 것을 모두 고른 것은?","d":"ㄱ. 총유물에 관한 사원의 의무는 사원의 지위를 상실함으로써 상실된다.\nㄴ. 총유물의 관리는 정관 기타 규약에 달리 정한 바가 없으면 사원총회의 결의에 의한다.\nㄷ. 종중이 그 총유재산에 대한 보존행위로서 소송을 하는 경우에도 특별한 사정이 없는 한, 종중총회에서 전체 종원 과반수 이상의 결의를 거쳐야 한다.\nㄹ. 비법인사단이 정관에 다른 정함이 있다는 등의 특별한 사정이 없음에도 불구하고 사원총회 결의 없이 총유재산의 처분에 관하여 자기 명의로 제기한 소송은 소송요건의 흠결로서 부적법하다.","o":["ㄱ, ㄷ","ㄱ, ㄴ, ㄹ","ㄱ, ㄷ, ㄹ","ㄴ, ㄷ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":2}},{"y":2017,"e":"변리사 1차","qn":16,"i":"변리사2017_54-16","t":"점유의 추정에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면 판","c":"A","mc":{"s":"점유의 추정에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면 판","d":"례에 따름)\nㄱ. 선의의 점유자라도 본권에 관한 소에 패소한 때에는 그 소가 제기된 때 로부터 악의의 점유자로 본다.\nㄴ. 전후 양 시점에 점유한 사실이 있는 때에는 그 점유는 계속한 것으로 추정되지만, 전후 양 시점의 점유자가 다른 경우에는 점유의 승계가 입증되더라도 점유계속은 추정되지 않는다.\nㄷ. 점유의 승계가 있는 경우, 전 점유자의 점유가 타주점유라 하여도 점유자의 승계인이 자기의 점유만을 주장하는 경우에는 현 점유자의 점유는 자주점유로 추정된다.\nㄹ. 점유자는 소유의 의사로 선의\u0001무과실, 평온 및 공연하게 점유한 것으로 추정한다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄷ, ㄹ","ㄱ, ㄷ, ㄹ","ㄴ, ㄷ, ㄹ"],"a":2}},{"y":2018,"e":"변리사 1차","qn":14,"i":"변리사2018_55-14-1","t":"甲이 그 소유건물을 乙에게 임대함으로써 현실적으로 건물이나 그 부지를 점거 하고 있지 않으면, 甲은 그 부지를 점유한다고 볼 수 없다.","ox":"X","m":"①","c":"A"},{"y":2018,"e":"변리사 1차","qn":14,"i":"변리사2018_55-14-2","t":"甲이 신축한 미등기건물을 양수하여 건물에 대한 사실상의 처분권을 보유하게된 乙은 그 건물의 부지도 함께 점유하고 있다고 볼 수 있다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"변리사 1차","qn":14,"i":"변리사2018_55-14-3","t":"甲이 신축한 건물의 경비원 乙이 甲의 지시를 받아 건물을 사실상 지배하고 있더라도 특별한 사정이 없는 한 乙은 그 건물의 점유자가 되지 못한다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"변리사 1차","qn":14,"i":"변리사2018_55-14-5","t":"甲 명의로 토지에 대한 소유권보존등기를 마쳤다면, 특별한 사정이 없는 한 甲이 그 등기 당시 그 토지의 점유를 이전받았다고 인정할 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"변리사 1차","qn":15,"i":"변리사2018_55-15","t":"甲 명의로 등기된 甲 소유 토지에 관해 乙이 관계서류를 위조하여 자기 명의로 이전등기를 한 뒤 丙에게 임대하였고, 丙은 그 토지 위에 주택을 완성하여 보존등기를 하고 현재까지 그 주택에 거주하고 있다. 이에 관한 설명으로 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"甲 명의로 등기된 甲 소유 토지에 관해 乙이 관계서류를 위조하여 자기 명의로 이전등기를 한 뒤 丙에게 임대하였고, 丙은 그 토지 위에 주택을 완성하여 보존등기를 하고 현재까지 그 주택에 거주하고 있다. 이에 관한 설명으로 옳은 것을 모두 고른 것은?","d":"ㄱ. 甲은 丙을 상대로 주택으로부터의 퇴거를 청구할 수 있다.\nㄴ. 甲은 乙을 상대로 토지에 대한 소유권이전등기를 청구할 수 있다.\nㄷ. 甲은 丙을 상대로 주택의 철거를 청구할 수 있다.\nㄹ. 만약 丁이 그 주택을 丙으로부터 임차하여 주민등록을 마치고 그 주택에 거주하고 있다면, 甲은 丁을 상대로 퇴거를 청구할 수 있다.","o":["ㄱ, ㄴ","ㄱ, ㄹ","ㄴ, ㄷ","ㄴ, ㄷ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":4}},{"y":2018,"e":"변리사 1차","qn":17,"i":"변리사2018_55-17-1","t":"취득시효 완성 후 등기 경료 전에 그 부동산이 제3자에게 명의신탁된 경우, 점유자는 시효완성을 이유로 그 제3자의 소유권 행사를 저지할 수 없다.","ox":"X","m":"①","c":"A","tp":"점유취득시효"},{"y":2018,"e":"변리사 1차","qn":17,"i":"변리사2018_55-17-2","t":"취득시효 기간의 계산에 있어 시효기간 동안 소유자에 변경이 없는 경우에는 그 기산점을 어디에 두던지 간에 취득시효 완성을 주장할 수 있는 시점에서 보아 그 기간이 경과된 사실이 확정되면 된다.","ox":"O","m":"②","c":"A","tp":"점유취득시효"},{"y":2018,"e":"변리사 1차","qn":17,"i":"변리사2018_55-17-3","t":"甲의 취득시효 완성 당시 미등기로 남아 있던 토지의 소유자가 취득시효 완성 후에 그 명의로 소유권보존등기를 마쳤다면, 甲은 토지소유자에 대하여 취득시효의 완성을 주장할 수 없다.","ox":"X","m":"③","c":"A","tp":"점유취득시효"},{"y":2018,"e":"변리사 1차","qn":17,"i":"변리사2018_55-17-4","t":"국유재산이 일반재산이던 당시에 취득시효가 완성되었다면 그 후 행정재산으로 되었다고 하더라도 시효취득을 원인으로 하는 소유권이전등기를 청구할 수 있다.","ox":"X","m":"④","c":"A","tp":"점유취득시효"},{"y":2018,"e":"변리사 1차","qn":17,"i":"변리사2018_55-17-5","t":"점유자가 취득시효기간이 경과한 후 소유자와의 분쟁을 간편하게 해결하기 위하여 상대방에게 매수제의를 하였다면, 점유자의 점유는 타주점유로 전환된다.","ox":"X","m":"⑤","c":"A","tp":"점유취득시효"},{"y":2018,"e":"변리사 1차","qn":20,"i":"변리사2018_55-20-1","t":"甲 소유의 동산을 乙이 丙에게 양도하고 丙이 다시 丁에게 양도한 경우, 만약 丙의 선의취득이 인정된다면 丁의 선의취득 여부는 문제되지 않는다.","ox":"O","m":"①","c":"A","tp":"동산 선의취득"},{"y":2018,"e":"변리사 1차","qn":20,"i":"변리사2018_55-20-2","t":"반환청구권의 양도에 의한 소유권의 양도의 경우에는 대항요건을 갖추었더라도 선의취득이 인정되지 않는다.","ox":"X","m":"②","c":"A","tp":"동산 선의취득"},{"y":2018,"e":"변리사 1차","qn":20,"i":"변리사2018_55-20-3","t":"甲이 자신의 소유 동산을 乙에게 매도하여 인도하고, 乙이 다시 丙에게 매도하여 인도한 경우, 甲과 乙의 매매가 사회질서에 반하여 무효라면 丙은 선의, 무과 실이더라도 선의취득할 수 없다.","ox":"X","m":"③","c":"A","tp":"동산 선의취득"},{"y":2018,"e":"변리사 1차","qn":20,"i":"변리사2018_55-20-4","t":"점유보조자가 횡령한 물건은 민법 제250조(도품, 유실물에 대한 특례)의 도품에 해당한다.","ox":"X","m":"④","c":"A","tp":"동산 선의취득"},{"y":2018,"e":"변리사 1차","qn":20,"i":"변리사2018_55-20-5","t":"甲 소유 동산을 점유하는 乙이 丙에게 매도함과 동시에 丙으로부터 임차하기로 약정한 경우 丙은 현실인도를 받기 전이라도 그 동산을 선의취득할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"동산 선의취득"},{"y":2018,"e":"변리사 1차","qn":22,"i":"변리사2018_55-22-1","t":"제3자가 공유물의 이용을 방해하고 있는 경우 각 공유자는 그의 지분에 기하여 단독으로 공유물 전부에 대한 방해의 제거를 청구할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"변리사 1차","qn":22,"i":"변리사2018_55-22-2","t":"제3자가 공유물의 이용을 방해하고 있는 경우 각 공유자는 제3자에 대하여 자신의 지분의 비율에 해당하는 부분에 한하여 부당이득의 반환을 청구할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"변리사 1차","qn":22,"i":"변리사2018_55-22-3","t":"공유물분할의 소는 공유자 전원이 당사자로 되어야 하므로, 원고를 제외한 공유자 모두가 피고로 된다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"변리사 1차","qn":22,"i":"변리사2018_55-22-4","t":"부동산 공유자의 공유지분 포기의 의사표시가 다른 공유자에게 도달하더라도 등 기를 하여야 공유지분 포기에 따른 물권변동의 효력이 발생한다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"변리사 1차","qn":22,"i":"변리사2018_55-22-5","t":"공유자 중 1인이 다른 공유자의 동의 없이 공유토지 전부를 매도하여 타인 명의로 소유권이전등기가 마쳐진 경우, 다른 공유자는 그 공유물 전부에 관해 소유권이전등기의 말소를 청구할 수 있다.","ox":"X","m":"⑤","c":"A"},{"y":2019,"e":"변리사 1차","qn":13,"i":"변리사2019_56-13-5","t":"X토지를 제3자가 불법점유하고 있다면, 丙은 제3자에 대하여 소유권에 기한 물권적 청구권을 행사할 수 있다.","ox":"X","m":"⑤","c":"A"},{"y":2019,"e":"변리사 1차","qn":15,"i":"변리사2019_56-15-1","t":"취득시효기간 만료 전에 등기부상 소유명의가 변경된 사실은 취득시효의 중단사유가될 수 없다.","ox":"O","m":"①","c":"A","tp":"취득시효 중단"},{"y":2019,"e":"변리사 1차","qn":15,"i":"변리사2019_56-15-2","t":"취득시효의 중단사유인 재판상 청구에는 소유권 침해의 경우, 그 소유권을 기초로 하는 방해배제 및 손해배상 또는 부당이득반환청구소송도 포함된다.","ox":"O","m":"②","c":"A","tp":"취득시효 중단"},{"y":2019,"e":"변리사 1차","qn":15,"i":"변리사2019_56-15-3","t":"취득시효를 주장하는 자가 소를 제기한 데 대하여 권리자가 피고로서 응소하고 그 소송에서 적극적으로 권리를 주장하여 그것이 받아들여진 경우에는 시효중단사유인 재판상 청구에 해당한다.","ox":"O","m":"③","c":"A","tp":"취득시효 중단"},{"y":2019,"e":"변리사 1차","qn":15,"i":"변리사2019_56-15-4","t":"시효중단의 효력은 당사자 및 그 승계인에 미치므로, 그 중단효과가 발생한 후의 특정승계인 또는 포괄승계인은 중단 당시의 당사자의 점유기간을 승계하여 시효취득을 주장할 수 없다.","ox":"O","m":"④","c":"A","tp":"취득시효 중단"},{"y":2019,"e":"변리사 1차","qn":15,"i":"변리사2019_56-15-5","t":"소유권이전등기의 말소를 구하는 소를 제기하였다가 그 소를 취하한 후, 그로부터 6개월 내에 다시 취하된 소와 동일한 내용의 소를 제기한 경우, 후소가 제기된 때로부터 취득시효의 진행이 중단된다.","ox":"X","m":"⑤","c":"A","tp":"취득시효 중단"},{"y":2019,"e":"변리사 1차","qn":17,"i":"변리사2019_56-17","t":"甲 소유의 산악자전거를 乙이 훔쳐 보관하던 중, 선의이지만 과실이 있는 丙에게 팔고 인도하였다. 며칠 후 甲은 丙이 자신의 자전거를 가지고 있는 것을 발견하여 이를 자력으로써 탈환하였다. 이에 관한 설명으로 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"甲 소유의 산악자전거를 乙이 훔쳐 보관하던 중, 선의이지만 과실이 있는 丙에게 팔고 인도하였다. 며칠 후 甲은 丙이 자신의 자전거를 가지고 있는 것을 발견하여 이를 자력으로써 탈환하였다. 이에 관한 설명으로 옳은 것을 모두 고른 것은?","d":"(다툼이 있으면 판례에 따름)\nㄱ. 丙은 甲에 대해 자전거의 반환을 청구할 수 있다.\nㄴ. 丙은 자전거에 대한 선의취득을 근거로 소유권을 주장할 수 있다.\nㄷ. 丙의 甲에 대한 점유의 소에서 甲은 자전거에 대한 소유권을 근거로 항변할 수 있다.\nㄹ. 甲은 탈환행위 전에 丙에 대해 점유물반환청구권을 행사할 수 있다.","o":["ㄱ","ㄱ, ㄴ","ㄴ, ㄷ","ㄱ, ㄴ, ㄹ","ㄴ, ㄷ, ㄹ"],"a":1}},{"y":2021,"e":"변리사 1차","qn":13,"i":"변리사2021_58-13-1","t":"대리인이 본인 소유가 아닌 물건을 처분하고 상대방이 본인 소유라고 오신한 경우에도 선의취득이 인정될 수 있다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"변리사 1차","qn":13,"i":"변리사2021_58-13-2","t":"자동차관리법이 적용되는 자동차이더라도 행정상 특례조치에 의하지 아니하고는 적법하게 등록할 수 없어서 등록하지 아니한 상태에 있고 통상적인 용도가 도로 외의 장소에서만 사용하는 것이라는 등의 특별한 사정이 있다면, 민법 제249조의 선의취득 규정이 적용될 수 있다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"변리사 1차","qn":13,"i":"변리사2021_58-13-3","t":"채무자 이외의 사람에 속하는 동산을 경매절차에서 경락받은 경우에도 선의취득이 성립할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"변리사 1차","qn":13,"i":"변리사2021_58-13-4","t":"매수인이 점유개정으로 동산의 점유를 취득한 경우에는 선의취득이 인정되지 않는다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"변리사 1차","qn":13,"i":"변리사2021_58-13-5","t":"점유보조자가 보관한 물건을 횡령하여 형사상 절도죄가 성립되는 경우, 그 물건은 민법 제250조(도품\u0001유실물에 대한 특례)의 도품에 해당되므로, 피해자는 점유를 상실한 날로부터 2년 내에 그 물건의 반환을 청구할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"선의취득"},{"y":2021,"e":"변리사 1차","qn":14,"i":"변리사2021_58-14","t":"점유자와 회복자의 법률관계에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에","c":"A","mc":{"s":"점유자와 회복자의 법률관계에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에","d":"따름)","o":["악의의 점유자가 점유물의 사용에 따른 이익을 반환하여야 하는 경우, 자신의 노력으 로 점유물을 활용하여 얻은 초과이익도 반환하여야 한다.","악의의 수익자는 받은 이익에 이자를 붙여 반환하여야 하며, 그 이자의 이행지체로 인한 지연손해금도 지급하여야 한다.","악의의 점유자가 과실(果實)을 수취하지 못한 경우, 이에 대한 과실(過失)이 없더라도 그 과실(果實)의 대가를 보상하여야 한다.","점유자가 점유물을 개량하기 위하여 유익비를 지출한 경우는 점유자가 점유물을 반환할 때에 그 상환을 청구할 수 있으나, 필요비를 지출한 경우에는 즉시 상환을 청구할 수 있다.","점유물이 점유자의 책임 있는 사유로 멸실된 때, 악의의 점유자라 하더라도 자주점유인 경우는 타주점유에 비하여 책임이 경감된다."],"a":2}},{"y":2021,"e":"변리사 1차","qn":17,"i":"변리사2021_58-17","t":"부동산 소유권의 점유취득시효에 관한 설명으로 옳지 않은 것은? (다툼이 있으면","c":"A","mc":{"s":"부동산 소유권의 점유취득시효에 관한 설명으로 옳지 않은 것은? (다툼이 있으면","d":"판례에 따름)","o":["시효완성자는 취득시효완성에 따른 등기를 하지 않더라도 시효완성 당시의 등기명의 인에 대하여 취득시효를 주장할 수 있다.","취득시효가 완성되기 전에 등기명의인이 바뀐 경우에는 시효완성자는 취득시효완성 당시의 등기명의인에게 취득시효를 주장할 수 있다.","취득시효완성 후 등기명의인이 변경되면 설사 등기원인이 취득시효 완성 전에 존재하 였더라도, 시효완성자는 변경된 등기명의인에게 취득시효를 주장할 수 없다.","취득시효기간이 진행하는 중에 등기명의인이 변동된 경우, 취득시효기간의 기산점을 임의로 선택하거나 소급하여 20년 이상 점유한 사실만을 내세워 시효완성을 주장할 수 없다.","취득시효완성 후 등기명의인이 바뀐 경우, 등기명의가 바뀐 시점으로부터 다시 취득시효기간이 경과하더라도 취득시효완성을 주장할 수 없다."],"a":5}},{"y":2023,"e":"변리사 1차","qn":13,"i":"변리사2023_60-13","t":"甲은 X토지에 대하여 등기부취득시효를 주장하고 있다. 이에 관한 설명으로 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"甲은 X토지에 대하여 등기부취득시효를 주장하고 있다. 이에 관한 설명으로 옳은 것을 모두 고른 것은?","d":"ㄱ. 甲이 개인이 아니라 지방자치단체인 경우 등기부취득시효를 주장할 수 없다.\nㄴ. 甲의 무과실은 전 시효기간을 통하여 인정되어야 하는 것은 아니다.\nㄷ. 甲이 X토지에 대하여 무효의 중복된 소유권보존등기를 마친 경우에는 등기부취득시효를 주장할 수 없다.","o":["ㄱ","ㄴ","ㄱ, ㄴ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":4}},{"y":2023,"e":"변리사 1차","qn":15,"i":"변리사2023_60-15-1","t":"甲이 부동산을 증여받아 점유를 개시한 이후에 그 증여가 무권리자에 의한 것임을 알았더라도 그 점유가 타주점유가 된다고 볼 수 없다.","ox":"O","m":"①","c":"A","tp":"점유자 甲의 권리관계 등"},{"y":2023,"e":"변리사 1차","qn":15,"i":"변리사2023_60-15-2","t":"甲의 통상의 필요비 청구가 부정되는 민법 제203조(점유자의 상환청구권) 제1항 단서 규정은 과실수취권이 없는 악의의 점유자에 대해서도 적용된다.","ox":"X","m":"②","c":"A","tp":"점유자 甲의 권리관계 등"},{"y":2023,"e":"변리사 1차","qn":15,"i":"변리사2023_60-15-3","t":"민법 제203조(점유자의 상환청구권) 제2항에서 유익비의 상환범위는 甲이 유익비로 지출한 금액과 현존하는 증가액 중에서 甲이 선택하는 것으로 정해진다.","ox":"X","m":"③","c":"A","tp":"점유자 甲의 권리관계 등"},{"y":2023,"e":"변리사 1차","qn":15,"i":"변리사2023_60-15-4","t":"점유물이 甲의 책임있는 사유로 인하여 멸실한 경우, 민법 제202조(점유자의 회복자에 대한 책임)에 따르면 甲이 악의의 점유자로서 부담하는 손해배상범위와 선의이면서 타주점유자로서 부담하는 손해배상범위는 다르다.","ox":"X","m":"④","c":"A","tp":"점유자 甲의 권리관계 등"},{"y":2023,"e":"변리사 1차","qn":15,"i":"변리사2023_60-15-5","t":"점유를 침탈당한 甲이 본권인 유치권 소멸에 따른 손해배상청구권을 행사하는 때에는 점유를 침탈당한 날부터 1년 내에 행사해야만 한다.","ox":"X","m":"⑤","c":"A","tp":"점유자 甲의 권리관계 등"},{"y":2023,"e":"변리사 1차","qn":17,"i":"변리사2023_60-17","t":"공동소유관계에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면 판례","c":"A","mc":{"s":"공동소유관계에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면 판례","d":"에 따름)\nㄱ. 공유물분할청구는 부동산의 구분소유적 공유관계에서 인정되지 않는다.\nㄴ. 지분권자로서의 사용권을 사실상 포기하는 공유자 사이의 특약은 그 사실을 알지 못하고 공유지분을 취득한 특정승계인에게 승계되지 않는다.\nㄷ. 비법인사단의 채권자가 채권자대위권에 기하여 비법인사단의 총유재산에 관한 권리를 적법하게 대위행사하는 경우에도 사원총회의 결의 등 비법인사단의 내부적인 의사결정절차를 거쳐야 한다.\nㄹ. 부동산의 합유자 중 일부가 사망한 경우 합유자 사이에 특별한 약정이 없는한 해당 부동산은 잔존 합유자가 2인 이상일 때에는 잔존 합유자의 합유로 귀속된다.","o":["ㄱ, ㄹ","ㄱ, ㄴ, ㄷ","ㄱ, ㄴ, ㄹ","ㄴ, ㄷ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":3}},{"y":2024,"e":"변리사 1차","qn":14,"i":"변리사2024_61-14-1","t":"명인방법에 의하여 공시되는 수목의 집단 중 토지로부터 분리된 수목은 선의취득의 대상이 될 수 있다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"변리사 1차","qn":14,"i":"변리사2024_61-14-2","t":"무권리자로부터 연립주택의 입주권을 평온\u0001공연하게 선의\u0001무과실로 매수하더라도 매수인은 입주권에 관한 선의취득을 주장할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"변리사 1차","qn":14,"i":"변리사2024_61-14-3","t":"법정대리인의 동의를 받지 않은 미성년자로부터 타인 소유의 자전거를 선의로 매수한 자는 그 미성년자가 제한능력을 이유로 매매계약을 취소하더라도 선의취득에 기해 그 자전거의 소유권을 취득한다.","ox":"X","m":"③","c":"A"},{"y":2024,"e":"변리사 1차","qn":14,"i":"변리사2024_61-14-4","t":"甲소유의 발전기를 임차하여 공장에서 사용 중인 乙이 발전기의 소유자를 乙로 오신한 丙에게 그 발전기를 매도함과 동시에 이를 丙으로부터 임차하여 점유의 이전없이 공장에서 계속 사용하고 있는 경우, 丙은 발전기의 소유권을 선의취득 할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"변리사 1차","qn":14,"i":"변리사2024_61-14-5","t":"선의취득의 대상이 된 금반지가 유실물일 때에는 유실자는 유실한 날로부터 2년 내에 그 금반지의 반환을 청구할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"변리사 1차","qn":15,"i":"변리사2024_61-15-1","t":"선의의 점유자라도 본권에 관한 소에 패소한 때에는 그 소가 확정된 때로부터 악의의 점유자로 본다.","ox":"X","m":"①","c":"A","tp":"점유권"},{"y":2024,"e":"변리사 1차","qn":15,"i":"변리사2024_61-15-2","t":"건물의 소유권이 양도된 경우에는 특별한 사정이 없는 한 건물의 양도인인 전(前) 소유자는 그 건물의 부지에 대한 점유를 상실한다.","ox":"O","m":"②","c":"A","tp":"점유권"},{"y":2024,"e":"변리사 1차","qn":15,"i":"변리사2024_61-15-3","t":"직접점유자가 그의 점유를 침탈당하거나 방해당하고 있는 경우, 직접점유자만이 점유 보호청구권을 가지고 간접점유자는 점유보호청구권을 행사할 수 없다.","ox":"X","m":"③","c":"A","tp":"점유권"},{"y":2024,"e":"변리사 1차","qn":15,"i":"변리사2024_61-15-4","t":"甲의 점유가 타주점유인 경우, 甲의 특정승계인 乙이 자기의 점유만을 주장하더라도 그 점유는 타주점유로 추정된다.","ox":"X","m":"④","c":"A","tp":"점유권"},{"y":2024,"e":"변리사 1차","qn":15,"i":"변리사2024_61-15-5","t":"과실수취권이 있는 점유자는 점유물로부터 과실을 취득하였더라도 회복자에 대하여 점유물을 보존하기 위하여 지출한 통상의 필요비의 상환을 청구할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"점유권"},{"y":2024,"e":"변리사 1차","qn":16,"i":"변리사2024_61-16","t":"甲이 2000. 2. 1.부터 乙소유의 X토지를 소유의 의사로 평온\u0001공연하게 현재까지 점유하고 있다. 이에 관한 설명으로 옳지 않은 것은? (각 지문은 독립적이며, 다","c":"A","mc":{"s":"甲이 2000. 2. 1.부터 乙소유의 X토지를 소유의 의사로 평온\u0001공연하게 현재까지 점유하고 있다. 이에 관한 설명으로 옳지 않은 것은? (각 지문은 독립적이며, 다","d":"툼이 있으면 판례에 따름)","o":["甲이 丙을 점유매개자로 하여 X토지를 간접적으로 점유하였더라도 甲은 시효취득을 주장할 수 있다.","乙이 X토지를 2015. 2. 1. 丙에게 매도하여 현재 丙이 소유권자로 등기되어 있는 경우, 甲은 丙에게 취득시효의 완성을 주장할 수 있다.","乙이 丙에게 무효인 매매계약에 기하여 2022. 2. 1. 소유권이전등기를 마쳐주었다면, 甲은 乙을 대위하여 丙 명의의 등기의 말소를 구할 수 있다.","乙의 채권자 丙이 채권을 보전하기 위하여 2018. 2. 1. X토지를 가압류 한 경우, 취득시효의 진행은 중단된다.","X토지에 관하여 甲의 취득시효가 완성된 경우, 乙은 甲에 대하여 취득시효 기간 동안 X토지를 점유하여 얻은 이득의 반환을 청구할 수 없다."],"a":4}},{"y":2024,"e":"변리사 1차","qn":17,"i":"변리사2024_61-17-1","t":"공유자는 다른 공유자의 동의없이 자기의 지분을 담보로 제공할 수 없다.","ox":"X","m":"①","c":"A","tp":"공동소유"},{"y":2024,"e":"변리사 1차","qn":17,"i":"변리사2024_61-17-2","t":"공유물의 변경은 공유자의 지분의 과반수로써 결정한다.","ox":"X","m":"②","c":"A","tp":"공동소유"},{"y":2024,"e":"변리사 1차","qn":17,"i":"변리사2024_61-17-3","t":"공유물의 관리에 관한 사항은 공유자의 과반수로써 결정한다.","ox":"X","m":"③","c":"A","tp":"공동소유"},{"y":2024,"e":"변리사 1차","qn":17,"i":"변리사2024_61-17-4","t":"합유자는 달리 정함이 없는 한 전원의 동의없이 합유물에 대한 지분을 처분하지 못한다.","ox":"O","m":"④","c":"A","tp":"공동소유"},{"y":2024,"e":"변리사 1차","qn":17,"i":"변리사2024_61-17-5","t":"총유물에 대한 보존행위는 달리 정함이 없는 한 비법인사단을 구성하는 각 사원이 할수 있다.","ox":"X","m":"⑤","c":"A","tp":"공동소유"},{"y":2026,"e":"변리사 1차","qn":18,"i":"변리사2026_63-18-1","t":"과실수취권이 있는 선의의 점유자의 점유는 자주점유일 것을 요하지 않는다.","ox":"O","m":"①","c":"A","tp":"점유자와 회복자"},{"y":2026,"e":"변리사 1차","qn":18,"i":"변리사2026_63-18-2","t":"선의의 점유자는 과실을 취득함으로 인하여 타인에게 손해를 입혔다 할지라도 그 과실취득으로 인한 이득을 그 타인에게 반환할 의무를 지지 않는다.","ox":"O","m":"②","c":"A","tp":"점유자와 회복자"},{"y":2026,"e":"변리사 1차","qn":18,"i":"변리사2026_63-18-3","t":"악의 점유자는 수취한 과실을 반환함에 있어서 그 받은 이익에 이자를 붙여 반환하여야 하는 것은 아니다.","ox":"X","m":"③","c":"A","tp":"점유자와 회복자"},{"y":2026,"e":"변리사 1차","qn":18,"i":"변리사2026_63-18-4","t":"선의의 점유자가 과실을 취득한 경우, 점유물의 보존을 위하여 지출한 통상의 필요비를 상환할 것을 청구할 수 없다.","ox":"O","m":"④","c":"A","tp":"점유자와 회복자"},{"y":2026,"e":"변리사 1차","qn":18,"i":"변리사2026_63-18-5","t":"점유자의 회복자에 대한 유익비상환청구권은 점유자가 회복자로부터 점유물의 반환을 청구받거나 회복자에게 점유물을 반환한 때에 비로소 행사할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"점유자와 회복자"},{"y":2026,"e":"변리사 1차","qn":19,"i":"변리사2026_63-19-1","t":"부동산에 대한 점유취득시효가 완성된 경우, 소유명의자는 점유자가 시효가 완성되기까 지 그 부동산으로부터 얻은 이익에 대하여 부당이득반환청구를 할 수 있다.","ox":"X","m":"①","c":"A"},{"y":2026,"e":"변리사 1차","qn":19,"i":"변리사2026_63-19-2","t":"토지에 관하여 점유취득시효 완성에 따라 소유권이전등기가 마쳐진 경우, 제3자가 등 기명의자의 취득시효 기간 중 일부 기간 동안 해당 토지 일부에 관하여 직접적\u0001현실 적인 점유를 한 사실이 있으면 그 등기는 원인무효의 등기가 된다.","ox":"X","m":"②","c":"A"},{"y":2026,"e":"변리사 1차","qn":19,"i":"변리사2026_63-19-3","t":"취득시효완성 사실을 알면서 소유자로부터 그 부동산을 매수하여 소유권이전등기를 마친 자는 특별한 사정이 없는 한 소유자의 등기의무를 승계한다.","ox":"X","m":"③","c":"A"},{"y":2026,"e":"변리사 1차","qn":19,"i":"변리사2026_63-19-4","t":"취득시효기간의 완성 전에 소유자의 채권자에 의하여 시효취득 목적물이 압류 또는 가압류가 된 경우, 취득시효는 중단된다.","ox":"X","m":"④","c":"A"},{"y":2026,"e":"변리사 1차","qn":19,"i":"변리사2026_63-19-5","t":"소유권의 취득시효를 완성한 자가 취득시효완성으로 인한 소유권이전등기청구권을 타인에게 양도하려는 경우, 소유명의인의 동의 또는 승낙을 요하지 않는다.","ox":"O","m":"⑤","c":"A"}],"7":[{"y":2016,"e":"변리사 1차","qn":18,"i":"변리사2016_53-18-1","t":"甲은 乙에게 A토지의 소유권을 넘겨주는 때에 C건물을 위한 관습법상 법정지상권을 취득한다.","ox":"X","m":"①","c":"A"},{"y":2016,"e":"변리사 1차","qn":18,"i":"변리사2016_53-18-2","t":"C가 무허가건물인 경우에는 무허가건물이라는 이유만으로도 C의 소유자는 그 건물의 소유를 위한 관습법상 법정지상권을 취득할 수 없다.","ox":"X","m":"②","c":"A"},{"y":2016,"e":"변리사 1차","qn":18,"i":"변리사2016_53-18-4","t":"만일 乙이 근저당권 설정 당시 존재하던 B건물을 철거하고 D건물을 신축한 후에 A토지에 대한 저당권이 실행되었다면, B건물과 D건물의 동일성이 인정되지 않는 한乙은 D건물을 위한 법정지상권을 취득할 수 없다.","ox":"X","m":"④","c":"A"},{"y":2016,"e":"변리사 1차","qn":19,"i":"변리사2016_53-19","t":"甲은 자신의 소유인 X주택을 乙에게 빌려주고 전세권을 설정하였다. 이에 관한 설명으로 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"甲은 자신의 소유인 X주택을 乙에게 빌려주고 전세권을 설정하였다. 이에 관한 설명으로 옳은 것을 모두 고른 것은?","d":"ㄱ. 甲과 乙 사이의 전세권설정계약이 그 합의에 따라 해지되더라도 乙은 전세권과 분리하여 전세금반환채권을 양도할 수 없다.\nㄴ. X주택의 소유권이 丙에게 양도된 후 전세권이 계약기간의 만료에 따라 소멸 하면, 乙은 甲에 대해서도 전세금반환을 청구할 수 있다.\nㄷ. 丁이 乙의 전세권에 대하여 저당권을 취득한 후 乙의 전세권이 기간만료로 소멸하면, 丁은 전세금반환채권에 대한 압류의 방법으로 권리를 행사하여 甲에 대해 전세금의 지급을 청구할 수 있다.","o":["ㄱ","ㄴ","ㄷ","ㄱ, ㄴ","ㄱ, ㄴ, ㄷ"],"a":3}},{"y":2017,"e":"변리사 1차","qn":15,"i":"변리사2017_54-15-1","t":"전세권설정자가 전세권자에 대하여 민법 제315조에 정한 손해배상채권 이외의 다른 채권을 가지고 있더라도 특별한 사정이 없는 한, 이를 가지고 전세금반환채권에 대하여 물상대위권을 행사한 전세권저당권자에게 상계로 대항할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"변리사 1차","qn":15,"i":"변리사2017_54-15-2","t":"X건물에 대해 1순위 저당권자 甲, 2순위 전세권자 乙, 3순위 저당권자 丙이 있고 그 중 丙이 경매신청을 하여 丁에게 매각된 경우, 乙의 전세권은 소멸하되 2순위로 우선변제권을 가진다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"변리사 1차","qn":15,"i":"변리사2017_54-15-3","t":"타인의 토지에 있는 건물에 전세권을 설정한 경우, 전세권의 효력은 그 건물의 소유를 목적으로 한 지상권에 미친다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"변리사 1차","qn":15,"i":"변리사2017_54-15-4","t":"지상권을 가진 건물소유자가 그 건물에 전세권을 설정하였으나 그가 2년 이상의 지료를 지급하지 아니한 경우, 토지소유자는 전세권자의 동의 없이 지상권 소멸 청구를 할 수 없다.","ox":"X","m":"④","c":"A"},{"y":2017,"e":"변리사 1차","qn":15,"i":"변리사2017_54-15-5","t":"전세권에 저당권이 설정되어 있는 경우에도 전세권의 존속기간이 만료되면 전세권의 용익물권적 권능은 전세권설정등기의 말소등기 없이도 당연히 소멸한다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"변리사 1차","qn":21,"i":"변리사2017_54-21-1","t":"지역권은 다른 약정이 없는 한 승역지소유권에 부종하여 이전한다.","ox":"X","m":"①","c":"A"},{"y":2017,"e":"변리사 1차","qn":21,"i":"변리사2017_54-21-2","t":"계약에 의하여 승역지소유자가 자기의 비용으로 지역권의 행사를 위하여 공작물의 설치 또는 수선의 의무를 부담하기로 한 경우, 위 약정으로 승역지소유자의 특별승계인에게 대항하기 위해서는 등기를 하여야 한다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"변리사 1차","qn":21,"i":"변리사2017_54-21-3","t":"통행지역권을 시효취득하기 위해서는 요역지의 소유자가 타인의 토지를 20년간 통행하였다는 사실만으로 충분하며, 요역지의 소유자가 타인의 소유인 승역지 위에 통로를 개설할 필요는 없다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"변리사 1차","qn":21,"i":"변리사2017_54-21-4","t":"요역지의 공유자 중 1인이 지역권을 시효로 취득하더라도 다른 공유자는 지역권을 취득하지 못한다.","ox":"X","m":"④","c":"A"},{"y":2017,"e":"변리사 1차","qn":21,"i":"변리사2017_54-21-5","t":"승역지는 반드시 1필의 토지이어야 하며, 토지의 일부 위에 지역권을 설정할 수 없다.","ox":"X","m":"⑤","c":"A"},{"y":2018,"e":"변리사 1차","qn":16,"i":"변리사2018_55-16-1","t":"토지에 관하여 1번 저당권 설정 당시 건물이 건축 중이던 경우에도 건물의 규모, 종류를 예상할 수 있었다면 법정지상권이 성립할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"변리사 1차","qn":16,"i":"변리사2018_55-16-2","t":"토지에 관하여 1번 저당권 설정 당시 건물이 존재하였다면, 그 후 그 건물을 철거하고 동일한 규모의 건물을 신축한 경우에도 법정지상권이 성립할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"변리사 1차","qn":16,"i":"변리사2018_55-16-3","t":"동일인 소유의 토지와 지상건물에 관하여 공동저당권을 설정한 후, 그 건물을 철거하고 새로 건물을 신축한 경우에는 특별한 사정이 없는 한 법정지상권이 성립하지 않는다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"변리사 1차","qn":16,"i":"변리사2018_55-16-4","t":"지상건물이 없는 토지에 관하여 1번 저당권을 설정할 당시 저당권자가 그 토지에 건물을 축조하는 것에 동의하였다면 법정지상권이 성립할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2018,"e":"변리사 1차","qn":16,"i":"변리사2018_55-16-5","t":"토지공유자 한 사람이 다른 공유자 지분 과반수의 동의를 얻어 건물을 건축한 후 경매로 인하여 토지와 건물의 소유자가 달라진 경우 법정지상권이 성립하지 않는다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"변리사 1차","qn":21,"i":"변리사2018_55-21-1","t":"무상의 지역권 설정도 가능하다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"변리사 1차","qn":21,"i":"변리사2018_55-21-2","t":"요역지의 불법점유자는 지역권을 시효취득할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"변리사 1차","qn":21,"i":"변리사2018_55-21-3","t":"지역권자 甲이 그 소유 토지를 乙에게 매도하고 이전등기한 경우, 특별한 사정이 없는 한 乙은 지역권의 이전등기 없이는 지역권을 취득하지 못한다.","ox":"X","m":"③","c":"A"},{"y":2018,"e":"변리사 1차","qn":21,"i":"변리사2018_55-21-4","t":"지역권자는 승역지의 점유를 침탈한 제3자를 상대로 지역권에 기초하여 승역지의 반환을 청구할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"변리사 1차","qn":21,"i":"변리사2018_55-21-5","t":"요역지를 여러 사람이 공유하는 경우 공유자 중 한 사람에 대한 지역권의 소멸시효 중단은 다른 공유자를 위하여 효력이 있다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"변리사 1차","qn":16,"i":"변리사2019_56-16-1","t":"지상권은 1필 토지의 전부가 아닌 일부에 대해서는 성립할 수 없다.","ox":"X","m":"①","c":"A"},{"y":2019,"e":"변리사 1차","qn":16,"i":"변리사2019_56-16-2","t":"지상권자는 존속기간이 만료한 때에 지상물이 현존하는 경우, 지상권설정자에 대해 선택적으로 지상권의 갱신청구 또는 지상물의 매수청구를 할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2019,"e":"변리사 1차","qn":16,"i":"변리사2019_56-16-3","t":"지상권은 지상물의 소유를 목적으로 토지를 사용하는 권리이므로, 지상권자는 지상권을 유보한 채 지상물 소유권만을 양도할 수 없다.","ox":"X","m":"③","c":"A"},{"y":2019,"e":"변리사 1차","qn":16,"i":"변리사2019_56-16-4","t":"지상권의 지료지급 연체가 토지소유권의 양도 전후에 걸쳐 이루어진 경우, 토지양수인에 대한 연체기간이 2년 이상이면 토지양수인은 지상권의 소멸을 청구할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"변리사 1차","qn":16,"i":"변리사2019_56-16-5","t":"금융기관이 토지에 저당권과 함께 지료 없는 지상권을 설정받으면서 채무자의 사용 수익권을 배제하지 않은 경우, 금융기관은 그 토지의 무단점유자에 대해 지상권침해를 근거로 임료 상당의 손해배상을 청구할 수 있다.","ox":"X","m":"⑤","c":"A"},{"y":2019,"e":"변리사 1차","qn":20,"i":"변리사2019_56-20","t":"甲은 乙 소유의 X주택 일부(A부분)에 전세금 1억원, 존속기간 2년으로 하는 전세 계약을 체결하고 전세권설정등기를 마쳤다. 이에 관한 설명으로 옳은 것은? (다툼","c":"A","mc":{"s":"甲은 乙 소유의 X주택 일부(A부분)에 전세금 1억원, 존속기간 2년으로 하는 전세 계약을 체결하고 전세권설정등기를 마쳤다. 이에 관한 설명으로 옳은 것은? (다툼","d":"이 있으면 판례에 따름)","o":["甲은 전세권 존속 중에는 장래에 그 전세권이 소멸하는 경우에 전세금반환채권이 발생하는 것을 조건으로 그 장래의 조건부 채권을 양도할 수 없다.","乙이 甲에게 전세금의 반환을 지체한 경우, 甲은 X주택의 A부분이 아니라 전부에 대하여 경매를 청구할 수 있다.","경매절차에서 X주택이 매각된 경우, 甲은 X주택의 전부에 대하여 후순위권리자보다 전세금을 우선 변제받을 수 없다.","甲의 채권자 丙이 甲의 전세권에 저당권을 취득한 경우, 전세권의 존속기간이 만료되 더라도 丙은 전세권 자체에 대하여 저당권을 실행할 수 있다.","甲의 전세권이 존속하는 동안에 乙이 X주택을 丁에게 매도하고 丁명의로 소유권이전등기를 마쳐준 경우, 乙은 전세금반환의무를 면하게 된다."],"a":5}},{"y":2021,"e":"변리사 1차","qn":18,"i":"변리사2021_58-18-1","t":"2020. 10. 1. 당시 丙은 X토지에 대하여 법정지상권 등기를 하지 않았기 때문에, 丙은 X토지에 대한 법정지상권을 취득하지 못한다.","ox":"X","m":"①","c":"A"},{"y":2021,"e":"변리사 1차","qn":18,"i":"변리사2021_58-18-2","t":"2020. 10. 1. 당시 丙이 법정지상권을 취득하였더라도 본인의 의사와 무관하게 취득한 것이므로, 지료를 지급할 필요가 없다.","ox":"X","m":"②","c":"A"},{"y":2021,"e":"변리사 1차","qn":18,"i":"변리사2021_58-18-4","t":"2021. 2. 10. 戊는 법정지상권 등기 없이도, X토지에 대하여 법정지상권을 취득한다.","ox":"X","m":"④","c":"A"},{"y":2021,"e":"변리사 1차","qn":20,"i":"변리사2021_58-20-1","t":"타인의 토지에 있는 건물의 소유자가 그 건물에 설정한 전세권의 효력은 그 건물의 소유를 목적으로 한 임차권에도 미친다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"변리사 1차","qn":20,"i":"변리사2021_58-20-2","t":"대지와 건물이 동일한 소유자에게 속한 경우에 건물에 전세권을 설정한 때에는 그 대지소유권의 특별승계인은 전세권설정자에 대하여 지상권을 설정한 것으로 본다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"변리사 1차","qn":20,"i":"변리사2021_58-20-3","t":"전세권이 법정갱신된 경우, 전세권자는 등기 없이도 그 목적물을 취득한 제3자에 대하여 갱신된 권리를 주장할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"변리사 1차","qn":20,"i":"변리사2021_58-20-4","t":"전세권에 저당권을 설정한 경우, 전세기간이 만료되더라도 전세권의 저당권자는 전세권 자체에 대하여 저당권을 실행하여 전세금을 배당받을 수 있다.","ox":"X","m":"④","c":"A"},{"y":2021,"e":"변리사 1차","qn":20,"i":"변리사2021_58-20-5","t":"토지전세권의 존속기간을 15년으로 약정한 경우에 그 존속기간은 10년으로 단축되지만, 당사자는 존속기간 만료 시에 갱신한 날로부터 10년을 넘지 않는 기간으로 전세권을 갱신할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"변리사 1차","qn":24,"i":"변리사2021_58-24","t":"관습법상 법정지상권이 성립되지 않는 경우를 모두 고른 것은? (다툼이 있으면","c":"A","mc":{"s":"관습법상 법정지상권이 성립되지 않는 경우를 모두 고른 것은? (다툼이 있으면","d":"판례에 따름)\nㄱ. 환지처분으로 인하여 토지와 그 지상건물의 소유자가 달라진 경우ㄴ. 미등기 건물을 그 대지와 함께 양수한 사람이 그 대지에 관하여서만 소유권이전등기를 넘겨받고 건물에 대하여는 그 등기를 이전받지 못하고 있는 상태에서 그 대지가 강제경매되어 소유자가 달라진 경우ㄷ. 공유토지 위에 신축한 건물을 단독 소유하던 토지공유자 1인이 자신의 토지지분만을 양도하여 건물과 토지의 소유자가 달라진 경우ㄹ. 토지를 매수하여 소유권이전등기를 마친 매수인이 그 지상에 건물을 신축한 후 그 토지의 소유권이전등기가 원인무효로 밝혀져 말소됨으로써 건물과 토지의 소유자가 달라진 경우","o":["ㄱ, ㄴ","ㄴ, ㄹ","ㄱ, ㄴ, ㄷ","ㄴ, ㄷ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":5}},{"y":2023,"e":"변리사 1차","qn":18,"i":"변리사2023_60-18","t":"지상권에 관한 설명으로 옳지 않은 것을 모두 고른 것은?","c":"A","mc":{"s":"지상권에 관한 설명으로 옳지 않은 것을 모두 고른 것은?","d":"ㄱ. 자기 소유 토지에 분묘를 설치한 甲이 그 토지를 乙에게 양도하면서 분묘 이장 의 특약을 하지 않음으로써 분묘기지권을 취득한 경우, 특별한 사정이 없는 한甲은 분묘기지권이 성립한 때가 아니라 지료청구를 받은 날부터 지료지급의무가 있다.\nㄴ. 지상권자 甲의 지료 지급 연체가 토지소유권의 양도 전후에 걸쳐 이루어진 경우 토지양수인 乙에 대한 연체기간이 2년이 되지 않는다면 乙은 지상권소멸청구를할 수 없다.\nㄷ. 甲 소유의 대지와 건물 모두 乙에게 매도되었으나 대지에 관하여서만 소유권이전등기가 경료된 경우에 甲과 乙 사이에 관습법상의 법정지상권이 인정된다.\nㄹ. 건물 소유자 甲과 토지 소유자 乙 사이에 건물의 소유를 목적으로 하는 토지 임대차계약을 체결한 경우에도 관습법상의 법정지상권이 인정된다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄷ, ㄹ","ㄱ, ㄷ, ㄹ","ㄴ, ㄷ, ㄹ"],"a":4}},{"y":2023,"e":"변리사 1차","qn":19,"i":"변리사2023_60-19-1","t":"甲이 보증금의 반환을 담보하기 위하여 전세권을 설정하면서 이와 동시에 목적물을 인도하지 않았으므로 전세권의 설정은 효력이 없다.","ox":"X","m":"①","c":"A"},{"y":2023,"e":"변리사 1차","qn":19,"i":"변리사2023_60-19-2","t":"전세금의 지급은 전세권 성립의 요소가 되는 것이므로 전세금을 현실적으로 지급하지 않고 기존의 채권으로 대신할 수 없다.","ox":"X","m":"②","c":"A"},{"y":2023,"e":"변리사 1차","qn":19,"i":"변리사2023_60-19-3","t":"乙이 차임의 지급을 연체하는 경우 甲은 연체된 차임을 보증금에서 공제할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"변리사 1차","qn":19,"i":"변리사2023_60-19-4","t":"임대차보증금의 반환을 담보하기 위하여 전세권설정등기가 경료되었음을 丙이 알지 못한 경우에도 甲은 연체차임의 공제를 가지고 丙에게 대항할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"변리사 1차","qn":19,"i":"변리사2023_60-19-5","t":"전세권의 존속기간이 만료되면 丙은 X상가에 대한 전세권저당권을 실행하는 방법으로 乙에 대한 대여금채권을 회수하여야 한다.","ox":"X","m":"⑤","c":"A"},{"y":2024,"e":"변리사 1차","qn":18,"i":"변리사2024_61-18","t":"건물의 소유를 목적으로 하는 지상권에 관한 설명으로 옳지 않은 것은? (다툼이","c":"A","mc":{"s":"건물의 소유를 목적으로 하는 지상권에 관한 설명으로 옳지 않은 것은? (다툼이","d":"있으면 판례에 따름)","o":["토지에 관하여 근저당권을 설정함과 아울러 그 토지의 담보가치가 저감하는 것을 막기 위해 채권자 앞으로 건물의 소유를 목적으로 하는 지상권이 설정된 경우, 피담보채권의 변제로 근저당권이 소멸하더라도 그 지상권은 소멸하지 않는다.","존속기간의 만료로 지상권이 소멸할 당시에 건물이 현존한 경우, 지상권자가 계약갱 신청구권을 행사하더라도 지상권설정자가 이를 거절하면 지상권은 갱신되지 않는다.","지상권이 소멸한 때 지상권설정자가 상당한 가액을 제공하여 건물의 매수를 청구한 때에는 지상권자는 정당한 이유없이 이를 거절하지 못한다.","건물의 소유를 목적으로 하는 지상권에서 그 건물이 멸실되더라도 존속기간이 만료되 지 않은 한 지상권은 소멸되지 않는다.","무상(無償)의 지상권자는 언제든지 지상권을 포기할 수 있지만, 지상권이 저당권의 목적인 때에는 저당권자의 동의가 있어야 포기할 수 있다."],"a":1}},{"y":2024,"e":"변리사 1차","qn":19,"i":"변리사2024_61-19-1","t":"甲이 丙에게 Y건물을 인도하지 않은 경우, 특별한 사정이 없는 한 丙의 전세권은 성립하지 않는다.","ox":"X","m":"①","c":"A"},{"y":2024,"e":"변리사 1차","qn":19,"i":"변리사2024_61-19-2","t":"甲과 丙이 전세권의 존속기간을 약정하지 아니한 경우, 甲과 丙은 언제든지 상대방에 대하여 전세권의 소멸을 통고할 수 있고 상대방이 이 통고를 받은 때 전세권은 소멸한다.","ox":"X","m":"②","c":"A"},{"y":2024,"e":"변리사 1차","qn":19,"i":"변리사2024_61-19-3","t":"전세금 3억 원은 현실적으로 수수되어야 하며, 丙이 甲에 대하여 갖는 기존의 채권으로 전세금의 지급에 갈음할 수 없다.","ox":"X","m":"③","c":"A"},{"y":2024,"e":"변리사 1차","qn":19,"i":"변리사2024_61-19-4","t":"특별한 사정이 없는 한, 전세기간 중 丙은 甲의 동의를 얻어야 Y건물을 타인에게 임대할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2024,"e":"변리사 1차","qn":19,"i":"변리사2024_61-19-5","t":"甲이 乙에게 약정한 지료를 2년분 이상 연체한 경우, 乙은 丙의 동의가 없어도 甲에게 지상권소멸을 청구할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"변리사 1차","qn":20,"i":"변리사2026_63-20-1","t":"지상권설정 당시에 공작물의 종류와 구조를 정하지 아니한 경우, 지상권의 최단존속 기간은 15년이다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"변리사 1차","qn":20,"i":"변리사2026_63-20-2","t":"지상권의 존속기간 만료 후 지상권자가 지상권갱신청구권을 지체 없이 행사하지 않아 지상권갱신청구권이 소멸한 경우, 지상권자는 지상물매수청구권을 행사할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"변리사 1차","qn":20,"i":"변리사2026_63-20-3","t":"지상권자는 토지소유자의 의사에 반하여도 지상권을 자유롭게 양도할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"변리사 1차","qn":20,"i":"변리사2026_63-20-4","t":"지상권자가 종전 소유자와 지료를 증액하지 않기로 특약을 맺은 경우, 이로써 새로운 소유자에게 대항하기 위해서는 그 특약을 등기하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"변리사 1차","qn":20,"i":"변리사2026_63-20-5","t":"지상물매수청구에 따른 지상물매매가격의 산출은 지상물 매수청구 당시의 시가가 아니라 지상권 소멸 당시의 시가에 의한다.","ox":"X","m":"⑤","c":"A"},{"y":2026,"e":"변리사 1차","qn":21,"i":"변리사2026_63-21-1","t":"전세권 존속기간이 시작되기 전에 마쳐진 전세권설정등기는 특별한 사정이 없는 한유효한 것으로 추정된다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"변리사 1차","qn":21,"i":"변리사2026_63-21-2","t":"임대차보증금반환채권을 담보할 목적으로 임대인과 임차인이 전세권설정계약을 체결하였고 전세권자인 임차인이 그 목적물을 사용\u0001수익한 경우, 특별한 사정이 없는 한그 전세권설정계약은 임대차계약과 양립할 수 없는 범위에서 통정허위표시에 해당하여 무효이다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"변리사 1차","qn":21,"i":"변리사2026_63-21-3","t":"토지의 전세권이 존속기간 만료로 종료된 경우, 최선순위 전세권자의 채권자는 전세권이 설정된 토지에 대한 경매절차에서 채권자대위권에 기하여 자기 이름으로 전세권에 대한 배당요구를 할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"변리사 1차","qn":21,"i":"변리사2026_63-21-4","t":"전세권설정자는 전세권자에 대하여 전세권자에게 책임있는 사유로 인하여 전세목적물이 멸실됨에 따른 손해배상채권 이외의 다른 채권을 가지고 전세금반환채권에 대하여 물상대위권을 행사한 전세권저당권자에게 상계 등으로 대항할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2026,"e":"변리사 1차","qn":21,"i":"변리사2026_63-21-5","t":"토지의 전세권이 존속기간 만료로 종료된 경우, 전세권설정자는 전세권저당권자가 존재하더라도 전세금반환채권에 대한 압류 등이 없는 한 전세권자에 대하여만 전세금반 환의무를 부담한다.","ox":"O","m":"⑤","c":"A"}],"8":[{"y":2016,"e":"변리사 1차","qn":20,"i":"변리사2016_53-20-2","t":"甲이 공장을 점유하는 과정에서 폭력을 사용하는 등의 불법행위가 있었더라도 공장을 점유한 이상 유치권은 성립한다.","ox":"X","m":"②","c":"A"},{"y":2016,"e":"변리사 1차","qn":20,"i":"변리사2016_53-20-3","t":"丙 은행에 근저당권이 설정된 후에 공장을 점유한 甲은 매수인 丁에 대해서는 유치권을 주장하지 못한다.","ox":"X","m":"③","c":"A"},{"y":2016,"e":"변리사 1차","qn":20,"i":"변리사2016_53-20-4","t":"甲이 丁에게 유치권을 행사할 수 있다는 것은 丁에게 직접 공사잔금 5억원을 청구할 수 있음을 뜻한다.","ox":"X","m":"④","c":"A"},{"y":2016,"e":"변리사 1차","qn":20,"i":"변리사2016_53-20-5","t":"공장을 유치하기 위한 방법으로 甲으로부터 공장의 점유를 위탁받은 戊에게 乙회사가 자신의 소유라고 하면서 반환을 청구할 경우, 戊는 이를 거절할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2016,"e":"변리사 1차","qn":21,"i":"변리사2016_53-21-2","t":"丙이 질권설정 사실을 승낙한 후 그 질권설정계약이 합의해지된 경우, 甲이 해지를 이유로 丙에게 원래의 채권으로 대항하려면 甲이 丙에게 해지 사실을 통지하여야 한다.","ox":"X","m":"②","c":"A","tp":"채무자 甲은 채권자 乙을 위하여 자신의 丙"},{"y":2016,"e":"변리사 1차","qn":21,"i":"변리사2016_53-21-3","t":"甲과 丙이 질권의 목적된 권리를 소멸하게 하는 행위를 하였더라도 이는 乙에 대한 관계에 있어 무효일 뿐이어서 특별한 사정이 없는 한 乙 아닌 제3자가 그 무효의 주장을 할 수는 없다.","ox":"O","m":"③","c":"A","tp":"채무자 甲은 채권자 乙을 위하여 자신의 丙"},{"y":2016,"e":"변리사 1차","qn":21,"i":"변리사2016_53-21-4","t":"甲에게 이미 변제한 丙이 착오로 乙에게 이의를 보류하지 아니하고 승낙하였다면, 乙에게 중과실이 있다고 하여도 丙은 변제로 乙에게 대항하지 못한다.","ox":"X","m":"④","c":"A","tp":"채무자 甲은 채권자 乙을 위하여 자신의 丙"},{"y":2016,"e":"변리사 1차","qn":21,"i":"변리사2016_53-21-5","t":"乙이 丙에게 직접청구권을 행사하여 변제받은 경우, 입질채권의 발생원인인 계약관계가 무효였다면 丙은 乙을 상대로 부당이득반환을 청구할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"채무자 甲은 채권자 乙을 위하여 자신의 丙"},{"y":2016,"e":"변리사 1차","qn":22,"i":"변리사2016_53-22-1","t":"물상보증인이 근저당권 채무자의 채무만을 면책적으로 인수하고 이를 원인으로 하여 근저당권 변경의 부기등기가 경료된 경우, 그 후 물상보증인이 다른 원인으로 근저당권자에 대하여 부담하게 된 새로운 채무까지 담보하는 것은 아니다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"변리사 1차","qn":22,"i":"변리사2016_53-22-2","t":"근저당권에 기해 경매신청을 하면 경매신청시에 근저당 채무액이 확정되고, 경매신청에 따른 경매개시결정이 있은 후에 경매신청이 취하되더라도 채무 확정의 효과가 번복되지 않는다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"변리사 1차","qn":22,"i":"변리사2016_53-22-3","t":"존속기간이나 결산기의 정함이 없는 때에는 특별한 사정이 없으면 근저당권설정자가 근저당권자를 상대로 언제든지 해지의 의사표시를 함으로써 피담보채무를 확정시킬 수 있다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"변리사 1차","qn":22,"i":"변리사2016_53-22-4","t":"근저당권설정등기가 원인 없이 말소된 이후에, 근저당목적물인 부동산에 관하여 다른 근저당권자의 신청에 따라 경매절차가 진행되어 매각허가결정이 확정되고 매수인이 매각대금을 완납하였더라도, 그 근저당권은 소멸하지 않는다.","ox":"X","m":"④","c":"A"},{"y":2016,"e":"변리사 1차","qn":22,"i":"변리사2016_53-22-5","t":"근저당권에 있어서 피담보채무의 이자는 최고액 중에 산입한 것으로 본다.","ox":"O","m":"⑤","c":"A"},{"y":2016,"e":"변리사 1차","qn":23,"i":"변리사2016_53-23","t":"甲소유의 X토지와 乙소유의 Y건물에 甲의 丙에 대한 채무 5억원을 담보하기 위하여 공동저당권이 설정되었고, X토지에는 甲의 丁에 대한 피담보채무 4억원을 담보하기 위하여 丁 명의의 2번 저당권이 설정되었다. X토지와 Y건물의 경매대가가 각각 4억원인 경우, 옳은 것을 모두 고른 것은? (매각 비용, 이자는 고려","c":"A","mc":{"s":"甲소유의 X토지와 乙소유의 Y건물에 甲의 丙에 대한 채무 5억원을 담보하기 위하여 공동저당권이 설정되었고, X토지에는 甲의 丁에 대한 피담보채무 4억원을 담보하기 위하여 丁 명의의 2번 저당권이 설정되었다. X토지와 Y건물의 경매대가가 각각 4억원인 경우, 옳은 것을 모두 고른 것은? (매각 비용, 이자는 고려","d":"하지 않으며, 다툼이 있으면 판례에 따름)\nㄱ. X토지의 경매대가가 먼저 배당되는 경우, 丁은 Y건물의 경매대가에서 배당받지 못한다.\nㄴ. Y건물의 경매대가가 먼저 배당되는 경우, 乙은 X토지의 경매대가에서 3억원을 배당받을 수 있다.\nㄷ. X토지와 Y건물의 경매대가가 동시에 배당되는 경우, 丁은 Y건물의 경매대가에서 1억 5천만원을 배당받을 수 있다.","o":["ㄴ","ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":2}},{"y":2016,"e":"변리사 1차","qn":24,"i":"변리사2016_53-24","t":"甲이 乙에 대한 1억원의 채무를 담보하기 위하여 자신의 소유인 X기계를 乙에게 점유개정의 방법으로 양도하였다. 그 후 甲이 丙에 대한 다른 금전채무 5천만원을 담보하기 위하여 다시 점유개정의 방법으로 X기계를 丙에게 양도하였다. 이에 관한 설명으로 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"甲이 乙에 대한 1억원의 채무를 담보하기 위하여 자신의 소유인 X기계를 乙에게 점유개정의 방법으로 양도하였다. 그 후 甲이 丙에 대한 다른 금전채무 5천만원을 담보하기 위하여 다시 점유개정의 방법으로 X기계를 丙에게 양도하였다. 이에 관한 설명으로 옳은 것을 모두 고른 것은?","d":"ㄱ. 甲과 乙 사이의 대내적 관계에서 X기계의 소유권은 乙에게 있다.\nㄴ. 甲이 X기계에 대한 점유를 상실하면 乙은 X기계에 대한 양도담보권을 상실한다.\nㄷ. 丙은 선의취득에 의하여 양도담보권을 취득한다.\nㄹ. 丙이 乙에게 양도담보권이 있음을 알면서 甲으로부터 그 기계를 인도받아 제3자에게 처분함으로써 乙의 담보권실행을 방해하였다면, 丙의 행위는 위법한 것으로 불법행위에 기한 손해배상청구의 대상이 될 수 있다.","o":["ㄹ","ㄱ, ㄷ","ㄴ, ㄹ","ㄱ, ㄴ, ㄷ","ㄴ, ㄷ, ㄹ"],"a":1}},{"y":2017,"e":"변리사 1차","qn":19,"i":"변리사2017_54-19-1","t":"피담보채권을 저당권과 함께 양수한 자는 저당권 이전의 부기등기를 마치고 저당권실행의 요건을 갖추고 있는 한 채권양도의 대항요건을 갖추고 있지 아니하더라도 경매신청을 할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"변리사 1차","qn":19,"i":"변리사2017_54-19-2","t":"저당권설정자로부터 저당토지에 용익권을 설정 받은 자가 그 토지에 건물을 축조한 경우라도 그 후 저당권설정자가 그 건물의 소유권을 취득하였다면, 저당권자는 토지와 함께 그 건물에 대하여 경매를 신청할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"변리사 1차","qn":19,"i":"변리사2017_54-19-3","t":"피담보채권이 저당권과 분리되어 양도된 경우, 채권의 처분에 따르지 않는 저당권은 소멸한다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"변리사 1차","qn":19,"i":"변리사2017_54-19-4","t":"저당부동산에 대하여 지상권을 취득한 제3자는 채무자의 의사에 반하여 저당권자에게 그 부동산으로 담보된 채권을 변제하고 저당권의 소멸을 청구할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"변리사 1차","qn":19,"i":"변리사2017_54-19-5","t":"저당권의 효력은 저당부동산에 대한 압류가 없더라도 저당권설정자가 그 부동산 으로부터 수취한 과실 또는 수취할 수 있는 과실에 미친다.","ox":"X","m":"⑤","c":"A"},{"y":2017,"e":"변리사 1차","qn":20,"i":"변리사2017_54-20-1","t":"경매개시결정이 있은 후, 甲이 경매신청을 취하하였다면 채무확정의 효과는 번복된다.","ox":"X","m":"①","c":"A"},{"y":2017,"e":"변리사 1차","qn":20,"i":"변리사2017_54-20-2","t":"甲의 경매신청 시에 근저당권이 확정되므로, 그 이후에 발생하는 甲의 원본채권은 근저당으로 담보되지 않는다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"변리사 1차","qn":20,"i":"변리사2017_54-20-3","t":"근저당권의 실행에 따른 경매비용은 채권최고액 1천만원에 포함되지 아니한다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"변리사 1차","qn":20,"i":"변리사2017_54-20-4","t":"甲의 피담보채권이 확정되기 전에 발생한 원본채권에 관하여 그 확정 후에 발생하는 원본채권의 이자나 지연손해금은 채권최고액의 범위 내에서는 근저당권에 의하여 담보된다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"변리사 1차","qn":20,"i":"변리사2017_54-20-5","t":"만일 X토지에 대하여 후순위 저당권을 취득한 丙이 경매를 신청한 경우에는 그 매각대금 완납 시에 甲의 피담보채권액이 확정된다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"변리사 1차","qn":22,"i":"변리사2017_54-22-1","t":"채권자와 채무자가 가등기담보권설정계약을 체결함에 있어 가등기 이후에 발생될 채무도 피담보채무의 범위에 포함시키기로 한 약정은 유효하다.","ox":"O","m":"①","c":"A","tp":"비전형담보"},{"y":2017,"e":"변리사 1차","qn":22,"i":"변리사2017_54-22-2","t":"가등기가 금전소비대차에 기한 차용금반환채무와 그 외의 원인으로 발생한 채무를 동시에 담보할 목적으로 경료되었으나 그 후 금전소비대차에 기한 차용금반 환채무만이 남게 된 경우, 그 가등기담보에 「가등기담보 등에 관한 법률」이 적용된다.","ox":"O","m":"②","c":"A","tp":"비전형담보"},{"y":2017,"e":"변리사 1차","qn":22,"i":"변리사2017_54-22-3","t":"양도담보 목적물이 소실되어 양도담보 설정자가 보험회사에 대하여 화재보험계 약에 따른 보험금청구권을 취득한 경우, 양도담보권자는 위 보험금청구권에 대하여 양도담보권에 기한 물상대위권을 행사할 수 있다.","ox":"O","m":"③","c":"A","tp":"비전형담보"},{"y":2017,"e":"변리사 1차","qn":22,"i":"변리사2017_54-22-4","t":"양도담보권자는 사용\u0001수익할 수 있는 정당한 권한이 있는 채무자나 그 채무자 로부터 사용\u0001수익할 수 있는 권한을 승계한 자에 대하여 그 사용\u0001수익을 하지 못한 것을 이유로 임료 상당의 손해배상이나 부당이득반환을 청구할 수 있다.","ox":"X","m":"④","c":"A","tp":"비전형담보"},{"y":2017,"e":"변리사 1차","qn":22,"i":"변리사2017_54-22-5","t":"채무자가 채무를 변제하고 가등기말소를 구하는 경우, 채무변제와 담보가등기말 소는 동시이행관계가 아니라 채무변제가 선이행의무이다.","ox":"O","m":"⑤","c":"A","tp":"비전형담보"},{"y":2017,"e":"변리사 1차","qn":23,"i":"변리사2017_54-23","t":"甲은 자신의 채권담보를 위해 乙로부터 X동산에 질권을 설정받아 이를 점유하고 있다. 이에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면","c":"A","mc":{"s":"甲은 자신의 채권담보를 위해 乙로부터 X동산에 질권을 설정받아 이를 점유하고 있다. 이에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면","d":"판례에 따름)\nㄱ. X동산의 소유자 乙이 제3자에 대하여 가지는 목적물반환청구권의 양도 의 방법으로 甲에게 질권을 설정하는 것도 유효하다.\nㄴ. 乙이 X동산에 대한 처분권 없이 질권을 설정한 경우, 甲이 X동산의 선의취득에 필요한 요건을 갖추었더라도 甲은 질권을 취득할 수 없다.\nㄷ. 甲의 채무자인 丙의 부탁을 받고 乙이 X동산에 질권을 설정한 경우, 甲의 질권 실행으로 X동산의 소유권을 상실한 乙은 자신의 구상범위 내에서 甲의 丙에 대한 권리를 대위할 수 있다.\nㄹ. 만약 X동산이 타인의 물건에 부합되어 乙이 보상금을 지급받은 경우, 甲은 물상대위권을 행사할 수 없다.","o":["ㄱ, ㄴ","ㄱ, ㄹ","ㄴ, ㄷ","ㄱ, ㄷ, ㄹ","ㄴ, ㄷ, ㄹ"],"a":4}},{"y":2017,"e":"변리사 1차","qn":24,"i":"변리사2017_54-24-1","t":"특별한 사정이 없는 한, 간접점유는 유치권의 성립요건이자 존속요건인 점유에 해당한다.","ox":"O","m":"①","c":"A","tp":"민사유치권"},{"y":2017,"e":"변리사 1차","qn":24,"i":"변리사2017_54-24-2","t":"건축자재공급업자가 건물 신축공사 수급인과 체결한 자재공급계약에 따라 건축 자재를 공급한 경우, 자재공급업자는 자재대금을 피담보채권으로 하여 건물에 대한 유치권을 행사할 수 없다.","ox":"O","m":"②","c":"A","tp":"민사유치권"},{"y":2017,"e":"변리사 1차","qn":24,"i":"변리사2017_54-24-3","t":"유치권에 의한 경매절차가 정지된 상태에서 그 목적물에 대한 담보권실행을 위한 경매가 진행되어 매각이 이루어지게 되면 그 유치권은 소멸한다.","ox":"X","m":"③","c":"A","tp":"민사유치권"},{"y":2017,"e":"변리사 1차","qn":24,"i":"변리사2017_54-24-4","t":"유치권자로부터 유치물을 유치하기 위한 방법으로 유치물의 점유를 위탁받은 자는 특별한 사정이 없는 한 점유할 권리가 있음을 들어 소유자의 소유물반환청구를 거부할 수 있다.","ox":"O","m":"④","c":"A","tp":"민사유치권"},{"y":2017,"e":"변리사 1차","qn":24,"i":"변리사2017_54-24-5","t":"건물신축공사를 도급받은 수급인은 사회통념상 독립한 건물이 되지 못한 정착물을 토지에 설치한 상태에서 공사가 중단된 경우, 위 정착물에 대하여 유치권을 행사할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"민사유치권"},{"y":2018,"e":"변리사 1차","qn":23,"i":"변리사2018_55-23-1","t":"세금체납을 이유로 한 체납처분압류가 되어 있는 부동산에 대한 경매절차가 개시되기 전에 유치권을 취득한 유치권자는 그 경매절차의 매수인에게 유치권을 주장할 수 없다.","ox":"X","m":"①","c":"A","tp":"민법상의 유치권"},{"y":2018,"e":"변리사 1차","qn":23,"i":"변리사2018_55-23-2","t":"아직 변제기에 이르지 아니한 채권에 기해서는 유치권을 행사할 수 없다.","ox":"O","m":"②","c":"A","tp":"민법상의 유치권"},{"y":2018,"e":"변리사 1차","qn":23,"i":"변리사2018_55-23-3","t":"매도인이 중도금만 받고서 매수인에게 부동산의 소유권을 이전한 경우, 매도인은 잔금채권을 피담보채권으로 하여 매수인에 대하여 유치권을 행사할 수 있다.","ox":"X","m":"③","c":"A","tp":"민법상의 유치권"},{"y":2018,"e":"변리사 1차","qn":23,"i":"변리사2018_55-23-4","t":"부동산 근저당권에 기한 압류의 효력이 발생한 후에 취득한 유치권으로 그 근저당권에 기한 경매절차의 매수인에게 대항할 수 있다.","ox":"X","m":"④","c":"A","tp":"민법상의 유치권"},{"y":2018,"e":"변리사 1차","qn":23,"i":"변리사2018_55-23-5","t":"건물신축공사를 도급받은 수급인이 사회통념상 독립한 건물이 되지 못한 정착물을 토지에 설치한 상태에서 공사가 중단된 경우, 토지에 대하여 유치권을 행사할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"민법상의 유치권"},{"y":2019,"e":"변리사 1차","qn":18,"i":"변리사2019_56-18-1","t":"질물의 과실에 대해서도 질권의 효력이 미친다.","ox":"O","m":"①","c":"A","tp":"동산질권"},{"y":2019,"e":"변리사 1차","qn":18,"i":"변리사2019_56-18-2","t":"질권설정을 위한 인도는 현실의 인도에 한하지 않고 점유개정에 의하더라도 무방하다.","ox":"X","m":"②","c":"A","tp":"동산질권"},{"y":2019,"e":"변리사 1차","qn":18,"i":"변리사2019_56-18-3","t":"질권자가 질물을 점유하고 있더라도 피담보채권의 소멸시효 진행에 영향을 미치지 않는다.","ox":"O","m":"③","c":"A","tp":"동산질권"},{"y":2019,"e":"변리사 1차","qn":18,"i":"변리사2019_56-18-4","t":"건물의 임대인이 임대차에 관한 채권에 의하여 그 건물에 부속한 임차인 소유의 동산을 압류한 때에는 질권과 동일한 효력이 있다.","ox":"O","m":"④","c":"A","tp":"동산질권"},{"y":2019,"e":"변리사 1차","qn":18,"i":"변리사2019_56-18-5","t":"질권설정자에게 처분권한이 없더라도 채권자가 평온·공연하게 선의이며 과실 없이 질권설정을 받은 경우, 채권자는 동산질권을 선의취득한다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"변리사 1차","qn":19,"i":"변리사2019_56-19-1","t":"채권자가 채무자의 직접점유를 통하여 간접점유하는 경우에는 유치권은 성립하지 않는다.","ox":"O","m":"①","c":"A","tp":"민사유치권"},{"y":2019,"e":"변리사 1차","qn":19,"i":"변리사2019_56-19-2","t":"유치권자는 채권의 변제를 받기 위하여 유치물을 경매할 수 있고, 매각대금에서 후순위 권리자보다 우선변제를 받을 수 있다.","ox":"X","m":"②","c":"A","tp":"민사유치권"},{"y":2019,"e":"변리사 1차","qn":19,"i":"변리사2019_56-19-3","t":"수급인이 자신의 노력과 재료를 들여 신축한 건물에 대한 소유권을 원시취득한 경우, 수급인은 공사대금을 지급받을 때까지 유치권을 행사할 수 있다.","ox":"X","m":"③","c":"A","tp":"민사유치권"},{"y":2019,"e":"변리사 1차","qn":19,"i":"변리사2019_56-19-4","t":"유치권의 피담보채권의 소멸시효기간이 확정판결 등에 의하여 10년으로 연장된 경우, 유치권이 성립된 부동산의 매수인은 종전의 단기소멸시효를 원용할 수 있다.","ox":"X","m":"④","c":"A","tp":"민사유치권"},{"y":2019,"e":"변리사 1차","qn":19,"i":"변리사2019_56-19-5","t":"공사대금채권에 기하여 유치권을 행사하는 자가 스스로 보존에 필요한 범위 내에서 유치물인 주택에 거주하며 사용하는 경우에도 소유자는 유치권의 소멸을 청구할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"민사유치권"},{"y":2019,"e":"변리사 1차","qn":21,"i":"변리사2019_56-21-4","t":"丙이 임대차계약서상에 확정일자를 받았다면, 丙은 甲에 우선하여 보증금 전액에 대해 우선변제를 받을 수 있다.","ox":"X","m":"④","c":"A","tp":"甲은 乙"},{"y":2019,"e":"변리사 1차","qn":21,"i":"변리사2019_56-21-5","t":"丙이 적법하게 배당요구를 하였다면 배당받을 수 있었던 금액이 丙의 적법한 배당요구가 없어서 丁과 戊에게 배당된 경우, 丙은 丁과 戊에게 부당이득반환을 청구할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"甲은 乙"},{"y":2019,"e":"변리사 1차","qn":22,"i":"변리사2019_56-22-1","t":"甲이 담보권실행을 통지할 때에 청산금이 없더라도 2개월의 청산기간이 지나기 전에는 가등기에 기한 본등기를 청구할 수 없다.","ox":"O","m":"①","c":"A","tp":"甲은 乙"},{"y":2019,"e":"변리사 1차","qn":22,"i":"변리사2019_56-22-2","t":"甲이 담보권실행을 통하여 우선변제 받게 되는 이자나 지연배상금 등 피담보채권의 범위는 청산금 지급 당시를 기준으로 확정된다.","ox":"X","m":"②","c":"A","tp":"甲은 乙"},{"y":2019,"e":"변리사 1차","qn":22,"i":"변리사2019_56-22-3","t":"甲이 담보권실행을 통지하고 2개월의 청산기간이 지난 경우, 청산금의 지급이 없더라도 乙은 대여금을 변제하고 가등기말소를 청구할 수는 없다.","ox":"X","m":"③","c":"A","tp":"甲은 乙"},{"y":2019,"e":"변리사 1차","qn":22,"i":"변리사2019_56-22-4","t":"甲이 주관적으로 평가한 청산금의 액수가 정당하게 평가된 청산금의 액수에 미치지 못하면 담보권실행 통지는 효력이 없다.","ox":"X","m":"④","c":"A","tp":"甲은 乙"},{"y":2019,"e":"변리사 1차","qn":22,"i":"변리사2019_56-22-5","t":"甲이 담보권실행을 위해 통지하여야 할 청산금의 평가액은 통지 당시의 목적부동산 가액에서 그 당시의 목적부동산에 존재하는 모든 피담보채권액을 공제한 차액이다.","ox":"X","m":"⑤","c":"A","tp":"甲은 乙"},{"y":2019,"e":"변리사 1차","qn":23,"i":"변리사2019_56-23","t":"채권자 甲이 채무자 乙에 대한 1억원의 채권을 담보하기 위해 물상보증인 丙 소유의 X부동산(가액 1억 2,000만원), 丁 소유의 Y부동산(가액 8,000만원)에 각각 1번 저당권을 취득하고, A가 8,000만원의 채권으로 X부동산에, B가 6,000만원 의 채권으로 Y부동산에 각각 2번 저당권을 취득하였다. 甲이 X부동산에 대하여 먼저 담보권실행을 위한 경매를 하여 매각대금 1억 2,000만원이 배당순위에 따라 甲과 A에게 배당되었다. 이 경우 A가 Y부동산의 매각대금(8,000만원)에서 배당받을 수 있는 금액은?","c":"A","mc":{"s":"채권자 甲이 채무자 乙에 대한 1억원의 채권을 담보하기 위해 물상보증인 丙 소유의 X부동산(가액 1억 2,000만원), 丁 소유의 Y부동산(가액 8,000만원)에 각각 1번 저당권을 취득하고, A가 8,000만원의 채권으로 X부동산에, B가 6,000만원 의 채권으로 Y부동산에 각각 2번 저당권을 취득하였다. 甲이 X부동산에 대하여 먼저 담보권실행을 위한 경매를 하여 매각대금 1억 2,000만원이 배당순위에 따라 甲과 A에게 배당되었다. 이 경우 A가 Y부동산의 매각대금(8,000만원)에서 배당받을 수 있는 금액은?","d":"(단, 실행비용\u0001이자 등은 고려하지 않고, 다툼이 있\n으면 판례에 따름)","o":["0원","2,000만원","4,000만원","6,000만원","8,000만원"],"a":3}},{"y":2019,"e":"변리사 1차","qn":24,"i":"변리사2019_56-24-1","t":"질권의 목적인 채권의 양도행위에는 질권자의 동의가 필요하다.","ox":"X","m":"①","c":"A","tp":"채권질권"},{"y":2019,"e":"변리사 1차","qn":24,"i":"변리사2019_56-24-2","t":"채권의 목적물이 금전인 때에는 질권자는 자기 채권의 한도에서 직접 청구할 수 있다.","ox":"O","m":"②","c":"A","tp":"채권질권"},{"y":2019,"e":"변리사 1차","qn":24,"i":"변리사2019_56-24-3","t":"채권질권의 효력은 질권의 목적이 된 채권의 지연손해금 등과 같은 부대채권에도 미친다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"변리사 1차","qn":24,"i":"변리사2019_56-24-4","t":"저당권으로 담보한 채권을 질권의 목적으로 한 때에는 그 저당권등기에 질권의 부기등기를 하여야 그 효력이 저당권에 미친다.","ox":"O","m":"④","c":"A","tp":"채권질권"},{"y":2019,"e":"변리사 1차","qn":24,"i":"변리사2019_56-24-5","t":"제3채무자가 질권설정 사실을 승낙한 후 질권설정계약이 합의해지된 경우, 질권설정자가 해지를 이유로 제3채무자에게 원래의 채권으로 대항하려면 질권자가 제3채무자에게 해지 사실을 통지하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"채권질권"},{"y":2021,"e":"변리사 1차","qn":19,"i":"변리사2021_58-19-1","t":"구분건물의 전유부분에 설정된 저당권의 효력은 특별한 사정이 없는 한 그 전유부분의 소유자가 나중에 취득한 대지권에도 미친다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"변리사 1차","qn":19,"i":"변리사2021_58-19-2","t":"저당목적물에 갈음하는 금전의 인도청구권에 대하여 저당권자가 압류하기 전에 그 금전이 물상보증인에게 지급되었더라도, 저당권자는 물상보증인에게 부당이득반환을 청구할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"변리사 1차","qn":19,"i":"변리사2021_58-19-3","t":"저당권부 채권을 양수한 채권자가 채권양도의 대항요건을 갖추지 않은 경우에는 그보다 후순위 저당권자에 대하여 채권양도로써 대항할 수 없다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"변리사 1차","qn":19,"i":"변리사2021_58-19-4","t":"물상대위권을 행사하지 아니하여 우선변제권을 상실한 저당권자는 저당목적물에 갈음한 보상금으로 이득을 얻은 다른 채권자에 대하여 그 이익을 부당이득으로 반환청구할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"변리사 1차","qn":19,"i":"변리사2021_58-19-5","t":"저당부동산에 대하여 전세권을 취득한 제3자는 저당권자에게 그 부동산으로 담보된 채권을 변제하고 저당권의 소멸을 청구할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"변리사 1차","qn":21,"i":"변리사2021_58-21-1","t":"유치권자는 유치물의 과실(果實)이 금전인 경우, 이를 수취하여 다른 채권보다 먼저 유치권으로 담보된 채권의 변제에 충당할 수 있다.","ox":"O","m":"①","c":"A","tp":"민사유치권"},{"y":2021,"e":"변리사 1차","qn":21,"i":"변리사2021_58-21-2","t":"유치권자가 유치물의 보존에 필요한 사용을 한 경우에는 특별한 사정이 없는 한, 차임 상당의 이득을 소유자에게 반환할 의무가 없다.","ox":"X","m":"②","c":"A","tp":"민사유치권"},{"y":2021,"e":"변리사 1차","qn":21,"i":"변리사2021_58-21-3","t":"건물공사대금의 채권자가 그 건물에 대하여 유치권을 행사하는 동안에는 그 공사대금채권의 소멸시효가 진행하지 않는다.","ox":"X","m":"③","c":"A","tp":"민사유치권"},{"y":2021,"e":"변리사 1차","qn":21,"i":"변리사2021_58-21-4","t":"임대인과 임차인 사이에 임대차 종료에 따른 건물명도 시에 권리금을 반환하기로 약정한 경우, 임차인은 권리금반환청구권을 가지고 건물에 대한 유치권을 행사할 수 있다.","ox":"X","m":"④","c":"A","tp":"민사유치권"},{"y":2021,"e":"변리사 1차","qn":21,"i":"변리사2021_58-21-5","t":"유치권자가 경매개시결정등기 전에 부동산에 관하여 유치권을 취득하였더라도 그 취득에 앞서 저당권설정등기가 먼저 되어 있었다면, 경매절차의 매수인에게 자기의 유치권으로 대항할 수 없다.","ox":"X","m":"⑤","c":"A","tp":"민사유치권"},{"y":2021,"e":"변리사 1차","qn":23,"i":"변리사2021_58-23-1","t":"피담보채권액이 입질채권액보다 적은 경우에도 질권의 효력은 입질채권 전부에 미친다.","ox":"O","m":"①","c":"A","tp":"채권질권"},{"y":2021,"e":"변리사 1차","qn":23,"i":"변리사2021_58-23-2","t":"주택임차인이 보증금반환채권을 담보로 질권을 설정한 경우, 질권자에게 임대차계약 서를 교부하지 않았더라도 그 질권은 유효하다.","ox":"O","m":"②","c":"A","tp":"채권질권"},{"y":2021,"e":"변리사 1차","qn":23,"i":"변리사2021_58-23-3","t":"질권설정자가 제3채무자에게 질권설정 사실을 통지한 후 제3채무자가 질권자의 동의 없이 질권설정자와 상계합의를 하여 질권의 목적인 채무를 소멸하게 한 경우, 질권자는 제3채무자에 대하여 직접 채무의 변제를 청구할 수 있다.","ox":"O","m":"③","c":"A","tp":"채권질권"},{"y":2021,"e":"변리사 1차","qn":23,"i":"변리사2021_58-23-4","t":"저당권부 채권에 질권을 설정한 경우에는 그 저당권등기에 질권의 부기등기를 하여야 질권의 효력이 저당권에 미친다.","ox":"O","m":"④","c":"A","tp":"채권질권"},{"y":2021,"e":"변리사 1차","qn":23,"i":"변리사2021_58-23-5","t":"저당권부 채권에 질권을 설정하면서 그 저당권의 피담보채권만을 질권의 목적으로 하고 저당권은 질권의 목적으로 하지 않는 것은 저당권의 부종성에 반하여 허용되지 않는다.","ox":"X","m":"⑤","c":"A","tp":"채권질권"},{"y":2023,"e":"변리사 1차","qn":20,"i":"변리사2023_60-20-1","t":"채무자는 상당한 담보를 제공하고 유치권의 소멸을 청구할 수 있는데, 유치물 가액이 피담보채권액보다 적을 경우에는 피담보채권액에 해당하는 담보를 제공하여야 한다.","ox":"X","m":"①","c":"A","tp":"민사유치권"},{"y":2023,"e":"변리사 1차","qn":20,"i":"변리사2023_60-20-2","t":"유치권자가 유치물에 대한 점유를 빼앗긴 경우에도 점유물반환청구권을 보유하고 있다면 점유를 회복하기 전에도 유치권이 인정된다.","ox":"X","m":"②","c":"A","tp":"민사유치권"},{"y":2023,"e":"변리사 1차","qn":20,"i":"변리사2023_60-20-3","t":"유치권의 존속 중에 유치물의 소유권이 제3자에게 양도된 경우에는 유치권자는 그 제3자에 대하여 유치권을 행사할 수 없다.","ox":"X","m":"③","c":"A","tp":"민사유치권"},{"y":2023,"e":"변리사 1차","qn":20,"i":"변리사2023_60-20-4","t":"유익비상환청구권을 담보하기 위하여 유치권을 행사하고 있는 경우에도, 법원이 유익비상환청구에 대하여 상당한 상환기간을 허락하면 유치권이 소멸한다.","ox":"O","m":"④","c":"A","tp":"민사유치권"},{"y":2023,"e":"변리사 1차","qn":20,"i":"변리사2023_60-20-5","t":"수급인은 도급계약에 따라 자신의 재료와 노력으로 건축된 자기 소유의 건물에 대해 서도 도급인으로부터 공사대금을 지급받을 때까지 유치권을 가진다.","ox":"X","m":"⑤","c":"A","tp":"민사유치권"},{"y":2023,"e":"변리사 1차","qn":21,"i":"변리사2023_60-21","t":"甲은 2021. 3. 6. 乙로부터 X주택을 보증금 10억 원에 임차하였고, 2021. 3. 13. 丙으로부터 6억 원을 대출받으면서 보증금반환채권 중 8억 원에 대하여 질권을 설정해 주었으며, 乙은 이를 승낙하였다. 乙은 2022. 6. 30. 甲에게 X주택을 15억 원에 매도하면서, 甲으로부터 보증금을 제외한 잔액을 지급받고서 소유권이전등 기절차를 마쳐주었다. 이에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있","c":"A","mc":{"s":"甲은 2021. 3. 6. 乙로부터 X주택을 보증금 10억 원에 임차하였고, 2021. 3. 13. 丙으로부터 6억 원을 대출받으면서 보증금반환채권 중 8억 원에 대하여 질권을 설정해 주었으며, 乙은 이를 승낙하였다. 乙은 2022. 6. 30. 甲에게 X주택을 15억 원에 매도하면서, 甲으로부터 보증금을 제외한 잔액을 지급받고서 소유권이전등 기절차를 마쳐주었다. 이에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있","d":"으면 판례에 따름)\nㄱ. 甲이 보증금반환채권에 대하여 질권을 설정하기 위해서는 질권설정의 합의 와 함께 임대차계약서를 교부하여야 한다.\nㄴ. 甲과 乙이 丙의 동의 없이 매매대금과 보증금반환채권을 상계한 것은 질권의 목적인 채무를 소멸하게 한 경우에 해당한다.\nㄷ. 만약 甲이 2021. 4. 20. 보증금반환채권을 담보하기 위하여 X주택에 대한 근저당권을 설정 받았다면, 丙이 가진 질권의 효력은 당연히 근저당권에도 미친다.\nㄹ. 乙이 X주택을 임차인인 甲에게 매도하였지만, 丙은 乙에게 직접 채무의 변제를 청구할 수 있다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄱ, ㄹ","ㄴ, ㄷ","ㄴ, ㄹ"],"a":5}},{"y":2023,"e":"변리사 1차","qn":22,"i":"변리사2023_60-22-1","t":"경매절차의 매수인이 증축부분의 소유권을 취득하기 위해서는 부합된 증축부분이 기존건물에 대한 경매절차에서 경매목적물로 평가되어야 한다.","ox":"X","m":"①","c":"A","tp":"민법상 저당권의 효력이 미치는 목적물의 범위"},{"y":2023,"e":"변리사 1차","qn":22,"i":"변리사2023_60-22-2","t":"건물의 증축부분이 저당목적물인 기존의 건물에 부합한 경우에는 특별한 사정이 없는한 저당권의 효력이 증축부분에도 미친다.","ox":"O","m":"②","c":"A","tp":"민법상 저당권의 효력이 미치는 목적물의 범위"},{"y":2023,"e":"변리사 1차","qn":22,"i":"변리사2023_60-22-3","t":"어떤 물건이 저당권이 설정된 후에 저당목적물의 종물이 된 경우에도 그 종물에 대하여 저당권의 효력이 미친다.","ox":"O","m":"③","c":"A","tp":"민법상 저당권의 효력이 미치는 목적물의 범위"},{"y":2023,"e":"변리사 1차","qn":22,"i":"변리사2023_60-22-4","t":"건물의 소유를 목적으로 하여 토지를 임차한 사람이 그 건물에 저당권을 설정한 때에는, 저당권의 효력은 그 건물의 소유를 목적으로 한 토지임차권에도 미친다.","ox":"O","m":"④","c":"A","tp":"민법상 저당권의 효력이 미치는 목적물의 범위"},{"y":2023,"e":"변리사 1차","qn":22,"i":"변리사2023_60-22-5","t":"특별한 사정이 없는 한 저당목적물인 건물에 대한 저당권자의 압류가 있으면 저당권 설정자의 건물 임차인에 대한 차임채권에 저당권의 효력이 미친다.","ox":"O","m":"⑤","c":"A","tp":"민법상 저당권의 효력이 미치는 목적물의 범위"},{"y":2023,"e":"변리사 1차","qn":23,"i":"변리사2023_60-23-1","t":"결산기에 확정된 채권액이 채권최고액을 넘는 경우, 채무자 겸 근저당권설정자는 최고액을 임의로 변제하더라도 근저당권등기의 말소를 청구할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"변리사 1차","qn":23,"i":"변리사2023_60-23-2","t":"공동근저당권자가 X건물과 Y건물에 대하여 공동저당을 설정한 후, 제3자가 신청한 X건물에 대한 경매절차에 참가하여 배당을 받으면, Y건물에 대한 피담보채권도 확정된다.","ox":"X","m":"②","c":"A"},{"y":2023,"e":"변리사 1차","qn":23,"i":"변리사2023_60-23-3","t":"공동근저당권자가 후순위근저당권자에 의하여 개시된 경매절차에서 피담보채권의 일부를 배당받은 경우, 우선변제 받은 금액에 관하여는 다시 공동근저당권자로서 우선변제권을 행사할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"변리사 1차","qn":23,"i":"변리사2023_60-23-4","t":"원본의 이행기일을 경과한 후 발생하는 지연손해금 중 1년이 지난 기간에 대한 지연손해금도 근저당권의 채권최고액 한도에서 전액 담보된다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"변리사 1차","qn":23,"i":"변리사2023_60-23-5","t":"근저당권의 피담보채권인 원본채권이 확정된 후에 발생하는 이자나 지연손해금 채권은 그 근저당권의 채권최고액의 범위에서 여전히 담보된다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"변리사 1차","qn":24,"i":"변리사2023_60-24-1","t":"가등기담보권자가 목적물의 소유권을 취득하려면 담보설정 당시 목적물의 평가액과 피담보채권액의 범위를 밝혀야 한다.","ox":"X","m":"①","c":"A","tp":"가등기담보 등"},{"y":2023,"e":"변리사 1차","qn":24,"i":"변리사2023_60-24-2","t":"가등기담보권자의 청산금 지급채무와 가등기담보권설정자의 소유권이전등기 및 인도 채무는 동시이행관계에 있다.","ox":"O","m":"②","c":"A","tp":"가등기담보 등"},{"y":2023,"e":"변리사 1차","qn":24,"i":"변리사2023_60-24-3","t":"목적부동산의 평가액이 채권액에 미달하여 청산금이 없다고 인정되는 때에는 그 뜻을 채무자에게 통지할 필요가 없다.","ox":"X","m":"③","c":"A","tp":"가등기담보 등"},{"y":2023,"e":"변리사 1차","qn":24,"i":"변리사2023_60-24-4","t":"채권자가 담보목적부동산에 관하여 이미 소유권이전등기를 마친 경우에는 청산금을 채무자에게 지급하지 않더라도 담보목적부동산의 소유권을 취득한다.","ox":"X","m":"④","c":"A","tp":"가등기담보 등"},{"y":2023,"e":"변리사 1차","qn":24,"i":"변리사2023_60-24-5","t":"채권자가 평가한 청산금의 액수가 정당하게 평가된 청산금의 액수에 미치지 못하는 경우에는 담보권 실행통지로서의 효력이 없다.","ox":"X","m":"⑤","c":"A","tp":"가등기담보 등"},{"y":2023,"e":"변리사 1차","qn":29,"i":"변리사2023_60-29","t":"甲은 乙로부터 5억 원을 차용하면서 자신의 X부동산(시가 3억 원)과 丙 소유의 Y부동산(시가 4억 원)에 공동저당권을 설정하고, 丁에게 부탁하여 연대보증인이 되도록 하였다. 이에 관한 설명으로 옳지 않은 것은? (부동산의 시가 변동이 없고","c":"A","mc":{"s":"甲은 乙로부터 5억 원을 차용하면서 자신의 X부동산(시가 3억 원)과 丙 소유의 Y부동산(시가 4억 원)에 공동저당권을 설정하고, 丁에게 부탁하여 연대보증인이 되도록 하였다. 이에 관한 설명으로 옳지 않은 것은? (부동산의 시가 변동이 없고","d":"이자 기타 비용은 고려하지 않으며, 다툼이 있으면 판례에 따름)","o":["甲이 자신의 유일한 재산인 X부동산을 매도한 경우 甲의 일반채권자는 그 매매계약을 사해행위로 취소할 수 없다.","丁이 자신의 유일한 재산을 처분한 경우 乙은 이를 사해행위로 취소할 수 있다.","乙에게 2억 원을 변제한 丁은 丙에 대하여 변제자대위를 하지 못한다.","丙이 5억 원 전액을 변제한 후 대위등기를 하기 전에 B가 X부동산을 취득하여 소유권이전등기를 마친 상황이라면 丙은 B에 대하여 변제자대위를 할 수 없다.","B가 X부동산을 취득하여 소유권이전등기를 마친 후 乙의 저당권실행경매로 B가 X부동 산의 소유권을 상실하더라도 B는 丙은 물론 丁에 대하여도 변제자대위를 하지 못한다."],"a":2}},{"y":2024,"e":"변리사 1차","qn":20,"i":"변리사2024_61-20-1","t":"채권자는 자기 소유의 물건에 대하여는 유치권을 취득할 수 없다.","ox":"O","m":"①","c":"A","tp":"민법상 유치권"},{"y":2024,"e":"변리사 1차","qn":20,"i":"변리사2024_61-20-2","t":"임대인과 임차인 사이에 건물명도시 권리금을 반환하기로 약정한 경우, 임차인은 권리금반환청구권을 피담보채권으로 하여 그 건물에 대하여 유치권을 행사할 수 없다.","ox":"O","m":"②","c":"A","tp":"민법상 유치권"},{"y":2024,"e":"변리사 1차","qn":20,"i":"변리사2024_61-20-3","t":"당사자가 미리 유치권의 발생을 배제하기로 하는 특약을 하는 것도 가능하다.","ox":"O","m":"③","c":"A","tp":"민법상 유치권"},{"y":2024,"e":"변리사 1차","qn":20,"i":"변리사2024_61-20-4","t":"어떠한 물건에 관련하여 채권이 발생한 후 채권자가 그 물건의 점유를 취득한 경우에도 유치권이 성립할 수 있다.","ox":"O","m":"④","c":"A","tp":"민법상 유치권"},{"y":2024,"e":"변리사 1차","qn":20,"i":"변리사2024_61-20-5","t":"유치권자가 소유자의 승낙 없이 유치목적물을 임대한 경우, 임차인의 점유는 소유자에게 대항할 수 있는 적법한 권원에 기한 것이다.","ox":"X","m":"⑤","c":"A","tp":"민법상 유치권"},{"y":2024,"e":"변리사 1차","qn":21,"i":"변리사2024_61-21-1","t":"동산질권은 선의취득의 대상이 될 수 있다.","ox":"O","m":"①","c":"A","tp":"민법상 질권"},{"y":2024,"e":"변리사 1차","qn":21,"i":"변리사2024_61-21-2","t":"저당권으로 담보한 채권을 질권의 목적으로 한 때에는 그 저당권등기에 질권의 부기등기를 하여야 그 효력이 저당권에 미친다.","ox":"O","m":"②","c":"A","tp":"민법상 질권"},{"y":2024,"e":"변리사 1차","qn":21,"i":"변리사2024_61-21-3","t":"근질권이 설정된 금전채권에 대하여 제3자의 압류로 강제집행절차가 개시된 경우, 근질 권의 피담보채권은 근질권자가 그 강제집행이 개시된 사실을 알게 된 때에 확정된다.","ox":"O","m":"③","c":"A","tp":"민법상 질권"},{"y":2024,"e":"변리사 1차","qn":21,"i":"변리사2024_61-21-4","t":"채무자의 부탁으로 그의 채무를 담보하기 위하여 자기 소유의 동산에 질권을 설정한 자는 그 채무의 이행기가 도래한 때 채무자에게 미리 구상권을 행사할 수 있다.","ox":"X","m":"④","c":"A","tp":"민법상 질권"},{"y":2024,"e":"변리사 1차","qn":21,"i":"변리사2024_61-21-5","t":"질물의 변형물인 금전 기타 물건에 대하여 이미 제3자가 압류한 경우, 질권자 스스로 이를 압류하지 않아도 물상대위권을 행사할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"민법상 질권"},{"y":2024,"e":"변리사 1차","qn":22,"i":"변리사2024_61-22-1","t":"구분지상권을 목적으로 하는 저당권의 설정도 가능하다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"변리사 1차","qn":22,"i":"변리사2024_61-22-2","t":"저당권 등기가 위법하게 말소된 후 그 저당부동산이 경매절차에서 매각된 경우, 저당권자는 매수인을 상대로 말소된 저당권 등기의 회복을 청구할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2024,"e":"변리사 1차","qn":22,"i":"변리사2024_61-22-3","t":"피담보채무의 소멸로 무효가 된 저당권 등기의 유용은 등기부상 이해관계가 있는 제3자가 생기지 않은 경우에 허용된다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"변리사 1차","qn":22,"i":"변리사2024_61-22-4","t":"저당부동산에 대한 압류가 있으면 압류 이후의 저당권설정자의 저당부동산에 관한 차임채권에도 저당권의 효력이 미친다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"변리사 1차","qn":22,"i":"변리사2024_61-22-5","t":"금전채권이 아닌 채권을 피담보채권으로 하는 저당권을 설정하면서 그 평가액을 등기한 경우, 채권자는 제3자에 대한 관계에 있어서 그 등기된 평가액의 한도에서만 저당권을 주장할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"변리사 1차","qn":23,"i":"변리사2024_61-23","t":"甲은 乙에 대한 3억 원의 채권을 담보하기 위하여 乙 소유의 X토지와 Y토지에 각각 1번 저당권을 설정하였다. 그 후 丙은 乙에 대한 2억 원의 피담보채권을 가지고 X토지에 2번 저당권을 설정하였다. 경매절차에서 X토지와 Y토지는 각각 4억 원, 2억 원에 매각되었다. 이에 관한 설명으로 옳은 것을 모두 고른 것은? (다","c":"A","mc":{"s":"甲은 乙에 대한 3억 원의 채권을 담보하기 위하여 乙 소유의 X토지와 Y토지에 각각 1번 저당권을 설정하였다. 그 후 丙은 乙에 대한 2억 원의 피담보채권을 가지고 X토지에 2번 저당권을 설정하였다. 경매절차에서 X토지와 Y토지는 각각 4억 원, 2억 원에 매각되었다. 이에 관한 설명으로 옳은 것을 모두 고른 것은? (다","d":"른 우선권자는 없고 원본만을 고려하며, 다툼이 있으면 판례에 따름)\nㄱ. 동시배당이 이루어지는 경우, 甲은 X토지의 매각대금으로부터 2억 원, Y토 지의 매각대금으로부터 1억 원을 배당받는다.\nㄴ. 먼저 X토지에 대한 경매가 이루어져 甲이 3억 원을 배당받은 경우, 丙은 Y토지에 대하여 1억 원의 범위에서 甲의 1번 저당권을 대위할 수 있다.\nㄷ. 먼저 X토지에 대한 경매가 이루어져 甲이 3억 원을 배당받은 경우, 만일 丙이 Y토지에 공동저당의 대위등기를 하지 아니한 사이에 甲이 Y토지에 대한 저당권을 말소하고 丁이 Y토지를 매수하여 소유권을 취득하였더라도 丙은 丁에 대하여 저당권을 주장할 수 있다.\nㄹ. 만일 甲이 경매가 개시되기 전에 Y토지에 대한 저당권을 포기하였다면 甲은 X토지의 매각대금으로부터 3억 원을 배당받고 丙은 Y토지에 대하여 1억 원의 범위에서 甲의 1번 저당권을 대위할 수 있다.","o":["ㄱ, ㄴ","ㄴ, ㄷ","ㄷ, ㄹ","ㄱ, ㄴ, ㄹ","ㄱ, ㄷ, ㄹ"],"a":1}},{"y":2024,"e":"변리사 1차","qn":24,"i":"변리사2024_61-24-1","t":"매매대금 채권을 담보하기 위하여 가등기를 한 경우에는 「가등기담보 등에 관한 법률」이 적용되지 않는다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"변리사 1차","qn":24,"i":"변리사2024_61-24-2","t":"가등기담보권이 설정되기 위해서는 피담보채권이 등기되어야 한다.","ox":"X","m":"②","c":"A"},{"y":2024,"e":"변리사 1차","qn":24,"i":"변리사2024_61-24-3","t":"당사자가 가등기담보권설정계약을 체결하면서 가등기 이후에 발생할 채권도 가등기부 동산의 피담보채권에 포함시키기로 약정한 경우, 이 약정은 특별한 사정이 없는 한유효하다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"변리사 1차","qn":24,"i":"변리사2024_61-24-4","t":"채권자가 가등기담보권을 실행하기 위해 청산금의 평가액을 통지하는 경우, 그가 주관적으로 평가한 청산금의 평가액을 통지하면 족하다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"변리사 1차","qn":24,"i":"변리사2024_61-24-5","t":"가등기담보권자는 담보목적부동산의 경매를 청구할 수 있고, 이 경우 경매에 관하여는 가등기담보권을 저당권으로 본다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"변리사 1차","qn":15,"i":"변리사2026_63-15","t":"저당권에 관한 설명으로 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"저당권에 관한 설명으로 옳은 것을 모두 고른 것은?","d":"ㄱ. 저당목적물인 건물에 대한 저당권자의 압류가 있으면 특별한 사정이 없는한 압류 이후의 저당권설정자의 건물 임차인에 대한 차임채권에도 저당권의 효력이 미친다.\nㄴ. 저당권 등기가 불법말소된 후 그 저당부동산이 경매절차에서 매각된 경우, 특별한 사정이 없는 한 저당권자는 경매절차의 매수인을 상대로 말소된 저당권 등기의 회복을 청구할 수 없다.\nㄷ. 채무자는 저당권자에게 ‘지연배상은 원본의 이행기일을 경과한 1년분에 한한다’는 민법 제360조에 근거하여 피담보채권의 제한을 주장할 수 있다.","o":["ㄱ","ㄷ","ㄱ, ㄴ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":3}},{"y":2026,"e":"변리사 1차","qn":16,"i":"변리사2026_63-16-1","t":"매매대금 채무를 담보하기 위하여 가등기를 한 경우에는 「가등기담보 등에 관한 법률」이 적용된다.","ox":"X","m":"①","c":"A"},{"y":2026,"e":"변리사 1차","qn":16,"i":"변리사2026_63-16-2","t":"공동명의로 담보가등기를 마친 수인(數人)의 채권자가 각자의 지분별로 별개의 독립 적인 매매예약완결권을 가지는 경우에도, 채권자 중 1인은 단독으로 자신의 지분에 관하여 소유권이전의 본등기절차 이행청구를 할 수 없다.","ox":"X","m":"②","c":"A","tp":"가등기담보"},{"y":2026,"e":"변리사 1차","qn":16,"i":"변리사2026_63-16-3","t":"담보가등기권리자가 담보목적부동산의 경매를 청구하는 방법을 선택하여 그 경매절차가 진행 중인 때에는 특별한 사정이 없는 한 그 가등기에 따른 본등기를 청구할 수 없다.","ox":"O","m":"③","c":"A","tp":"가등기담보"},{"y":2026,"e":"변리사 1차","qn":16,"i":"변리사2026_63-16-4","t":"채권자가 평가한 청산금의 액수가 정당하게 평가된 청산금의 액수에 미치지 못하는 경우에는 담보권 실행통지로서의 효력이 없다.","ox":"X","m":"④","c":"A","tp":"가등기담보"},{"y":2026,"e":"변리사 1차","qn":16,"i":"변리사2026_63-16-5","t":"채무담보를 위하여 가등기가 경료되어 있는 경우, 특별한 사정이 없는 한 피담보채무의 변제와 그 가등기말소절차의 이행의무는 동시이행관계에 있다.","ox":"X","m":"⑤","c":"A","tp":"가등기담보"},{"y":2026,"e":"변리사 1차","qn":22,"i":"변리사2026_63-22-1","t":"도급인과 수급인이 ‘수급인은 공사대금채권의 미지급을 이유로 신축건물에 유치권을 행사할 수 없다’는 약정을 한 경우, 수급인의 파산관재인은 유치권을 행사할 수 없다.","ox":"O","m":"①","c":"A","tp":"민법상 유치권"},{"y":2026,"e":"변리사 1차","qn":22,"i":"변리사2026_63-22-2","t":"상가임대인이 임차건물의 객관적 가치상승과 무관하게 임차인이 지출한 비용에 대해 서도 임차인에게 상환하기로 약정한 경우, 임차인은 그 채권을 피담보채권으로 하여 유치권을 행사할 수 있다.","ox":"X","m":"②","c":"A","tp":"민법상 유치권"},{"y":2026,"e":"변리사 1차","qn":22,"i":"변리사2026_63-22-3","t":"유치권자가 선관주의의무를 위반하여 유치물을 타인에게 임대한 경우, 그 후 유치물을 양수한 자는 유치권자에 대하여 선관주의의무 위반을 이유로 유치권소멸을 청구할 수 없다.","ox":"X","m":"③","c":"A","tp":"민법상 유치권"},{"y":2026,"e":"변리사 1차","qn":22,"i":"변리사2026_63-22-4","t":"甲이 하나의 채권을 피담보채권으로 하여 乙 소유 여러 필지의 토지에 대하여 유치권을 취득하고, 일부 필지의 토지에 대하여 乙의 승낙없이 무단으로 사무실을 설치한 경우, 乙은 甲에게 유치목적물 전부에 대한 유치권의 소멸을 청구할 수 있다.","ox":"X","m":"④","c":"A","tp":"민법상 유치권"},{"y":2026,"e":"변리사 1차","qn":22,"i":"변리사2026_63-22-5","t":"저당목적물에 유익비를 지출한 저당목적물의 제3취득자는 저당권실행에 따른 경매절차의 매수인에 대하여 민법 제367조의 제3취득자의 비용상환청구권을 피담보채권으로 하는 유치권을 행사할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"민법상 유치권"},{"y":2026,"e":"변리사 1차","qn":23,"i":"변리사2026_63-23-1","t":"임대차보증금반환채권에 대하여 질권을 설정하는 경우, 그 채권증서인 임대차계약서를 질권자에게 교부하여야 질권의 효력이 생긴다.","ox":"X","m":"①","c":"A","tp":"채권질권"},{"y":2026,"e":"변리사 1차","qn":23,"i":"변리사2026_63-23-2","t":"저당권부채권에 질권을 설정하면서 그 부기등기를 마친 경우, 채권의 지연손해금을 별도로 등기부에 기재하지 않더라도 지연손해금은 질권의 피담보채권의 범위에 속한다.","ox":"O","m":"②","c":"A","tp":"채권질권"},{"y":2026,"e":"변리사 1차","qn":23,"i":"변리사2026_63-23-3","t":"담보가 없는 채권에 질권이 설정된 후 그 채권담보를 위하여 저당권이 설정된 경우, 저당권설정등기에 질권의 부기등기를 하지 않으면 질권의 효력이 저당권에 미치지 않는다.","ox":"O","m":"③","c":"A","tp":"채권질권"},{"y":2026,"e":"변리사 1차","qn":23,"i":"변리사2026_63-23-4","t":"질권설정자는 질권자의 동의없이 질권의 목적인 채권을 양도할 수 있다.","ox":"O","m":"④","c":"A","tp":"채권질권"},{"y":2026,"e":"변리사 1차","qn":23,"i":"변리사2026_63-23-5","t":"질권설정자가 제3채무자에게 질권설정 사실을 통지한 후에는 제3채무자가 질권자의 동의 없이 질권의 목적인 채무를 질권설정자에게 변제하더라도 질권자에게 대항할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"채권질권"},{"y":2026,"e":"변리사 1차","qn":24,"i":"변리사2026_63-24","t":"물상보증인이 채무자를 위하여 저당권을 설정하는 경우에 관한 설명으로 옳지 않은 것을 모두 고른 것은?","c":"A","mc":{"s":"물상보증인이 채무자를 위하여 저당권을 설정하는 경우에 관한 설명으로 옳지 않은 것을 모두 고른 것은?","d":"ㄱ. 수탁보증인의 사전구상권에 관한 민법 제442조는 원칙적으로 물상보증인에 게도 적용되므로 물상보증인은 사전구상권을 행사할 수 있다.\nㄴ. 물상보증인이 담보권의 실행으로 타인의 채무를 담보하기 위하여 제공한 부동산의 소유권을 잃은 경우, 물상보증인이 채무자에게 구상할 수 있는 범위는 특별한 사정이 없는 한 매수인이 매각대금을 완납한 때의 부동산시 가가 아니라 매각대금을 기준으로 하여야 한다.\nㄷ. 근저당권의 물상보증인은 민법 제357조에서 말하는 채권의 최고액만을 변제하면 근저당권설정등기의 말소청구를 할 수 있고, 채권최고액을 초과하는 부분의 채권액까지 변제할 의무가 있는 것이 아니다.","o":["ㄱ","ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":2}}],"9":[{"y":2016,"e":"변리사 1차","qn":25,"i":"변리사2016_53-25-1","t":"목적물의 인도장소가 정해지지 않은 경우 특정물의 인도는 채권성립 당시 그 물건이 있던 장소에서 하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"변리사 1차","qn":25,"i":"변리사2016_53-25-2","t":"특정물채권에서 채무자의 목적물에 대한 선관주의의무의 존속기간은 특정물채무의 성립시부터 이행기까지이다.","ox":"X","m":"②","c":"A"},{"y":2016,"e":"변리사 1차","qn":25,"i":"변리사2016_53-25-3","t":"종류채권에서 지정권자로 된 채무자가 이행기가 지나도 이행할 물건을 지정하지 않는 경우, 채권자가 상당한 기간을 정하여 최고하였으나 채무자가 이행할 물건을 지정하지 않으면 지정권은 채권자에게 이전한다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"변리사 1차","qn":25,"i":"변리사2016_53-25-4","t":"이미 발생한 이자에 관하여 채무자가 이행을 지체한 경우에는 그 이자에 대한 지연손해금을 청구할 수 있다.","ox":"O","m":"④","c":"A","tp":"채권"},{"y":2016,"e":"변리사 1차","qn":25,"i":"변리사2016_53-25-5","t":"채무자가 자신이 가진 주식의 일부분을 담보로 제공하기로 한 경우, 담보약정에 기한 채권은 제한종류채권에 해당한다.","ox":"O","m":"⑤","c":"A"},{"y":2016,"e":"변리사 1차","qn":26,"i":"변리사2016_53-26-1","t":"이행불능 후에 가격이 등귀하였다고 하여도 매도인이 이행불능 당시 이를 알았거나알 수 있었던 경우에만 등귀한 가격에 의한 손해배상을 청구할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"변리사 1차","qn":26,"i":"변리사2016_53-26-2","t":"불법행위의 직접적 대상에 대한 손해가 아닌 간접적 손해는 가해자가 그 사정을 알았거나 알 수 있었을 것이라고 인정되는 경우에만 배상책임이 있다.","ox":"O","m":"②","c":"A","tp":"손해배상"},{"y":2016,"e":"변리사 1차","qn":26,"i":"변리사2016_53-26-3","t":"재산상 손해의 발생이 인정되는데도 입증곤란 등의 이유로 그 손해액의 확정이 불가능하여 그 배상을 받을 수 없다는 사정은 위자료의 증액사유로 참작할 수 있다.","ox":"O","m":"③","c":"A","tp":"손해배상"},{"y":2016,"e":"변리사 1차","qn":26,"i":"변리사2016_53-26-4","t":"손해발생으로 인하여 피해자에게 이득이 생겼다면 손해액을 산정할 때 먼저 손익상계를 한 후에 과실상계를 하여야 한다.","ox":"X","m":"④","c":"A","tp":"손해배상"},{"y":2016,"e":"변리사 1차","qn":26,"i":"변리사2016_53-26-5","t":"손해배상액 산정에서 손익상계가 허용되기 위해서는 피해자의 이득이 배상 의무자가 배상하여야 할 손해의 범위에 대응하는 것이어야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2016,"e":"변리사 1차","qn":27,"i":"변리사2016_53-27-1","t":"임차건물이 화재로 소실된 경우 그 화재의 발생 원인이 불명이면, 임차인은 임차 건물의 보존에 관한 선관주의의무를 다하지 않은 경우에도 그 책임을 면한다.","ox":"X","m":"①","c":"A","tp":"채무불이행"},{"y":2016,"e":"변리사 1차","qn":27,"i":"변리사2016_53-27-2","t":"이행보조자의 불법행위로 인하여 채무자가 채무불이행책임을 부담하는 경우 이행보조자의 손해배상책임과 채무자의 채무불이행책임은 연대채무관계에 있다.","ox":"X","m":"②","c":"A"},{"y":2016,"e":"변리사 1차","qn":27,"i":"변리사2016_53-27-3","t":"채무자의 제3채무자에 대한 채권의 가압류가 있는 경우에는 그 채권의 이행기가 도래하였다고 하더라도 제3채무자는 그 지체책임을 부담하지 않는다.","ox":"X","m":"③","c":"A","tp":"채무불이행"},{"y":2016,"e":"변리사 1차","qn":27,"i":"변리사2016_53-27-4","t":"채무불이행으로 인하여 계약이 합의해제 되었더라도 손해배상을 금하는 특약이 없는 한 채무불이행으로 인한 손해배상을 청구할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2016,"e":"변리사 1차","qn":27,"i":"변리사2016_53-27-5","t":"이행거절이라는 채무불이행이 인정되기 위해서는 채무를 이행하지 아니할 채무자의 명백한 의사표시가 위법한 것으로 평가되어야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2016,"e":"변리사 1차","qn":29,"i":"변리사2016_53-29-1","t":"2016년 1월 12일(화)까지 채무를 이행하기로 한 경우에는 2016년 1월 13일부터 지체책임을 진다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"변리사 1차","qn":29,"i":"변리사2016_53-29-2","t":"지시채권의 경우 확정기한이 정하여져 있는 때에도 그 기한이 도래한 후 소지인이 증서를 제시하여 이행을 청구한 때로부터 지체책임이 있다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"변리사 1차","qn":29,"i":"변리사2016_53-29-3","t":"2016년 1월 12일(화)에 채권자가 방문하면 상품을 인도하기로 하였으나 채권자가 오지 않아서 이행을 못한 때에는, 2016년 1월 13일이 지나도 채무자는 지체책임을 지지 않는다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"변리사 1차","qn":29,"i":"변리사2016_53-29-4","t":"원인채무의 이행확보를 위해 발행한 어음의 반환과 원인채무의 이행이 동시이행관계에 있는 경우, 원인채무의 이행기가 지났다 하더라도 채무자는 어음을 반환 받을 때까지는 이행지체책임을 지지 않는다.","ox":"X","m":"④","c":"A"},{"y":2016,"e":"변리사 1차","qn":29,"i":"변리사2016_53-29-5","t":"금전채무의 채무자는 확정된 지연손해금채무에 대하여 채권자로부터 이행청구를 받은 때부터 지체책임을 진다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"변리사 1차","qn":25,"i":"변리사2017_54-25-1","t":"매매계약 당시 매매목적 토지의 소유권이 매도인에게 속하지 아니함을 알고 있던 매수인은 소유권이전의무의 이행불능에 매도인의 귀책사유가 있더라도 채무불이행을 이유로 계약을 해제하고 손해배상을 청구할 수 없다.","ox":"X","m":"①","c":"A"},{"y":2017,"e":"변리사 1차","qn":25,"i":"변리사2017_54-25-2","t":"이행보증계약에 기한 보증인의 보증금지급의무에 관하여 지급금지가처분결정이 있었다고 하더라도, 이로써 보증인에게 지급거절의 권능이 발생한다고 할 수 없다.","ox":"O","m":"②","c":"A","tp":"채무불이행"},{"y":2017,"e":"변리사 1차","qn":25,"i":"변리사2017_54-25-3","t":"매매의 대상인 권리가 타인에게 귀속되어 있다는 이유만으로 채무자의 계약에 따른 이행이 불능이라고 할 수는 없다.","ox":"O","m":"③","c":"A","tp":"채무불이행"},{"y":2017,"e":"변리사 1차","qn":25,"i":"변리사2017_54-25-4","t":"부당이득반환의무는 이행기한의 정함이 없는 채무이므로 그 채무자는 이행청구를 받은 그 다음 날부터 지체책임을 진다.","ox":"O","m":"④","c":"A","tp":"채무불이행"},{"y":2017,"e":"변리사 1차","qn":25,"i":"변리사2017_54-25-5","t":"채무자가 채무 발생원인 내지 존재에 관한 잘못된 법률적 판단을 통하여 자신의 채무가 없다고 믿고 채무이행을 거부한 채 소송을 통하여 다툰 경우, 특별한 사정이 없는 한 채무불이행에 관하여 채무자에게 고의나 과실이 인정된다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"변리사 1차","qn":26,"i":"변리사2017_54-26-1","t":"계약 당시 당사자 사이에 손해배상액을 예정하는 내용의 약정이 있는 경우, 특별한 사정이 없는 한 위 약정은 그 계약과 관련된 불법행위책임에 따른 손해배상까지 예정한 것이라고는 볼 수 없다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"변리사 1차","qn":26,"i":"변리사2017_54-26-2","t":"채권자가 그 채권의 목적인 물건 또는 권리의 가액전부를 손해배상으로 받은 때에는 채무자는 그 물건 또는 권리에 관하여 당연히 채권자를 대위한다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"변리사 1차","qn":26,"i":"변리사2017_54-26-3","t":"숙박업자가 숙박계약상의 고객보호의무를 다하지 못하여 투숙객이 사망한 경우, 그 투숙객의 근친자가 그 사고로 인하여 정신적 고통을 받았다면, 숙박계약의 당사자가 아닌 그 근친자는 숙박업자의 그 망인에 대한 숙박계약상의 채무불이행을 이유로 위자료를 청구할 수 있다.","ox":"X","m":"③","c":"A","tp":"손해배상"},{"y":2017,"e":"변리사 1차","qn":26,"i":"변리사2017_54-26-4","t":"피용자의 고의에 의한 불법행위로 인하여 사용자가 사용자책임을 부담하는 경우, 사용자책임의 범위를 정함에 있어서 피해자의 과실을 고려하여 그 책임을 제한할 수 있다.","ox":"O","m":"④","c":"A","tp":"손해배상"},{"y":2017,"e":"변리사 1차","qn":26,"i":"변리사2017_54-26-5","t":"과실상계는 매매계약이 해제되어 원상회복의무의 이행으로서 이미 지급한 매매대금 기타 급부의 반환을 구하는 경우에는 적용되지 않는다.","ox":"O","m":"⑤","c":"A","tp":"손해배상"},{"y":2018,"e":"변리사 1차","qn":25,"i":"변리사2018_55-25-1","t":"채권자지체 중에 채무자가 채권의 목적물을 보관하던 중 그의 경과실로 목적물이 멸실된 경우, 채무자는 그 멸실로 인한 책임이 없다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"변리사 1차","qn":25,"i":"변리사2018_55-25-2","t":"채권자지체 중에 이행불능이 된 경우, 채권자지체가 발생한 사실에 대한 증명책임은 채권자에게 있다.","ox":"X","m":"②","c":"A"},{"y":2018,"e":"변리사 1차","qn":25,"i":"변리사2018_55-25-3","t":"채권자지체로 인하여 채권의 목적물을 보관 또는 변제하기 위한 비용이 증가된 때에 그 증가액은 채무자가 부담한다.","ox":"X","m":"③","c":"A"},{"y":2018,"e":"변리사 1차","qn":25,"i":"변리사2018_55-25-4","t":"이자 있는 채권의 경우에 채권자지체 중에도 채무자는 이자를 지급할 의무가 있다.","ox":"X","m":"④","c":"A"},{"y":2018,"e":"변리사 1차","qn":25,"i":"변리사2018_55-25-5","t":"민법 제538조 제1항의 ‘채권자의 수령지체 중에 당사자 쌍방의 책임 없는 사유로 채무를 이행할 수 없게 된 때’에 해당하기 위해서 채무자의 현실 제공 또는 구두 제공이 필요한 것은 아니다.","ox":"X","m":"⑤","c":"A","tp":"채권자지체"},{"y":2018,"e":"변리사 1차","qn":27,"i":"변리사2018_55-27","t":"甲은 자신이 사용하던 노트북 X, Y 중에 하나를 乙에게 팔기로 하였고, 대금 지급일에 乙이 선택하기로 하였다. 그런데 대금지급일 전에 甲이 X노트북을 丙에게 매도하고 인도까지 해주었다. 이에 관한 설명으로 옳은 것은? (다툼","c":"A","mc":{"s":"甲은 자신이 사용하던 노트북 X, Y 중에 하나를 乙에게 팔기로 하였고, 대금 지급일에 乙이 선택하기로 하였다. 그런데 대금지급일 전에 甲이 X노트북을 丙에게 매도하고 인도까지 해주었다. 이에 관한 설명으로 옳은 것은? (다툼","d":"이 있으면 판례에 따름)","o":["乙이 Y노트북을 선택하고 그 의사를 甲에게 전달한 경우, 乙은 특별한 사정이 없는 한 甲의 동의 없이도 이를 철회할 수 있다.","乙은 Y노트북을 선택하면서 조건을 붙일 수 있다.","乙이 X노트북을 선택하더라도 채권의 목적물은 Y노트북으로 확정된다.","乙은 X노트북을 선택하고 丙에게 X노트북의 반환을 청구할 수 있다.","乙은 X노트북을 선택하고 甲에게 채무불이행을 이유로 손해배상을 청구할 수 있다."],"a":5}},{"y":2019,"e":"변리사 1차","qn":27,"i":"변리사2019_56-27","t":"채무불이행으로 인한 손해배상책임에 관한 설명으로 옳지 않은 것은? (다툼이","c":"A","mc":{"s":"채무불이행으로 인한 손해배상책임에 관한 설명으로 옳지 않은 것은? (다툼이","d":"있으면 판례에 따름)","o":["손해배상 방법으로서 금전배상의 경우, 금전은 우리나라 통화를 의미하지만, 당사자의 약정이 있으면 외국통화로 배상할 수 있다.","채무불이행으로 인한 손해배상책임과 달리 매매계약의 해제로 인한 원상회복의무의 이행으로서 이미 지급한 매매대금 기타 급부의 반환을 구하는 경우에는 과실상계의 법리가 적용되지 않는다.","지체상금이 손해배상의 예정으로 인정되어 감액할 때, 채무자가 계약을 위반한 경위 등 제반사정이 참작되므로, 손해배상액의 감경에 앞서 채권자의 과실 등을 들어 따로 감경할 필요는 없다.","특별손해의 배상에서 채무자가 그 사정을 알았거나 알 수 있었는지의 여부는 채무의 이행기가 아니라 계약체결 당시를 기준으로 판단하여야 한다.","매도인이 매수인으로부터 부동산 매매대금을 약정기일에 지급받지 못한 결과 제3자로부터 이와 유사한 부동산을 매수하고 그 잔대금을 지급하지 못하여 계약금이 몰수되는 손해를 입었다면, 이는 특별한 사정으로 인한 손해에 해당한다."],"a":4}},{"y":2019,"e":"변리사 1차","qn":31,"i":"변리사2019_56-31-1","t":"증여계약의 대상인 권리가 타인에게 귀속되어 있다는 이유만으로 증여자의 계약에 따른 이행이 불능이라고 할 수는 없다.","ox":"O","m":"①","c":"A","tp":"이행불능"},{"y":2019,"e":"변리사 1차","qn":31,"i":"변리사2019_56-31-2","t":"매매목적물인 부동산이 가압류되었다는 사유만으로 매도인의 이행불능을 이유로 매매계약을 해제할 수는 없다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"변리사 1차","qn":31,"i":"변리사2019_56-31-3","t":"부동산의 소유권이전등기의무자가 그 부동산에 제3자 명의로 가등기를 마쳐주면, 부동산의 처분권한 상실로 소유권이전등기의무가 이행불능이 된다.","ox":"X","m":"③","c":"A"},{"y":2019,"e":"변리사 1차","qn":31,"i":"변리사2019_56-31-4","t":"매수인의 잔대금지급의무가 소유권이전등기의무와 동시이행관계에 있더라도, 소유권이전등기의무의 이행불능을 이유로 매수인이 매매계약을 해제하기 위해서는 매수인이 대금지급의무의 이행제공을 할 필요가 없다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"변리사 1차","qn":31,"i":"변리사2019_56-31-5","t":"임대인에게 임대목적물에 대한 소유권이 없는 경우, 임차인이 진실한 소유자로부터 목적물의 반환청구를 받는 등의 이유로 임차인이 이를 사용·수익할 수가 없게 되면 임대인의 채무는 이행불능이 된다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"변리사 1차","qn":25,"i":"변리사2021_58-25-1","t":"동산매매계약에서 매도인 甲이 매수인 乙에 대해 잔금 지급기일 도과를 이유로 지연손해금을 청구하려면 甲은 자기 채무의 이행제공을 계속하여야 한다.","ox":"O","m":"①","c":"A","tp":"이행지체"},{"y":2021,"e":"변리사 1차","qn":25,"i":"변리사2021_58-25-2","t":"신축 중인 상가를 乙에게 분양한 甲이 분양대금의 중도금지급기한을 1층 골조공사 완료시로 약정한 경우, 1층 골조공사 완료 후 乙이 그 사실을 안 날의 다음 날부터 중 도금지급채무의 지체책임을 진다.","ox":"O","m":"②","c":"A","tp":"이행지체"},{"y":2021,"e":"변리사 1차","qn":25,"i":"변리사2021_58-25-3","t":"이행기의 정함이 없는 매매대금채권을 甲으로부터 양수한 丙이 채무자 乙을 상대로 그 이행을 구하는 소를 제기하고 소송 계속 중 甲이 乙에 대해 채권양도통지를 한 경우, 특별한 사정이 없는 한 乙은 채권양도통지가 도달된 날의 다음 날부터 이행지체의 책임을 진다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"변리사 1차","qn":25,"i":"변리사2021_58-25-4","t":"매수인 乙이 매도인 甲의 영업소에서 쌀 10포대를 받아가기로 약정한 경우, 乙이 변제기 이후에 오지 않은 이상 甲은 지연에 따른 손해배상책임을 지지 않는다.","ox":"O","m":"④","c":"A","tp":"이행지체"},{"y":2021,"e":"변리사 1차","qn":25,"i":"변리사2021_58-25-5","t":"甲은 乙로부터 1억 원을 빌리면서 5회에 걸쳐 매회 2천만 원씩 분할상환하되, 분할변 제기한을 1회라도 지체하였을 때는 기한의 이익을 잃는 것으로 특약한 경우, 특별한 사정이 없는 한 甲은 1회 변제기한이라도 지체하면 미상환금액 전부에 대하여 지체책임을 진다.","ox":"X","m":"⑤","c":"A","tp":"이행지체"},{"y":2021,"e":"변리사 1차","qn":26,"i":"변리사2021_58-26-1","t":"수임인이 위임사무의 처리과정에서 받은 물건으로 위임인에게 인도할 목적물이 대체 물이더라도 당사자 사이에는 특정된 물건과 같은 것으로 보아야 한다.","ox":"O","m":"①","c":"A","tp":"채권의 목적"},{"y":2021,"e":"변리사 1차","qn":26,"i":"변리사2021_58-26-2","t":"채권의 성질 또는 당사자의 의사표시로 달리 정한 바가 없는 이상, 특정물의 인도는 채권성립 당시의 그 물건의 소재지에서 한다.","ox":"O","m":"②","c":"A","tp":"채권의 목적"},{"y":2021,"e":"변리사 1차","qn":26,"i":"변리사2021_58-26-3","t":"제한종류채권에서 채무자가 지정권자인 경우, 채권의 기한이 도래한 후 채권자의 최고에도 불구하고 채무자가 이행할 물건을 지정하지 않으면 그 지정권은 채권자에게 이전한다.","ox":"O","m":"③","c":"A","tp":"채권의 목적"},{"y":2021,"e":"변리사 1차","qn":26,"i":"변리사2021_58-26-4","t":"채권액이 외국통화로 지정된 금액채권인 외화채권의 경우, 채권자는 대용급부권을 행사하여 우리나라 통화로 환산하여 청구할 수 없다.","ox":"X","m":"④","c":"A","tp":"채권의 목적"},{"y":2021,"e":"변리사 1차","qn":26,"i":"변리사2021_58-26-5","t":"이자제한법상 제한이자를 초과하는 이자채권을 자동채권으로 하여 상계의 의사표시를 하더라도 그 상계의 효력은 발생하지 않는다.","ox":"O","m":"⑤","c":"A","tp":"채권의 목적"},{"y":2021,"e":"변리사 1차","qn":27,"i":"변리사2021_58-27-1","t":"토지거래허가구역 내의 토지에 관하여 허가를 조건으로 매매계약을 체결한 경우, 그 허가 전에는 거래계약상의 채무를 이행할 수 없게 되더라도 그에 따른 손해배상책임을 지지 않는다.","ox":"O","m":"①","c":"A","tp":"이행불능"},{"y":2021,"e":"변리사 1차","qn":27,"i":"변리사2021_58-27-2","t":"쌍무계약에서 당사자 일방이 부담하는 채무의 일부만이 채무자의 책임 있는 사유로 이행할 수 없게 된 경우, 이행가능한 나머지 부분만의 이행으로 계약목적을 달성할 수 없다면 채무의 이행은 전부가 불능이라고 보아야 한다.","ox":"O","m":"②","c":"A","tp":"이행불능"},{"y":2021,"e":"변리사 1차","qn":27,"i":"변리사2021_58-27-3","t":"민법상 임대차에서 목적물을 사용\u0001수익하게 할 임대인의 의무는 임대인이 임대차목 적물의 소유권을 상실한 것만으로 이행불능이 된다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"변리사 1차","qn":27,"i":"변리사2021_58-27-4","t":"매매목적물에 관하여 매도인의 다른 채권자가 강제경매를 신청하여 그 절차가 진행 중에 있다는 사유만으로 매도인의 채무가 이행불능이 되는 것은 아니다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"변리사 1차","qn":27,"i":"변리사2021_58-27-5","t":"쌍무계약에서 당사자 일방의 급부뿐만 아니라 상대방의 반대급부도 전부 이행불능이된 경우, 특별한 사정이 없는 한 당사자 일방은 상대방에게 대상청구를 할 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"변리사 1차","qn":25,"i":"변리사2023_60-25-1","t":"계약당사자 일방이 자신의 계약상 채무 이행에 장애가 될 수 있는 사유를 계약체결 시에 예견할 수 있었음에도 상대방에게 고지하지 않은 경우, 그 사유로 인해 채무불이행이 되는 것에 어떠한 잘못도 없었다면 채무불이행에 대한 귀책사유를 인정할 수 없다.","ox":"X","m":"①","c":"A"},{"y":2023,"e":"변리사 1차","qn":25,"i":"변리사2023_60-25-2","t":"이행보조자의 행위가 채무자의 이행업무와 객관적, 외형적으로 관련된 경우, 그 행위가 채권자에게 불법행위가 되더라도 채무자는 채권자에 대하여 책임을 부담한다.","ox":"O","m":"②","c":"A","tp":"채무불이행"},{"y":2023,"e":"변리사 1차","qn":25,"i":"변리사2023_60-25-3","t":"매매목적물의 인도전 화재로 매도인이 수령할 화재보험금에 대하여 매수인이 대상청구권을 행사할 수 있는 경우, 그 범위는 매매대금의 범위내로 제한되지 않는다.","ox":"O","m":"③","c":"A","tp":"채무불이행"},{"y":2023,"e":"변리사 1차","qn":25,"i":"변리사2023_60-25-4","t":"대상청구권을 행사하려는 일방당사자가 부담하는 급부도 전부불능이 된 경우, 대상청 구권의 행사는 허용되지 않는다.","ox":"O","m":"④","c":"A","tp":"채무불이행"},{"y":2023,"e":"변리사 1차","qn":25,"i":"변리사2023_60-25-5","t":"이행기의 정함이 없는 채권을 양수한 자가 채무자를 상대로 이행의 소를 제기하고 소송계속 중 채무자에 대하여 채권양도통지가 된 경우, 채무자는 원칙적으로 그 통지가 도달된 다음 날부터 이행지체책임을 진다.","ox":"O","m":"⑤","c":"A","tp":"채무불이행"},{"y":2023,"e":"변리사 1차","qn":28,"i":"변리사2023_60-28-1","t":"특정물채권의 채무자는 이행기에 이행하여도 손해를 면할 수 없는 경우가 아닌 한,이행지체 중에 과실없이 목적물이 멸실되더라도 배상책임을 부담한다.","ox":"O","m":"①","c":"A","tp":"채권의 목적"},{"y":2023,"e":"변리사 1차","qn":28,"i":"변리사2023_60-28-2","t":"원본채권이 시효로 소멸한 경우 그로부터 발생한 지분적 이자채권도 함께 소멸한다.","ox":"O","m":"②","c":"A","tp":"채권의 목적"},{"y":2023,"e":"변리사 1차","qn":28,"i":"변리사2023_60-28-3","t":"금전채무불이행에 따른 통상손해배상의 경우 채권자는 자신의 손해를 증명할 필요가 없다.","ox":"O","m":"③","c":"A","tp":"채권의 목적"},{"y":2023,"e":"변리사 1차","qn":28,"i":"변리사2023_60-28-4","t":"채무자가 금전채무를 이행하지 않아 발생한 확정된 지연손해금에 대하여 채권자가 이행청구를 하는 경우 그 지연손해금에 대하여 다시 지연손해금의 지급을 구할 수는 없다.","ox":"X","m":"④","c":"A","tp":"채권의 목적"},{"y":2023,"e":"변리사 1차","qn":28,"i":"변리사2023_60-28-5","t":"무권대리에서 상대방이 그의 선택에 따라 행사할 수 있는 계약의 이행 또는 손해배상 청구권은 선택권을 행사할 수 있는 때부터 소멸시효가 진행한다.","ox":"O","m":"⑤","c":"A","tp":"채권의 목적"},{"y":2024,"e":"변리사 1차","qn":25,"i":"변리사2024_61-25-1","t":"특정물매매에 있어서 매수인의 대금지급채무가 이행지체에 빠졌다고 하더라도 그 목적물이 매수인에게 인도될 때까지는 매수인은 매매대금의 이자를 지급할 필요가 없다.","ox":"O","m":"①","c":"A","tp":"특정물채권"},{"y":2024,"e":"변리사 1차","qn":25,"i":"변리사2024_61-25-2","t":"특정물매매의 경우, 매수인이 매매대금을 지급하지 않더라도 인도받지 않은 목적물로부터 생긴 과실에 대한 수취권은 특별한 사정이 없는 한 매수인에게 귀속된다.","ox":"X","m":"②","c":"A","tp":"특정물채권"},{"y":2024,"e":"변리사 1차","qn":25,"i":"변리사2024_61-25-3","t":"채권자는 특정물에 관한 자신의 채권을 보전하기 위하여 채무자의 제3채무자에 대한 그 특정물에 관한 권리만을 대위행사할 수 있다.","ox":"O","m":"③","c":"A","tp":"특정물채권"},{"y":2024,"e":"변리사 1차","qn":25,"i":"변리사2024_61-25-4","t":"103동 607호, 107동 203호 등으로 아파트를 지정하여 매매하는 것을 내용으로 하는 아파트분양계약은 수량을 지정한 매매가 아닌 특정물을 목적으로 한 매매에 해당한다.","ox":"O","m":"④","c":"A","tp":"특정물채권"},{"y":2024,"e":"변리사 1차","qn":25,"i":"변리사2024_61-25-5","t":"채권자가 특정물채권을 보전하기 위해 채권자취소권을 행사하는 것은 허용되지 않는다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"변리사 1차","qn":26,"i":"변리사2024_61-26-1","t":"이행보조자는 채무자의 의사 관여 아래 채무의 이행행위에 속하는 활동을 하는 자이면 충분하고, 반드시 채무자의 지시 또는 감독을 받는 관계에 있어야 하는 것은 아니다.","ox":"O","m":"①","c":"A","tp":"채무불이행"},{"y":2024,"e":"변리사 1차","qn":26,"i":"변리사2024_61-26-2","t":"이행기의 정함이 없는 지명채권을 양수한 채권양수인이 채무자를 상대로 그 이행을 구하는 소를 제기하고, 그 소송 계속 중 채무자에 대한 채권양도통지가 이루어진 경우에는 특별한 사정이 없는 한 채무자는 그 소가 제기된 날부터 채권양수인에 대해 이행지체의 책임을 진다.","ox":"X","m":"②","c":"A","tp":"채무불이행"},{"y":2024,"e":"변리사 1차","qn":26,"i":"변리사2024_61-26-3","t":"매매목적물에 관하여 이중으로 제3자와 매매계약을 체결하였다는 사실만 가지고는 먼저 체결된 매매계약이 법률상 이행불능이라고 할 수 없다.","ox":"O","m":"③","c":"A","tp":"채무불이행"},{"y":2024,"e":"변리사 1차","qn":26,"i":"변리사2024_61-26-4","t":"매매목적물이 채무자의 과실에 의한 화재로 소실됨으로써 채무자의 매매목적물에 대한 인도의무가 이행불능으로 된 경우, 채권자는 화재사고로 채무자가 지급받게 되는 화재보험금에 대하여 대상청구권을 행사할 수 있다.","ox":"O","m":"④","c":"A","tp":"채무불이행"},{"y":2024,"e":"변리사 1차","qn":26,"i":"변리사2024_61-26-5","t":"임대인이 임대물수선의무를 이행하기 위하여 제3자에게 도급을 주어 임차물을 공사하던 중 그 수급인의 과실에 의한 임차물의 화재로 인해 임차인의 손해가 발생한 경우, 임대인은 임차인에 대하여 채무불이행에 따른 손해배상책임을 부담한다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"변리사 1차","qn":27,"i":"변리사2024_61-27","t":"채무불이행에 따른 손해배상에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에","c":"A","mc":{"s":"채무불이행에 따른 손해배상에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에","d":"따름)","o":["숙박업자가 숙박계약에 따른 의무를 다하지 못하여 투숙객이 사망한 경우, 숙박계약 의 당사자가 아니면서 그 사고로 인하여 정신적 고통을 받은 그 투숙객의 근친자는 그 투숙객에 대한 숙박계약상의 채무불이행을 이유로 숙박업자에게 위자료를 청구할 수 있다.","채무불이행을 이유로 계약이 해제된 경우에 채권자는 이행이익의 배상 대신에 계약이 이행되리라고 믿고 지출한 비용을 채무불이행으로 인한 손해로 배상을 청구할 수 있으며, 그 지출비용이 이행이익의 범위를 초과하더라도 그 전부를 청구할 수 있다.","부동산매매계약에서 매도인의 이행거절로 인한 채무불이행에서의 손해액 산정은 이행 거절 당시의 부동산의 시가를 표준으로 한다.","채무자의 채무불이행으로 인한 손해배상액이 예정되어 있는 경우에 채무불이행으로 인한 손해의 발생 및 확대에 채권자에게도 과실이 있다면 과실상계를 할 수 있다.","위약금이 위약벌로 해석되기 위해 특별한 사정이 주장\u0001입증될 필요는 없으며, 도급계약서에 계약보증금 외에 지체상금도 규정되어 있다면 이 자체로 계약보증금은 위약 벌이 된다."],"a":3}},{"y":2026,"e":"변리사 1차","qn":26,"i":"변리사2026_63-26-1","t":"원본채권이 양도된 경우, 이미 변제기에 도달한 이자채권은 원본채권의 양도당시 그 이자채권도 양도한다는 의사표시가 없는 한 당연히 양도되지는 않는다.","ox":"O","m":"①","c":"A","tp":"채권의 목적"},{"y":2026,"e":"변리사 1차","qn":26,"i":"변리사2026_63-26-2","t":"보유주식 일정량을 담보로 제공하기로 한 담보약정에 기한 채권은 일종의 제한종류채 권이다.","ox":"O","m":"②","c":"A","tp":"채권의 목적"},{"y":2026,"e":"변리사 1차","qn":26,"i":"변리사2026_63-26-3","t":"채권의 성질 또는 당사자의 의사표시로 달리 정한 바가 없는 이상, 특정물의 인도는 채권성립 당시에 그 물건이 있던 장소에서 해야 한다.","ox":"O","m":"③","c":"A","tp":"채권의 목적"},{"y":2026,"e":"변리사 1차","qn":26,"i":"변리사2026_63-26-4","t":"제한종류채권에 관하여 당사자가 합의하여 급부 목적물을 특정하거나 특정방법 또는 지정권자를 정하는 경우에는 그에 따라야 한다.","ox":"O","m":"④","c":"A","tp":"채권의 목적"},{"y":2026,"e":"변리사 1차","qn":26,"i":"변리사2026_63-26-5","t":"토지소유자가 수필의 토지 중 일정 면적을 상대방에게 매도한 경우, 양도할 토지의 위치가 확정되지 않았다면 특별한 사정이 없는 한 상대방의 채권은 종류채권에 해당한다.","ox":"X","m":"⑤","c":"A","tp":"채권의 목적"},{"y":2026,"e":"변리사 1차","qn":27,"i":"변리사2026_63-27-1","t":"채권자가 채무자의 이행거절을 이유로 해제권을 행사하는 경우, 특별한 사정이 없는한 채권자는 이행기 전이라도 이행의 최고 없이 계약을 해제할 수 있다.","ox":"O","m":"①","c":"A","tp":"채무불이행"},{"y":2026,"e":"변리사 1차","qn":27,"i":"변리사2026_63-27-2","t":"이행기의 정함이 없는 채권을 양수한 채권양수인이 채무자를 상대로 그 이행을 구하는 소를 제기하고 소송 계속 중 채무자에 대한 채권양도통지가 이루어진 경우에는 특별한 사정이 없는 한 채무자는 채권양도통지가 도달된 다음 날부터 지체책임을 진다.","ox":"O","m":"②","c":"A","tp":"채무불이행"},{"y":2026,"e":"변리사 1차","qn":27,"i":"변리사2026_63-27-3","t":"채무불이행으로 인한 손해배상채무는 특별한 사정이 없는 한 채권자가 이행청구를 하면 채무자는 그에 대한 지체책임을 부담한다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"변리사 1차","qn":27,"i":"변리사2026_63-27-4","t":"이행불능으로 인한 손해배상청구권은 본래의 채권이 시효로 소멸하더라도 본래의 채권과 함께 소멸하지 않는다.","ox":"X","m":"④","c":"A","tp":"채무불이행"},{"y":2026,"e":"변리사 1차","qn":27,"i":"변리사2026_63-27-5","t":"부동산 이중매매의 매도인이 선의의 제2매수인에게 소유권이전등기를 마쳐준 때에는 특별한 사정이 없는 한 매도인이 제1매수인에게 부담하는 소유권이전등기의무는 이행 불능의 상태에 있다.","ox":"O","m":"⑤","c":"A","tp":"채무불이행"}],"11":[{"y":2016,"e":"변리사 1차","qn":28,"i":"변리사2016_53-28-1","t":"甲이 丁에게 900만원을 변제하였다면 甲은 乙과 丙에게 각 300만원씩 구상할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"변리사 1차","qn":28,"i":"변리사2016_53-28-2","t":"乙이 변제기가 도래한 丁에 대한 2,000만원의 금전채권을 자동채권으로 하여 상계한 경우, 2,000만원의 범위 내에서 甲과 丙의 채무도 소멸한다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"변리사 1차","qn":28,"i":"변리사2016_53-28-3","t":"乙이 丁에 대한 채권으로 상계하지 않는 경우, 甲은 乙의 丁에 대한 금전채권을 자동채권으로 하여 1,000만원의 범위 내에서 상계할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"변리사 1차","qn":28,"i":"변리사2016_53-28-4","t":"丁의 甲에 대한 채권이 시효완성으로 인하여 소멸하였다면 乙과 丙도 채무를 전부 면하게 된다.","ox":"X","m":"④","c":"A"},{"y":2016,"e":"변리사 1차","qn":28,"i":"변리사2016_53-28-5","t":"丁이 丙에 대하여 채무 전부를 면제해 주었다면 이제 甲과 乙은 丁에 대하여 2,000만원의 연대채무를 부담하게 된다.","ox":"O","m":"⑤","c":"A"},{"y":2016,"e":"변리사 1차","qn":30,"i":"변리사2016_53-30-1","t":"丙이 乙에게 자신의 명의로 된 확정일자 있는 채권양도통지서를 발송하여 도달 되었다면, 특별한 사정이 없는 한 丙은 乙에게 위 채권양도로 대항할 수 있다.","ox":"X","m":"①","c":"A","tp":"甲이 자신의 乙"},{"y":2016,"e":"변리사 1차","qn":30,"i":"변리사2016_53-30-2","t":"매매대금채권에 관하여 甲과 乙 사이에 양도금지 특약이 있다면, 乙은 경과실로 이를 알지 못한 丙에게 위 특약으로써 대항할 수 있다.","ox":"X","m":"②","c":"A","tp":"甲이 자신의 乙"},{"y":2016,"e":"변리사 1차","qn":30,"i":"변리사2016_53-30-3","t":"丙이 乙로부터 변제를 받은 후 甲과 乙 사이의 매매계약이 해제되었다면 乙은 직접 丙에게 급부의 반환을 청구할 수 있다.","ox":"O","m":"③","c":"A","tp":"甲이 자신의 乙"},{"y":2016,"e":"변리사 1차","qn":30,"i":"변리사2016_53-30-4","t":"甲이 乙에 대한 위 채권을 丁에게도 양도하였고 丙과 丁에 대한 양도에 대하여 확정일자 있는 증서에 의한 통지가 이루어졌다면 丙과 丁 간의 우열은 확정일자의 선후에 의한다.","ox":"X","m":"④","c":"A","tp":"甲이 자신의 乙"},{"y":2016,"e":"변리사 1차","qn":30,"i":"변리사2016_53-30-5","t":"丙이 乙에 대하여 매매대금의 지급을 소구(訴求)하였다고 하더라도 丙이 아직 대항요건을 갖추지 못하였다면 丙의 재판상 청구는 소멸시효 중단사유로 인정되지 않는다.","ox":"X","m":"⑤","c":"A","tp":"甲이 자신의 乙"},{"y":2016,"e":"변리사 1차","qn":31,"i":"변리사2016_53-31-1","t":"채무인수계약에 있어서 당사자 의사가 면책적 채무인수인지 중첩적 채무인수인지 분명하지 아니한 경우, 중첩적 채무인수로 보아야 한다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"변리사 1차","qn":31,"i":"변리사2016_53-31-2","t":"계약당사자 중 일방이 상대방의 승낙을 얻어 계약상 당사자의 지위를 포괄적으로 제3자에게 이전하는 경우, 제3자는 종래 계약에서 이미 발생한 채권\u0001채무도 모두 이전 받는다.","ox":"O","m":"②","c":"A","tp":"채무인수"},{"y":2016,"e":"변리사 1차","qn":31,"i":"변리사2016_53-31-3","t":"중첩적 채무인수인이 채권자에 대한 채권을 자동채권으로 하여 채권자의 인수인에 대한 채권을 대등액에서 상계한 경우, 원채무자의 채권자에 대한 채무도 그 범위에서 소멸된다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"변리사 1차","qn":31,"i":"변리사2016_53-31-4","t":"토지매수인이 그 토지에 관한 임대차보증금 반환채무 등을 인수하면서 채무액을 매매대금에서 공제하기로 약정한 경우, 그 인수는 특별한 사정이 없는 한 면책적 채무인수로 보아야 한다.","ox":"X","m":"④","c":"A"},{"y":2016,"e":"변리사 1차","qn":31,"i":"변리사2016_53-31-5","t":"인수인이 채무자의 부탁을 받지 아니하고 채권자와의 계약으로 채무를 중첩적으로 인수한 경우, 채무자와 인수인은 부진정연대관계에 있는 것으로 보아야 한다.","ox":"O","m":"⑤","c":"A","tp":"채무인수"},{"y":2017,"e":"변리사 1차","qn":29,"i":"변리사2017_54-29-1","t":"甲이 1천만원의 채무에 대한 소멸시효 기간이 경과한 후 시효의 이익을 포기한 경우, 丙은 소멸시효를 원용하여 연대보증채무의 소멸을 주장할 수 없다.","ox":"X","m":"①","c":"A"},{"y":2017,"e":"변리사 1차","qn":29,"i":"변리사2017_54-29-2","t":"甲이 乙에게 8백만원의 채권을 가지고 있는 경우, 丙은 5백만원의 한도 내에서만 상계를 할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2017,"e":"변리사 1차","qn":29,"i":"변리사2017_54-29-3","t":"乙이 甲에 대한 채권을 丁에게 양도하고 확정일자 있는 증서로 甲에게 통지한 경우, 乙이 丙에게 보증채권 양도의 통지를 해야 丙에 대한 채권이 丁에게 이전된다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"변리사 1차","qn":29,"i":"변리사2017_54-29-4","t":"乙의 甲에 대한 채권에 시효중단 사유가 발생한 경우, 丙에게 통지 등 별도의 중단조치를 하지 않아도 丙에게 시효중단의 효력이 미친다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"변리사 1차","qn":29,"i":"변리사2017_54-29-5","t":"甲의 채무가 본래 단기소멸시효에 걸리는 것이었지만 확정판결에 의해 소멸시효 기간이 10년으로 연장된 경우, 丙의 보증채무도 10년의 소멸시효기간이 적용된다.","ox":"X","m":"⑤","c":"A"},{"y":2017,"e":"변리사 1차","qn":30,"i":"변리사2017_54-30","t":"甲은 2016. 1. 5. 乙에게 1억원을 대여하였고, 그 후 A 또는 B에게 자신의 채권을 양도하였다. 이에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이","c":"A","mc":{"s":"甲은 2016. 1. 5. 乙에게 1억원을 대여하였고, 그 후 A 또는 B에게 자신의 채권을 양도하였다. 이에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이","d":"있으면 판례에 따름)\nㄱ. 甲이 A에게만 채권을 양도하였을 경우, A가 甲의 대리인으로서 乙에게한 채권양도의 통지도 효력이 있다.\nㄴ. 甲이 乙에게 휴대폰 문자로 양수인을 A로 한 채권양도의 통지를 하였고 이에 따라 乙이 A에 대하여 채무를 변제하였는데, 그 후 다시 甲이 양수인을 B로 한 확정일자 있는 증서로 채권양도통지를 하였더라도 乙의 A에 대한 채무변제는 유효하다.\nㄷ. 甲이 乙에게 양수인을 A로 한 단순한 채권양도의 통지를 하였고, 그 후 乙이 아직 변제하지 않은 상태에서 다시 양수인을 B로 한 확정일자 있는 증서로 채권양도를 통지하였다면 乙이 A에 대하여 한 변제로 B에게 대항할 수 없다.\nㄹ. 채권양수인을 A로 한 양도통지서의 확정일자는 2017. 1. 10.이고, B로한 양도통지서의 확정일자는 2017. 1. 11.이었으나, 양수인 B로 한 확정 일자 있는 증서가 먼저 乙에게 도달하였을 경우, 乙은 B에게 변제할 책임이 있다.","o":["ㄱ","ㄴ, ㄹ","ㄱ, ㄷ, ㄹ","ㄴ, ㄷ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":5}},{"y":2017,"e":"변리사 1차","qn":31,"i":"변리사2017_54-31-1","t":"이행인수인은 법정대위를 할 수 있는 변제할 정당한 이익이 있는 자에 해당하지 않는다.","ox":"X","m":"①","c":"A","tp":"채무인수 등"},{"y":2017,"e":"변리사 1차","qn":31,"i":"변리사2017_54-31-2","t":"채권자와 보증인 사이에 보증인이 주채무를 중첩적으로 인수하기로 약정한 경우, 특별한 사정이 없는 한 보증인은 주채무자에 대한 관계에서는 종전의 보증인의 지위를 그대로 유지한다.","ox":"O","m":"②","c":"A","tp":"채무인수 등"},{"y":2017,"e":"변리사 1차","qn":31,"i":"변리사2017_54-31-3","t":"부동산 매수인이 매매목적물에 설정된 근저당권의 피담보채무를 이행인수한 뒤그 변제를 게을리 하여 근저당권이 실행됨으로써 매도인이 매매목적물에 대한 소유권을 상실한 경우, 이는 매수인의 책임 있는 사유로 소유권이전등기의무가 이행불능으로 된 경우에 해당하고 그에 대하여 매도인의 과실도 인정된다.","ox":"X","m":"③","c":"A","tp":"채무인수 등"},{"y":2017,"e":"변리사 1차","qn":31,"i":"변리사2017_54-31-4","t":"계약당사자로서의 지위가 제3자에게 이전되는 경우, 계약상 지위를 전제로 한권리관계가 이전될 뿐만 아니라 불법행위에 기한 손해배상청구권도 별도의 채권양도절차 없이 제3자에게 당연히 이전된다.","ox":"X","m":"④","c":"A","tp":"채무인수 등"},{"y":2017,"e":"변리사 1차","qn":31,"i":"변리사2017_54-31-5","t":"채무자와 인수인의 합의에 의한 중첩적 채무인수의 경우, 채권자의 수익의 의사표시는 계약의 성립요건이 아니라 효력발생요건이다.","ox":"X","m":"⑤","c":"A","tp":"채무인수 등"},{"y":2018,"e":"변리사 1차","qn":28,"i":"변리사2018_55-28-1","t":"甲이 丁에 대한 4천만원의 반대채권을 가지고 유효하게 상계한 경우, 丙은 2천 만원의 채무를 면한다.","ox":"X","m":"①","c":"A"},{"y":2018,"e":"변리사 1차","qn":28,"i":"변리사2018_55-28-2","t":"乙이 6천만원의 지급에 갈음하여 丁에게 자신의 주택의 소유권이전을 내용으로 하는 경개계약을 체결한 경우, 甲과 丙의 丁에 대한 연대채무는 소멸한다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"변리사 1차","qn":28,"i":"변리사2018_55-28-3","t":"甲이 丁에게 6천만원을 변제하고 과실(過失) 없이 바로 乙과 丙에게 구상하려는 데 乙이 무자력이 된 경우, 甲은 丙에게 3천만원을 구상할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"변리사 1차","qn":28,"i":"변리사2018_55-28-4","t":"丁이 丙의 채무를 면제한 경우, 甲과 乙은 丁에 대해 4천만원에 대하여 연대채무를 부담한다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"변리사 1차","qn":28,"i":"변리사2018_55-28-5","t":"甲이 乙과 丙에게 사전통지를 하지 않은 채 丁에게 채무 전부를 변제하고 乙과 丙에게 구상권을 행사하였는데 乙이 甲의 변제 전에 丁에 대하여 4천만원의 상계적상인 반대채권을 갖고 있었던 경우, 乙의 丁에 대한 채권은 2천만원에 한하여 甲에게 이전된다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"변리사 1차","qn":29,"i":"변리사2018_55-29-1","t":"丙이 보증계약 후 乙의 변제기를 연장해 준 경우, 특별한 사정이 없는 한 甲은 주채무의, 보증계약 당시의 이행기가 되더라도 乙에게 미리 구상권을 행사할 수 없다.","ox":"X","m":"①","c":"A"},{"y":2018,"e":"변리사 1차","qn":29,"i":"변리사2018_55-29-2","t":"甲이 丙에게 변제한 이후 乙과 丙의 계약이 해제되어 소급적으로 소멸한 경우, 甲은 丙을 상대로 이미 이행한 급부를 부당이득으로 반환청구할 수 없다.","ox":"X","m":"②","c":"A"},{"y":2018,"e":"변리사 1차","qn":29,"i":"변리사2018_55-29-3","t":"乙이 채무를 변제하고도 그 사실을 甲에게 통지하지 않고 있던 중에 甲이 이러한 사실을 모르고 乙에 대한 사전통지 없이 채무를 변제한 경우, 甲은 乙에 대하여 자기의 변제가 유효함을 주장할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"변리사 1차","qn":29,"i":"변리사2018_55-29-4","t":"丙이 乙에 대한 대금채권을 실행하기 위해 乙의 재산을 압류하더라도 甲의 보증채무의 소멸시효는 중단되지 않는다.","ox":"X","m":"④","c":"A"},{"y":2018,"e":"변리사 1차","qn":29,"i":"변리사2018_55-29-5","t":"甲이 변제로 乙의 채무를 소멸시킨 경우, 甲은 乙이 그 당시에 이익을 받은 한도에서 구상할 수 있다.","ox":"X","m":"⑤","c":"A"},{"y":2018,"e":"변리사 1차","qn":30,"i":"변리사2018_55-30-2","t":"甲으로부터 채권양도통지 권한을 위임받은 丙이 대리관계를 현명하지 않고 丙명의의 채권양도통지서를 乙에게 발송하여 도달한 경우, 특별한 사정이 없는 한그 양도통지는 효력이 없다.","ox":"O","m":"②","c":"A","tp":"甲이 乙에게 자신의 주택을 매도한 후에 乙"},{"y":2018,"e":"변리사 1차","qn":30,"i":"변리사2018_55-30-3","t":"甲이 乙에게 채권양도 사실을 통지한 후에 乙이 甲에게 금전을 빌려주었다면, 乙은 그 대여금반환채권에 의한 상계로써 丙에게 대항할 수 없다.","ox":"O","m":"③","c":"A","tp":"甲이 乙에게 자신의 주택을 매도한 후에 乙"},{"y":2018,"e":"변리사 1차","qn":30,"i":"변리사2018_55-30-4","t":"채권양도에 대한 乙의 승낙이 있은 후에 채권양도계약이 해제되어 甲이 乙에게 양도철회통지를 한 경우, 乙은 이로써 丙의 채무이행청구에 대하여 대항할 수 있다.","ox":"X","m":"④","c":"A","tp":"甲이 乙에게 자신의 주택을 매도한 후에 乙"},{"y":2018,"e":"변리사 1차","qn":30,"i":"변리사2018_55-30-5","t":"甲이 乙에게 채권양도의 사실을 통지하였으나 양도행위가 적법하게 취소된 경우, 乙이 이 사실을 모르고 丙에게 변제하였다면 이를 가지고 甲에게 대항할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"甲이 乙에게 자신의 주택을 매도한 후에 乙"},{"y":2018,"e":"변리사 1차","qn":31,"i":"변리사2018_55-31-1","t":"채무인수인은 특별한 의사표시가 없으면 자신의 구(舊)채무자에 대한 항변사유를 가지고 채권자에게 대항할 수 있다.","ox":"X","m":"①","c":"A"},{"y":2018,"e":"변리사 1차","qn":31,"i":"변리사2018_55-31-2","t":"채무자와 인수인 사이의 계약에 의해 채무인수가 이루어지는 경우, 채권자가 승낙을 거절하면 이후에 다시 승낙을 하더라도 면책적 채무인수의 효력이 발생하지 않는다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"변리사 1차","qn":31,"i":"변리사2018_55-31-3","t":"토지매수인이 토지에 관한 매도인의 채무를 인수하면서 그 채무액을 매매대금에서 공제하기로 약정한 경우, 특별한 사정이 없는 한 면책적 채무인수에 해당한다.","ox":"X","m":"③","c":"A"},{"y":2018,"e":"변리사 1차","qn":31,"i":"변리사2018_55-31-4","t":"채무자 아닌 제3자가 설정한 근저당권에 관하여 그 제3자의 동의를 얻어 채무인수를 원인으로 채무자를 교체하는 변경등기가 마쳐졌다면, 특별한 사정이 없는 한그 근저당권은 그 후 채무인수인이 다른 원인으로 부담하는 채무까지 담보한다.","ox":"X","m":"④","c":"A"},{"y":2018,"e":"변리사 1차","qn":31,"i":"변리사2018_55-31-5","t":"채무자와 인수인 간의 중첩적 채무인수계약의 경우에 채권자는 인수인에 대하여 수익의 의사표시 없이도 직접 청구할 권리를 갖는다.","ox":"X","m":"⑤","c":"A"},{"y":2019,"e":"변리사 1차","qn":26,"i":"변리사2019_56-26-1","t":"보증인은 보증채무에 대하여 위약금 또는 손해배상액을 예정할 수 있다.","ox":"O","m":"①","c":"A","tp":"보증계약"},{"y":2019,"e":"변리사 1차","qn":26,"i":"변리사2019_56-26-2","t":"채무자가 보증인을 세울 의무가 있는 경우, 채권자가 보증인을 지명하였다면 보증인은 행위능력 및 변제자력이 없어도 된다.","ox":"O","m":"②","c":"A","tp":"보증계약"},{"y":2019,"e":"변리사 1차","qn":26,"i":"변리사2019_56-26-3","t":"주채무자의 의사에 반하여 보증인이 된 자가 과실 없이 변제 기타 자기의 출재로 주채무를 소멸시킨 경우, 주채무자는 현존 이익의 한도에서 배상하여야 한다.","ox":"O","m":"③","c":"A","tp":"보증계약"},{"y":2019,"e":"변리사 1차","qn":26,"i":"변리사2019_56-26-4","t":"채권자가 연대보증인에게 채무이행을 청구한 경우, 연대보증인은 채무자의 변제자력이 있는 사실 및 그 집행이 용이할 것을 증명하여 먼저 채무자에게 청구할 것과 그 재산에 대하여 집행할 것을 항변할 수 있다.","ox":"X","m":"④","c":"A","tp":"보증계약"},{"y":2019,"e":"변리사 1차","qn":26,"i":"변리사2019_56-26-5","t":"주채무자의 부탁으로 보증인이 된 자가 과실 없이 변제 기타의 출재로 주채무를 소멸시킨 경우, 보증인은 주채무자를 상대로 면책된 날 이후의 법정이자에 관하여 구상청구를 할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"보증계약"},{"y":2019,"e":"변리사 1차","qn":28,"i":"변리사2019_56-28","t":"甲이 乙에 대한 대여금채권을 丙에게 양도하였고 乙이 이를 승낙하여 그 의사표시가 丙에게 도달되었다. 이에 관한 설명으로 옳지 않은 것은? (다툼이 있으면 판례","c":"A","mc":{"s":"甲이 乙에 대한 대여금채권을 丙에게 양도하였고 乙이 이를 승낙하여 그 의사표시가 丙에게 도달되었다. 이에 관한 설명으로 옳지 않은 것은? (다툼이 있으면 판례","d":"에 따름)","o":["乙의 승낙에는 조건을 붙일 수 있다.","乙이 이의 없이 승낙을 하더라도 특별한 사정이 없는 한 乙에게는 甲의 대여금채권의 성립이나 소멸에 영향을 미치는 사정을 丙에게 알려야 할 주의의무가 없다.","丙이 甲의 대여금채권에 양도금지특약이 있다는 사실을 알았더라도 그 후 乙이 승낙 하였다면, 채권양도는 다른 약정이 없는 한 그 성립 당시로 소급하여 유효하게 된다.","乙이 이의 없이 승낙을 하였더라도 그 때까지 발생한 乙의 甲에 대한 항변사유를 丙이 중대한 과실로 알지 못하였다면, 乙은 甲에 대한 그 항변사유로 丙에게 대항할 수 있다.","甲의 대여금채권에 관하여 보증인 丁이 있는 경우, 다른 약정이 없는 한 丁에 대한 보증채권의 양도에 관하여 별도의 대항요건을 갖추지 않더라도 甲의 대여금채권과 함께 丁에 대한 보증채권 역시 丙에게 이전된다."],"a":3}},{"y":2019,"e":"변리사 1차","qn":32,"i":"변리사2019_56-32-1","t":"중첩적 채무인수는 채권자와 인수인 사이의 합의가 있으면 채무자의 의사에 반해서도할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"변리사 1차","qn":32,"i":"변리사2019_56-32-2","t":"면책적 채무인수가 있는 경우, 인수채무의 소멸시효기간은 채무인수에 따라 중단되고 채무인수일로부터 새로이 진행한다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"변리사 1차","qn":32,"i":"변리사2019_56-32-3","t":"채권자의 승낙에 의하여 채무인수의 효력이 생기는 경우, 채권자가 승낙을 거절하면 그 이후에는 채권자가 다시 승낙하여도 채무인수로서의 효력이 생기지 않는다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"변리사 1차","qn":32,"i":"변리사2019_56-32-4","t":"면책적 채무인수에 대한 채권자의 승낙은 묵시적으로도 가능하며, 채권자가 승낙을 하지 않는 대신 직접 인수인을 상대로 인수채무의 이행을 청구하는 것도 묵시적 승낙에 해당한다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"변리사 1차","qn":32,"i":"변리사2019_56-32-5","t":"매수인이 매매목적물에 관한 임대차보증금반환채무를 인수하면서 그 채무액을 매매대금에서 공제하기로 약정한 경우, 임차인의 승낙이 없으면 병존적 채무인수로 본다.","ox":"X","m":"⑤","c":"A"},{"y":2021,"e":"변리사 1차","qn":28,"i":"변리사2021_58-28-1","t":"채무자와 채무인수인 사이의 면책적 채무인수에서 채권자가 승낙을 거절하였더라도 다시 승낙하면 채무인수의 효력이 생긴다.","ox":"X","m":"①","c":"A"},{"y":2021,"e":"변리사 1차","qn":28,"i":"변리사2021_58-28-2","t":"채무자와 채무인수인 사이의 면책적 채무인수에서 채권자가 채무인수인에게 인수금의 지급을 청구하더라도 채무인수의 승낙으로 볼 수 없다.","ox":"X","m":"②","c":"A"},{"y":2021,"e":"변리사 1차","qn":28,"i":"변리사2021_58-28-3","t":"채무자와 채무인수인 사이의 면책적 채무인수에서 채권자의 승낙이 없는 경우, 채무자와 인수인 사이에는 이행인수로서의 효력도 인정될 수 없다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"변리사 1차","qn":28,"i":"변리사2021_58-28-4","t":"채권자와 채무인수인 사이의 중첩적 채무인수는 채무자의 의사에 반하여도 이루어질 수 있다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"변리사 1차","qn":28,"i":"변리사2021_58-28-5","t":"면책적 채무인수의 경우, 채무인수인은 채무자에 대한 항변사유로 채권자에게 대항할 수 있다.","ox":"X","m":"⑤","c":"A"},{"y":2021,"e":"변리사 1차","qn":29,"i":"변리사2021_58-29","t":"다수당사자의 채권관계에 관한 설명으로 옳지 않은 것은? (다툼이 있으면 판례에","c":"A","mc":{"s":"다수당사자의 채권관계에 관한 설명으로 옳지 않은 것은? (다툼이 있으면 판례에","d":"따름)","o":["甲과 乙이 공유하는 부동산을 丙에게 공동으로 임대한 경우, 임대차 종료 시 甲과 乙은 지분비율에 따라 丙에게 임대차보증금을 반환할 채무를 부담한다.","丙에 대해 불가분채권을 가지고 있는 甲과 乙 중 甲이 丙에게 이행을 청구하여 丙이 이행지체에 빠진 경우, 丙은 乙에게도 이행지체 책임을 진다.","甲과 乙이 공유하는 부동산을 丙이 무단으로 점유\u0001사용하고 있는 경우, 특별한 사정이 없는 한 甲과 乙은 丙에 대해 지분 비율에 따른 부당이득반환청구권을 갖는다.","甲이 乙의 丙에 대한 채무를 중첩적으로 인수하는 경우, 甲과 乙은 원칙적으로 연대채무를 부담한다.","甲의 채권자 丁이 甲의 연대채무자 乙, 丙에 대한 채권 중 甲의 乙에 대한 채권에 대해 압류 및 추심명령을 발령받았더라도 甲은 丙에 대해 이행을 청구할 수 있다."],"a":1}},{"y":2021,"e":"변리사 1차","qn":30,"i":"변리사2021_58-30","t":"수급인 甲은 2020. 10. 1. 도급인 乙과 도급계약을 체결하고, 2021. 1. 5. 공사를 완성하여 乙에 대한 1억 원의 공사대금채권을 갖고 있던 중 위 채권을 丙에게 양도하고, 이를 乙에게 통지하였다. 이에 관한 설명으로 옳지 않은 것은? (다툼이","c":"A","mc":{"s":"수급인 甲은 2020. 10. 1. 도급인 乙과 도급계약을 체결하고, 2021. 1. 5. 공사를 완성하여 乙에 대한 1억 원의 공사대금채권을 갖고 있던 중 위 채권을 丙에게 양도하고, 이를 乙에게 통지하였다. 이에 관한 설명으로 옳지 않은 것은? (다툼이","d":"있으면 판례에 따름)","o":["甲이 丙에게 공사대금채권의 추심 기타 행사를 위임하면서 그 채권을 양도하였으나 양도의 원인인 위임이 해지된 경우, 공사대금채권은 甲에게 복귀한다.","甲이 주채무자 乙에 대한 채권과 그의 보증인 丁에 대한 채권 중 丁에 대한 채권만을 양도하기로 한 경우, 그 약정은 효력이 없다.","甲과 乙 사이에 채권양도금지특약이 있는 경우, 이와 같은 사실을 알고 있는 甲의 채권자 戊가 甲의 乙에 대한 채권에 대해 압류 및 전부명령을 받았다면 乙은 戊에게 위 특약에 의해 대항할 수 없다.","甲이 丙에게 공사대금채권 중 5,000만 원만 양도하고 乙에게 채권양도통지 후 乙이 甲에 대한 2,000만 원의 하자보수에 갈음하는 손해배상채권을 취득한 경우, 乙의 위 채권에 의한 상계는 각 분할된 채권액의 채권 총액에 대한 비율에 따라야 한다.","甲의 丙에 대한 채권양도 및 乙에 대한 확정일자부 통지와 甲의 채권자 戊가 신청한 甲의 乙에 대한 채권에 대한 압류 및 전부명령이 乙에게 동시에 도달한 경우, 乙은 채권자를 알 수 없음을 이유로 변제공탁을 할 수 있다."],"a":4}},{"y":2023,"e":"변리사 1차","qn":30,"i":"변리사2023_60-30","t":"채권의 양도 또는 계약 인수에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼","c":"A","mc":{"s":"채권의 양도 또는 계약 인수에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼","d":"이 있으면 판례에 따름)\nㄱ. 임차권양도를 금지하는 임대차계약상 특약이 임대차계약에 기한 임대보증 금반환채권의 양도를 금지하는 것으로 볼 수는 없다.\nㄴ. 채무자가 양도인에게 이의를 보류하지 않고 승낙을 하였을 경우, 승낙 당시 이미 상계를 할 수 있는 원인이 있었다는 사정을 양수인이 알고 있었다면 승낙 이후에 상계적상이 생기더라도 채무자는 양수인에게 상계로 대항할 수 있다.\nㄷ. 부동산 명의신탁자가 유효한 명의신탁약정을 해지한 다음 제3자에게 ‘명의신탁 해지를 원인으로 한 소유권이전등기청구권’을 양도하였다면, 명의수탁 자가 그 양도에 대하여 동의하지 않더라도 양수인은 명의수탁자에 대하여 직접 소유권이전등기청구를 할 수 있다.\nㄹ. 임대인의 지위는 원칙적으로 임대인과 임대목적물을 양수한 자의 계약만으 로 양도될 수 있다.","o":["ㄱ, ㄴ, ㄷ","ㄱ, ㄴ, ㄹ","ㄱ, ㄷ, ㄹ","ㄴ, ㄷ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":2}},{"y":2023,"e":"변리사 1차","qn":31,"i":"변리사2023_60-31-1","t":"이행인수인이 채권자에 대하여 채무자의 채무를 승인하더라도 특별한 사정이 없는 한시효중단의 효력은 발생하지 않는다.","ox":"O","m":"①","c":"A","tp":"채무인수 등"},{"y":2023,"e":"변리사 1차","qn":31,"i":"변리사2023_60-31-2","t":"저당권이 설정된 부동산의 매수인이 피담보채무를 인수하면서 그 채무액을 매매대금에서 공제하기로 하고 잔액만을 지급한 경우, 특별한 사정이 없는 한 매수인은 잔금 지급의무를 다한 것으로 볼 수 없다.","ox":"X","m":"②","c":"A","tp":"채무인수 등"},{"y":2023,"e":"변리사 1차","qn":31,"i":"변리사2023_60-31-3","t":"주택의 임차인이 대항력을 갖추었다면 그가 그 주택의 소유권을 취득하더라도 특별한 사정이 없는 한 임대인에 대한 보증금반환청구권은 혼동으로 소멸하지 않는다.","ox":"X","m":"③","c":"A","tp":"채무인수 등"},{"y":2023,"e":"변리사 1차","qn":31,"i":"변리사2023_60-31-4","t":"중첩적 채무인수에서 채무자와 인수인은 채권자에 대하여 원칙적으로 부진정연대채무 관계에 있다.","ox":"X","m":"④","c":"A","tp":"채무인수 등"},{"y":2023,"e":"변리사 1차","qn":31,"i":"변리사2023_60-31-5","t":"채무가 인수된 경우 특별한 사정이 없는 한 제3자가 제공한 담보물권도 함께 이전한다.","ox":"X","m":"⑤","c":"A","tp":"채무인수 등"},{"y":2024,"e":"변리사 1차","qn":29,"i":"변리사2024_61-29","t":"연대채무자 甲\u0001乙\u0001丙이 채권자 丁에게 대여금 3억 원을 변제하기로 하는 채무를 부담하는 경우, 이에 관한 설명으로 옳지 않은 것은? (甲\u0001乙\u0001丙의 부담부분","c":"A","mc":{"s":"연대채무자 甲\u0001乙\u0001丙이 채권자 丁에게 대여금 3억 원을 변제하기로 하는 채무를 부담하는 경우, 이에 관한 설명으로 옳지 않은 것은? (甲\u0001乙\u0001丙의 부담부분","d":"은 균등하며 원본만 고려함. 각 지문은 독립적이고, 다툼이 있으면 판례에 따름)","o":["丁이 변제기에 甲을 상대로 채무이행의 소를 제기하여 승소판결이 확정된 경우, 그 소멸시효 중단의 효과는 乙과 丙에게도 발생한다.","乙이 丁에 대해 상계적상에 있는 2억 원의 채권을 가지고 있으나 상계하지 아니한 경우, 丙은 乙의 丁에 대한 2억 원의 채권 중 1억 원에 한해 상계할 수 있다.","丙이 채무 3억 원의 지급에 갈음하여 자신이 소유하는 부동산의 소유권을 丁에게 이 전하기로 하는 경개계약을 丁과 유효하게 체결한 경우, 丁에 대한 甲과 乙의 채무는 소멸한다.","丁이 甲에 대해 채무 전부를 면제한 경우, 丁에 대한 乙과 丙의 채무 전부도 소멸한다.","丙이 丁의 위 채권(3억 원)을 유효하게 양수한 경우, 甲과 乙은 丙에게 각 1억 원을 변제하여야 한다."],"a":4}},{"y":2024,"e":"변리사 1차","qn":30,"i":"변리사2024_61-30-1","t":"부동산매매로 인한 소유권이전등기청구권이 양도된 경우, 양도인의 채무자에 대한 통지만으로 채무자에 대한 대항력이 발생한다.","ox":"X","m":"①","c":"A","tp":"채권의 양도"},{"y":2024,"e":"변리사 1차","qn":30,"i":"변리사2024_61-30-2","t":"소송행위를 하게 하는 것을 주목적으로 지명채권의 양도가 이루어진 경우, 그 채권양도가 신탁법상의 신탁에 해당하지 않는 경우에는 유효이다.","ox":"X","m":"②","c":"A"},{"y":2024,"e":"변리사 1차","qn":30,"i":"변리사2024_61-30-3","t":"주채무자에 대한 지명채권이 양도된 후 양수인이 보증인에게 보증채권을 행사하기 위해서는 주채권의 양도에 대한 대항요건과 별도로 보증채권의 양도에 대한 대항요건을 갖추어야 한다.","ox":"X","m":"③","c":"A"},{"y":2024,"e":"변리사 1차","qn":30,"i":"변리사2024_61-30-4","t":"선순위의 근저당권부채권을 양수한 채권자보다 후순위의 근저당권자는 ‘지명채권양도의 대항요건을 갖추지 아니한 경우에 대항할 수 없는 제3자’에 포함되지 않는다.","ox":"O","m":"④","c":"A","tp":"채권의 양도"},{"y":2024,"e":"변리사 1차","qn":30,"i":"변리사2024_61-30-5","t":"채권자와 양수인 사이의 계약에 의해 지명채권이 양도된 경우, 양수인은 제3자에 대한 대항요건을 구비하기 위함이라고 하더라도 그 채권자에게 채권양도통지절차의 이 행을 청구할 수 없다.","ox":"X","m":"⑤","c":"A","tp":"채권의 양도"},{"y":2024,"e":"변리사 1차","qn":31,"i":"변리사2024_61-31","t":"채무의 인수에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면 판례에","c":"A","mc":{"s":"채무의 인수에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면 판례에","d":"따름)\nㄱ. 중첩적 채무인수는 채권자와 채무인수인과의 합의가 있는 이상 채무자의 의사에 반하여서도 이루어질 수 있다.\nㄴ. 면책적 채무인수가 있은 경우, 인수채무의 소멸시효기간은 특별한 사정이 없는 한 채무인수와 동시에 이루어진 채무인수인의 채무승인에 따라 채무 인수일로부터 새로이 진행된다.\nㄷ. 채무자와 채무인수인의 합의에 의한 중첩적 채무인수는 제3자를 위한 계약에 해당하지 않으며, 채권자는 채무인수인에게 수익의 의사를 표시하지 않더라도 채무인수인에 대하여 직접 청구할 권리를 갖는다.","o":["ㄱ","ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":2}},{"y":2026,"e":"변리사 1차","qn":30,"i":"변리사2026_63-30-1","t":"전세권 존속 중에는 장래에 그 전세권이 소멸하는 경우에 전세금반환채권이 발생하는 것을 조건으로 그 장래의 조건부 채권을 양도할 수 없다.","ox":"X","m":"①","c":"A","tp":"채권양도"},{"y":2026,"e":"변리사 1차","qn":30,"i":"변리사2026_63-30-2","t":"A채무의 이행을 담보할 목적으로 유효한 채권양도가 이루어진 이후 A채무가 변제로 소멸된 경우, 양도된 채권의 채무자는 이를 이유로 채권양수인의 양수금 청구를 거절할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"변리사 1차","qn":30,"i":"변리사2026_63-30-3","t":"채권자와 채무자 사이의 채권양도금지 특약에 대하여 선의인 채권양수인으로부터 다시 채권을 양수한 악의의 전득자는 채권을 유효하게 취득할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"변리사 1차","qn":30,"i":"변리사2026_63-30-4","t":"임대인이 임대차보증금반환채권의 양도 통지를 받은 후에는 임차인과 임대차계약의 갱신에 관하여 명시적으로 합의하더라도 그 합의의 효과는 보증금반환채권의 양수인에게 미치지 않는다.","ox":"O","m":"④","c":"A","tp":"채권양도"},{"y":2026,"e":"변리사 1차","qn":30,"i":"변리사2026_63-30-5","t":"주채권과 분리하여 보증채권만을 양도하기로 하는 약정은 그 효력이 없다.","ox":"O","m":"⑤","c":"A","tp":"채권양도"},{"y":2026,"e":"변리사 1차","qn":31,"i":"변리사2026_63-31-1","t":"면책적 채무인수가 있더라도 종전채무자의 채무에 대한 보증은 보증인의 동의 없이도 존속한다.","ox":"X","m":"①","c":"A"},{"y":2026,"e":"변리사 1차","qn":31,"i":"변리사2026_63-31-2","t":"면책적 채무인수가 있으면 인수채무의 소멸시효는 중단되고 채무인수일로부터 새로이 시효가 진행된다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"변리사 1차","qn":31,"i":"변리사2026_63-31-3","t":"면책적 채무인수에서 채권자는 승낙 또는 거절의 의사표시를 채무자와 인수인 모두에게 하여야 한다.","ox":"X","m":"③","c":"A"},{"y":2026,"e":"변리사 1차","qn":31,"i":"변리사2026_63-31-4","t":"채무자와 인수인의 합의에 의한 중첩적 채무인수에서 채권자의 수익의 의사표시는 그 채무인수 계약의 효력발생을 위한 요건이다.","ox":"X","m":"④","c":"A"},{"y":2026,"e":"변리사 1차","qn":31,"i":"변리사2026_63-31-5","t":"채무자와 인수인이 면책적 채무인수의 약정을 한 경우, 채권자의 승낙이 없더라도 채무자는 채무를 면한다.","ox":"X","m":"⑤","c":"A"},{"y":2026,"e":"변리사 1차","qn":32,"i":"변리사2026_63-32-1","t":"채권자가 주채무자에 대하여 상계적상이 있는 자동채권을 상계하지 않는 경우, 보증인은 이를 이유로 보증채무의 이행을 거절할 수 있다.","ox":"X","m":"①","c":"A","tp":"다수당사자의 채권관계"},{"y":2026,"e":"변리사 1차","qn":32,"i":"변리사2026_63-32-2","t":"채권자의 연대보증인 중 1인에 대한 채무면제는 연대보증인 사이에 연대특약이 없더라도 다른 연대보증인에 대하여 그 효력이 미친다.","ox":"X","m":"②","c":"A","tp":"다수당사자의 채권관계"},{"y":2026,"e":"변리사 1차","qn":32,"i":"변리사2026_63-32-3","t":"부진정연대채무자 상호간에 구상권을 행사하기 위해서는 사전 또는 사후에 통지를 하여야 한다.","ox":"X","m":"③","c":"A","tp":"다수당사자의 채권관계"},{"y":2026,"e":"변리사 1차","qn":32,"i":"변리사2026_63-32-4","t":"사용대차에서 공동차주의 목적물 반환의무는 원칙적으로 불가분채무이다.","ox":"X","m":"④","c":"A","tp":"다수당사자의 채권관계"},{"y":2026,"e":"변리사 1차","qn":32,"i":"변리사2026_63-32-5","t":"보증인의 부담이 주채무의 목적이나 형태보다 중한 때에는 주채무의 한도로 감축한다.","ox":"O","m":"⑤","c":"A","tp":"다수당사자의 채권관계"}],"12":[{"y":2016,"e":"변리사 1차","qn":32,"i":"변리사2016_53-32-1","t":"채무자가 채권자에게 채무변제에 갈음하여 다른 채권을 양도하기로 한 경우, 채권양도의 요건을 갖추어 대체급부가 이루어짐으로써 원래의 채무는 소멸한다.","ox":"O","m":"①","c":"A","tp":"대물변제"},{"y":2016,"e":"변리사 1차","qn":32,"i":"변리사2016_53-32-2","t":"채무자가 채권자에게 채무변제에 갈음하여 다른 채권을 양도하기로 한 경우, 양도인은 양도된 채권의 채무자의 변제자력까지 담보하는 것으로 보아야 한다.","ox":"X","m":"②","c":"A","tp":"대물변제"},{"y":2016,"e":"변리사 1차","qn":32,"i":"변리사2016_53-32-3","t":"채무자가 채무 담보를 위해 대물변제의 예약을 한 후 같은 채권자로부터 추가로 채무를 지는 경우에는 특별한 사정이 없는 한 추가되는 채무도 대물변제 예약의 대상이 되는 채무 범위에 포함된다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"변리사 1차","qn":32,"i":"변리사2016_53-32-4","t":"대물변제가 채무소멸의 효력을 발생하려면 채무자가 본래의 이행에 갈음하여 행하는 다른 급부가 현실적인 것이어야 한다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"변리사 1차","qn":32,"i":"변리사2016_53-32-5","t":"대물변제예약완결권의 행사기간에 관한 약정이 없는 때에는 그 권리가 발생한 때로부터 10년 내에 이를 행사하여야 하고, 이 기간을 도과한 때에는 예약완결권은 소멸한다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"변리사 1차","qn":32,"i":"변리사2017_54-32-1","t":"가압류의 효력 발생 당시 乙의 채권과 甲의 채권의 변제기가 모두 도래한 경우, 乙은 상계로써 丙에게 대항할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"변리사 1차","qn":32,"i":"변리사2017_54-32-2","t":"가압류 효력발생 당시 乙의 채권이 변제기에 도달하지 않은 경우, 乙의 채권의 변제기가 甲의 채권의 변제기와 동시에 도래하면, 乙은 상계로써 丙에게 대항할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"변리사 1차","qn":32,"i":"변리사2017_54-32-3","t":"가압류의 효력발생 당시 乙의 채권이 변제기에 도달하지 않은 경우, 甲의 채권의 변제기 후에 乙의 채권이 변제기에 도달하더라도 乙은 상계로써 丙에게 대항할 수 있다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"변리사 1차","qn":32,"i":"변리사2017_54-32-4","t":"가압류 효력발생 당시 乙의 채권이 변제기에 도달하지 않은 경우, 乙의 채권의 변제기가 甲의 채권의 변제기보다 먼저 도래하면 乙은 상계로써 丙에게 대항할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"변리사 1차","qn":32,"i":"변리사2017_54-32-5","t":"가압류 효력발생 당시 비록 甲과 乙의 채권이 변제기에 도달하였더라도 乙이 甲에 대하여 상계의 의사표시를 하지 않은 경우, 특별한 사정이 없는 한 乙은상 계로써 丙에게 대항할 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"변리사 1차","qn":32,"i":"변리사2018_55-32","t":"甲이 乙에게 5천만원을 빌릴 때 丙은 甲을 위한 보증인이 되었다. 丁은 乙에 대하여 3천만원의 공사대금채권을 갖고 있으며, 甲은 乙에 대하여 2천만원의 채권을 갖고 있다. 이에 관한 설명으로 옳지 않은 것은? (모든 채무는 상계","c":"A","mc":{"s":"甲이 乙에게 5천만원을 빌릴 때 丙은 甲을 위한 보증인이 되었다. 丁은 乙에 대하여 3천만원의 공사대금채권을 갖고 있으며, 甲은 乙에 대하여 2천만원의 채권을 갖고 있다. 이에 관한 설명으로 옳지 않은 것은? (모든 채무는 상계","d":"적상에 있음을 가정하며, 다툼이 있으면 판례에 따름)","o":["甲과 乙 상호간의 채권이 상계로 인해 소멸하는 경우, 그 효력은 각 채무가 상계할 수 있는 때로 소급하여 발생한다.","丙은 甲의 乙에 대한 위 금전채권에 의한 상계로 乙에게 대항할 수 있다.","甲과 乙이 상계금지 특약을 하였는데, 乙에 대해 보증금반환채무를 부담하는 A 가 그 특약 사실을 모른 채 甲의 乙에 대한 위 금전채권을 양수하고 채권양도의 대항요건을 갖춘 경우, A는 그 양수채권을 가지고 乙에 대한 자신의 채무와 상계할 수 있다.","만약 丁이 乙의 甲에 대한 대여금채권을 압류한 이후에 甲이 乙에게 자동차를 매도하여 위 금전채권을 취득하였다면, 甲은 乙에 대한 위 금전채권에 의한 상 계로써 丁에게 대항할 수 있다.","만약 甲의 乙에 대한 위 금전채권이 고의의 불법행위로 인한 것이라면, 甲은 이를 자동채권으로 하여 상계할 수 있다."],"a":4}},{"y":2019,"e":"변리사 1차","qn":25,"i":"변리사2019_56-25","t":"甲은 乙에 대한 대여금채무 6억원을 담보하기 위하여 자기 소유 X토지에 乙명의의 저당권을 설정해주었다. 甲의 부탁으로 위 채무를 담보하기 위하여 丙은 乙과 보증계약을 체결하였고, 丁과 戊는 각각 자기 소유 Y토지와 Z토지에 乙명의의 저당권을 설정해주었다. 이에 관한 설명으로 옳지 않은 것은? (단, 이자 및 지연배상금은","c":"A","mc":{"s":"甲은 乙에 대한 대여금채무 6억원을 담보하기 위하여 자기 소유 X토지에 乙명의의 저당권을 설정해주었다. 甲의 부탁으로 위 채무를 담보하기 위하여 丙은 乙과 보증계약을 체결하였고, 丁과 戊는 각각 자기 소유 Y토지와 Z토지에 乙명의의 저당권을 설정해주었다. 이에 관한 설명으로 옳지 않은 것은? (단, 이자 및 지연배상금은","d":"고려하지 않고, 다툼이 있으면 판례에 따름)","o":["丁이 甲의 대여금채무를 모두 변제한 경우, 丁은 甲에 대하여 구상권을 행사할 수 있다.","丁이 甲의 대여금채무를 모두 변제한 경우, 丁은 乙을 대위하여 丙을 상대로 2억원의 지급을 청구할 수 있다.","戊는 甲의 대여금채무를 변제할 정당한 이익이 있는 자이므로, 戊가 그 채무를 모두 변제하였다면 乙의 승낙이 없어도 당연히 乙을 대위한다.","丙이 甲의 대여금채무를 모두 변제한 경우, 미리 저당권등기에 대위의 부기등기를 하지 않더라도 丁에 대하여 乙을 대위할 수 있다.","A가 甲과의 매매계약을 원인으로 X토지의 소유권이전등기를 마친 후 甲의 대여금채무를 모두 변제한 경우, A는 丙에 대하여 乙을 대위할 수 있다."],"a":5}},{"y":2021,"e":"변리사 1차","qn":31,"i":"변리사2021_58-31","t":"변제에 관한 설명으로 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"변제에 관한 설명으로 옳은 것을 모두 고른 것은?","d":"ㄱ. 甲은 乙에 대해 1,000만 원의 채무를 부담하고 있는데, 丙이 자신의 채무로 오해하여 乙에게 1,000만 원을 지급한 경우, 제3자 변제에 해당하지 않는다.\nㄴ. 甲이 그의 乙에 대한 공사대금채무의 담보로 乙의 유치권이 성립한 그 소유의 건물을 丙에게 매도하면서 소유권이전등기시까지 임대한 경우, 丙은 甲의 의사에 반하여 공사대금채무를 乙에게 변제할 수 없다.\nㄷ. 예금주 甲의 대리인이라고 주장하는 乙이 甲의 통장과 인감을 소지하고 丙은행에 예금반환청구를 한 경우, 대리인을 사칭한 乙은 채권의 사실상 귀속자와 같은 외형을 갖추고 있지 아니하여 채권의 준점유자로 볼수 없다.\nㄹ. 지시채권 증서 소지인 甲에 대한 乙의 변제는 乙이 甲의 권리 없음을 알았거나 중과실이 있는 경우를 제외하고 유효하다.","o":["ㄱ","ㄱ, ㄴ","ㄱ, ㄹ","ㄱ, ㄴ, ㄷ","ㄴ, ㄷ, ㄹ"],"a":3}},{"y":2023,"e":"변리사 1차","qn":32,"i":"변리사2023_60-32-1","t":"채무자가 채무액 일부를 지급하면서 이자 아닌 원본에 충당할 것을 지정하고 채권자가 이를 이의 없이 수령하여 묵시적 합의가 인정되는 때에는 지급된 금전은 원본에 충당된다.","ox":"O","m":"①","c":"A","tp":"채권의 소멸"},{"y":2023,"e":"변리사 1차","qn":32,"i":"변리사2023_60-32-2","t":"원금채무는 소멸시효가 완성되지 않았으나 이자채무는 소멸시효가 완성된 상태에서 채무자가 변제충당을 지정하지 않고 채무의 일부를 변제한 때에는 특별한 사정이 없는 한 이자채무에 먼저 충당된다.","ox":"O","m":"②","c":"A","tp":"채권의 소멸"},{"y":2023,"e":"변리사 1차","qn":32,"i":"변리사2023_60-32-3","t":"상계가 금지되는 채권이라고 하더라도 압류금지채권에 해당하지 않는 한 강제집행에 의한 전부명령의 대상이 될 수 있다.","ox":"O","m":"③","c":"A","tp":"채권의 소멸"},{"y":2023,"e":"변리사 1차","qn":32,"i":"변리사2023_60-32-4","t":"피용자의 고의의 불법행위로 인하여 사용자책임이 성립하는 경우, 사용자는 자신의 고의가 없음을 주장하여 피해자의 손해배상채권을 수동채권으로 하는 상계권을 행사할 수 있다.","ox":"X","m":"④","c":"A","tp":"채권의 소멸"},{"y":2023,"e":"변리사 1차","qn":32,"i":"변리사2023_60-32-5","t":"소멸시효가 완성된 채권이 그 완성 전에 상계할 수 있었던 것이면 채권자는 그 채권을 자동채권으로 하여 상계할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"채권의 소멸"},{"y":2024,"e":"변리사 1차","qn":32,"i":"변리사2024_61-32","t":"채권의 소멸에 관한 설명으로 옳지 않은 것을 모두 고른 것은? (다툼이 있으면","c":"A","mc":{"s":"채권의 소멸에 관한 설명으로 옳지 않은 것을 모두 고른 것은? (다툼이 있으면","d":"판례에 따름)\nㄱ. 법정변제충당의 순위를 정함에 있어서 변제의 유예가 있는 채무에 대하여 는 유예기까지 변제기가 도래하지 않은 것과 같게 보아야 한다.\nㄴ. 채권자의 태도로 보아 채무자가 채무의 이행제공을 하였더라도 그 수령을 거절하였을 것이 명백한 경우에도 채무자는 이행의 제공을 하지 않고 바로 변제공탁할 수는 없다.\nㄷ. 변제공탁이 적법한 경우에는 채권자가 공탁물 출급청구를 하였는지와 관계없이 공탁을 한 때에 변제의 효력이 발생하지만, 그 후 공탁물 출급청구권 에 대하여 가압류 집행이 된 경우에는 변제의 효력이 발생하지 아니한다.\nㄹ. 매도인의 담보책임을 기초로 한 손해배상채권의 제척기간이 지난 경우, 매수인은 그 제척기간이 지나기 전에 상계할 수 있었을지라도 그 손해배상채권을 자동채권으로 해서 매도인의 채권과 상계할 수 없다.","o":["ㄱ, ㄴ","ㄷ, ㄹ","ㄱ, ㄴ, ㄷ","ㄱ, ㄷ, ㄹ","ㄴ, ㄷ, ㄹ"],"a":5}},{"y":2026,"e":"변리사 1차","qn":33,"i":"변리사2026_63-33-1","t":"대위변제자와 채무자 사이의 구상금에 관한 지연손해금 약정은 특별한 사정이 없는한 변제자대위권의 행사에는 적용될 수 없다.","ox":"O","m":"①","c":"A","tp":"채무를 변제할 이익이 있는 자가 채무자를 위하여 채무를 대위변제한 경우"},{"y":2026,"e":"변리사 1차","qn":33,"i":"변리사2026_63-33-2","t":"근저당권의 피담보채권이 확정되기 전에는 그 채권의 일부가 대위변제되더라도 그 근저당권이 대위변제자에게 이전될 수 없다.","ox":"O","m":"②","c":"A","tp":"채무를 변제할 이익이 있는 자가 채무자를 위하여 채무를 대위변제한 경우"},{"y":2026,"e":"변리사 1차","qn":33,"i":"변리사2026_63-33-3","t":"보증인이 채무를 변제한 후 저당권의 등기에 대위를 부기하지 않아도 그 저당물에 후 순위 근저당권을 취득한 제3자에 대하여 채권자를 대위할 수 있다.","ox":"O","m":"③","c":"A","tp":"채무를 변제할 이익이 있는 자가 채무자를 위하여 채무를 대위변제한 경우"},{"y":2026,"e":"변리사 1차","qn":33,"i":"변리사2026_63-33-4","t":"채무자로부터 담보부동산을 취득한 후에 채무를 변제한 제3자는 물상보증인에 대하여 채권자를 대위할 수 있다.","ox":"X","m":"④","c":"A","tp":"채무를 변제할 이익이 있는 자가 채무자를 위하여 채무를 대위변제한 경우"},{"y":2026,"e":"변리사 1차","qn":33,"i":"변리사2026_63-33-5","t":"수인(數人)의 물상보증인 중 1인이 채무를 변제한 때에는 다른 물상보증인에 대하여각 부동산의 가액에 비례하여 채권자를 대위한다.","ox":"O","m":"⑤","c":"A","tp":"채무를 변제할 이익이 있는 자가 채무자를 위하여 채무를 대위변제한 경우"}],"13":[{"y":2016,"e":"변리사 1차","qn":33,"i":"변리사2016_53-33-1","t":"당사자 쌍방의 채무가 각각 별개의 계약에 의하여 생긴 경우에는 특별한 사정이 없는 한 동시이행의 항변권이 인정되지 않는다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"변리사 1차","qn":33,"i":"변리사2016_53-33-2","t":"당사자 일방의 채무가 손해배상채무로 전환되는 경우 본래의 채무와 손해배상 채무는 동일성을 유지하므로 동시이행항변권은 존속한다.","ox":"O","m":"②","c":"A","tp":"동시이행의 항변권"},{"y":2016,"e":"변리사 1차","qn":33,"i":"변리사2016_53-33-3","t":"공사도급계약의 도급인이 자기 소유의 토지에 근저당권을 설정하여 수급인으로 하여금 공사에 필요한 자금을 대출받도록 한 경우, 수급인의 근저당권말소의무는 도급인의 공사대금채무보다 먼저 이행되어야 한다.","ox":"X","m":"③","c":"A","tp":"동시이행의 항변권"},{"y":2016,"e":"변리사 1차","qn":33,"i":"변리사2016_53-33-4","t":"매수인이 선이행해야 할 중도금을 지급하지 않은 채 잔대금지급일을 경과한 경우, 매수인의 중도금과 지연손해금 및 잔대금지급채무와 매도인의 소유권이전등기의무는 특별한 사정이 없는 한 동시이행관계에 있다.","ox":"O","m":"④","c":"A","tp":"동시이행의 항변권"},{"y":2016,"e":"변리사 1차","qn":33,"i":"변리사2016_53-33-5","t":"당사자 일방이 먼저 현실의 제공을 함으로써 상대방을 수령지체에 빠지게 하였다 하더라도 그 이행의 제공이 계속되지 않는 경우에는 과거에 이행의 제공이 있었다는 사실만으로 상대방이 가지는 동시이행의 항변권이 소멸하지 않는다.","ox":"O","m":"⑤","c":"A"},{"y":2016,"e":"변리사 1차","qn":35,"i":"변리사2016_53-35-1","t":"계약당사자가 위 규정상의 해약권을 배제하는 약정을 한 경우에 그 약정은 유효하다.","ox":"O","m":"①","c":"A","tp":"해약금(민법 제565조)"},{"y":2016,"e":"변리사 1차","qn":35,"i":"변리사2016_53-35-2","t":"매도인이 계약금의 배액을 상환하고 계약을 해제하려면 계약해제의 의사표시를 하고 계약금 배액을 지급하여야 하며, 상대방이 수령하지 않는 경우에는 이를 공탁하여야 한다.","ox":"X","m":"②","c":"A","tp":"해약금(민법 제565조)"},{"y":2016,"e":"변리사 1차","qn":35,"i":"변리사2016_53-35-3","t":"계약당사자가 위 민법규정에 따라 매매계약을 해제하는 경우, 상대방에 대하여 원상회복은 청구할 수 없으나 채무불이행을 이유로 손해배상은 청구할 수 있다.","ox":"X","m":"③","c":"A","tp":"해약금(민법 제565조)"},{"y":2016,"e":"변리사 1차","qn":35,"i":"변리사2016_53-35-4","t":"매도인이 매수인에게 매매계약의 이행을 최고하고 매매잔대금의 지급을 구하는 소송을 제기한 것만으로도 이행에 착수한 것이다.","ox":"X","m":"④","c":"A","tp":"해약금(민법 제565조)"},{"y":2016,"e":"변리사 1차","qn":35,"i":"변리사2016_53-35-5","t":"토지거래허가구역 내 토지에 관하여 매매계약을 체결하고 계약금만 주고받은 상태에서 토지거래허가를 받았다면, 매도인은 이제 더 이상 해약금규정에 따른 계약해제를 할 수 없다.","ox":"X","m":"⑤","c":"A","tp":"해약금(민법 제565조)"},{"y":2016,"e":"변리사 1차","qn":36,"i":"변리사2016_53-36-1","t":"채권자가 채무불이행을 이유로 하여 계약을 적법하게 해제한 후에도 채무자는 착오를 이유로 그 계약을 취소할 수 있다.","ox":"O","m":"①","c":"A","tp":"계약해제"},{"y":2016,"e":"변리사 1차","qn":36,"i":"변리사2016_53-36-2","t":"채권자대위권행사의 통지를 받은 후 채무자의 채무불이행을 이유로 제3채무자가 매매계약을 해제한 경우, 특별한 사정이 없는 한 그 제3채무자는 계약해제로써 대위권을 행사하는 채권자에게 대항할 수 없다.","ox":"X","m":"②","c":"A"},{"y":2016,"e":"변리사 1차","qn":36,"i":"변리사2016_53-36-3","t":"매도인의 소유권이전등기의무가 이행불능임을 이유로 매매계약을 해제함에 있어서, 상대방의 잔대금지급의무가 매도인의 소유권이전등기의무와 동시이행관계에 있더라도 그 이행의 제공을 필요로 하지 않는다.","ox":"O","m":"③","c":"A","tp":"계약해제"},{"y":2016,"e":"변리사 1차","qn":36,"i":"변리사2016_53-36-4","t":"제3자를 위한 계약에서 수익자는 낙약자의 채무불이행을 이유로 계약을 해제할 수 없다.","ox":"O","m":"④","c":"A","tp":"계약해제"},{"y":2016,"e":"변리사 1차","qn":36,"i":"변리사2016_53-36-5","t":"수증자가 증여자에 대하여 범죄행위를 한 경우에 증여자는 그 증여를 해제할 수 있지만, 그 해제는 이미 이행한 부분에는 효력을 미치지 않는다.","ox":"O","m":"⑤","c":"A","tp":"계약해제"},{"y":2017,"e":"변리사 1차","qn":34,"i":"변리사2017_54-34-1","t":"X주택의 소유권이전의무가 甲의 과실로 이행불능이 된 경우, 乙은 丙의 동의 없이 매매계약을 해제할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"변리사 1차","qn":34,"i":"변리사2017_54-34-3","t":"甲과 乙 간의 매매계약이 乙의 사기를 이유로 취소된 경우, 丙이 그 사실을 몰랐더라도 丙은 선의의 제3자로서 보호받지 못한다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"변리사 1차","qn":34,"i":"변리사2017_54-34-4","t":"만약 丙이 甲의 대리인으로서 乙을 기망하여 乙이 위 매매계약을 체결한 경우, 乙은 丙의 대금지급청구를 거절할 수 있을 뿐이고 위 매매계약을 취소할 수는 없다.","ox":"X","m":"④","c":"A"},{"y":2017,"e":"변리사 1차","qn":34,"i":"변리사2017_54-34-5","t":"甲의 채무불이행으로 위 매매계약이 해제된 경우, 乙이 丙에게 매매대금의 일부를 이미 지급하였더라도, 특별한 사정이 없는 한 乙은 丙을 상대로 부당이득을 원인으로 이미 지급한 대금의 반환을 청구할 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"변리사 1차","qn":35,"i":"변리사2017_54-35-1","t":"만약 계약 당시 乙이 계약금 5백만원을 지급하였더라도 계약의 이행 착수 전이라면, 甲은 1천만원을 상환하고 위 매매계약을 해제할 수 있다.","ox":"X","m":"①","c":"A"},{"y":2017,"e":"변리사 1차","qn":35,"i":"변리사2017_54-35-2","t":"甲의 채권자 丙이 2015. 2. 15. 甲의 잔대금 채권을 가압류한 경우라면, 丙은 민법 제548조 제1항 단서에 의해 보호받을 수 있는 제3자에 해당한다.","ox":"X","m":"②","c":"A"},{"y":2017,"e":"변리사 1차","qn":35,"i":"변리사2017_54-35-3","t":"2015. 3. 1. 丁이 乙과 X주택에 대하여 매매예약을 하고 그에 기해 소유권이전등 기청구권 보전을 위한 가등기를 마쳤다면, 위 매매계약의 해제에도 불구하고 丁은 매매예약에 기한 본등기를 할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"변리사 1차","qn":35,"i":"변리사2017_54-35-4","t":"乙 명의의 등기말소 전인 2015. 4. 20. 乙로부터 X주택의 일부를 임차하여 주택 임대차보호법상 대항력을 갖춘 임차인은 위 매매계약이 해제된 사실을 알고 있었더라도 X주택에 대한 甲의 명도청구에 대항할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2017,"e":"변리사 1차","qn":35,"i":"변리사2017_54-35-5","t":"X주택을 사용한 乙이 계약의 해제로 이를 甲에게 반환하는 경우, X주택이 乙의 사용으로 인해 훼손되었다고 볼 수 없는 경우에도 그 사용이익 외에 감가상각비를 별도로 산정하여 반환하여야 한다.","ox":"X","m":"⑤","c":"A"},{"y":2017,"e":"변리사 1차","qn":40,"i":"변리사2017_54-40-1","t":"사업자와 고객 사이에 교섭이 이루어진 약관 조항도 「약관의 규제에 관한 법률」에 정한 약관에 해당한다.","ox":"X","m":"①","c":"A"},{"y":2017,"e":"변리사 1차","qn":40,"i":"변리사2017_54-40-2","t":"약관조항이 무효로 되면, 민법상 일부무효의 법리에 따라 그 전부를 무효로 함이 원칙이다.","ox":"X","m":"②","c":"A"},{"y":2017,"e":"변리사 1차","qn":40,"i":"변리사2017_54-40-3","t":"약관에 정하여진 사항이 거래상 일반적이고 공통된 것이어서 고객이 별도의 설명 없이도 충분히 예상할 수 있었던 사항이더라도, 사업자에게 명시\u0001설명 의무가 있다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"변리사 1차","qn":40,"i":"변리사2017_54-40-4","t":"사업자가 고객의 대리인과 계약을 체결하는 경우, 설명의무의 상대방이 계약자 본인에 국한되는 것은 아니므로 그 대리인에게 약관을 설명하는 것으로 충분하다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"변리사 1차","qn":40,"i":"변리사2017_54-40-5","t":"동일한 약관집 내의 대다수의 조항들이 교섭되고 변경된 사정이 있다고 하더라도, 변경되지 아니한 나머지 소수의 조항들에 대해서 교섭이 이루어진 것으로 추정할 수는 없다.","ox":"X","m":"⑤","c":"A"},{"y":2018,"e":"변리사 1차","qn":33,"i":"변리사2018_55-33-1","t":"乙이 甲과의 계약을 해제하기 위해서는 상당한 기간을 정해 이행을 최고하여야 한다.","ox":"X","m":"①","c":"A","tp":"甲은 자신이 소유하는 토지를 乙에게 매도하고 중도금까지 받았는데, 乙에게 그 토지"},{"y":2018,"e":"변리사 1차","qn":33,"i":"변리사2018_55-33-2","t":"乙이 甲과의 계약을 해제하면 乙은 甲에 대해 원상회복청구권을 갖는데, 그 권리의 소멸시효는 해제권이 발생한 때로부터 진행한다.","ox":"X","m":"②","c":"A","tp":"甲은 자신이 소유하는 토지를 乙에게 매도하고 중도금까지 받았는데, 乙에게 그 토지"},{"y":2018,"e":"변리사 1차","qn":33,"i":"변리사2018_55-33-3","t":"乙이 甲과의 계약을 해제하기 위해서는 甲의 소유권이전등기의무와 동시이행관계에 있는 잔대금지급의무의 이행제공을 하여야 한다.","ox":"X","m":"③","c":"A","tp":"甲은 자신이 소유하는 토지를 乙에게 매도하고 중도금까지 받았는데, 乙에게 그 토지"},{"y":2018,"e":"변리사 1차","qn":33,"i":"변리사2018_55-33-4","t":"만약 丙이 아직 甲에게 매매대금을 지급하지 않았다면, 乙은 甲과의 계약을 해제하지 않고 丙을 상대로 甲에게 지급할 매매대금을 자신에게 대상(代償)으로 지급하라고 청구할 수 있다.","ox":"X","m":"④","c":"A","tp":"甲은 자신이 소유하는 토지를 乙에게 매도하고 중도금까지 받았는데, 乙에게 그 토지"},{"y":2018,"e":"변리사 1차","qn":33,"i":"변리사2018_55-33-5","t":"만약 丁이 甲의 乙에 대한 채무의 이행을 보증하였고 乙이 甲의 채무불이행을 이유로 계약을 해제하였다면, 丁은 특별한 사정이 없는 한 甲의 乙에 대한 원상회복의무에 대해 책임을 부담한다.","ox":"O","m":"⑤","c":"A","tp":"甲은 자신이 소유하는 토지를 乙에게 매도하고 중도금까지 받았는데, 乙에게 그 토지"},{"y":2018,"e":"변리사 1차","qn":37,"i":"변리사2018_55-37","t":"동시이행의 항변권에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있","c":"A","mc":{"s":"동시이행의 항변권에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있","d":"으면 판례에 따름)\nㄱ. 매매계약을 맺은 후에야 매수인이 등기부상의 매매목적물이 매도인의 소유가 아니라는 것을 알게 되었다면 매수인은 중도금지급을 선이행하 기로 하였더라도 그 지급을 거절할 수 있다.\nㄴ. 임대차계약 종료 후 발생하는, 임차인의 임차목적물반환의무와 임대인의 임차보증금반환의무는 동시이행관계이다.\nㄷ. 임대차계약 해제에 따른 임차인의 목적물반환의무와 임대인의 목적물을 사용수익하게 할 의무불이행에 대한 약정 지연손해배상의무는 특별한 사정이 없는 한 동시이행관계이다.\nㄹ. 채무자의 변제와 채권자의 채권증서반환의무는 동시이행관계이다.\nㅁ. 가압류등기가 있는 부동산의 매매계약에서 매도인의 소유권이전등기 의 무와 아울러 가압류등기의 말소의무도 매수인의 대금지급의무와 동시이행관계이다.\nㅂ. 부동산 매매계약에서 부동산 소유권이전등기의무뿐만 아니라 그 인도의 무도 대금지급의무와 동시이행관계이다.","o":["ㄱ, ㄴ","ㄴ, ㄷ","ㄱ, ㄴ, ㅁ, ㅂ","ㄱ, ㄷ, ㄹ, ㅁ","ㄴ, ㄷ, ㅁ, ㅂ"],"a":3}},{"y":2018,"e":"변리사 1차","qn":40,"i":"변리사2018_55-40","t":"계약해제에 관한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"계약해제에 관한 설명으로 옳지 않은 것은?","d":"","o":["해제권자가 그 상대방으로부터 인도받은 목적물을 자신의 과실(過失)로 인해 반환할 수 없게 된 경우에 그 해제권은 소멸한다.","당사자가 수인인 경우에 적용되는 해제권의 불가분성에 관한 규정(민법 제547 조)에 대해 당사자는 특약으로 그 적용을 배제할 수 있다.","해제권의 행사기간을 정하지 아니한 때에는 상대방은 상당한 기간을 정하여 해 제권행사 여부의 확답을 해제권자에게 최고할 수 있다.","계약에서 위약시의 해제권을 배제하기로 약정하지 않은 경우, 어느 일방에 대한 약정해제권의 유보는 채무불이행으로 인한 법정해제권의 발생에 영향을 주지 않는다.","매수인이 매도인의 채무불이행을 이유로 계약금 반환을 구하는 소를 제기함으로써 계약해제권을 행사하고 그 소장이 송달된 후, 그 소를 취하하고 본래의 매매계약의 이행을 구하는 소를 제기하면 매도인은 매매계약상의 의무를 이행하여야 한다. 함께해요! 청렴실천 만들어요! 청렴문화"],"a":5}},{"y":2019,"e":"변리사 1차","qn":33,"i":"변리사2019_56-33-1","t":"계약금의 일부만 지급된 경우, 수령자는 실제 지급된 계약금이 아니라 약정계약금의 배액을 상환하고 계약을 해제할 수 있다.","ox":"O","m":"①","c":"A","tp":"해약금 규정(민법 제565조)에 의하여 계약을 해제하는 경우"},{"y":2019,"e":"변리사 1차","qn":33,"i":"변리사2019_56-33-2","t":"계약당사자 일방이 채무의 이행기 전에 이미 채무의 이행에 착수하였다면 특별한 사정이 없는 한 계약당사자는 해제권을 행사할 수 없다.","ox":"O","m":"②","c":"A","tp":"해약금 규정(민법 제565조)에 의하여 계약을 해제하는 경우"},{"y":2019,"e":"변리사 1차","qn":33,"i":"변리사2019_56-33-3","t":"계약당사자가 계약금에 기한 해제권을 배제하기로 하는 약정을 하였다면, 각 당사자는 해제권을 행사할 수 없다.","ox":"O","m":"③","c":"A","tp":"해약금 규정(민법 제565조)에 의하여 계약을 해제하는 경우"},{"y":2019,"e":"변리사 1차","qn":33,"i":"변리사2019_56-33-4","t":"계약금을 수령한 매도인이 매수인에 대하여 해제권을 행사하기 위해서는 수령한 계약 금의 배액의 이행제공을 하여야 하며 매수인이 수령을 거부하는 경우, 이를 공탁하여야 한다.","ox":"X","m":"④","c":"A","tp":"해약금 규정(민법 제565조)에 의하여 계약을 해제하는 경우"},{"y":2019,"e":"변리사 1차","qn":33,"i":"변리사2019_56-33-5","t":"토지거래허가구역 내의 토지에 관한 매매계약의 당사자가 토지거래허가신청절차의 협력의무를 이행하여 관할관청으로부터 거래허가를 받았더라도, 그러한 사정만으로는 아직 이행의 착수가 있다고 볼 수 없다.","ox":"O","m":"⑤","c":"A","tp":"해약금 규정(민법 제565조)에 의하여 계약을 해제하는 경우"},{"y":2019,"e":"변리사 1차","qn":34,"i":"변리사2019_56-34-1","t":"甲은 乙이 발송한 편지를 2018. 9. 19. 받았는데, 甲이 2018. 9. 24. 개봉하여 읽었다면 매매계약은 2018. 9. 24. 성립한다.","ox":"X","m":"①","c":"A"},{"y":2019,"e":"변리사 1차","qn":34,"i":"변리사2019_56-34-2","t":"乙이 승낙의 의사표시를 하였으므로, 乙이 발송한 편지를 甲이 2018. 9. 25.까지 받지 못하였더라도 매매계약은 성립한다.","ox":"X","m":"②","c":"A"},{"y":2019,"e":"변리사 1차","qn":34,"i":"변리사2019_56-34-3","t":"甲은 乙이 발송한 편지를 2018. 9. 20. 받았다면, 매매계약은 그 때부터 성립하고 효력이 발생한다.","ox":"X","m":"③","c":"A"},{"y":2019,"e":"변리사 1차","qn":34,"i":"변리사2019_56-34-4","t":"乙이 발송한 편지가 2018. 9. 26. 甲에게 도달하였고 甲이 2018. 9. 27. 연착의 통지를한 경우, 매매계약은 성립하지 않는다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"변리사 1차","qn":34,"i":"변리사2019_56-34-5","t":"乙이 2018. 9. 17. 매수하겠다는 편지를 발송하기 전까지 특별한 사정이 없는 한 甲은 乙에 대하여 매각의 의사표시를 철회할 수 있다.","ox":"X","m":"⑤","c":"A"},{"y":2019,"e":"변리사 1차","qn":35,"i":"변리사2019_56-35-1","t":"근저당권 실행을 위한 경매가 무효로 된 경우, 매수인의 채무자에 대한 소유권이전등기 말소의무와 근저당권자의 매수인에 대한 배당금반환의무는 동시이행관계에 있다.","ox":"X","m":"①","c":"A","tp":"동시이행의 항변권"},{"y":2019,"e":"변리사 1차","qn":35,"i":"변리사2019_56-35-2","t":"동시이행관계에 있는 쌍방의 채무 중 어느 한 채무가 이행불능이 됨으로 인하여 발생한 손해배상채무는 다른 채무와 동시이행관계에 있지 않다.","ox":"X","m":"②","c":"A","tp":"동시이행의 항변권"},{"y":2019,"e":"변리사 1차","qn":35,"i":"변리사2019_56-35-3","t":"가압류등기가 있는 부동산 매매계약의 경우, 특별한 사정이 없는 한 매도인의 가압류 등기의 말소의무는 매수인의 대금지급의무와 동시이행관계에 있지 않다.","ox":"X","m":"③","c":"A","tp":"동시이행의 항변권"},{"y":2019,"e":"변리사 1차","qn":35,"i":"변리사2019_56-35-4","t":"쌍방의 채무가 동시이행관계에 있는 경우, 상대방 채무의 이행제공이 없더라도 채무자가 이행기에 채무를 이행하지 않으면 이행지체의 책임을 진다.","ox":"X","m":"④","c":"A","tp":"동시이행의 항변권"},{"y":2019,"e":"변리사 1차","qn":35,"i":"변리사2019_56-35-5","t":"부동산 매매계약에서 매수인이 부가가치세를 부담하기로 약정한 경우, 특별한 사정이 없는 한 부가가치세를 포함한 매매대금 전부와 부동산 소유권이전등기의무가 동시이행관계에 있다.","ox":"O","m":"⑤","c":"A","tp":"동시이행의 항변권"},{"y":2019,"e":"변리사 1차","qn":36,"i":"변리사2019_56-36","t":"계약의 합의해제 등에 관한 설명으로 옳지 않은 것은? (다툼이 있으면 판례에","c":"A","mc":{"s":"계약의 합의해제 등에 관한 설명으로 옳지 않은 것은? (다툼이 있으면 판례에","d":"따름)","o":["계약이 합의해제된 경우, 특별한 사정이 없는 한 채무불이행으로 인한 손해배상청구는할 수 없다.","매도인이 매수인에게 매매계약의 합의해제를 청약하였더라도 매수인이 그 청약에 대하여 조건을 붙여 승낙한 경우, 매도인의 청약은 실효된다.","계약이 일부이행된 경우, 그 원상회복에 관하여 의사가 일치되지 않아도 계약의 묵시적 합의해제가 인정될 수 있다.","매매계약을 합의해제한 후 그 합의해제를 무효화시키고, 해제된 매매계약을 부활시키는 약정은 적어도 당사자 사이에서는 가능하다.","당사자 사이에 약정이 없는 이상 합의해지로 인하여 반환할 금전에 그 받은 날로부터 이자를 붙여서 반환할 의무는 없다."],"a":3}},{"y":2021,"e":"변리사 1차","qn":33,"i":"변리사2021_58-33","t":"甲은 자신 소유의 X노트북을 乙에게 매도하면서 그 대금은 乙이 甲의 채권자 丙에게 직접 지급하기로 하는 제3자를 위한 계약을 체결하였고, 丙은 乙에게 수익의 의사를 표시하였다. 이에 관한 설명으로 옳지 않은 것은? (다툼이 있으면 판례에","c":"A","mc":{"s":"甲은 자신 소유의 X노트북을 乙에게 매도하면서 그 대금은 乙이 甲의 채권자 丙에게 직접 지급하기로 하는 제3자를 위한 계약을 체결하였고, 丙은 乙에게 수익의 의사를 표시하였다. 이에 관한 설명으로 옳지 않은 것은? (다툼이 있으면 판례에","d":"따름)","o":["甲과 乙이 미리 매매계약에서 丙의 권리를 변경․소멸할 수 있음을 유보한 경우, 이 러한 약정은 丙에 대해서도 효력이 있다.","甲은 丙의 동의가 없는 한 乙의 채무불이행을 이유로 계약을 해제할 수 없다.","제3자를 위한 계약의 체결 원인이 된 甲과 丙 사이의 법률관계가 취소된 경우, 특별한 사정이 없는 한 乙은 丙에게 대금지급을 거절할 수 없다.","乙의 채무불이행을 이유로 甲이 계약을 해제한 경우, 丙은 乙에게 자기가 입은 손해에 대한 배상을 청구할 수 있다.","甲과 乙의 매매계약이 취소된 경우, 乙이 丙에게 이미 매매대금을 지급하였다고 하더라도 특별한 사정이 없는 한 乙은 丙을 상대로 부당이득반환청구를 할 수 없다."],"a":2}},{"y":2021,"e":"변리사 1차","qn":34,"i":"변리사2021_58-34-1","t":"계약의 당사자가 누구인지는 계약에 관여한 당사자의 의사해석 문제로서, 당사자들의 의사가 일치하는 경우에는 그 의사에 따라 계약의 당사자를 확정해야 한다.","ox":"O","m":"①","c":"A","tp":"계약의 성립"},{"y":2021,"e":"변리사 1차","qn":34,"i":"변리사2021_58-34-2","t":"임대차계약에서 보증금의 지급약정이 있는 경우, 보증금의 수수는 임대차계약의 성립 요건이 아니다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"변리사 1차","qn":34,"i":"변리사2021_58-34-3","t":"계약이 의사의 불합치로 성립하지 아니한 경우, 그로 인하여 손해를 입은 당사자는 상대방에 대하여 민법 제535조(계약체결상의 과실)를 유추적용하여 손해배상을 청구할 수 있다.","ox":"X","m":"③","c":"A","tp":"계약의 성립"},{"y":2021,"e":"변리사 1차","qn":34,"i":"변리사2021_58-34-4","t":"매매계약체결 당시 목적물과 대금이 구체적으로 확정되지 않았더라도, 이행기 전까지 구체적으로 확정될 수 있는 방법과 기준이 정해져 있다면 계약의 성립을 인정할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"변리사 1차","qn":34,"i":"변리사2021_58-34-5","t":"청약자의 의사표시나 관습에 의해 승낙의 통지가 필요하지 않은 경우, 계약은 승낙의 의사표시로 인정되는 사실이 있는 때에 성립한다.","ox":"O","m":"⑤","c":"A","tp":"계약의 성립"},{"y":2021,"e":"변리사 1차","qn":35,"i":"변리사2021_58-35-1","t":"부동산 매매계약에서 매수인이 부가가치세를 부담하기로 약정한 경우, 특별한 사정이 없는 한 부가가치세를 포함한 매매대금 전부와 부동산의 소유권이전등기의무는 동시이행관계에 있다.","ox":"O","m":"①","c":"A","tp":"동시이행의 항변권"},{"y":2021,"e":"변리사 1차","qn":35,"i":"변리사2021_58-35-2","t":"공사도급계약상 도급인의 지체상금채권과 수급인의 공사대금채권은 특별한 사정이 없는 한 동시이행관계에 있다고 할 수 없다.","ox":"O","m":"②","c":"A","tp":"동시이행의 항변권"},{"y":2021,"e":"변리사 1차","qn":35,"i":"변리사2021_58-35-3","t":"구분소유적 공유관계가 전부 해소된 경우, 공유지분권자 상호간의 지분이전등기의무는 동시이행의 관계에 있다.","ox":"O","m":"③","c":"A","tp":"동시이행의 항변권"},{"y":2021,"e":"변리사 1차","qn":35,"i":"변리사2021_58-35-4","t":"원인채무의 지급을 담보하기 위하여 어음이 교부된 경우, 채무자는 어음반환과 동시이행을 주장하여 원인채무의 지급을 거절할 수는 없다.","ox":"X","m":"④","c":"A","tp":"동시이행의 항변권"},{"y":2021,"e":"변리사 1차","qn":35,"i":"변리사2021_58-35-5","t":"동시이행의 관계에 있는 쌍방의 채무 중 어느 한 채무가 이행불능이 됨으로 인하여 발생한 손해배상채무도 여전히 다른 채무와 동시이행의 관계에 있다.","ox":"O","m":"⑤","c":"A","tp":"동시이행의 항변권"},{"y":2021,"e":"변리사 1차","qn":36,"i":"변리사2021_58-36-1","t":"甲과 乙이 계약해제로 인한 원상회복의무로 반환할 매매대금에 가산할 이자를 4%로 약정한 경우, 동 약정이율은 매매대금 반환의무의 이행지체로 인한 지연손해금률에도 적용된다.","ox":"X","m":"①","c":"A"},{"y":2021,"e":"변리사 1차","qn":36,"i":"변리사2021_58-36-2","t":"甲이 乙의 채무불이행을 이유로 매매계약을 해제한 후에도 乙은 착오를 이유로 매매계약을 취소할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"변리사 1차","qn":36,"i":"변리사2021_58-36-3","t":"乙 명의로 소유권이전등기가 경료된 X토지에 대하여 乙의 채권자 丙이 가압류 집행을 마쳐둔 경우, 甲은 丙에 대하여 乙의 채무불이행을 이유로 한 해제의 소급효를 주장할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"변리사 1차","qn":36,"i":"변리사2021_58-36-4","t":"甲이 乙의 채무불이행에 관하여 원인의 일부를 제공하였다고 하더라도 乙이 이를 이유로 甲의 계약해제에 따른 원상회복청구에 대하여 과실상계하는 것은 인정되지 않는다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"변리사 1차","qn":36,"i":"변리사2021_58-36-5","t":"乙이 중도금을 약정된 기일에 지급하지 않으면 최고 없이 계약은 자동적으로 해제되는 것으로 약정한 경우, 특별한 사정이 없는 한 그 불이행이 있으면 계약은 자동적으로 해제된다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"변리사 1차","qn":33,"i":"변리사2023_60-33","t":"동시이행관계가 인정되는 것을 모두 고른 것은? (특별한 사정이 없고, 다툼이 있","c":"A","mc":{"s":"동시이행관계가 인정되는 것을 모두 고른 것은? (특별한 사정이 없고, 다툼이 있","d":"으면 판례에 따름)\nㄱ. 매매계약상 매도인의 소유권이전의무가 이행불능이 되어 생긴 손해배상채 무와 매수인의 대금지급채무ㄴ. 매매계약상 매도인의 소유권이전의무와 매수인의 대금지급의무 중 어느 하 나를 선이행의무로 약정한 경우, 각 의무의 이행기가 모두 지난 후의 쌍방의 의무ㄷ. 근저당권 실행을 위한 경매가 무효로 되어 근저당권자가 채무자인 소유자 를 대위하여 낙찰자에 대한 소유권이전등기말소청구권을 행사하는 경우, 낙찰자의 소유권이전등기말소의무와 근저당권자의 배당금반환의무","o":["ㄱ","ㄴ","ㄱ, ㄴ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":3}},{"y":2023,"e":"변리사 1차","qn":34,"i":"변리사2023_60-34-1","t":"요약자는 원칙적으로 제3자의 권리와 별도로 낙약자에 대하여 제3자에게 급부를 이행할 것을 요구할 수 있는 권리를 가진다.","ox":"O","m":"①","c":"A","tp":"제3자를 위한 계약"},{"y":2023,"e":"변리사 1차","qn":34,"i":"변리사2023_60-34-2","t":"제3자가 수익의 의사표시를 한 경우, 계약의 당사자가 제3자의 권리를 임의로 변경\u0001소멸시키는 행위를 하더라도 특별한 사정이 없는 한 제3자에 대하여 효력이 없다.","ox":"O","m":"②","c":"A","tp":"제3자를 위한 계약"},{"y":2023,"e":"변리사 1차","qn":34,"i":"변리사2023_60-34-3","t":"요약자와 수익자 사이의 법률관계(대가관계)의 효력 상실을 이유로 요약자는 낙약자와 요약자 사이의 법률관계(기본관계)상 낙약자에게 부담하는 채무의 이행을 거절할 수 있다.","ox":"X","m":"③","c":"A","tp":"제3자를 위한 계약"},{"y":2023,"e":"변리사 1차","qn":34,"i":"변리사2023_60-34-4","t":"채무자와 인수인 사이의 계약으로 체결되는 중첩적 채무인수의 경우, 채권자의 수익의 의사표시는 그 계약의 성립요건 또는 효력발생요건이 아니다.","ox":"O","m":"④","c":"A","tp":"제3자를 위한 계약"},{"y":2023,"e":"변리사 1차","qn":34,"i":"변리사2023_60-34-5","t":"낙약자와 요약자 사이의 계약(기본관계)이 무효가 된 경우, 낙약자는 특별한 사정이 없는 한 제3자를 상대로 그가 제3자에게 한 급부를 부당이득으로 반환 청구할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"제3자를 위한 계약"},{"y":2023,"e":"변리사 1차","qn":35,"i":"변리사2023_60-35-1","t":"타인 권리의 매매로 인한 담보책임으로 매수인이 계약을 해제한 경우, 매수인이 진정한 권리자인 타인에게 직접 목적물을 반환한 때에는 그 반환한 범위에서 매도인에게 반환할 의무를 부담하지 않는다.","ox":"O","m":"①","c":"A","tp":"계약의 해제, 해지"},{"y":2023,"e":"변리사 1차","qn":35,"i":"변리사2023_60-35-2","t":"사정변경을 이유로 한 계약의 해제나 해지에서 사정변경에 대한 예견가능성이 있었는 지는 개별적 사정을 고려하지 않고 추상적\u0001일반적으로 판단하여야 한다.","ox":"X","m":"②","c":"A","tp":"계약의 해제, 해지"},{"y":2023,"e":"변리사 1차","qn":35,"i":"변리사2023_60-35-3","t":"매수인의 사망으로 매수인의 지위를 상속한 상속인들이 매매계약을 해제하려면, 특별한 사정이 없는 한 전원이 해제의 의사표시를 하여야 한다.","ox":"O","m":"③","c":"A","tp":"계약의 해제, 해지"},{"y":2023,"e":"변리사 1차","qn":35,"i":"변리사2023_60-35-4","t":"조합계약에서는 계약을 해제 또는 해지하고 조합원에게 그로 인한 원상회복의 의무를 부담지울 수는 없다.","ox":"O","m":"④","c":"A","tp":"계약의 해제, 해지"},{"y":2023,"e":"변리사 1차","qn":35,"i":"변리사2023_60-35-5","t":"계약이 합의에 따라 해제되거나 해지된 경우, 특별한 사정이 없는 한 채무불이행으로 인한 손해배상을 청구할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"계약의 해제, 해지"},{"y":2024,"e":"변리사 1차","qn":33,"i":"변리사2024_61-33-1","t":"의사표시의 불일치로 인해 계약이 성립하지 않는 경우, 그로 인해 손해를 입은 당사자는 상대방이 계약의 불성립을 알았거나 알 수 있었음을 이유로 계약체결상의 과실로 인한 손해배상을 청구할 수 있다.","ox":"X","m":"①","c":"A","tp":"계약의 성립"},{"y":2024,"e":"변리사 1차","qn":33,"i":"변리사2024_61-33-2","t":"은행 직원이 예금자로부터 돈을 받아 확인한 후에는 실제로 입금하지 않아도 예금자와 은행 사이에 예금계약이 성립한다.","ox":"O","m":"②","c":"A","tp":"계약의 성립"},{"y":2024,"e":"변리사 1차","qn":33,"i":"변리사2024_61-33-3","t":"甲이 자신의 X건물을 乙에게 1억 원에 팔겠다는 청약을 하였는데, 이 사실을 모르는 乙이 甲에게 X건물을 1억 원에 구입하겠다고 청약을 한 경우에 두 청약이 상대방에게 도달한 때에 계약은 성립한다.","ox":"O","m":"③","c":"A","tp":"계약의 성립"},{"y":2024,"e":"변리사 1차","qn":33,"i":"변리사2024_61-33-4","t":"매도인이 매수인에게 매매계약의 합의해제를 청약하였는데, 매수인이 그 청약에 대하여 조건을 붙여 승낙한 경우에는 합의해제의 청약이 실효된다.","ox":"O","m":"④","c":"A","tp":"계약의 성립"},{"y":2024,"e":"변리사 1차","qn":33,"i":"변리사2024_61-33-5","t":"임대인이 임대목적물에 대한 소유권 기타 이를 임대할 권한이 없다고 하더라도 임대차계약은 유효하게 성립할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"계약의 성립"},{"y":2024,"e":"변리사 1차","qn":34,"i":"변리사2024_61-34-1","t":"乙의 과실로 도자기가 멸실된 경우, 甲은 도자기 이전의무를 면하면서 얻은 이익이 있더라도 이를 乙에게 상환할 필요는 없다.","ox":"X","m":"①","c":"A"},{"y":2024,"e":"변리사 1차","qn":34,"i":"변리사2024_61-34-2","t":"도자기가 2024. 2. 20. 지진으로 멸실된 경우, 甲은 乙에게 매매대금의 지급을 청구할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"변리사 1차","qn":34,"i":"변리사2024_61-34-3","t":"乙이 계약체결 당시 甲에게 매매대금을 지급하였는데, 도자기가 2024. 2. 20. 지진으로 멸실된 경우에 乙은 甲에게 부당이득반환을 청구할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"변리사 1차","qn":34,"i":"변리사2024_61-34-4","t":"乙의 과실로 도자기가 멸실된 경우, 甲은 乙에게 매매대금의 지급을 청구할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"변리사 1차","qn":34,"i":"변리사2024_61-34-5","t":"乙의 수령지체 중에 지진으로 도자기가 멸실된 경우, 甲은 乙에게 매매대금의 지급을 청구할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"변리사 1차","qn":25,"i":"변리사2026_63-25-1","t":"甲에게 乙과의 위 매매계약에 관한 적법한 해제권이 발생하였다면 이후 甲의 과실로 X토지가 현저히 훼손되었더라도 甲의 해제권은 소멸하지 않는다.","ox":"X","m":"①","c":"A","tp":"甲은 그 소유의 X토지에 관하여 乙과 매매계약을 체결하였다. 계약의 해제"},{"y":2026,"e":"변리사 1차","qn":25,"i":"변리사2026_63-25-2","t":"X토지가 토지거래허가구역내의 토지이고 甲과 乙의 매매계약이 주무관청의 허가를 받지 않아 유동적 무효의 상태에 있는 경우, 甲은 乙의 채무불이행을 이유로 위 매매계약을 해제할 수 있다.","ox":"X","m":"②","c":"A","tp":"甲은 그 소유의 X토지에 관하여 乙과 매매계약을 체결하였다. 계약의 해제"},{"y":2026,"e":"변리사 1차","qn":25,"i":"변리사2026_63-25-3","t":"甲의 해제권 행사가 있기 이전에 乙이 丙에게 X토지를 처분함으로써 이후 甲의 해제권 행사에 따른 乙의 원물반환이 불가능하게 된 경우, 乙이 甲에게 원상회복의무로써 반환하여야 할 금액은 甲의 해제권 행사 당시의 목적물의 대가이다.","ox":"X","m":"③","c":"A","tp":"甲은 그 소유의 X토지에 관하여 乙과 매매계약을 체결하였다. 계약의 해제"},{"y":2026,"e":"변리사 1차","qn":25,"i":"변리사2026_63-25-4","t":"계약해제로 인한 원상회복의무가 이행지체에 빠진 이후의 지연손해금률에 관하여 약정이 있는 경우, 그 지연손해금률이 법정이율보다 낮더라도 약정에 따른 지연손해금률이 적용된다.","ox":"O","m":"④","c":"A","tp":"甲은 그 소유의 X토지에 관하여 乙과 매매계약을 체결하였다. 계약의 해제"},{"y":2026,"e":"변리사 1차","qn":25,"i":"변리사2026_63-25-5","t":"乙이 甲에 대한 X토지의 소유권이전등기청구권을 丁에게 양도하고 이를 甲에게 통지한 후 甲과 乙의 매매계약이 해제된 경우, 특별한 사정이 없는 한 丁은 민법 제548조 제1항 단서에 의해 보호되는 제3자에 해당한다.","ox":"X","m":"⑤","c":"A","tp":"甲은 그 소유의 X토지에 관하여 乙과 매매계약을 체결하였다. 계약의 해제"},{"y":2026,"e":"변리사 1차","qn":34,"i":"변리사2026_63-34","t":"동시이행관계에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면 판례에","c":"A","mc":{"s":"동시이행관계에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면 판례에","d":"따름)\nㄱ. 저당권이 설정된 부동산의 매매계약을 체결하면서 매수인이 그 저당권의 피담보 채무를 이행인수하기로 약정한 경우, 매수인의 인수채무불이행으로 인한 손해배상채무와 매도인의 소유권이전등기의무는 동시이행관계에 있다.\nㄴ. 임대차계약을 체결하면서 임대차보증금을 전세금으로 하는 전세권설정등기를 경료한 경우, 임대차보증금 반환의무와 전세권설정등기 말소의무는 동시이행관계에 있다.\nㄷ. 가압류등기가 있는 부동산의 매매계약에서 매도인의 소유권이전등기의무 및 가압류등기의 말소의무는 매수인의 대금지급의무와 동시이행관계에 있다.","o":["ㄴ","ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":5}},{"y":2026,"e":"변리사 1차","qn":35,"i":"변리사2026_63-35-1","t":"丙이 수익의 의사표시를 한 후, 甲과 乙이 丙의 권리를 임의로 소멸시키는 약정을 하더라도 특별한 사정이 없는 한 丙에 대하여는 그 효력이 없다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"변리사 1차","qn":35,"i":"변리사2026_63-35-2","t":"丙은 乙에게 의사표시의 흠결이 있었다 하더라도 특별한 사정이 없는 한 이를 이유로 매매계약을 취소할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"변리사 1차","qn":35,"i":"변리사2026_63-35-3","t":"丙이 수익의 의사표시를 한 이후라도 甲은 丙의 동의 없이 乙의 채무불이행을 이유로 매매계약을 해제할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"변리사 1차","qn":35,"i":"변리사2026_63-35-4","t":"丙의 甲에 대한 대여금채권이 소멸한 경우, 乙은 이를 이유로 丙에게 매매대금의 지급을 거절할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2026,"e":"변리사 1차","qn":35,"i":"변리사2026_63-35-5","t":"乙이 丙에게 매매대금을 지급한 후 매매계약이 해제된 경우, 특별한 사정이 없는 한乙은 계약해제에 기한 원상회복을 원인으로 丙에게 그 반환을 청구할 수 없다.","ox":"O","m":"⑤","c":"A"}],"10":[{"y":2016,"e":"변리사 1차","qn":34,"i":"변리사2016_53-34-1","t":"乙이 丙에 대하여 채무의 이행을 청구하는 소를 제기하였다가 패소한 경우에도 甲은 丙에 대하여 채권자대위권을 행사할 수 있다.","ox":"X","m":"①","c":"A","tp":"甲이 乙을 대위하여 丙에 대하여 채권자대위권을 행사한 경우"},{"y":2016,"e":"변리사 1차","qn":34,"i":"변리사2016_53-34-2","t":"甲이 丙에 대하여 채권자대위권을 행사한 경우 丙은 甲의 乙에 대한 채권이 시효로 소멸하였음을 주장할 수 있다.","ox":"X","m":"②","c":"A","tp":"甲이 乙을 대위하여 丙에 대하여 채권자대위권을 행사한 경우"},{"y":2016,"e":"변리사 1차","qn":34,"i":"변리사2016_53-34-3","t":"甲이 乙에 대하여 이행청구의 소를 제기하여 승소한 경우에도, 丙은 甲의 채권자 대위권 행사에 대항하여 乙에 대한 甲의 채권이 무효임을 주장할 수 있다.","ox":"X","m":"③","c":"A","tp":"甲이 乙을 대위하여 丙에 대하여 채권자대위권을 행사한 경우"},{"y":2016,"e":"변리사 1차","qn":34,"i":"변리사2016_53-34-4","t":"무자력인 丙이 자신의 채무자인 丁의 채무를 면제함으로써 乙에 대한 관계에서 사해행위를 한 경우, 甲은 丙의 사해행위를 취소하기 위하여 乙의 채권자취소권을 대위할 수 있다.","ox":"O","m":"④","c":"A","tp":"甲이 乙을 대위하여 丙에 대하여 채권자대위권을 행사한 경우"},{"y":2016,"e":"변리사 1차","qn":34,"i":"변리사2016_53-34-5","t":"甲이 채권자대위권을 행사하는 과정에서 비용을 지출하였더라도 甲은 乙에게 그 비용의 상환을 청구할 수 없다.","ox":"X","m":"⑤","c":"A","tp":"甲이 乙을 대위하여 丙에 대하여 채권자대위권을 행사한 경우"},{"y":2017,"e":"변리사 1차","qn":27,"i":"변리사2017_54-27-1","t":"채권자대위소송에서 제3채무자로 하여금 직접 대위채권자에게 금전의 지급을 명하는 판결이 확정된 경우, 피대위채권이 변제 등으로 소멸하기 전이라면 채무자의 다른 채권자가 이를 압류 또는 가압류할 수 있다.","ox":"O","m":"①","c":"A","tp":"채권자대위권"},{"y":2017,"e":"변리사 1차","qn":27,"i":"변리사2017_54-27-2","t":"채권자대위소송에서 제3채무자는 채권자의 채무자에 대한 권리의 발생원인이 된법률행위가 무효라거나 변제 등으로 소멸하였다는 등의 사실을 주장하여 채권자의 채무자에 대한 권리가 인정되는지를 다툴 수 없다.","ox":"X","m":"②","c":"A","tp":"채권자대위권"},{"y":2017,"e":"변리사 1차","qn":27,"i":"변리사2017_54-27-3","t":"토지거래허가구역에 있는 토지의 매수인은 채권보전의 필요성 여부와 무관하게 토지거래허가 신청절차의 협력의무 이행청구권을 보전하기 위하여 매도인의 권리를 대위하여 행사할 수 있다.","ox":"X","m":"③","c":"A","tp":"채권자대위권"},{"y":2017,"e":"변리사 1차","qn":27,"i":"변리사2017_54-27-4","t":"이행인수 약정이 체결된 경우, 채무자는 인수인이 그 채무를 이행하지 아니하면 인수인에 대하여 채권자에게 이행할 것을 청구할 수 있으나, 채무자의 인수인에 대한 위 청구권을 채권자가 대위행사할 수 없다.","ox":"X","m":"④","c":"A","tp":"채권자대위권"},{"y":2017,"e":"변리사 1차","qn":27,"i":"변리사2017_54-27-5","t":"지하도상가 내 점포의 사용청구권을 가지는 자는 상가의 소유자인 시(市)가 불법점유자들에 대하여 가지는 점포의 인도청구권을 대위행사할 수 없다.","ox":"X","m":"⑤","c":"A","tp":"채권자대위권"},{"y":2017,"e":"변리사 1차","qn":28,"i":"변리사2017_54-28-1","t":"채권자가 수익자를 상대로 사해행위 취소 및 원상회복으로 소유권이전등기의 말소를 명하는 판결을 받았으나 말소등기를 마치지 않은 경우, 소송당사자가 아닌 다른 채권자가 위 판결에 따라 채무자를 대위하여 마친 말소등기는 등기절차상의 흠에도 불구하고 실체관계에 부합하는 등기로서 유효하다.","ox":"O","m":"①","c":"A","tp":"채권자취소권"},{"y":2017,"e":"변리사 1차","qn":28,"i":"변리사2017_54-28-2","t":"채권자의 채권이 사해행위 이전에 성립한 이상 사해행위 이후에 양도되었다고 하더라도 양수인의 채권은 채권자취소권의 피보전채권이 될 수 있다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"변리사 1차","qn":28,"i":"변리사2017_54-28-3","t":"주채무의 전액에 관하여 물상보증인의 담보로 채권자의 우선변제권이 확보되어 있다면, 연대보증인이 유일한 재산을 처분하였더라도 사해행위가 되지 않는다.","ox":"O","m":"③","c":"A","tp":"채권자취소권"},{"y":2017,"e":"변리사 1차","qn":28,"i":"변리사2017_54-28-4","t":"채무자의 수익자에 대한 채권양도가 사해행위로 취소되고, 그에 따른 원상회복으로서 제3채무자에게 채권양도가 취소되었다는 취지의 통지가 이루어진 경우, 채권자는 채무자를 대위하여 제3채무자에게 채권에 관한 지급을 청구할 수 있다.","ox":"X","m":"④","c":"A","tp":"채권자취소권"},{"y":2017,"e":"변리사 1차","qn":28,"i":"변리사2017_54-28-5","t":"채권자가 채무자의 채권자취소권을 대위행사하는 경우, 채권자취소권을 대위행사하는 채권자가 취소원인을 안 지 1년이 경과하였다고 하더라도 채무자가 취소 원인을 안 날로부터 1년, 법률행위가 있은 날로부터 5년 내라면 채권자취소의 소를 제기할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"변리사 1차","qn":26,"i":"변리사2018_55-26-1","t":"채무자의 법률행위가 통정허위표시로 무효인 경우에는 채권자취소권의 대상이될 수 없다.","ox":"X","m":"①","c":"A"},{"y":2018,"e":"변리사 1차","qn":26,"i":"변리사2018_55-26-2","t":"매매계약을 원인으로 하는 가등기에 기하여 본등기가 경료된 경우, 사해행위 요건의 구비 여부는 특별한 사정이 없는 한 본등기를 한 시점을 기준으로 판단하여야 한다.","ox":"X","m":"②","c":"A","tp":"채권자취소권"},{"y":2018,"e":"변리사 1차","qn":26,"i":"변리사2018_55-26-3","t":"부동산이 이중(二重)으로 매도되고 제2매수인에게 소유권이전등기가 이루어진 경우, 제1매수인은 자신의 소유권이전등기청구권을 보전하기 위하여, 매도인과 제2매수인 사이에 이루어진 양도행위에 대하여 채권자취소권을 행사할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"변리사 1차","qn":26,"i":"변리사2018_55-26-4","t":"채무자가 저당권이 설정되어 있는 자신의 유일한 재산을 양도한 경우, 저당권의 피담보채권액이 그 재산의 가액을 초과하더라도 당해 재산의 양도는 사해행위에 해당한다.","ox":"X","m":"④","c":"A","tp":"채권자취소권"},{"y":2018,"e":"변리사 1차","qn":26,"i":"변리사2018_55-26-5","t":"채권자가 채무자와 수익자 사이의 부동산매매계약을 사해행위로 취소함에 따라 수익자 명의의 소유권이전등기가 말소되어 채무자의 등기명의가 회복된 경우, 채무자는 그 부동산의 소유권을 제3자에게 유효하게 양도할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"채권자취소권"},{"y":2019,"e":"변리사 1차","qn":29,"i":"변리사2019_56-29-3","t":"토지거래허가신청절차의 협력의무이행청구권도 A채권이 될 수 있다.","ox":"O","m":"③","c":"A","tp":"甲이 乙"},{"y":2019,"e":"변리사 1차","qn":29,"i":"변리사2019_56-29-4","t":"丙은 특별한 사정이 없는 한 甲에 대하여 A채권의 소멸시효가 완성되었음을 항변할 수 없다.","ox":"O","m":"④","c":"A","tp":"甲이 乙"},{"y":2019,"e":"변리사 1차","qn":29,"i":"변리사2019_56-29-5","t":"丙은 甲에 대하여 A채권의 발생원인이 된 법률행위가 무효라는 사실을 주장하여 A 채권의 인정 여부를 다툴 수 있다.","ox":"O","m":"⑤","c":"A","tp":"甲이 乙"},{"y":2019,"e":"변리사 1차","qn":30,"i":"변리사2019_56-30","t":"乙이 유일하게 소유하고 있는 X토지를 丙에게 매도한 후 소유권이전등기를 마쳐 주었고, 甲은 乙에 대한 대여금채권을 보전하기 위하여 丙을 상대로 채권자취소 소송을 제기하여 승소하였다. 이에 관한 설명으로 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"乙이 유일하게 소유하고 있는 X토지를 丙에게 매도한 후 소유권이전등기를 마쳐 주었고, 甲은 乙에 대한 대여금채권을 보전하기 위하여 丙을 상대로 채권자취소 소송을 제기하여 승소하였다. 이에 관한 설명으로 옳은 것을 모두 고른 것은?","d":"(다툼이 있으면 판례에 따름)\nㄱ. 채권자취소소송의 확정판결에 따라 丙 명의의 소유권이전등기가 말소 되면 乙은 소유권이전등기명의의 회복으로 X토지의 소유권을 취득한다.\nㄴ. 甲의 대여금채권이 乙과 丙 사이의 매매계약 전에 성립되었다면 그 액수나 범위가 구체적으로 확정되지 않아도 피보전채권이 된다.\nㄷ. 甲이 사해행위의 취소만을 먼저 구한 다음 원상회복을 나중에 청구하는 경우, 사해행위취소청구가 채권자취소권의 행사기간 내에 제기되었다면 원상회복청구는 그 기간이 지난 뒤에도 할 수 있다.\nㄹ. 채권자취소소송의 확정판결에 따라 丙 명의의 소유권이전등기가 말소된 후, 乙이 회복된 소유권이전등기명의를 기화로 丁에게 X토지를 매도하고 소유권이전등기를 마쳐준 경우, 사해행위취소와 원상회복의 효력을 받는 乙의 다른 일반채권자 戊는 丁을 상대로 소유권이전등기말소를 청구할 수 없다.","o":["ㄱ, ㄷ","ㄴ, ㄷ","ㄷ, ㄹ","ㄱ, ㄴ, ㄹ","ㄴ, ㄷ, ㄹ"],"a":2}},{"y":2021,"e":"변리사 1차","qn":32,"i":"변리사2021_58-32-1","t":"甲이 乙을 상대로 위 대여금채무의 이행청구소송을 제기하였으나 2020. 9. 1. 원고패 소로 확정된 경우, 甲의 사해행위취소청구는 인용될 수 없다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"변리사 1차","qn":32,"i":"변리사2021_58-32-2","t":"乙이 2020. 9. 1. 甲의 위 대여금채권에 대한 담보로 그 소유의 X부동산에 저당권설정등기를 한 경우, 우선변제적 효력이 미치는 범위 내에서는 甲의 채권자취소권 행사도 허용되지 않는다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"변리사 1차","qn":32,"i":"변리사2021_58-32-3","t":"甲이 위 대여금채권에 기해 2021. 1. 3. 乙 소유의 X부동산에 가압류를 한 후 乙은 丁의 丙에 대한 채무를 담보하기 위해 X부동산에 대하여 2021. 1. 15. 丙과 저당권설정계 약을 체결하고 저당권설정등기를 마쳐준 경우, 甲은 채권자취소권을 행사할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"변리사 1차","qn":32,"i":"변리사2021_58-32-4","t":"乙이 2020. 10. 3. 그 소유 X부동산(시가 6,000만 원)과 Y부동산(시가 4,000만 원)에 丁에 대한 3,000만 원의 피담보채무를 담보하기 위해 공동저당권을 설정한 후, 2021. 1. 15. 丙에게 X부동산을 매도하고 당일 소유권이전등기를 마친 경우, 4,200만 원의 범위 내에서 사해행위가 성립한다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"변리사 1차","qn":32,"i":"변리사2021_58-32-5","t":"乙의 채권자 戊가 2020. 12. 3. 乙 소유의 X부동산을 가압류한 상태에서, 2021. 1. 15. 乙로부터 X부동산을 양도받은 丙이 乙의 戊에 대한 가압류채무를 변제한 경우, X부 동산의 양도계약이 사해행위로 취소되면 丙은 특별한 사정이 없는 한 甲에게 가액반 환을 하여야 하고, 위 변제액을 공제하여야 한다.","ox":"X","m":"⑤","c":"A"},{"y":2023,"e":"변리사 1차","qn":26,"i":"변리사2023_60-26-1","t":"채권자는 피보전채권의 변제기 전에 채권자대위권을 행사해서 피대위채권의 시효중단을 위한 이행청구를 하지 못한다.","ox":"X","m":"①","c":"A"},{"y":2023,"e":"변리사 1차","qn":26,"i":"변리사2023_60-26-2","t":"임대인의 동의없는 임차권의 양도는 당사자 사이에서는 유효하므로 임차권의 양수인은 임대인의 권한을 대위 행사할 수 있다.","ox":"X","m":"②","c":"A","tp":"채권자대위권"},{"y":2023,"e":"변리사 1차","qn":26,"i":"변리사2023_60-26-3","t":"조합원이 조합을 탈퇴할 권리는 일신전속적 권리가 아니므로, 특별한 사정이 없는 한피대위권리가 될 수 있다.","ox":"O","m":"③","c":"A","tp":"채권자대위권"},{"y":2023,"e":"변리사 1차","qn":26,"i":"변리사2023_60-26-4","t":"채권자가 채무자의 토지 소유권이전등기청구권을 대위행사한 후 이를 채무자에게 통지한 경우, 채무자가 그 토지 소유권을 이전받는 것은 처분권제한에 위배되어 무효이다.","ox":"X","m":"④","c":"A","tp":"채권자대위권"},{"y":2023,"e":"변리사 1차","qn":26,"i":"변리사2023_60-26-5","t":"제3채무자가 직접 대위채권자에게 금전을 지급하도록 하는 채권자대위소송의 판결이 확정된 경우, 대위채권자의 채권자는 대위채권자가 제3채무자로부터 지급받을 권리를 압류할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"채권자대위권"},{"y":2023,"e":"변리사 1차","qn":27,"i":"변리사2023_60-27-1","t":"채권자취소권은 재판상으로만 행사할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"변리사 1차","qn":27,"i":"변리사2023_60-27-2","t":"채권자가 채무자 소유의 부동산에 저당권을 설정받아 채권전액에 대한 우선변제권을 확보하고 있다면, 그 채무의 수탁보증인은 사전구상권을 피보전권리로 하여 채무자의 법률행위를 사해행위로 취소하지 못한다.","ox":"O","m":"②","c":"A","tp":"채권자취소권"},{"y":2023,"e":"변리사 1차","qn":27,"i":"변리사2023_60-27-3","t":"저당권이 설정된 부동산이 사해행위로 양도된 후 그 저당권의 실행으로 양수인인 수 익자에게 배당이 되었다면 취소채권자는 수익자를 상대로 배당금 상당액의 반환을 청구할 수 있다.","ox":"O","m":"③","c":"A","tp":"채권자취소권"},{"y":2023,"e":"변리사 1차","qn":27,"i":"변리사2023_60-27-4","t":"사해행위 취소로 등기명의를 회복한 부동산을 채무자가 제3자에게 처분한 경우, 취소 채권자뿐만 아니라 사해행위 취소와 원상회복의 효력을 받는 채권자도 명의인을 상대로 등기의 말소를 청구할 수 있다.","ox":"O","m":"④","c":"A","tp":"채권자취소권"},{"y":2023,"e":"변리사 1차","qn":27,"i":"변리사2023_60-27-5","t":"취소채권자는 수익자가 사해행위로 취득한 근저당권에 배당된 배당금을 가압류한 수 익자의 채권자에 대하여서도 우선하여 배당을 받을 수 있다.","ox":"X","m":"⑤","c":"A","tp":"채권자취소권"},{"y":2024,"e":"변리사 1차","qn":28,"i":"변리사2024_61-28-1","t":"농지취득자격증명 발급신청권은 채권자대위권의 행사대상이 될 수 있다.","ox":"O","m":"①","c":"A","tp":"책임재산의 보전"},{"y":2024,"e":"변리사 1차","qn":28,"i":"변리사2024_61-28-2","t":"채권자대위권 행사의 효과는 채무자에게 귀속되는 것이므로 채권자대위소송의 제기로 인한 피대위채권의 소멸시효 중단의 효과는 채무자에게 생긴다.","ox":"O","m":"②","c":"A","tp":"책임재산의 보전"},{"y":2024,"e":"변리사 1차","qn":28,"i":"변리사2024_61-28-3","t":"취득시효의 대상인 부동산의 소유자가 취득시효 완성 후에 그 부동산을 처분하여 점유자의 시효취득을 원인으로 한 소유권이전등기청구권이 침해된 경우, 그 점유자는 소유권이전등기청구권의 보전을 위해 채권자취소권을 행사할 수 있다.","ox":"X","m":"③","c":"A","tp":"책임재산의 보전"},{"y":2024,"e":"변리사 1차","qn":28,"i":"변리사2024_61-28-4","t":"채권자는 원칙적으로 자신의 채권액을 초과하여 채권자취소권을 행사할 수 없다.","ox":"O","m":"④","c":"A","tp":"책임재산의 보전"},{"y":2024,"e":"변리사 1차","qn":28,"i":"변리사2024_61-28-5","t":"사해행위에 해당하는지가 문제되는 법률행위가 수익자의 대리인에 의하여 이루어진 때에는 특별한 사정이 없는 한 수익자의 사해의사는 대리인을 표준으로 결정한다.","ox":"O","m":"⑤","c":"A","tp":"책임재산의 보전"},{"y":2026,"e":"변리사 1차","qn":28,"i":"변리사2026_63-28-1","t":"민법상 조합의 조합원이 조합을 탈퇴할 권리는 특별한 사정이 없는 한 피대위권리가될 수 있다.","ox":"O","m":"①","c":"A","tp":"채권자대위권"},{"y":2026,"e":"변리사 1차","qn":28,"i":"변리사2026_63-28-2","t":"이혼으로 인한 재산분할청구권은 협의 또는 심판에 의해 구체적 내용이 형성되기 전에는 특별한 사정이 없는 한 채권자대위권의 목적이 될 수 없다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"변리사 1차","qn":28,"i":"변리사2026_63-28-3","t":"채권자가 자기의 금전채권을 보전하기 위하여 채무자의 금전채권을 대위행사하는 경우, 제3채무자로 하여금 직접 대위채권자 자신에게 이행하도록 청구할 수 있다.","ox":"O","m":"③","c":"A","tp":"채권자대위권"},{"y":2026,"e":"변리사 1차","qn":28,"i":"변리사2026_63-28-4","t":"채권자가 채권자대위권을 행사하는 경우, 수임인의 비용상환청구권에 관한 민법 제688 조를 준용하여 채무자에게 그 비용의 상환을 청구할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"변리사 1차","qn":28,"i":"변리사2026_63-28-5","t":"비법인사단이 총유재산에 관한 권리를 행사하지 않고 있어 비법인사단의 채권자가 그 권리를 대위행사하는 경우에는 사원총회의 결의를 거쳐야 한다.","ox":"X","m":"⑤","c":"A","tp":"채권자대위권"},{"y":2026,"e":"변리사 1차","qn":29,"i":"변리사2026_63-29-1","t":"채권자취소권의 행사로 채무자가 부동산소유명의를 회복한 경우, 채무자가 그 부동산을 제3자에게 처분하였다면 이는 무권리자의 처분으로서 효력이 없다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"변리사 1차","qn":29,"i":"변리사2026_63-29-2","t":"채무자의 재산적 법률행위라 하더라도 채무자의 책임재산이 아닌 재산에 관한 법률행위인 경우에는 채권자취소권의 대상이 될 수 없다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"변리사 1차","qn":29,"i":"변리사2026_63-29-3","t":"사해행위 이전에 성립한 채권이 사해행위 이후에 양도되었다면 그 채권양수인은 채권자취소권을 행사할 수 없다.","ox":"X","m":"③","c":"A"},{"y":2026,"e":"변리사 1차","qn":29,"i":"변리사2026_63-29-4","t":"채권자가 채권자취소권을 행사하는 경우, 사해행위의 취소만을 먼저 청구한 다음 원상회복을 나중에 청구할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"변리사 1차","qn":29,"i":"변리사2026_63-29-5","t":"수익자를 상대로 한 사해행위취소소송에서는 수익자의 선의 여부만이 문제 되고 수익자의 선의에 과실이 있는지 여부는 묻지 않는다.","ox":"O","m":"⑤","c":"A","tp":"채권자취소권"}],"14":[{"y":2016,"e":"변리사 1차","qn":37,"i":"변리사2016_53-37-1","t":"수급인이 재료의 전부 또는 주요부분을 제공한 경우 특약이나 기타 특별한 사정이 없으면 완성된 건물의 소유권은 수급인에게 속한다.","ox":"O","m":"①","c":"A","tp":"도급"},{"y":2016,"e":"변리사 1차","qn":37,"i":"변리사2016_53-37-2","t":"건설공사 도급계약에서 많이 행해지는 지체상금 약정의 법적 성질은 손해배상액의 예정이므로 법원은 이를 감액할 수도 있다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"변리사 1차","qn":37,"i":"변리사2016_53-37-3","t":"제작물공급계약에서 그 제작물이 부대체물인 경우에는 도급에 관한 규정이 적용된다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"변리사 1차","qn":37,"i":"변리사2016_53-37-4","t":"수급인의 하수급인에 대한 하도급 공사대금채무를 인수한 도급인은 수급인의 하수급인에 대한 하자보수청구권 내지 하자에 갈음한 손해배상채권 등에 기한 동시이행의 항변으로 하수급인에게 대항할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"변리사 1차","qn":37,"i":"변리사2016_53-37-5","t":"건축주 사정으로 공사가 중단된 미완성의 건물을 인도받아 완공하였다면, 그 건물이 공사 중단 시점에서 사회통념상 독립한 건물이라고 볼 수 있는 형태와 구조를 갖추고 있었더라도 완공자가 그 건물의 소유권을 원시취득한다.","ox":"X","m":"⑤","c":"A","tp":"도급"},{"y":2016,"e":"변리사 1차","qn":38,"i":"변리사2016_53-38-1","t":"조합원 중에 변제할 자력이 없는 자가 있는 때에는 그 변제할 수 없는 부분에 대해서는 다른 조합원이 출자가액에 비례하여 변제할 책임이 있다.","ox":"X","m":"①","c":"A","tp":"조합계약"},{"y":2016,"e":"변리사 1차","qn":38,"i":"변리사2016_53-38-2","t":"조합이 그 목적을 달성하여 해산된 경우, 별도로 처리할 조합의 잔무가 없고 다만 잔여재산을 분배하는 일만이 남아 있을 때에는 따로 청산절차를 거칠 필요가 없다.","ox":"O","m":"②","c":"A","tp":"조합계약"},{"y":2016,"e":"변리사 1차","qn":38,"i":"변리사2016_53-38-3","t":"조합원 3분의 2 이상의 찬성으로 일부 조합원을 업무집행자로 선임할 수 있지만, 그를 해임하기 위해서는 조합원의 일치된 의사가 있어야 한다.","ox":"O","m":"③","c":"A","tp":"조합계약"},{"y":2016,"e":"변리사 1차","qn":38,"i":"변리사2016_53-38-4","t":"조합의 대표조합원이 그 대표자격을 밝히고 어음상의 서명을 하는 경우에는 그 조합의 대표자격을 밝히기만 하면 유효한 것이며 반드시 어음행위의 본인이 되는 전조합원을 구체적으로 표시할 필요는 없다.","ox":"O","m":"④","c":"A","tp":"조합계약"},{"y":2016,"e":"변리사 1차","qn":38,"i":"변리사2016_53-38-5","t":"동업자들이 공동으로 처리해야 할 업무를 동업자 중 1인에게 그 업무집행을 위임하여 처리하도록 한 경우, 다른 동업자는 그 1인의 업무집행 과정에서 발생한 불법행위에 대해 사용자책임을 진다.","ox":"O","m":"⑤","c":"A","tp":"조합계약"},{"y":2017,"e":"변리사 1차","qn":33,"i":"변리사2017_54-33-1","t":"乙의 차임채무불이행으로 임대차가 종료되어도 乙은 甲에게 Y건물의 매수를 청구할 수 있다.","ox":"X","m":"①","c":"A"},{"y":2017,"e":"변리사 1차","qn":33,"i":"변리사2017_54-33-2","t":"乙이 적법하게 Y건물의 매수를 청구한 경우, 甲의 대금지급의무는 乙의 Y건물 명도 및 소유권이전의무보다 선이행되어야 한다.","ox":"X","m":"②","c":"A"},{"y":2017,"e":"변리사 1차","qn":33,"i":"변리사2017_54-33-3","t":"乙이 Y건물에 대한 보존등기를 마친 후 甲이 丙에게 X토지를 매도하고 소유권이전등기를 마쳐 준 경우, 乙의 임차권이 기간만료로 소멸하면 乙은 丙을 상대로 Y건물의 매수를 청구할 수 없다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"변리사 1차","qn":33,"i":"변리사2017_54-33-4","t":"만약 乙의 채권자 명의로 근저당권이 설정된 Y건물에 대하여 乙이 적법하게 매수청구권을 행사한 경우, 甲은 근저당권이 말소되지 않았음을 이유로 채권최고 액에 상당한 대금의 지급을 거절할 수 없다.","ox":"X","m":"④","c":"A"},{"y":2017,"e":"변리사 1차","qn":33,"i":"변리사2017_54-33-5","t":"만약 Y건물이 미등기 상태에 있더라도 임대차기간이 만료되어 乙이 적법하게 매수청구권을 행사한 경우, Y건물은 그 매수청구의 대상이 될 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"변리사 1차","qn":36,"i":"변리사2017_54-36","t":"甲은 영업공간을 제공하고, 乙과 丙은 각 1억원을 출자하여 A식당을 공동 운영하기로 하는 조합계약을 체결하였다. 다음 설명 중 옳은 것은? (다툼이","c":"A","mc":{"s":"甲은 영업공간을 제공하고, 乙과 丙은 각 1억원을 출자하여 A식당을 공동 운영하기로 하는 조합계약을 체결하였다. 다음 설명 중 옳은 것은? (다툼이","d":"있으면 판례에 따름)","o":["乙이 출자를 지연한 때에는 연체이자를 지급하면 되고, 그 외에 손해까지 배상할 필요는 없다.","乙의 채권자는 특별한 사정이 없는 한, 乙을 집행채무자로 하여 A식당의 채권에 대하여 강제집행을 할 수 있다.","현물을 출자한 甲이 동업에서 탈퇴하게 되면, 甲의 지분은 금전으로 반환할 수 없다.","甲은 동업자로서의 지위를 유지한 채 전체 지분을 제3자에게 처분할 수도 있다.","A식당이 영업이익으로 구입한 부동산에 대하여 합유등기를 하지 않고 甲 명의로 소유권이전등기를 하였다면, 이는 A식당이 甲에게 명의신탁한 것으로 보아야 한다."],"a":5}},{"y":2017,"e":"변리사 1차","qn":39,"i":"변리사2017_54-39","t":"임차인에게 불리한 약정을 하여도 그 효력이 인정되는 것은?","c":"A","mc":{"s":"임차인에게 불리한 약정을 하여도 그 효력이 인정되는 것은?","d":"","o":["토지임차인의 지상물매수청구권","임차인의 비용상환청구권","임차인의 차임감액청구권","임대차기간의 약정이 없는 임차인의 해지통고","임차인의 차임연체로 인한 임대인의 해지권"],"a":2}},{"y":2018,"e":"변리사 1차","qn":34,"i":"변리사2018_55-34-1","t":"건물 임차인은 임대인에게 지급한 보증금의 반환을 위하여 그 임차목적물에 대해 유치권을 주장할 수 없다.","ox":"O","m":"①","c":"A","tp":"임차보증금"},{"y":2018,"e":"변리사 1차","qn":34,"i":"변리사2018_55-34-2","t":"임차인의 차임연체를 이유로 임대차계약이 해지되어, 임대인이 임차목적물의 인도와 연체차임의 지급을 구하는 소송을 제기한 경우 그 소송비용은 특별한 합의가 없는 한 보증금에서 당연히 공제될 수 없다.","ox":"X","m":"②","c":"A","tp":"임차보증금"},{"y":2018,"e":"변리사 1차","qn":34,"i":"변리사2018_55-34-3","t":"임대차계약이 계속되는 동안에 임차인이 차임지급을 연체한 경우, 그 연체차임은 임대인의 별도의 의사표시 없이 보증금에서 당연히 공제되는 것은 아니다.","ox":"O","m":"③","c":"A","tp":"임차보증금"},{"y":2018,"e":"변리사 1차","qn":34,"i":"변리사2018_55-34-4","t":"보증금반환채권에 대해 전부명령이 있은 후, 임대인의 임차인에 대한 연체차임 채권이 발생하였다면 그 전부명령은 임차목적물을 반환할 때까지 임대인의 임차인에 대한 그 채권을 보증금에서 공제한 잔액에 대해서만 효력을 가진다.","ox":"O","m":"④","c":"A","tp":"임차보증금"},{"y":2018,"e":"변리사 1차","qn":34,"i":"변리사2018_55-34-5","t":"임대보증금이 지급된 임대차계약에서 차임채권에 관하여 추심명령이 송달된 경우, 당해 임대차계약이 종료되어 목적물이 반환될 때에는 그 때까지 추심되지 않은 잔존 차임채권 상당액도 임대보증금에서 공제된다.","ox":"O","m":"⑤","c":"A","tp":"임차보증금"},{"y":2018,"e":"변리사 1차","qn":38,"i":"변리사2018_55-38","t":"매도인의 담보책임에 관한 설명으로 옳지 않은 것은? (다툼이 있으면 판례에","c":"A","mc":{"s":"매도인의 담보책임에 관한 설명으로 옳지 않은 것은? (다툼이 있으면 판례에","d":"따름)","o":["甲이 변제기에 도달하지 않은 채권을 乙에게 매도하면서 그 채무자의 자력을 담보한 경우, 甲은 변제기의 자력을 담보한 것으로 추정한다.","甲의 채권자 丙이 甲 소유의 물건에 흠결이 있다는 것을 안 상태에서 담보권 실행을 위한 경매를 신청하였고 乙이 그 물건을 경락받은 경우, 乙은 그 물건에 흠결이 있음을 이유로 丙에게 손해배상을 청구할 수 없다.","매수인 乙이 매도인 甲으로부터 취득한 목적물에 대한 소유권을 제3자의 저당권의 실행으로 잃게 된 경우, 乙은 매매의 목적물에 저당권이 설정되어 있다는 사실을 계약체결 당시에 알고 있었더라도 甲과의 계약을 해제할 수 있다.","매도인 甲이 계약을 체결할 당시에 매매목적물에 대한 소유권이 자신에게 속하지 않는다는 사실을 알지 못하였고, 그 소유권을 취득하여 매수인 乙에게 이전할 수 없는 경우, 甲은 손해를 배상하고 乙과의 계약을 해제할 수 있다.","가압류의 목적이 된 부동산을 甲으로부터 매수한 乙이 그 가압류에 기한 강제집행으로 소유권을 상실하였고, 그로 인해 손해를 입은 경우, 乙은 계약체결 당시에 가압류의 존재를 알고 있었더라도 손해배상을 청구할 수 있다."],"a":2}},{"y":2018,"e":"변리사 1차","qn":39,"i":"변리사2018_55-39-1","t":"매도인이 계약과 동시에 환매할 권리를 보류한 때에는 환매대금은 매도인이 영수한 대금 및 매수인이 부담한 매매비용에 한정되며, 당사자가 특약으로 환매대 금을 다르게 정할 수 없다.","ox":"X","m":"①","c":"A"},{"y":2018,"e":"변리사 1차","qn":39,"i":"변리사2018_55-39-2","t":"당사자가 부동산에 대한 환매기간을 정하지 않은 때에는 그 기간은 5년으로 되며, 이와 달리 환매기간을 정한 때에는 이를 다시 연장하지 못한다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"변리사 1차","qn":39,"i":"변리사2018_55-39-3","t":"환매특약의 실효는 원칙적으로 매매계약의 효력에 영향을 주지 않는다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"변리사 1차","qn":39,"i":"변리사2018_55-39-4","t":"환매의 경우, 특별한 약정이 없으면 목적물의 과실과 대금의 이자는 상계한 것으로 본다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"변리사 1차","qn":39,"i":"변리사2018_55-39-5","t":"부동산 매매계약에서 소유권이전등기와 함께 환매특약에 따라 환매등기가 있은 후, 그 부동산에 제3자의 저당권등기가 마쳐진 경우라도, 매도인이 환매기간 내에 적법하게 환매권을 행사하면 제3자의 저당권은 소멸한다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"변리사 1차","qn":37,"i":"변리사2019_56-37-3","t":"甲과 乙 사이의 임대차계약은 무단전대를 이유로 甲의 해지의 의사표시가 없더라도 해지의 효력이 발생한다.","ox":"X","m":"③","c":"A"},{"y":2019,"e":"변리사 1차","qn":37,"i":"변리사2019_56-37-4","t":"임대차 및 전대차기간 만료시에 丙이 신축한 건물이 X토지에 현존하고 甲이 임대차계약의 갱신을 거절한 경우, 丙은 甲에게 건물매수를 청구할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"변리사 1차","qn":37,"i":"변리사2019_56-37-5","t":"甲과 乙 사이의 임대차계약이 존속하더라도 甲은 X토지의 불법점유를 이유로 丙에게 차임상당의 부당이득반환을 청구할 수 있다.","ox":"X","m":"⑤","c":"A"},{"y":2019,"e":"변리사 1차","qn":39,"i":"변리사2019_56-39-1","t":"조합원은 정당한 사유가 있는 경우에 한하여 조합의 업무 및 재산상태를 검사할 수 있다.","ox":"X","m":"①","c":"A","tp":"민법상 조합"},{"y":2019,"e":"변리사 1차","qn":39,"i":"변리사2019_56-39-2","t":"조합의 존속기간을 정한 때에도 조합원은 부득이한 사유가 있으면 탈퇴할 수 있다.","ox":"O","m":"②","c":"A","tp":"민법상 조합"},{"y":2019,"e":"변리사 1차","qn":39,"i":"변리사2019_56-39-3","t":"조합원의 제명은 정당한 사유가 있는 때에 한하여 다른 조합원 3분의 2 이상의 찬성으로 결정된다.","ox":"X","m":"③","c":"A","tp":"민법상 조합"},{"y":2019,"e":"변리사 1차","qn":39,"i":"변리사2019_56-39-4","t":"조합의 채무자는 그 채무와 조합원에 대하여 개인적으로 가지는 채권과 상계할 수 있다.","ox":"X","m":"④","c":"A","tp":"민법상 조합"},{"y":2019,"e":"변리사 1차","qn":39,"i":"변리사2019_56-39-5","t":"조합원의 제명 결정은 제명된 조합원에게 통지하지 않아도 그 조합원에게 대항할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"민법상 조합"},{"y":2021,"e":"변리사 1차","qn":38,"i":"변리사2021_58-38","t":"甲은 주택을 짓기 위하여 건축업자 乙과 도급계약을 체결하면서 지체상금약정도 하였다. 이에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면 판례에","c":"A","mc":{"s":"甲은 주택을 짓기 위하여 건축업자 乙과 도급계약을 체결하면서 지체상금약정도 하였다. 이에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면 판례에","d":"따름)\nㄱ. 乙에 의해 완공된 주택에 하자가 있어 계약의 목적을 달성할 수 없는 경우라도 甲은 도급계약을 해제할 수 없다.\nㄴ. 乙에 의해 완공된 주택에 발생한 하자가 중요하지 않는데도 그 보수에 과다한 비용이 드는 경우, 甲은 하자보수에 갈음하는 손해배상을 청구할 수 있다.\nㄷ. 지체상금의 종기는 특별한 사정이 없는 한 乙이 공사를 중단하거나 기타 해제사유가 있어 甲이 실제로 해제한 때로부터 甲이 다른 업자에게 의뢰하여 완공할 수 있었던 시점까지로 제한된다.\nㄹ. 예정된 준공기한 전에 도급계약이 해제되어 乙이 공사를 완료하지 아니한 경우에는 특별한 사정이 없는 한 지체상금약정은 적용되지 않는다.","o":["ㄱ, ㄴ","ㄱ, ㄹ","ㄴ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"a":2}},{"y":2021,"e":"변리사 1차","qn":39,"i":"변리사2021_58-39-1","t":"어느 조합원이 출자의무를 이행하지 않은 경우, 다른 조합원은 이를 이유로 조합계약을 해제할 수 있다.","ox":"X","m":"①","c":"A","tp":"민법상 조합"},{"y":2021,"e":"변리사 1차","qn":39,"i":"변리사2021_58-39-2","t":"조합계약이 성립하기 위한 공동사업이란 조합원 전원이 사업의 성공에 대하여 이해관계를 가지는 것으로 일부 조합원만이 이익분배를 받는 관계는 조합이 아니다.","ox":"O","m":"②","c":"A","tp":"민법상 조합"},{"y":2021,"e":"변리사 1차","qn":39,"i":"변리사2021_58-39-3","t":"부동산의 공동매수인들이 전매차익을 얻으려는 목적으로만 상호 협력하는 경우에도 민법상 조합관계에 있다고 볼 수 있다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"변리사 1차","qn":39,"i":"변리사2021_58-39-4","t":"조합원의 채권자는 조합재산을 구성하는 개개의 재산에 대한 조합원의 합유지분에 대하여 강제집행을 할 수 있다.","ox":"X","m":"④","c":"A","tp":"민법상 조합"},{"y":2021,"e":"변리사 1차","qn":39,"i":"변리사2021_58-39-5","t":"조합원이 조합을 탈퇴할 권리는 그 성질상 채권자대위가 허용되지 않는 일신전속적 권리에 해당한다.","ox":"X","m":"⑤","c":"A","tp":"민법상 조합"},{"y":2021,"e":"변리사 1차","qn":40,"i":"변리사2021_58-40-1","t":"수량지정매매에 해당하는 부동산매매계약에서 실제면적이 계약면적에 미달하는 경우, 매수인은 대금감액청구권의 행사와 별도로 부당이득반환청구도 할 수 있다.","ox":"X","m":"①","c":"A","tp":"매도인의 담보책임"},{"y":2021,"e":"변리사 1차","qn":40,"i":"변리사2021_58-40-2","t":"타인의 권리를 매매한 자가 그 권리를 이전할 수 없게 된 경우, 매도인은 선의의 매수인에 대하여 불능 당시의 시가를 표준으로 이행이익을 배상할 의무가 있다.","ox":"O","m":"②","c":"A","tp":"매도인의 담보책임"},{"y":2021,"e":"변리사 1차","qn":40,"i":"변리사2021_58-40-3","t":"매매계약 내용의 중요부분에 착오가 있는 경우, 매수인은 매도인의 하자담보책임이 성립하는지와 상관없이 착오를 이유로 그 매매계약을 취소할 수 있다.","ox":"O","m":"③","c":"A","tp":"매도인의 담보책임"},{"y":2021,"e":"변리사 1차","qn":40,"i":"변리사2021_58-40-4","t":"매수인이 하자의 발생과 확대에 잘못이 있는 경우, 법원은 매도인의 손해배상액을 산정함에 있어 매수인의 과실을 직권으로 참작하여 그 범위를 정해야 한다.","ox":"O","m":"④","c":"A","tp":"매도인의 담보책임"},{"y":2021,"e":"변리사 1차","qn":40,"i":"변리사2021_58-40-5","t":"저당권이 설정된 부동산의 매수인이 저당권의 행사로 그 소유권을 취득할 수 없는 경우, 악의의 매수인이라도 특별한 사정이 없는 한 계약을 해제할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"매도인의 담보책임"},{"y":2023,"e":"변리사 1차","qn":36,"i":"변리사2023_60-36","t":"매매의 일방예약 또는 매매계약에 관한 설명으로 옳지 않은 것은? (다툼이 있으","c":"A","mc":{"s":"매매의 일방예약 또는 매매계약에 관한 설명으로 옳지 않은 것은? (다툼이 있으","d":"면 판례에 따름)","o":["예약완결권을 재판상 행사하는 경우, 소장 부본이 제척기간 내에 상대방에게 송달되 어야만 제척기간 내에 행사한 것으로 본다.","당사자들이 약정한 예약완결권의 행사기간은 그 매매예약이 성립한 때부터 10년을 초과하더라도 무방하다.","매매예약 성립 후 당사자일방의 매매예약 완결권의 행사 전에 상대방의 매매목적물이 멸실된 경우, 매매예약 완결의 의사표시가 있더라도 매매의 효력이 생기지 않는다.","계약이행의 착수가 있기 전에 매도인이 민법 제565조(해약금) 제1항에 따라 계약을 해제하려면, 계약금의 배액을 상환하거나 적어도 이행제공 상태에 두어야 한다.","매수인이 매매목적물을 대금지급 전에 인도받았다면 대금지급의무와 소유권이전등기의무가 동시이행관계에 있더라도 민법 제587조(과실의 귀속, 대금의 이자)에 의한 매매대금이자를 지급할 의무가 있다."],"a":5}},{"y":2023,"e":"변리사 1차","qn":37,"i":"변리사2023_60-37","t":"임대차에 관한 설명으로 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"임대차에 관한 설명으로 옳은 것을 모두 고른 것은?","d":"ㄱ. 임대차가 종료된 경우, 그 임대목적물이 임대인이 아닌 타인 소유라도 특별한 사정이 없는 한 임차인은 임대인에게 임대차 종료일까지의 연체 차임뿐 만 아니라 그 이후부터 인도완료일까지 차임 상당의 부당이득금도 반환할 의무가 있다.\nㄴ. 임대인이 임차인에게 필요비상환의무를 이행하지 않는 경우, 임차인은 지출한 필요비 금액의 한도에서 차임의 지급을 거절할 수 있다.\nㄷ. 임차인이 임대인의 동의 없이 임차물을 제3자에게 전대한 경우, 임대인은 임대차계약의 존속 여부를 불문하고 제3자에게 불법점유를 이유로 한 차임 상당액의 손해배상청구를 할 수 있다.\nㄹ. 임차인이 임대인의 동의를 얻어 임차물을 전대한 경우, 전대인과 전차인이 전대차계약상의 차임을 감액하여 전차인이 임대인에 대하여 직접 부담하는 의무의 범위가 변경되더라도 특별한 사정이 없는 한 전차인은 변경된 전대 차계약의 내용을 임대인에게 주장할 수 있다.","o":["ㄱ, ㄴ","ㄷ, ㄹ","ㄱ, ㄴ, ㄷ","ㄱ, ㄴ, ㄹ","ㄴ, ㄷ, ㄹ"],"a":4}},{"y":2023,"e":"변리사 1차","qn":38,"i":"변리사2023_60-38-1","t":"조합재산을 구성하는 개개의 재산에 대한 합유지분을 압류 기타 강제집행의 대상으로 삼을 수 있다.","ox":"X","m":"①","c":"A","tp":"조합계약"},{"y":2023,"e":"변리사 1차","qn":38,"i":"변리사2023_60-38-2","t":"2인으로 구성된 조합에서 1인이 탈퇴하여 조합관계가 종료되는 경우, 특별한 사정이 없는 한 해산이나 청산을 거쳐야 조합재산은 남은 조합원의 단독소유에 속하게 된다.","ox":"X","m":"②","c":"A","tp":"조합계약"},{"y":2023,"e":"변리사 1차","qn":38,"i":"변리사2023_60-38-3","t":"2인으로 구성된 조합에서 1인이 존속기한을 정하지 않고 부동산 사용권을 출자하였다가 탈퇴한 경우, 특별한 사정이 없는 한 탈퇴 시 남은 조합원의 부동산 사용권은 소멸한다.","ox":"X","m":"③","c":"A","tp":"조합계약"},{"y":2023,"e":"변리사 1차","qn":38,"i":"변리사2023_60-38-4","t":"공동이행방식의 건설공동수급체의 구성원인 조합원이 그 출자의무를 불이행하면, 특별한 사정이 없는 한 출자의무의 불이행을 이유로 이익분배 자체를 거부할 수 있다.","ox":"X","m":"④","c":"A","tp":"조합계약"},{"y":2023,"e":"변리사 1차","qn":38,"i":"변리사2023_60-38-5","t":"조합원이 다른 조합원 전원의 동의 하에 조합지분을 양도하면, 조합원 지위의 변동은 조합지분의 양도양수에 관한 약정으로써 바로 효력이 생긴다.","ox":"O","m":"⑤","c":"A","tp":"조합계약"},{"y":2024,"e":"변리사 1차","qn":35,"i":"변리사2024_61-35-1","t":"부담부 증여에서 상대방의 부담의무 불이행을 이유로 한 증여자의 계약해제는 이미 이행한 부분에 대하여는 영향을 미치지 아니한다.","ox":"X","m":"①","c":"A","tp":"증여계약"},{"y":2024,"e":"변리사 1차","qn":35,"i":"변리사2024_61-35-2","t":"증여계약 성립 이후에 그 계약이 존속하는 동안 서면을 작성한 경우에는 그때부터 당사자가 임의로 이를 해제할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"변리사 1차","qn":35,"i":"변리사2024_61-35-3","t":"재단법인의 설립을 위하여 서면에 의해 출연하였더라도 착오취소를 위한 요건이 갖춰진 경우, 출연자는 착오를 이유로 출연의 의사표시를 취소할 수 있다.","ox":"O","m":"③","c":"A","tp":"증여계약"},{"y":2024,"e":"변리사 1차","qn":35,"i":"변리사2024_61-35-4","t":"서면에 의하지 않음을 이유로 증여계약을 해제하는 경우에는 원칙적으로 형성권의 제 척기간의 적용을 받지 않는다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"변리사 1차","qn":35,"i":"변리사2024_61-35-5","t":"정기의 급여를 목적으로 한 증여는 특별한 사정이 없는 한 증여자의 사망으로 인하여 그 효력을 잃는다.","ox":"O","m":"⑤","c":"A","tp":"증여계약"},{"y":2024,"e":"변리사 1차","qn":36,"i":"변리사2024_61-36","t":"甲은 자신의 토지 위에 건물신축을 위해 乙과 공사도급계약을 체결하였다. 이에 관한 설명으로 옳지 않은 것을 모두 고른 것은?","c":"A","mc":{"s":"甲은 자신의 토지 위에 건물신축을 위해 乙과 공사도급계약을 체결하였다. 이에 관한 설명으로 옳지 않은 것을 모두 고른 것은?","d":"ㄱ. 乙이 일을 완성하기 전에 甲은 손해를 배상하고 계약을 해제할 수 있으며, 특별한 사정이 없는 한 甲은 乙에 대한 손해배상에 있어서 과실상계를 주장할 수 있다.\nㄴ. 乙로부터 공사대금채권을 양수받은 자의 저당권설정청구에 의하여 甲이 신축건물에 저당권을 설정하는 행위는 특별한 사정이 없는 한 甲의 채권자에 대한 사해행위에 해당하지 아니한다.\nㄷ. 甲이 하자보수에 갈음하여 손해배상을 청구하는 경우, 甲은 보수(報酬)가 손해배상액을 초과하더라도 乙이 그 손해배상채무를 이행할 때까지 乙에게 그 보수 전액의 지급을 거절할 수 있다.\nㄹ. 완성된 건물에 중요한 하자가 있어 甲이 하자보수에 갈음하여 손해배상을 청구하는 경우, 그 하자보수비는 건물의 완성시를 기준으로 산정해야 한다.","o":["ㄱ, ㄴ","ㄴ, ㄹ","ㄷ, ㄹ","ㄱ, ㄷ, ㄹ","ㄴ, ㄷ, ㄹ"],"a":4}},{"y":2024,"e":"변리사 1차","qn":37,"i":"변리사2024_61-37-1","t":"보수의 수령 여부와 관계없이 수임인은 선량한 관리자의 주의의무를 부담한다.","ox":"O","m":"①","c":"A","tp":"위임계약"},{"y":2024,"e":"변리사 1차","qn":37,"i":"변리사2024_61-37-2","t":"수임인이 위임사무의 처리로 인하여 받은 금전을 위임인에게 반환할 경우, 특별한 사정이 없는 한 위임종료시를 기준으로 그 금전의 범위가 정해진다.","ox":"O","m":"②","c":"A","tp":"위임계약"},{"y":2024,"e":"변리사 1차","qn":37,"i":"변리사2024_61-37-3","t":"위임인이 성년후견개시심판을 받더라도 위임이 종료되는 것은 아니다.","ox":"O","m":"③","c":"A","tp":"위임계약"},{"y":2024,"e":"변리사 1차","qn":37,"i":"변리사2024_61-37-4","t":"위임계약의 당사자는 특별한 이유 없이도 언제든지 위임계약을 해지할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"변리사 1차","qn":37,"i":"변리사2024_61-37-5","t":"수임인이 위임인의 지명에 의하여 복수임인을 선임한 경우, 위임인에 대하여 그 선임감독에 관한 책임을 진다.","ox":"X","m":"⑤","c":"A","tp":"위임계약"},{"y":2024,"e":"변리사 1차","qn":40,"i":"변리사2024_61-40","t":"매도인의 담보책임에 관한 설명으로 옳은 것을 모두 고른 것은? (특별한 사정은","c":"A","mc":{"s":"매도인의 담보책임에 관한 설명으로 옳은 것을 모두 고른 것은? (특별한 사정은","d":"없으며, 다툼이 있으면 판례에 따름)\nㄱ. 타인의 권리의 매매에서 매도인이 그 권리를 매수인에게 이전할 수 없게된 경우, 매도인의 손해배상액은 이행불능 당시의 목적물의 시가를 기준으로 산정한다.\nㄴ. 매매목적물의 일부가 계약 당시에 이미 멸실되어 매도인이 그 부분을 이전할 수 없는 경우, 악의의 매수인은 대금감액을 청구할 수 없다.\nㄷ. 매매목적물이 유치권의 목적이 되어 있는 경우, 계약의 목적을 달성할 수 있더라도 선의의 매수인은 계약을 해제할 수 있다.\nㄹ. 매매당사자가 건축을 위해 매매한 토지에 대하여 건축허가를 받을 수 없어 건축이 불가능한 경우는 물건의 하자에 해당하며, 하자의 존부는 매매계약 성립시를 기준으로 판단한다.","o":["ㄱ, ㄴ","ㄴ, ㄹ","ㄷ, ㄹ","ㄱ, ㄴ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":4}},{"y":2026,"e":"변리사 1차","qn":36,"i":"변리사2026_63-36","t":"매도인 甲과 매수인 乙 사이에 X토지에 관한 매매계약이 체결된 이후의 매도인 甲의 담보책임에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면 판례에","c":"A","mc":{"s":"매도인 甲과 매수인 乙 사이에 X토지에 관한 매매계약이 체결된 이후의 매도인 甲의 담보책임에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면 판례에","d":"따름)\nㄱ. X토지가 丙의 단독소유이고 甲이 丙으로부터 X토지의 소유권을 취득하여 乙에게 이전할 수 없는 경우, 乙이 위 계약체결 당시 X토지가 丙의 소유라 는 사실에 대해 선의였다면 乙은 민법 제570조에 따른 매도인의 담보책임을 근거로 甲에게 손해배상을 청구할 수 있다.\nㄴ. X토지의 실제 면적이 계약면적에 미달할 경우, 甲과 乙의 매매계약이 수량을 지정한 매매에 해당할 때에 한하여 乙은 민법 제574조에 따른 매도인의 담보책임을 근거로 甲에게 대금감액청구권을 행사할 수 있다.\nㄷ. 乙이 X토지의 소유권을 보존하기 위하여 자신의 출재로 X토지에 설정된 저당권을 소멸시킨 경우, 乙이 위 매매계약의 체결당시에 저당권이 설정되어 있었음을 알았다면 乙은 민법 제576조 제2항에 따른 매도인의 담보책임을 근거로 甲에게 그 출재의 상환을 청구할 수 없다.","o":["ㄴ","ㄷ","ㄱ, ㄴ","ㄱ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":3}},{"y":2026,"e":"변리사 1차","qn":37,"i":"변리사2026_63-37-2","t":"甲이 乙의 사용\u0001수익권을 보장하기 위하여 X건물을 수선한 경우, 그 수선기간 동안 乙의 사용\u0001수익에 지장이 생겼다 하더라도 乙은 그 지장의 한도에서 차임의 지급을 거절할 수 없다.","ox":"X","m":"②","c":"A"},{"y":2026,"e":"변리사 1차","qn":37,"i":"변리사2026_63-37-3","t":"임대차계약의 체결 당시에 乙이 필요비상환청구권을 미리 포기하기로 약정한 경우, 특별한 사정이 없는 한 이러한 약정은 乙에게 일방적으로 불리한 것으로서 그 사법상 효력이 인정되지 않는다.","ox":"X","m":"③","c":"A"},{"y":2026,"e":"변리사 1차","qn":37,"i":"변리사2026_63-37-4","t":"乙이 甲의 동의 없이 X건물을 丙에게 전대한 경우, 甲은 乙과의 임대차계약이 존속하는 한도 내에서는 丙에게 X건물의 불법점유를 이유로 한 차임상당의 손해배상을 청구할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"변리사 1차","qn":37,"i":"변리사2026_63-37-5","t":"甲이 丁에게 X건물을 양도하고 소유권등기를 이전한 후 X건물의 임대차가 종료되어 丁이 乙에게 임대차보증금을 반환하여야 하는 경우, 丁이 甲의 지위를 승계하기 전까지 발생한 연체차임은 그에 관하여 채권양도의 요건을 갖추지 않는 한 임대차보증금에서 공제되지 않는다.","ox":"X","m":"⑤","c":"A"},{"y":2026,"e":"변리사 1차","qn":38,"i":"변리사2026_63-38-1","t":"乙이 직접 X건물을 건축하지 않고 이행대행자로서 丙을 사용하였다면 특별한 사정이 없는 한 乙은 도급계약을 불이행한 것으로 볼 수 있다.","ox":"X","m":"①","c":"A","tp":"도급인 甲과 수급인 乙은 X건물의 신축을 목적으로 하는 도급계약을 체결하였다. 이"},{"y":2026,"e":"변리사 1차","qn":38,"i":"변리사2026_63-38-2","t":"乙이 전적으로 자신의 노력과 재료로 X건물을 신축하였다면 특별한 사정이 없는 한乙은 X건물의 소유권을 원시취득한다.","ox":"O","m":"②","c":"A","tp":"도급인 甲과 수급인 乙은 X건물의 신축을 목적으로 하는 도급계약을 체결하였다. 이"},{"y":2026,"e":"변리사 1차","qn":38,"i":"변리사2026_63-38-3","t":"乙이 甲에 대한 공사대금채권을 丁에게 양도한 경우, 특별한 사정이 없는 한 민법 제 666조에서 정하는 수급인의 저당권설정청구권도 이에 수반하여 丁에게 이전된다.","ox":"O","m":"③","c":"A","tp":"도급인 甲과 수급인 乙은 X건물의 신축을 목적으로 하는 도급계약을 체결하였다. 이"},{"y":2026,"e":"변리사 1차","qn":38,"i":"변리사2026_63-38-4","t":"乙의 甲에 대한 공사대금채권과 甲의 乙에 대한 지체상금채권은 특별한 사정이 없는한 동시이행의 관계에 있지 않다.","ox":"O","m":"④","c":"A","tp":"도급인 甲과 수급인 乙은 X건물의 신축을 목적으로 하는 도급계약을 체결하였다. 이"},{"y":2026,"e":"변리사 1차","qn":38,"i":"변리사2026_63-38-5","t":"X건물이 완성되었으나 중요하지 않으면서도 보수에 과다한 비용이 요구되는 하자가 발생한 경우, 甲은 乙에게 그 하자보수를 청구할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"도급인 甲과 수급인 乙은 X건물의 신축을 목적으로 하는 도급계약을 체결하였다. 이"}],"15":[{"y":2016,"e":"변리사 1차","qn":39,"i":"변리사2016_53-39-1","t":"사무관리의 성립요건인‘타인을 위하여 사무를 처리하려는 의사’는 관리자 자신의 이익을 도모하려는 의사와 병존할 수 없다.","ox":"X","m":"①","c":"A"},{"y":2016,"e":"변리사 1차","qn":39,"i":"변리사2016_53-39-2","t":"甲이 乙과의 계약에 따라 丙의 사무를 처리한 경우에 원칙적으로 甲과 丙 사이에서는 사무관리가 성립하지 않는다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"변리사 1차","qn":39,"i":"변리사2016_53-39-3","t":"사무관리자가 본인의 의사에 반하여 사무를 관리한 때에는 본인에 대하여 비용의 상환을 청구할 수 없다.","ox":"X","m":"③","c":"A"},{"y":2016,"e":"변리사 1차","qn":39,"i":"변리사2016_53-39-4","t":"사무관리자는 본인에 대하여 비용의 상환을 청구할 수 있는 외에 사무관리에 의하여 결과적으로 사실상 이익을 얻은 다른 제3자에 대하여 직접 부당이득반환을 청구할 수도 있다.","ox":"X","m":"④","c":"A"},{"y":2016,"e":"변리사 1차","qn":39,"i":"변리사2016_53-39-5","t":"사무관리 관계의 종료를 위해서는 본인이 명시적으로 관리자에게 그 목적인 사무를 스스로 직접 관리하겠다는 의사표시를 하여야 한다.","ox":"X","m":"⑤","c":"A"},{"y":2016,"e":"변리사 1차","qn":40,"i":"변리사2016_53-40-1","t":"어업권의 임대차를 금지하는 구 수산업법 규정을 위반하여 어업권을 임대한 어업권자는 임차인이 어장을 점유\u0001사용함으로써 얻은 이익을 부당이득으로 반환청구할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"변리사 1차","qn":40,"i":"변리사2016_53-40-2","t":"고의의 불법행위를 원인으로 한 부당이득반환채권을 수동채권으로 하는 상계는 허용된다.","ox":"X","m":"②","c":"A"},{"y":2016,"e":"변리사 1차","qn":40,"i":"변리사2016_53-40-3","t":"과반수 지분의 공유자가 다른 공유자들의 허락 없이 공유토지의 전부를 배타적으로 점유\u0001사용하고 있는 경우 다른 공유자들은 부당이득반환채권을 가진다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"변리사 1차","qn":40,"i":"변리사2016_53-40-4","t":"확정판결 이후 그 내용에 반하는 다른 확정판결이 있더라도 최초 확정판결이 취소 되지 않는 한 최초 확정판결에 기한 강제집행으로 교부받은 금전이 부당이득이라고할 수는 없다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"변리사 1차","qn":40,"i":"변리사2016_53-40-5","t":"부동산에 대한 점유취득시효가 완성된 경우 소유명의자는 점유자가 시효가 완성 되기까지 그 부동산으로부터 얻은 이익에 대하여 부당이득반환청구를 할 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"변리사 1차","qn":37,"i":"변리사2017_54-37-1","t":"사무처리의 긴급성 등으로 국가의 사무에 대하여 사인의 개입이 정당화되는 경우, 사인은 국가의 사무를 처리하면서 지출한 필요비를 청구할 수 있으나 유익비의 상환을 청구할 수는 없다.","ox":"X","m":"①","c":"A","tp":"사무관리"},{"y":2017,"e":"변리사 1차","qn":37,"i":"변리사2017_54-37-2","t":"관리인이 본인에게 인도할 금전을 자기를 위하여 소비한 때에는 소비한 날 이후의 이자뿐만 아니라 그에 따른 손해까지 배상하여야 한다.","ox":"O","m":"②","c":"A","tp":"사무관리"},{"y":2017,"e":"변리사 1차","qn":37,"i":"변리사2017_54-37-3","t":"관리자가 타인의 명예에 대한 급박한 위해를 면하게 하기 위하여 그 사무를 관리한 경우, 그의 경과실로 인하여 본인에게 손해가 발생하여도 그에 따른 손해배상책임을 지지 않는다.","ox":"O","m":"③","c":"A","tp":"사무관리"},{"y":2017,"e":"변리사 1차","qn":37,"i":"변리사2017_54-37-4","t":"관리자가 사무관리를 함에 있어서 과실 없이 손해를 받은 때에는 본인의 현존이 익의 한도에서 그 손해의 보상을 청구할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"변리사 1차","qn":37,"i":"변리사2017_54-37-5","t":"타인을 위하여 사무를 처리하는 의사는 관리자 자신의 이익을 위한 의사와 병존할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"사무관리"},{"y":2018,"e":"변리사 1차","qn":24,"i":"변리사2018_55-24","t":"甲男은 乙女와 부첩(夫妾)관계를 맺고, 그 대가로 자신이 소유하는 주택을 乙에게 증여하여 乙 앞으로 소유권이전등기를 해주었다. 현재 乙은 위 주택 에서 거주하고 있다. 다음 보기 중 옳은 설명을 모두 고른 것은? (다툼이 있","c":"A","mc":{"s":"甲男은 乙女와 부첩(夫妾)관계를 맺고, 그 대가로 자신이 소유하는 주택을 乙에게 증여하여 乙 앞으로 소유권이전등기를 해주었다. 현재 乙은 위 주택 에서 거주하고 있다. 다음 보기 중 옳은 설명을 모두 고른 것은? (다툼이 있","d":"으면 판례에 따름)\nㄱ. 甲과 乙의 증여계약은 무효이다.\nㄴ. 甲은 乙 명의의 이전등기의 말소를 청구할 수 있다.\nㄷ. 甲은 乙을 상대로 주택의 명도를 청구할 수 없다.\nㄹ. 만약 乙이 丙에게 주택을 양도하고 이전등기를 해준 경우 甲은 丙 명의의 이전등기의 말소를 청구할 수 없다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄹ","ㄱ, ㄷ, ㄹ","ㄴ, ㄷ, ㄹ"],"a":4}},{"y":2018,"e":"변리사 1차","qn":35,"i":"변리사2018_55-35-1","t":"임대차계약이 합의해지된 후, 임차인이 임차목적물을 계속 점유하였으나, 이를 사용\u0001수익하지 않았다면 임대인은 임차인에게 차임상당액의 부당이득반환을 청구할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"변리사 1차","qn":35,"i":"변리사2018_55-35-2","t":"타인 소유의 토지 위에 권한 없이 건물을 소유하고 있는 자는 이를 사용\u0001수익하지 않았더라도 특별한 사정이 없는 한, 그 자체만으로 토지소유자에게 토지의 차임에 상당하는 부당이득반환의무를 부담한다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"변리사 1차","qn":35,"i":"변리사2018_55-35-3","t":"임차인이 임대차계약 종료 후 임차건물을 계속 점유하였으나, 임차인의 사정으로 인해 임차건물을 사용\u0001수익하지 아니하여 이익을 얻지 못한 경우, 임차인은 차임 상당액의 부당이득반환의무를 부담하지 않는다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"변리사 1차","qn":35,"i":"변리사2018_55-35-4","t":"甲이 乙에게 부동산을 매도하고 목적물을 인도하지 않은 상태에서 乙로부터 중 도금까지 받았으나 매매계약이 처음부터 무효였다면, 甲은 선의였더라도 乙로부터 받은 금전에 받은 날로부터 이자를 가산하여 반환하여야 한다.","ox":"X","m":"④","c":"A","tp":"부당이득"},{"y":2018,"e":"변리사 1차","qn":35,"i":"변리사2018_55-35-5","t":"甲 소유의 토지에 대한 사용권한 없이 미등기 건물을 신축한 乙로부터 그 건물을 丙이 매수하여, 이전등기를 넘겨받지 않았으나 그것에 대하여 사실상의 처분권을 갖고 있는 경우, 乙은 특별한 사정이 없는 한 甲에게 건물 부지부분에 관한 차임에 상당하는 부당이득반환의무를 부담한다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"변리사 1차","qn":38,"i":"변리사2019_56-38","t":"사무관리에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면 판례에","c":"A","mc":{"s":"사무관리에 관한 설명으로 옳은 것을 모두 고른 것은? (다툼이 있으면 판례에","d":"따름)\nㄱ. 관리자가 사무관리를 함에 있어서 과실 없이 손해를 받은 경우, 본인에게 그 손해 전부의 보상을 청구할 수 있다.\nㄴ. 관리자는 본인의 청구가 있는 때에 사무처리의 상황을 보고하여야 하며, 사무처리가 종료된 때에는 지체 없이 그 전말을 보고하여야 한다.\nㄷ. 타인을 위하여 사무를 처리하는 의사는 관리자 자신의 이익을 위한 의사와 병존할 수 있고, 반드시 외부적으로 표시될 필요가 없으며, 사무를 관리할 당시에 확정되어 있을 필요도 없다.\nㄹ. 제3자와의 약정에 따라 타인의 사무를 처리한 경우에도 그 타인과의 관계에서는 의무 없이 타인의 사무를 처리한 것이므로, 그 타인과의 관계에서 원칙적으로 사무관리가 성립한다.","o":["ㄱ, ㄴ","ㄴ, ㄷ","ㄷ, ㄹ","ㄱ, ㄴ, ㄹ","ㄱ, ㄷ, ㄹ"],"a":2}},{"y":2023,"e":"변리사 1차","qn":39,"i":"변리사2023_60-39-1","t":"쌍무계약에서 당사자 쌍방의 귀책사유 없이 일방의 채무가 후발적으로 불능이 된 경우, 상대방은 이미 이행한 급부에 대하여 부당이득반환을 청구할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"변리사 1차","qn":39,"i":"변리사2023_60-39-2","t":"집행력 있는 정본을 가진 채권자가 배당요구의 종기까지 적법한 배당요구를 하지 않아 배당에서 제외된 경우, 배당금을 수령한 다른 채권자를 상대로 부당이득반환청구를 할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"변리사 1차","qn":39,"i":"변리사2023_60-39-3","t":"과세관청이 3자간 등기명의신탁에 따라 해당 부동산의 공부상 소유자가 된 명의수탁 자에게 재산세 부과처분을 하여 명의수탁자가 재산세를 납부한 경우, 그는 명의신탁 자나 그 상속인을 상대로 재산세 상당액에 대한 부당이득반환청구를 할 수 있다.","ox":"X","m":"③","c":"A"},{"y":2023,"e":"변리사 1차","qn":39,"i":"변리사2023_60-39-4","t":"임차인이 임대차계약 종료 후 임대차건물을 계속 점유하였으나, 본래의 임대차계약상의 목적에 따라 사용\u0001수익하지 아니하여 실질적인 이득을 얻은 바가 없는 경우, 임차인은 차임 상당의 부당이득반환의무를 부담하지 않는다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"변리사 1차","qn":39,"i":"변리사2023_60-39-5","t":"송금의뢰인과 수취인 사이에 계좌이체의 원인이 되는 법률관계가 존재하지 않는데도 송금의뢰인의 착오송금으로 인해 수취인이 계좌이체금액에 해당하는 예금채권을 취득한 경우, 송금의뢰인이 수취인에 대하여 부당이득반환청구권을 갖는다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"변리사 1차","qn":38,"i":"변리사2024_61-38-1","t":"관리자가 사무의 적절한 관리를 함에 있어 과실없이 손해를 받은 때에는 본인에 대하여 그 손해 전액의 보상을 청구할 수 있다.","ox":"X","m":"①","c":"A","tp":"사무관리"},{"y":2024,"e":"변리사 1차","qn":38,"i":"변리사2024_61-38-2","t":"관리자가 본인을 위하여 본인의 의사에 부합하게 사무를 관리하면서 유익비를 지출한 경우, 현존이익 한도에서 그 상환을 청구할 수 있다.","ox":"X","m":"②","c":"A","tp":"사무관리"},{"y":2024,"e":"변리사 1차","qn":38,"i":"변리사2024_61-38-3","t":"상대방과의 약정에 따라 제3자의 사무를 관리한 경우, 그 관리자와 제3자 사이에서는 원칙적으로 사무관리가 성립된다.","ox":"X","m":"③","c":"A"},{"y":2024,"e":"변리사 1차","qn":38,"i":"변리사2024_61-38-4","t":"관리자에게 타인을 위해 사무를 처리하는 의사와 관리자 자신의 이익을 위한 의사가 모두 있는 경우에는 사무관리가 성립할 수 없다.","ox":"X","m":"④","c":"A"},{"y":2024,"e":"변리사 1차","qn":38,"i":"변리사2024_61-38-5","t":"관리자가 타인의 신체에 대한 급박한 위해를 면하게 하기 위하여 그 사무를 관리한 경우, 그의 경과실로 인해 발생한 본인의 손해를 배상할 책임이 없다.","ox":"O","m":"⑤","c":"A","tp":"사무관리"},{"y":2026,"e":"변리사 1차","qn":39,"i":"변리사2026_63-39-1","t":"타인 소유의 토지 위에 권한 없이 건물을 소유하고 있는 자는 이를 사용\u0001수익하지 않았더라도 특별한 사정이 없는 한, 그 자체만으로 토지소유자에게 토지의 차임에 상당하는 부당이득반환의무를 부담한다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"변리사 1차","qn":39,"i":"변리사2026_63-39-2","t":"물상대위권을 행사하지 아니하여 우선변제권을 상실한 저당권자는 저당목적물에 갈음한 보상금으로 이득을 얻은 다른 채권자에 대하여 그 이익을 부당이득으로 반환청구할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"변리사 1차","qn":39,"i":"변리사2026_63-39-3","t":"채권자가 채무자에게 지급되어야 할 대상(代償)청구의 대상이 되는 보상금을 어떤 사유로 직접 자신의 명의로 지급받았다면 채무자에 대한 관계에서 바로 부당이득이 된다.","ox":"X","m":"③","c":"A"},{"y":2026,"e":"변리사 1차","qn":39,"i":"변리사2026_63-39-4","t":"법률상 원인 없이 제3자에 대한 채권을 취득한 경우, 채권의 이득자가 아직 그 채권을 현실적으로 추심하지 못하였다면 손실자는 채권의 이득자에 대하여 그 채권 가액에 해당하는 금전의 반환을 청구할 수 없다.","ox":"O","m":"④","c":"A","tp":"부당이득"},{"y":2026,"e":"변리사 1차","qn":39,"i":"변리사2026_63-39-5","t":"채무자가 피해자로부터 횡령한 금전을 자신의 채권자에 대한 채무변제에 사용하는 경우, 채권자가 변제를 수령하면서 그 금전이 횡령한 것이라는 사실에 대하여 악의 또는 중대한 과실이 없는 한 채권자의 금전취득은 피해자에 대한 관계에서 법률상 원인이 있는 것으로 보아야 한다.","ox":"O","m":"⑤","c":"A","tp":"부당이득"}],"16":[{"y":2017,"e":"변리사 1차","qn":38,"i":"변리사2017_54-38-2","t":"甲이 丙에 대한 대여금채권을 자동채권으로 하여 2천만원을 상계한 경우, 乙은 丙에 대하여 4백 5십만원의 손해배상채무를 부담하게 된다.","ox":"X","m":"②","c":"A"},{"y":2017,"e":"변리사 1차","qn":38,"i":"변리사2017_54-38-3","t":"甲이 丙에게 손해배상채무를 전액 배상한 경우, 甲의 乙에 대한 구상채권의 소멸시효는 10년으로 완성되고, 그 기산점은 甲이 현실로 丙에게 손해배상금을 지급한 때이다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"변리사 1차","qn":38,"i":"변리사2017_54-38-5","t":"甲의 보증인 丁이 丙에 대하여 손해배상채무를 변제한 경우, 丁은 乙에게 乙의 부담부분에 한하여 구상권을 행사할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"변리사 1차","qn":36,"i":"변리사2018_55-36-1","t":"피용자의 불법행위에 기한 손해배상채무가 시효로 인해 소멸하더라도, 그것에 의해 사용자책임에 기한 손해배상채무까지 소멸하는 것은 아니다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"변리사 1차","qn":36,"i":"변리사2018_55-36-2","t":"도급인이 수급인에 대하여 특정한 행위를 지휘하는 등의 노무도급의 경우에도 급인은 수급인의 불법행위에 대해 사용자책임을 질 수 있다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"변리사 1차","qn":36,"i":"변리사2018_55-36-3","t":"지입차량의 차주가 고용한 운전자의 과실로 인한 불법행위로 인해 타인에게 손해가 발생한 경우, 그 운전자의 불법행위에 대해 지입회사는 사용자책임을 질수 있다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"변리사 1차","qn":36,"i":"변리사2018_55-36-4","t":"피용자가 제3자와의 공동불법행위로 피해자에게 손해를 입힌 경우, 사용자가 피용자의 부담부분을 초과하여 피해자에게 손해를 배상하면 사용자는 제3자에게 그 초과부분에 대해 구상권을 행사할 수 있다.","ox":"O","m":"④","c":"A","tp":"사용자책임"},{"y":2018,"e":"변리사 1차","qn":36,"i":"변리사2018_55-36-5","t":"피용자와 제3자와의 공동불법행위로 인해 손해를 입은 피해자에게 사용자가 채권을 가지고 있으나 사용자가 상계할 수 있음에도 상계하지 않는 경우, 제3자는 사용자의 부담부분 범위 내에서 사용자의 채권을 가지고 피해자에게 상계할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"사용자책임"},{"y":2019,"e":"변리사 1차","qn":40,"i":"변리사2019_56-40-1","t":"수인이 공동의 불법행위로 타인에게 손해를 가한 때에는 연대하여 그 손해를 배상할 책임이 있다.","ox":"O","m":"①","c":"A","tp":"공동불법행위"},{"y":2019,"e":"변리사 1차","qn":40,"i":"변리사2019_56-40-2","t":"공동불법행위가 성립하기 위해서는 행위자 사이에 의사의 공통이나 행위공동의 인식은 필요하지 않다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"변리사 1차","qn":40,"i":"변리사2019_56-40-3","t":"공동불법행위자 중 1인의 변제는 변제된 금액의 한도 내에서 다른 공동불법행위자를 위하여 공동면책의 효력이 있다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"변리사 1차","qn":40,"i":"변리사2019_56-40-4","t":"가해자불명의 공동불법행위의 경우, 개별 행위자가 자기의 행위와 손해발생 사이에 인과관계가 없음을 증명하면 불법행위책임을 면한다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"변리사 1차","qn":40,"i":"변리사2019_56-40-5","t":"공동불법행위자 중 1인인 甲의 손해배상채무가 시효로 소멸한 후에, 다른 공동불법행위자 乙이 피해자에게 자기의 부담부분을 넘는 손해를 배상하였더라도 乙은 甲에게 구상권을 행사할 수 없다.","ox":"X","m":"⑤","c":"A"},{"y":2021,"e":"변리사 1차","qn":37,"i":"변리사2021_58-37","t":"甲은 친구 乙이 운전하는 차량에 호의로 동승하여 귀가하던 중 신호를 무시하고 운전하던 丙의 차량과 충돌하는 사고로 부상을 당하였다. 이 사고로 인한 甲의 손해액은 1,000만 원, 乙과 丙의 과실비율은 2:8로 확정되었다. 이에 관한 설명으로 옳지 않은 것은?","c":"A","mc":{"s":"甲은 친구 乙이 운전하는 차량에 호의로 동승하여 귀가하던 중 신호를 무시하고 운전하던 丙의 차량과 충돌하는 사고로 부상을 당하였다. 이 사고로 인한 甲의 손해액은 1,000만 원, 乙과 丙의 과실비율은 2:8로 확정되었다. 이에 관한 설명으로 옳지 않은 것은?","d":"(단, 자동차손해배상보장법은 고려하지 않으며, 다툼이 있으면 판\n례에 따름)","o":["甲의 손해에 대하여 乙, 丙은 부진정연대책임을 진다.","甲의 호의동승으로 인해 乙의 책임이 제한되는 경우, 이는 丙에게도 인정된다.","甲이 乙의 난폭운전으로 사고발생의 위험성이 상당할 정도로 우려된다는 것을 인식한 경우, 甲에게 안전운전을 촉구할 주의의무가 인정된다.","甲의 호의동승에 따른 책임제한이 30%로 인정되고 丙이 甲에게 600만 원을 변제한 경우, 丙은 乙에게 40만 원을 구상할 수 있다.","丙이 甲에게 손해 전부를 배상하고 乙에 대한 구상권을 취득한 후 甲의 乙에 대한 손해배상채권이 시효로 소멸한 경우, 丙은 乙에게 더 이상 구상권을 행사할 수 없다."],"a":5}},{"y":2023,"e":"변리사 1차","qn":40,"i":"변리사2023_60-40-1","t":"공동불법행위자들 중에 고의로 불법행위를 행한 자가 있는 경우, 모든 공동불법행위 자가 과실상계의 주장을 할 수 없다.","ox":"X","m":"①","c":"A"},{"y":2023,"e":"변리사 1차","qn":40,"i":"변리사2023_60-40-2","t":"위법행위 시점과 손해의 발생 시점에 시간적 간격이 있는 경우, 불법행위로 인한 재산상 손해에 대한 배상책임이 성립하는 시기는 손해의 발생 시점이다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"변리사 1차","qn":40,"i":"변리사2023_60-40-3","t":"금전을 대여한 채권자가 고의 또는 과실로 이자제한법을 위반하여 최고이자율을 초과하는 이자를 받아 채무자에게 손해를 입힌 경우, 특별한 사정이 없는 한 불법행위가 성립한다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"변리사 1차","qn":40,"i":"변리사2023_60-40-4","t":"민법 제756조(사용자의 배상책임)의 사용관계는 실제로 지휘\u0001감독하고 있는지 여부에 의하여 결정되는 것이 아니라 객관적으로 지휘\u0001감독을 하여야 할 관계에 있는지 여부에 따라 결정된다.","ox":"O","m":"④","c":"A","tp":"불법행위"},{"y":2023,"e":"변리사 1차","qn":40,"i":"변리사2023_60-40-5","t":"불법행위로 인한 손해배상채무는 특별한 사정이 없는 한 채무 성립과 동시에 지연손해금이 발생한다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"변리사 1차","qn":39,"i":"변리사2024_61-39-1","t":"공동불법행위자 甲과 乙중 甲의 손해배상채무가 시효로 소멸한 후에 乙이 피해자에게 자기의 부담 부분을 넘는 손해를 배상한 경우, 乙은 甲을 상대로 구상권을 행사할 수 없다.","ox":"X","m":"①","c":"A"},{"y":2024,"e":"변리사 1차","qn":39,"i":"변리사2024_61-39-2","t":"자신의 과실에 의해 초래된 급박한 위난을 피하기 위해 부득이 타인에게 손해를 가한 자는 그 손해에 대한 배상책임을 지지 않는다.","ox":"X","m":"②","c":"A","tp":"불법행위"},{"y":2024,"e":"변리사 1차","qn":39,"i":"변리사2024_61-39-3","t":"공작물의 설치\u0001보존의 하자로 인해 타인에게 입힌 손해에 대하여 점유자가 면책된 경우, 그 공작물의 소유자는 과실이 없어도 배상책임을 진다.","ox":"O","m":"③","c":"A","tp":"불법행위"},{"y":2024,"e":"변리사 1차","qn":39,"i":"변리사2024_61-39-4","t":"피용자와 제3자가 공동불법행위에 따른 손해배상채무를 부담하는 경우, 사용자가 피용자와 제3자의 책임비율에 의해 정해진 부담부분을 초과하여 피해자에게 배상하더라도 제3자에 대하여 구상권을 행사할 수 없다.","ox":"X","m":"④","c":"A"},{"y":2024,"e":"변리사 1차","qn":39,"i":"변리사2024_61-39-5","t":"불법행위로 인하여 건물이 훼손되어 사용 및 수리가 불가능한 경우, 손해배상액의 기준이 되는 건물의 시가에는 원칙적으로 건물의 철거비용이 포함된다.","ox":"X","m":"⑤","c":"A"},{"y":2026,"e":"변리사 1차","qn":40,"i":"변리사2026_63-40-1","t":"피용자의 고의에 의한 불법행위로 인하여 사용자가 사용자책임을 부담하는 경우, 사용 자책임의 범위를 정함에 있어서 피해자의 과실을 고려하여 그 책임을 제한할 수 없다.","ox":"X","m":"①","c":"A"},{"y":2026,"e":"변리사 1차","qn":40,"i":"변리사2026_63-40-2","t":"사용관계의 존재 여부는 실제로 지휘\u0001감독하고 있는지 여부에 의하여 결정되는 것이 아니라 객관적\u0001규범적으로 지휘\u0001감독을 하여야 할 관계에 있는지 여부에 따라 결정된다.","ox":"O","m":"②","c":"A","tp":"사용자책임"},{"y":2026,"e":"변리사 1차","qn":40,"i":"변리사2026_63-40-3","t":"도급인이 수급인에 대하여 특정한 행위를 지휘하는 등의 노무도급의 경우에 도급인은 수급인의 불법행위에 대해 사용자책임이 인정될 수 있다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"변리사 1차","qn":40,"i":"변리사2026_63-40-4","t":"피용자가 제3자와의 공동불법행위로 피해자에게 손해를 입힌 경우, 사용자가 피용자의 부담부분을 초과하여 피해자에게 손해를 배상하면 사용자는 제3자에게 그 초과부 분에 대해 구상권을 행사할 수 있다.","ox":"O","m":"④","c":"A","tp":"사용자책임"},{"y":2026,"e":"변리사 1차","qn":40,"i":"변리사2026_63-40-5","t":"부진정연대의 관계에 있는 사용자와 피용자의 피해자에 대한 손해배상액이 달라진 경우, 다액채무자인 피용자가 손해배상액의 일부를 변제하면 이로 인하여 먼저 소멸하는 부분은 그 피용자가 단독으로 채무를 부담하는 부분이다.","ox":"O","m":"⑤","c":"A","tp":"사용자책임"}]};
window.PAIRS=[{"n":1,"s":0.327,"o":{"i":"변리사2019_56-03-4","t":"이사의 대표권에 대한 제한은 이를 등기하지 않으면, 제3자가 악의이더라도 대항하지 못한다.","y":2019,"e":"변리사 1차"},"x":{"i":"변리사2023_60-03-3","t":"이사의 대표권에 대한 제한은 이를 등기하지 아니하면 그 효력이 없다.","y":2023,"e":"변리사 1차"}},{"n":1,"s":0.301,"o":{"i":"변리사2018_55-10-3","t":"미성년자가 의사무능력 상태에서 법정대리인의 동의 없이 법률행위를 한 경우, 법정대리인은 미성년을 이유로 법률행위를 취소할 수 있다.","y":2018,"e":"변리사 1차"},"x":{"i":"변리사2018_55-04-5","t":"미성년자가 법정대리인의 동의 없이 법률행위를 하면서 특약에 의하여 미성년을 이유로 한 취소를 하지 않기로 한 경우에는 미성년을 이유로 그 법률행위를 취소할 수 없다.","y":2018,"e":"변리사 1차"}},{"n":3,"s":0.678,"o":{"i":"변리사2026_63-09-5","t":"乙이 甲을 단독으로 상속하여 X토지의 소유자가 되면, 특별한 사정이 없는 한 乙은 본인의 지위에서 매매계약의 추인을 거절할 수 없다.","y":2026,"e":"변리사 1차"},"x":{"i":"변리사2017_54-08-3","t":"乙이 甲을 단독으로 상속하여 X토지의 소유자가 되면, 乙은 본인의 지위에서 매매계약의 추인을 거절할 수 있다.","y":2017,"e":"변리사 1차"}},{"n":3,"s":0.519,"o":{"i":"변리사2021_58-12-2","t":"丙이 계약체결 당시에 乙에게 매매계약 체결의 대리권이 없음을 알았더라도 丙의 甲에 대한 최고권이 인정된다.","y":2021,"e":"변리사 1차"},"x":{"i":"변리사2021_58-12-3","t":"丙이 계약체결 당시에 乙에게 매매계약 체결의 대리권이 없음을 알았더라도 계약을 철회할 수 있다.","y":2021,"e":"변리사 1차"}},{"n":3,"s":0.453,"o":{"i":"변리사2024_61-06-4","t":"경과실로 인한 착오로 의사표시를 한 자가 착오를 이유로 그 의사표시를 취소한 경우, 상대방은 이로 인해 손해를 입더라도 표의자에게 불법행위로 인한 손해배상을 청구할 수 없다.","y":2024,"e":"변리사 1차"},"x":{"i":"변리사2021_58-08-5","t":"표의자가 착오를 이유로 의사표시를 취소한 경우, 취소로 인하여 손해를 입은 상대방은 표의자에게 불법행위로 인한 손해배상을 청구할 수 있다.","y":2021,"e":"변리사 1차"}},{"n":3,"s":0.423,"o":{"i":"변리사2024_61-06-5","t":"상대방이 표의자의 착오를 알고 이용한 경우에는 착오가 표의자의 중대한 과실로 인한 것이더라도 표의자는 착오를 이유로 의사표시를 취소할 수 있다.","y":2024,"e":"변리사 1차"},"x":{"i":"변리사2019_56-05-1","t":"착오가 의사표시자의 중대한 과실로 인한 경우에는 상대방이 그 착오를 알고 이를 이용하였더라도 의사표시자는 착오를 이유로 의사표시를 취소할 수 없다.","y":2019,"e":"변리사 1차"}},{"n":5,"s":0.652,"o":{"i":"변리사2021_58-16-2","t":"乙은 丙에 대하여 소유권에 기한 방해배제청구권을 행사할 수 없지만, 甲의 소유권에 기한 방해배제청구권을 대위 행사할 수 있다.","y":2021,"e":"변리사 1차"},"x":{"i":"변리사2021_58-16-4","t":"甲은 丙에 대하여 점유권에 기한 방해배제청구권을 행사할 수 없지만, 乙의 점유권에 기한 방해배제청구권을 대위 행사할 수 있다.","y":2021,"e":"변리사 1차"}},{"n":7,"s":0.429,"o":{"i":"변리사2017_54-15-1","t":"전세권설정자가 전세권자에 대하여 민법 제315조에 정한 손해배상채권 이외의 다른 채권을 가지고 있더라도 특별한 사정이 없는 한, 이를 가지고 전세금반환채권에 대하여 물상대위권을 행사한 전세권저당권자에게 상계로 대항할 수 없다.","y":2017,"e":"변리사 1차"},"x":{"i":"변리사2026_63-21-4","t":"전세권설정자는 전세권자에 대하여 전세권자에게 책임있는 사유로 인하여 전세목적물이 멸실됨에 따른 손해배상채권 이외의 다른 채권을 가지고 전세금반환채권에 대하여 물상대위권을 행사한 전세권저당권자에게 상계 등으로 대항할 수 있다.","y":2026,"e":"변리사 1차"}},{"n":8,"s":0.744,"o":{"i":"변리사2017_54-24-5","t":"건물신축공사를 도급받은 수급인은 사회통념상 독립한 건물이 되지 못한 정착물을 토지에 설치한 상태에서 공사가 중단된 경우, 위 정착물에 대하여 유치권을 행사할 수 없다.","y":2017,"e":"변리사 1차"},"x":{"i":"변리사2018_55-23-5","t":"건물신축공사를 도급받은 수급인이 사회통념상 독립한 건물이 되지 못한 정착물을 토지에 설치한 상태에서 공사가 중단된 경우, 토지에 대하여 유치권을 행사할 수 있다.","y":2018,"e":"변리사 1차"}},{"n":8,"s":0.653,"o":{"i":"변리사2024_61-24-1","t":"매매대금 채권을 담보하기 위하여 가등기를 한 경우에는 「가등기담보 등에 관한 법률」이 적용되지 않는다.","y":2024,"e":"변리사 1차"},"x":{"i":"변리사2026_63-16-1","t":"매매대금 채무를 담보하기 위하여 가등기를 한 경우에는 「가등기담보 등에 관한 법률」이 적용된다.","y":2026,"e":"변리사 1차"}},{"n":8,"s":0.545,"o":{"i":"변리사2019_56-24-5","t":"제3채무자가 질권설정 사실을 승낙한 후 질권설정계약이 합의해지된 경우, 질권설정자가 해지를 이유로 제3채무자에게 원래의 채권으로 대항하려면 질권자가 제3채무자에게 해지 사실을 통지하여야 한다.","y":2019,"e":"변리사 1차"},"x":{"i":"변리사2016_53-21-2","t":"丙이 질권설정 사실을 승낙한 후 그 질권설정계약이 합의해지된 경우, 甲이 해지를 이유로 丙에게 원래의 채권으로 대항하려면 甲이 丙에게 해지 사실을 통지하여야 한다.","y":2016,"e":"변리사 1차"}},{"n":8,"s":0.478,"o":{"i":"변리사2024_61-20-2","t":"임대인과 임차인 사이에 건물명도시 권리금을 반환하기로 약정한 경우, 임차인은 권리금반환청구권을 피담보채권으로 하여 그 건물에 대하여 유치권을 행사할 수 없다.","y":2024,"e":"변리사 1차"},"x":{"i":"변리사2021_58-21-4","t":"임대인과 임차인 사이에 임대차 종료에 따른 건물명도 시에 권리금을 반환하기로 약정한 경우, 임차인은 권리금반환청구권을 가지고 건물에 대한 유치권을 행사할 수 있다.","y":2021,"e":"변리사 1차"}},{"n":9,"s":0.627,"o":{"i":"변리사2026_63-27-2","t":"이행기의 정함이 없는 채권을 양수한 채권양수인이 채무자를 상대로 그 이행을 구하는 소를 제기하고 소송 계속 중 채무자에 대한 채권양도통지가 이루어진 경우에는 특별한 사정이 없는 한 채무자는 채권양도통지가 도달된 다음 날부터 지체책임을 진다.","y":2026,"e":"변리사 1차"},"x":{"i":"변리사2024_61-26-2","t":"이행기의 정함이 없는 지명채권을 양수한 채권양수인이 채무자를 상대로 그 이행을 구하는 소를 제기하고, 그 소송 계속 중 채무자에 대한 채권양도통지가 이루어진 경우에는 특별한 사정이 없는 한 채무자는 그 소가 제기된 날부터 채권양수인에 대해 이행지체의 책임을 진다.","y":2024,"e":"변리사 1차"}},{"n":11,"s":0.302,"o":{"i":"변리사2018_55-31-2","t":"채무자와 인수인 사이의 계약에 의해 채무인수가 이루어지는 경우, 채권자가 승낙을 거절하면 이후에 다시 승낙을 하더라도 면책적 채무인수의 효력이 발생하지 않는다.","y":2018,"e":"변리사 1차"},"x":{"i":"변리사2021_58-28-1","t":"채무자와 채무인수인 사이의 면책적 채무인수에서 채권자가 승낙을 거절하였더라도 다시 승낙하면 채무인수의 효력이 생긴다.","y":2021,"e":"변리사 1차"}},{"n":12,"s":0.569,"o":{"i":"변리사2017_54-32-4","t":"가압류 효력발생 당시 乙의 채권이 변제기에 도달하지 않은 경우, 乙의 채권의 변제기가 甲의 채권의 변제기보다 먼저 도래하면 乙은 상계로써 丙에게 대항할 수 있다.","y":2017,"e":"변리사 1차"},"x":{"i":"변리사2017_54-32-3","t":"가압류의 효력발생 당시 乙의 채권이 변제기에 도달하지 않은 경우, 甲의 채권의 변제기 후에 乙의 채권이 변제기에 도달하더라도 乙은 상계로써 丙에게 대항할 수 있다.","y":2017,"e":"변리사 1차"}},{"n":12,"s":0.34,"o":{"i":"변리사2016_53-32-1","t":"채무자가 채권자에게 채무변제에 갈음하여 다른 채권을 양도하기로 한 경우, 채권양도의 요건을 갖추어 대체급부가 이루어짐으로써 원래의 채무는 소멸한다.","y":2016,"e":"변리사 1차"},"x":{"i":"변리사2016_53-32-2","t":"채무자가 채권자에게 채무변제에 갈음하여 다른 채권을 양도하기로 한 경우, 양도인은 양도된 채권의 채무자의 변제자력까지 담보하는 것으로 보아야 한다.","y":2016,"e":"변리사 1차"}},{"n":13,"s":0.677,"o":{"i":"변리사2021_58-35-5","t":"동시이행의 관계에 있는 쌍방의 채무 중 어느 한 채무가 이행불능이 됨으로 인하여 발생한 손해배상채무도 여전히 다른 채무와 동시이행의 관계에 있다.","y":2021,"e":"변리사 1차"},"x":{"i":"변리사2019_56-35-2","t":"동시이행관계에 있는 쌍방의 채무 중 어느 한 채무가 이행불능이 됨으로 인하여 발생한 손해배상채무는 다른 채무와 동시이행관계에 있지 않다.","y":2019,"e":"변리사 1차"}},{"n":10,"s":0.344,"o":{"i":"변리사2026_63-29-2","t":"채무자의 재산적 법률행위라 하더라도 채무자의 책임재산이 아닌 재산에 관한 법률행위인 경우에는 채권자취소권의 대상이 될 수 없다.","y":2026,"e":"변리사 1차"},"x":{"i":"변리사2018_55-26-1","t":"채무자의 법률행위가 통정허위표시로 무효인 경우에는 채권자취소권의 대상이될 수 없다.","y":2018,"e":"변리사 1차"}},{"n":10,"s":0.338,"o":{"i":"변리사2017_54-28-2","t":"채권자의 채권이 사해행위 이전에 성립한 이상 사해행위 이후에 양도되었다고 하더라도 양수인의 채권은 채권자취소권의 피보전채권이 될 수 있다.","y":2017,"e":"변리사 1차"},"x":{"i":"변리사2026_63-29-3","t":"사해행위 이전에 성립한 채권이 사해행위 이후에 양도되었다면 그 채권양수인은 채권자취소권을 행사할 수 없다.","y":2026,"e":"변리사 1차"}},{"n":15,"s":0.456,"o":{"i":"변리사2017_54-37-4","t":"관리자가 사무관리를 함에 있어서 과실 없이 손해를 받은 때에는 본인의 현존이 익의 한도에서 그 손해의 보상을 청구할 수 있다.","y":2017,"e":"변리사 1차"},"x":{"i":"변리사2024_61-38-1","t":"관리자가 사무의 적절한 관리를 함에 있어 과실없이 손해를 받은 때에는 본인에 대하여 그 손해 전액의 보상을 청구할 수 있다.","y":2024,"e":"변리사 1차"}},{"n":15,"s":0.407,"o":{"i":"변리사2017_54-37-5","t":"타인을 위하여 사무를 처리하는 의사는 관리자 자신의 이익을 위한 의사와 병존할 수 있다.","y":2017,"e":"변리사 1차"},"x":{"i":"변리사2016_53-39-1","t":"사무관리의 성립요건인‘타인을 위하여 사무를 처리하려는 의사’는 관리자 자신의 이익을 도모하려는 의사와 병존할 수 없다.","y":2016,"e":"변리사 1차"}}];
